import { Input } from "@/components/ui/input";
import { saveSettingsRowsSafely } from "@/components/estimator/settings/settingsSaveGuard";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import SettingsTransferBar from "@/components/estimator/settings/SettingsTransferBar";
import { CNC_SETTINGS_DEFAULTS, resetValuesToDefaults } from "@/components/estimator/settings/moduleSettingDefaults";

const SIZES = ["1/16", "1/8", "3/16", "1/4", "3/8", "1/2", "5/8", "3/4", "7/8", "1", "1-1/4", "1-1/2", "2", "2-1/2", "3", "3-1/2", "4"];
const MATERIALS = ["Acrylic", "Wood", "MDF", "Plywood", "PVC", "HDPE", "Aluminum", "Corian"];

const KEYS = new Set([
  "cnc_machine_rate", "cnc_labor_rate", "cnc_setup_time_percentage", "min_cnc_setup_hours", "min_cnc_labor_hours", "cnc_letter_perimeter_factor",
  "cnc_purchase_price", "cnc_lifespan_years", "cnc_usage_hours_per_week", "cnc_annual_maintenance_cost", "cnc_power_consumption_kw", "cnc_tooling_cost_per_hour",
  "electricity_cost_per_kwh", "operator_cost_per_hour", "facility_overhead_per_hour",
  ...MATERIALS.map((m) => `${m.toLowerCase()}_cnc_cut_multiplier`),
  ...SIZES.map((s) => `cnc_cut_speed_${s.replaceAll("/", "_").replaceAll("-", "_")}`),
]);

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;

export default function CNCSettings() {
  const [rows, setRows] = useState([]);
  const [values, setValues] = useState({});
  const [original, setOriginal] = useState({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const settingsSaveRef = useRef(false);

  useEffect(() => {
    const load = async () => {
      try {
        const all = await loadAllEntityRows({ entity: SettingsEntity, sort: null, label: "CNC Settings catalog" });
        const relevant = (all || []).filter((row) => KEYS.has(row.setting_name));
        const map = Object.fromEntries(relevant.map((row) => [row.setting_name, row.setting_value ?? ""]));
        setRows(relevant);
        setValues(map);
        setOriginal(map);
      } catch (e) {
        setError(e.message || "Could not load CNC settings.");
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  const patch = (key, value) => setValues((prev) => ({ ...prev, [key]: String(value) }));
  const dirtyCount = rows.filter((row) => String(values[row.setting_name] ?? "") !== String(original[row.setting_name] ?? "")).length;

  const rate = useMemo(() => {
    const purchasePrice = num(values.cnc_purchase_price);
    const lifespan = Math.max(num(values.cnc_lifespan_years, 1), 0.000001);
    const usageHours = Math.max(num(values.cnc_usage_hours_per_week, 1), 0.000001);
    const annualHours = usageHours * 52;
    const depreciation = (purchasePrice / lifespan) / annualHours;
    const maintenance = num(values.cnc_annual_maintenance_cost) / annualHours;
    const power = num(values.cnc_power_consumption_kw) * num(values.electricity_cost_per_kwh);
    const tooling = num(values.cnc_tooling_cost_per_hour);
    const overhead = num(values.facility_overhead_per_hour);
    const operator = num(values.operator_cost_per_hour);
    // Preserve legacy SignEstimate Pro behavior: operator labor is shown for reference,
    // but is intentionally excluded from CNC machine rate because labor is priced separately.
    return { depreciation, maintenance, power, tooling, overhead, operator, total: depreciation + maintenance + power + tooling + overhead };
  }, [values]);

  // #83 â€” stage every managed key back to the calculator's documented fallback.
  const handleResetDefaults = () => {
    setValues((prev) => resetValuesToDefaults(prev, CNC_SETTINGS_DEFAULTS, [...KEYS]));
    setMessage("Defaults staged â€” click Save to persist them.");
  };

  const handleSave = async () => {
    if (settingsSaveRef.current) return;
    settingsSaveRef.current = true;
    setSaving(true);
    setError("");
    setMessage("");
    try {
      const result = await saveSettingsRowsSafely({
        SettingsEntity,
        rows,
        values,
        originalValues: original,
      });
      setRows(result.rows);
      setOriginal(result.snapshot);
      setMessage(result.changedCount ? `Saved ${result.changedCount} CNC setting${result.changedCount === 1 ? "" : "s"}.` : "No CNC settings changed.");
    } catch (e) {
      setError(e.message || "Could not save CNC settings. Admin permission may be required.");
    } finally {
      settingsSaveRef.current = false;
      setSaving(false);
    }
  };

  if (loading) return <div className="p-10 text-center text-gray-400">Loading CNC settings…</div>;

  return (
    <div className="min-h-full bg-gray-50">
      <div className="max-w-[1180px] mx-auto p-4 sm:p-5 space-y-4">
        <div className="flex items-center justify-between gap-3">
          <Link to="/EstimatorSettings" className="inline-flex items-center gap-1 text-[12px] font-semibold text-gray-600 hover:text-gray-900"><ArrowLeft className="w-4 h-4" /> Estimator Settings</Link>
          <div className="flex items-center gap-2"><SettingsTransferBar values={values} allowedKeys={Object.keys(values)} fileName="cnc-settings" onImport={(imported) => setValues((v) => ({ ...v, ...imported }))} /><Button variant="outline" onClick={handleResetDefaults} disabled={saving} className="h-[32px] text-[12px] font-semibold" title="Stage calculator fallback defaults â€” Save to persist"><RotateCcw className="w-4 h-4 mr-1.5" /> Reset to defaults</Button><Button onClick={handleSave} disabled={saving || dirtyCount === 0} className="h-[32px] bg-[#454545] hover:bg-[#353535] text-white text-[12px] font-semibold disabled:opacity-50"><Save className="w-4 h-4 mr-1.5" /> {saving ? "Saving…" : `Save${dirtyCount ? ` (${dirtyCount})` : ""}`}</Button></div>
        </div>

        <div className="bg-white border border-gray-200 rounded-md px-4 py-3 flex items-center gap-3">
          <div className="w-9 h-9 rounded bg-emerald-100 text-emerald-700 flex items-center justify-center"><Cpu className="w-5 h-5" /></div>
          <div className="min-w-0 flex-1"><h1 className="text-[18px] font-bold text-gray-900">CNC Settings</h1><p className="text-[10px] text-gray-500">Edits the existing migrated CNC Settings records used by the current CNC Builder.</p></div>
          <div className="hidden md:block text-right text-[10px] text-gray-500">Current machine rate<br /><b className="text-[14px] text-gray-900">${num(values.cnc_machine_rate).toFixed(2)}/hr</b></div>
        </div>

        {message && <div className="px-3 py-2 rounded border border-green-200 bg-green-50 text-[11px] text-green-700">{message}</div>}
        {error && <div className="px-3 py-2 rounded border border-red-200 bg-red-50 text-[11px] text-red-700">{error}</div>}

        <section className="bg-white border border-gray-200 rounded-md overflow-hidden">
          <SectionHeader icon={Calculator} title="CNC Machine Rate Calculator" subtitle="Legacy operational-cost calculator. Operator labor remains separate from machine cost." />
          <div className="grid lg:grid-cols-[minmax(0,1fr)_330px] gap-4 p-4">
            <div className="grid sm:grid-cols-2 gap-3">
              <SettingField label="Purchase price" suffix="$" value={values.cnc_purchase_price} onChange={(v) => patch("cnc_purchase_price", v)} />
              <SettingField label="Expected lifespan" suffix="years" value={values.cnc_lifespan_years} onChange={(v) => patch("cnc_lifespan_years", v)} />
              <SettingField label="Usage" suffix="hr/week" value={values.cnc_usage_hours_per_week} onChange={(v) => patch("cnc_usage_hours_per_week", v)} />
              <SettingField label="Annual maintenance" suffix="$/yr" value={values.cnc_annual_maintenance_cost} onChange={(v) => patch("cnc_annual_maintenance_cost", v)} />
              <SettingField label="Power consumption" suffix="kW" value={values.cnc_power_consumption_kw} onChange={(v) => patch("cnc_power_consumption_kw", v)} />
              <SettingField label="Tooling" suffix="$/hr" value={values.cnc_tooling_cost_per_hour} onChange={(v) => patch("cnc_tooling_cost_per_hour", v)} />
              <SettingField label="Electricity" suffix="$/kWh" value={values.electricity_cost_per_kwh} onChange={(v) => patch("electricity_cost_per_kwh", v)} />
              <SettingField label="Facility overhead" suffix="$/hr" value={values.facility_overhead_per_hour} onChange={(v) => patch("facility_overhead_per_hour", v)} />
              <SettingField label="Operator labor reference" suffix="$/hr" value={values.operator_cost_per_hour} onChange={(v) => patch("operator_cost_per_hour", v)} />
            </div>
            <div className="bg-gray-50 border border-gray-200 rounded p-4 self-start text-[11px] space-y-2">
              <RateRow label="Depreciation" value={rate.depreciation} />
              <RateRow label="Maintenance" value={rate.maintenance} />
              <RateRow label="Power" value={rate.power} />
              <RateRow label="Tooling" value={rate.tooling} />
              <RateRow label="Facility overhead" value={rate.overhead} />
              <RateRow label="Operator labor (excluded)" value={rate.operator} muted />
              <div className="border-t border-gray-300 pt-2 mt-2 flex items-center justify-between"><span className="font-bold text-gray-800">Calculated machine rate</span><span className="text-[18px] font-bold text-emerald-700">${rate.total.toFixed(2)}/hr</span></div>
              <Button type="button" variant="outline" onClick={() => patch("cnc_machine_rate", rate.total.toFixed(2))} className="h-[30px] w-full text-[11px] mt-2">Use Calculated Rate</Button>
              <p className="text-[9px] text-gray-400">This stages the calculated value in CNC Machine Rate. Click Save above to persist all changes together.</p>
            </div>
          </div>
        </section>

        <div className="grid lg:grid-cols-2 gap-4">
          <section className="bg-white border border-gray-200 rounded-md overflow-hidden">
            <SectionHeader icon={DollarSign} title="Rates & Labor" />
            <div className="p-4 grid sm:grid-cols-2 gap-3">
              <SettingField label="Machine rate" suffix="$/hr" value={values.cnc_machine_rate} onChange={(v) => patch("cnc_machine_rate", v)} />
              <SettingField label="Labor rate" suffix="$/hr" value={values.cnc_labor_rate} onChange={(v) => patch("cnc_labor_rate", v)} />
              <SettingField label="Setup time" suffix="% machine time" value={values.cnc_setup_time_percentage} onChange={(v) => patch("cnc_setup_time_percentage", v)} />
              <SettingField label="Fixed setup" suffix="hours/job" value={values.min_cnc_setup_hours} onChange={(v) => patch("min_cnc_setup_hours", v)} />
              <SettingField label="Minimum dynamic labor" suffix="hours/job" value={values.min_cnc_labor_hours} onChange={(v) => patch("min_cnc_labor_hours", v)} />
              <SettingField label="Letter perimeter factor" suffix="× height" value={values.cnc_letter_perimeter_factor} onChange={(v) => patch("cnc_letter_perimeter_factor", v)} />
            </div>
          </section>

          <section className="bg-white border border-gray-200 rounded-md overflow-hidden">
            <SectionHeader icon={Wrench} title="Material Cut-Time Multipliers" />
            <div className="p-4 grid sm:grid-cols-2 gap-3">
              {MATERIALS.map((material) => {
                const key = `${material.toLowerCase()}_cnc_cut_multiplier`;
                return <SettingField key={key} label={material} suffix="×" value={values[key]} onChange={(v) => patch(key, v)} />;
              })}
            </div>
          </section>
        </div>

        <section className="bg-white border border-gray-200 rounded-md overflow-hidden">
          <SectionHeader icon={Gauge} title="Default Cut Speed by Thickness" subtitle="Used when a CNC item thickness is selected. Units are inches per minute." />
          <div className="p-4 grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 lg:grid-cols-6 gap-3">
            {SIZES.map((size) => {
              const key = `cnc_cut_speed_${size.replaceAll("/", "_").replaceAll("-", "_")}`;
              return <SettingField key={key} label={`${size}\"`} suffix="in/min" value={values[key]} onChange={(v) => patch(key, v)} compact />;
            })}
          </div>
        </section>

        <div className="text-[10px] text-gray-400 pb-3">Loaded {rows.length} existing CNC/shared Settings records. Unused compatibility settings remain preserved and are not modified by this page.</div>
      </div>
    </div>
  );
}

function SectionHeader({ icon: Icon, title, subtitle }) {
  return <div className="px-4 py-2.5 bg-gray-50 border-b border-gray-200 flex items-start gap-2"><Icon className="w-3.5 h-3.5 text-gray-500 mt-0.5" /><div><div className="text-[11px] font-bold text-gray-700 uppercase tracking-wide">{title}</div>{subtitle && <div className="text-[9px] text-gray-500 mt-0.5">{subtitle}</div>}</div></div>;
}

function SettingField({ label, suffix, value, onChange, compact = false }) {
  return <label className="text-[10px] text-gray-500 min-w-0"><span className="block mb-1 truncate">{label}</span><div className="relative"><Input type="number" step="0.01" value={value ?? ""} onChange={(e) => onChange(e.target.value)} className={`h-[30px] text-[11px] ${suffix ? "pr-16" : ""} ${compact ? "px-2" : ""}`} />{suffix && <span className="absolute right-2 top-1/2 -translate-y-1/2 text-[9px] text-gray-400 pointer-events-none">{suffix}</span>}</div></label>;
}

function RateRow({ label, value, muted = false }) {
  return <div className={`flex items-center justify-between gap-3 ${muted ? "text-gray-400" : "text-gray-600"}`}><span>{label}</span><span className="font-mono font-semibold">${Number(value || 0).toFixed(2)}/hr</span></div>;
}

import { useEffect, useRef, useState } from "react";
import { Settings as SettingsEntity } from "@/entities/all";
import { Link } from "react-router-dom";
import { ArrowLeft, Hammer, RotateCcw, Save } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { saveSettingsRowsSafely } from "@/components/estimator/settings/settingsSaveGuard";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import SettingsTransferBar from "@/components/estimator/settings/SettingsTransferBar";
import { METAL_SETTINGS_DEFAULTS, resetValuesToDefaults } from "@/components/estimator/settings/moduleSettingDefaults";

const ACTIVE_KEYS = new Set(["metal_fabrication_rate", "metal_welding_rate", "metal_finishing_rate"]);

export default function MetalSettings() {
  const [rows, setRows] = useState([]);
  const [values, setValues] = useState({});
  const [original, setOriginal] = useState({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const settingsSaveRef = useRef(false);

  useEffect(() => {
    const load = async () => {
      try {
        const all = await loadAllEntityRows({ entity: SettingsEntity, sort: null, label: "Metal Settings catalog" });
        const relevant = (all || []).filter((row) => ACTIVE_KEYS.has(row.setting_name));
        const map = Object.fromEntries(relevant.map((row) => [row.setting_name, row.setting_value ?? ""]));
        setRows(relevant);
        setValues(map);
        setOriginal(map);
      } catch (e) {
        setError(e.message || "Could not load Metal settings.");
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  const patch = (key, value) => setValues((prev) => ({ ...prev, [key]: String(value) }));
  const dirtyCount = rows.filter((row) => String(values[row.setting_name] ?? "") !== String(original[row.setting_name] ?? "")).length;

  // #83 — stage every managed key back to the calculator's documented fallback.
  const handleResetDefaults = () => {
    setValues((prev) => resetValuesToDefaults(prev, METAL_SETTINGS_DEFAULTS, [...ACTIVE_KEYS]));
    setMessage("Defaults staged — click Save to persist them.");
  };

  const save = async () => {
    if (settingsSaveRef.current) return;
    settingsSaveRef.current = true;
    setSaving(true);
    setError("");
    setMessage("");
    try {
      const result = await saveSettingsRowsSafely({
        SettingsEntity,
        rows,
        values,
        originalValues: original,
      });
      setRows(result.rows);
      setOriginal(result.snapshot);
      setMessage(result.changedCount ? `Saved ${result.changedCount} Metal setting${result.changedCount === 1 ? "" : "s"}.` : "No Metal settings changed.");
    } catch (e) {
      setError(e.message || "Could not save Metal settings. Admin permission may be required.");
    } finally {
      settingsSaveRef.current = false;
      setSaving(false);
    }
  };

  if (loading) return <div className="p-10 text-center text-gray-400">Loading Metal settings…</div>;

  return (
    <div className="min-h-full bg-gray-50">
      <div className="max-w-3xl mx-auto p-4 sm:p-5 space-y-4">
        <div className="flex items-center justify-between gap-3">
          <Link to="/EstimatorSettings" className="inline-flex items-center gap-1 text-[12px] font-semibold text-gray-600 hover:text-gray-900"><ArrowLeft className="w-4 h-4" /> Estimator Settings</Link>
          <div className="flex items-center gap-2"><SettingsTransferBar values={values} allowedKeys={Object.keys(values)} fileName="metal-settings" onImport={(imported) => setValues((v) => ({ ...v, ...imported }))} /><Button variant="outline" onClick={handleResetDefaults} disabled={saving} className="h-[32px] text-[12px] font-semibold" title="Stage calculator fallback defaults — Save to persist"><RotateCcw className="w-4 h-4 mr-1.5" /> Reset to defaults</Button><Button onClick={save} disabled={saving || dirtyCount === 0} className="h-[32px] bg-[#454545] hover:bg-[#353535] text-white text-[12px] font-semibold disabled:opacity-50"><Save className="w-4 h-4 mr-1.5" /> {saving ? "Saving…" : `Save${dirtyCount ? ` (${dirtyCount})` : ""}`}</Button></div>
        </div>

        <div className="bg-white border border-gray-200 rounded-md px-4 py-3 flex items-center gap-3">
          <div className="w-9 h-9 rounded bg-orange-100 text-orange-700 flex items-center justify-center"><Hammer className="w-5 h-5" /></div>
          <div><h1 className="text-[18px] font-bold text-gray-900">Metal Fabrication Settings</h1><p className="text-[10px] text-gray-500">Global labor defaults used when a new Metal Builder Product is created.</p></div>
        </div>

        {message && <div className="px-3 py-2 rounded border border-green-200 bg-green-50 text-[11px] text-green-700">{message}</div>}
        {error && <div className="px-3 py-2 rounded border border-red-200 bg-red-50 text-[11px] text-red-700">{error}</div>}

        <section className="bg-white border border-gray-200 rounded-md overflow-hidden">
          <div className="px-4 py-2.5 bg-gray-50 border-b border-gray-200"><div className="text-[11px] font-bold text-gray-700 uppercase tracking-wide">Labor Rates</div><div className="text-[9px] text-gray-500 mt-0.5">These values seed new Metal projects. Existing saved projects retain their own rates until intentionally changed.</div></div>
          <div className="p-4 grid sm:grid-cols-3 gap-3">
            <Field label="Fabrication" suffix="$/hr" value={values.metal_fabrication_rate} onChange={(v) => patch("metal_fabrication_rate", v)} />
            <Field label="Welding" suffix="$/hr" value={values.metal_welding_rate} onChange={(v) => patch("metal_welding_rate", v)} />
            <Field label="Finishing" suffix="$/hr" value={values.metal_finishing_rate} onChange={(v) => patch("metal_finishing_rate", v)} />
          </div>
        </section>

        <div className="px-3 py-2.5 bg-amber-50 border border-amber-200 rounded text-[10px] text-amber-800">
          The migrated <code>weld_time_per_inch</code> compatibility setting is preserved but not shown here because the current Metal Builder prices welding from entered welding hours; it does not currently auto-calculate welding hours from weld length.
        </div>
      </div>
    </div>
  );
}

function Field({ label, suffix, value, onChange }) {
  return <label className="text-[10px] text-gray-500"><span className="block mb-1">{label}</span><div className="relative"><Input type="number" step="0.01" min="0" value={value ?? ""} onChange={(e) => onChange(e.target.value)} className="h-[30px] text-[11px] pr-14" /><span className="absolute right-2 top-1/2 -translate-y-1/2 text-[9px] text-gray-400">{suffix}</span></div></label>;
}

import { useEffect, useMemo, useRef, useState } from "react";
import { MaintenanceActionRate, Settings as SettingsEntity } from "@/entities/all";
import { Link } from "react-router-dom";
import { ArrowLeft, Clock, DollarSign, Info, MapPin, Package, RotateCcw, Save, Wrench } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import RatesBySignTypeTab from "@/components/signMaintenance/RatesBySignTypeTab";
import TravelTab from "@/components/signMaintenance/TravelTab";
import MinimumsTab from "@/components/signMaintenance/MinimumsTab";
import SiteConditionsTab from "@/components/signMaintenance/SiteConditionsTab";
import MaintenanceMaterialRulesTab from "@/components/signMaintenance/MaintenanceMaterialRulesTab";
import { preflightSettingsRows } from "@/components/estimator/settings/settingsSaveGuard";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { expectedEntityFields, replaceEntityFieldsIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";
import { createMaintenanceActionRateIfAbsent } from "@/components/signMaintenance/maintenanceActionRatePersistence";
import SettingsTransferBar from "@/components/estimator/settings/SettingsTransferBar";
import { MAINTENANCE_SETTINGS_DEFAULTS, resetValuesToDefaults } from "@/components/estimator/settings/moduleSettingDefaults";

const LABOR_FIELDS = [
  { key: "maintenance_crew_lead_rate", label: "Crew Lead", suffix: "$/hr" },
  { key: "maintenance_tech_rate", label: "Service Tech", suffix: "$/hr" },
  { key: "maintenance_helper_rate", label: "Helper", suffix: "$/hr" },
];

const RATE_FIELDS = [
  "rate_basis", "is_enabled",
  "base_minutes_xs", "base_minutes_s", "base_minutes_m", "base_minutes_l", "base_minutes_xl", "base_minutes_xxl",
  "base_minutes_cab_s", "base_minutes_cab_m", "base_minutes_cab_l", "base_minutes_cab_xl", "base_minutes_flat",
];

const comparableRate = (row = {}) => Object.fromEntries(RATE_FIELDS.map((field) => [field, row[field] ?? null]));
const sameRate = (a, b) => JSON.stringify(comparableRate(a)) === JSON.stringify(comparableRate(b));
const loadAllSettings = () => loadAllEntityRows({ entity: SettingsEntity, sort: "created_date", label: "Estimator Settings" });
const loadAllMaintenanceRates = () => loadAllEntityRows({ entity: MaintenanceActionRate, sort: "created_date", label: "Maintenance action rates" });

export default function MaintenanceSettings() {
  const [settingsRows, setSettingsRows] = useState([]);
  const [globalSettings, setGlobalSettings] = useState({});
  const [originalSettings, setOriginalSettings] = useState({});
  const [rates, setRates] = useState([]);
  const [originalRates, setOriginalRates] = useState(new Map());
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const settingsSaveRef = useRef(false);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      setError("");
      try {
        const [allSettings, allRates] = await Promise.all([
          loadAllSettings(),
          loadAllMaintenanceRates(),
        ]);
        const maintenanceRows = (allSettings || []).filter((row) => String(row.setting_name || "").startsWith("maintenance_"));
        const settingsMap = Object.fromEntries(maintenanceRows.map((row) => [row.setting_name, row.setting_value ?? ""]));
        setSettingsRows(maintenanceRows);
        setGlobalSettings(settingsMap);
        setOriginalSettings(settingsMap);
        setRates(allRates || []);
        setOriginalRates(new Map((allRates || []).map((row) => [`${row.sign_type}|${row.action}`, structuredClone(row)])));
      } catch (e) {
        setError(e.message || "Could not load Maintenance settings.");
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  const rateMap = useMemo(() => {
    const map = new Map();
    rates.forEach((row) => map.set(`${row.sign_type}|${row.action}`, row));
    return map;
  }, [rates]);

  const changedSettingRows = useMemo(
    () => settingsRows.filter((row) => String(globalSettings[row.setting_name] ?? "") !== String(originalSettings[row.setting_name] ?? "")),
    [settingsRows, globalSettings, originalSettings]
  );

  const changedRateRows = useMemo(
    () => rates.filter((row) => {
      const original = originalRates.get(`${row.sign_type}|${row.action}`);
      return !original || !sameRate(row, original);
    }),
    [rates, originalRates]
  );

  const dirtyCount = changedSettingRows.length + changedRateRows.length;

  const changeRate = (signTypeId, actionId, patch) => {
    setRates((prev) => {
      const index = prev.findIndex((row) => row.sign_type === signTypeId && row.action === actionId);
      if (index < 0) {
        // Do not pre-seed unsupported or absent combinations. If a valid current
        // UI combination is ever genuinely missing, only create it after the user
        // explicitly edits that combination and saves this page.
        return [...prev, { sign_type: signTypeId, action: actionId, ...patch }];
      }
      const next = [...prev];
      next[index] = { ...next[index], ...patch };
      return next;
    });
  };

  // #83 — stage the managed keys that have documented calculator fallbacks
  // back to their defaults (chained install_* overrides are left untouched).
  const handleResetDefaults = () => {
    setGlobalSettings((prev) => resetValuesToDefaults(prev, MAINTENANCE_SETTINGS_DEFAULTS, Object.keys(MAINTENANCE_SETTINGS_DEFAULTS)));
    setMessage("Defaults staged — click Save to persist them.");
  };

  const saveAll = async () => {
    if (dirtyCount === 0 || settingsSaveRef.current) return;
    settingsSaveRef.current = true;
    setSaving(true);
    setMessage("");
    setError("");
    try {
      // Preflight Settings and the rate matrix before the first write so an older
      // admin browser cannot silently overwrite newer pricing/labor configuration.
      const settingsPreflight = await preflightSettingsRows({
        SettingsEntity,
        rows: settingsRows,
        values: globalSettings,
        originalValues: originalSettings,
        changedRows: changedSettingRows,
      });
      const liveSettingsById = new Map((settingsPreflight.liveRows || []).map((row) => [row.id, row]));

      const liveRates = await loadAllMaintenanceRates();
      const liveById = new Map((liveRates || []).filter((row) => row.id).map((row) => [row.id, row]));
      const liveByKey = new Map((liveRates || []).map((row) => [`${row.sign_type}|${row.action}`, row]));
      const existingRateConflicts = changedRateRows.filter((row) => {
        if (!row.id) return false;
        const key = `${row.sign_type}|${row.action}`;
        const loaded = originalRates.get(key);
        const live = liveById.get(row.id);
        if (!loaded || !live) return true;
        const versionChanged = !!(loaded.updated_date && live.updated_date && loaded.updated_date !== live.updated_date);
        return versionChanged || !sameRate(live, loaded);
      });
      const appearedRateRows = changedRateRows.filter((row) => !row.id && liveByKey.has(`${row.sign_type}|${row.action}`));
      if (existingRateConflicts.length || appearedRateRows.length) {
        const keys = [...existingRateConflicts, ...appearedRateRows].map((row) => `${row.sign_type}/${row.action}`).join(", ");
        throw new Error(`These Maintenance action rates changed in another session: ${keys}. Reload this page, review the latest values, and apply your changes again.`);
      }

      // Create genuinely missing, explicitly edited rate rows first. The helper
      // converges lost responses and removes only this save's identifiable losing
      // duplicate when another admin creates the same sign-type/action key.
      for (const row of changedRateRows.filter((item) => !item.id)) {
        const payload = { sign_type: row.sign_type, action: row.action, ...comparableRate(row) };
        const result = await createMaintenanceActionRateIfAbsent({
          entity: MaintenanceActionRate,
          payload,
          label: `Maintenance action rate ${row.sign_type}/${row.action}`,
        });
        if (result.status === "existing" || result.status === "concurrent_duplicate_discarded") {
          throw new Error(`The Maintenance action rate ${row.sign_type}/${row.action} was created concurrently in another session. Reload and review the canonical row before saving again.`);
        }
      }

      let confirmedWrites = changedRateRows.filter((item) => !item.id).length;
      const totalWrites = changedSettingRows.length + changedRateRows.length;
      for (const row of changedSettingRows) {
        const live = liveSettingsById.get(row.id);
        const desired = { setting_value: String(globalSettings[row.setting_name] ?? "") };
        try {
          await replaceEntityFieldsIfUnchanged({
            entity: SettingsEntity,
            id: row.id,
            expectedUpdatedAt: live?.updated_date || "",
            expectedFields: expectedEntityFields(live || {}, desired),
            nextFields: desired,
            label: `Maintenance setting ${row.setting_name}`,
          });
          confirmedWrites += 1;
        } catch (error) {
          throw new Error(`Maintenance settings save stopped after ${confirmedWrites} of ${totalWrites} required writes were confirmed. Reload before retrying; remaining rows were not skipped automatically. ${error?.message || ""}`.trim());
        }
      }
      for (const row of changedRateRows.filter((item) => item.id)) {
        const live = liveById.get(row.id);
        const desired = {
          sign_type: row.sign_type,
          action: row.action,
          ...comparableRate(row),
        };
        try {
          await replaceEntityFieldsIfUnchanged({
            entity: MaintenanceActionRate,
            id: row.id,
            expectedUpdatedAt: live?.updated_date || "",
            expectedFields: expectedEntityFields(live || {}, desired),
            nextFields: desired,
            label: `Maintenance action rate ${row.sign_type}/${row.action}`,
          });
          confirmedWrites += 1;
        } catch (error) {
          throw new Error(`Maintenance settings save stopped after ${confirmedWrites} of ${totalWrites} required writes were confirmed. Reload before retrying; remaining rows were not skipped automatically. ${error?.message || ""}`.trim());
        }
      }

      const [freshSettings, freshRates] = await Promise.all([loadAllSettings(), loadAllMaintenanceRates()]);
      const freshSettingsById = new Map((freshSettings || []).filter((row) => row.id).map((row) => [row.id, row]));
      const freshRatesById = new Map((freshRates || []).filter((row) => row.id).map((row) => [row.id, row]));
      const settingVerificationFailures = changedSettingRows.filter((row) => {
        const current = freshSettingsById.get(row.id);
        return !current || String(current.setting_value ?? "") !== String(globalSettings[row.setting_name] ?? "");
      });
      const rateVerificationFailures = changedRateRows.filter((row) => {
        if (row.id) {
          const current = freshRatesById.get(row.id);
          return !current || current.sign_type !== row.sign_type || current.action !== row.action || !sameRate(current, row);
        }
        const matches = (freshRates || []).filter((item) => item.sign_type === row.sign_type && item.action === row.action);
        return matches.length !== 1 || !sameRate(matches[0], row);
      });
      if (settingVerificationFailures.length || rateVerificationFailures.length) {
        const names = [
          ...settingVerificationFailures.map((row) => row.setting_name),
          ...rateVerificationFailures.map((row) => `${row.sign_type}/${row.action}`),
        ];
        throw new Error(`Maintenance settings final verification found concurrent or incomplete changes: ${names.join(", ")}. Reload and review before saving again.`);
      }
      const maintenanceRows = (freshSettings || []).filter((row) => String(row.setting_name || "").startsWith("maintenance_"));
      const settingsMap = Object.fromEntries(maintenanceRows.map((row) => [row.setting_name, row.setting_value ?? ""]));
      setSettingsRows(maintenanceRows);
      setGlobalSettings(settingsMap);
      setOriginalSettings(settingsMap);
      setRates(freshRates || []);
      setOriginalRates(new Map((freshRates || []).map((row) => [`${row.sign_type}|${row.action}`, structuredClone(row)])));
      setMessage(`Saved ${dirtyCount} Maintenance change${dirtyCount === 1 ? "" : "s"}.`);
    } catch (e) {
      // Reload both stores after any failure so a retry never starts from a
      // partially stale browser snapshot.
      try {
        const [freshSettings, freshRates] = await Promise.all([loadAllSettings(), loadAllMaintenanceRates()]);
        const maintenanceRows = (freshSettings || []).filter((row) => String(row.setting_name || "").startsWith("maintenance_"));
        const settingsMap = Object.fromEntries(maintenanceRows.map((row) => [row.setting_name, row.setting_value ?? ""]));
        setSettingsRows(maintenanceRows);
        setGlobalSettings(settingsMap);
        setOriginalSettings(settingsMap);
        setRates(freshRates || []);
        setOriginalRates(new Map((freshRates || []).map((row) => [`${row.sign_type}|${row.action}`, structuredClone(row)])));
      } catch (reloadError) {
        console.error("Maintenance settings reload after save failure also failed:", reloadError);
      }
      setError(e.message || "Could not save Maintenance settings. Admin permission may be required.");
    } finally {
      settingsSaveRef.current = false;
      setSaving(false);
    }
  };

  if (loading) return <div className="p-10 text-center text-gray-400">Loading Maintenance settings…</div>;

  return (
    <div className="min-h-full bg-gray-50">
      <div className="max-w-[1280px] mx-auto p-4 sm:p-5 space-y-4">
        <div className="flex items-center justify-between gap-3">
          <Link to="/EstimatorSettings" className="inline-flex items-center gap-1 text-[12px] font-semibold text-gray-600 hover:text-gray-900"><ArrowLeft className="w-4 h-4" /> Estimator Settings</Link>
          <div className="flex items-center gap-2"><SettingsTransferBar values={globalSettings} allowedKeys={Object.keys(globalSettings)} fileName="maintenance-settings" onImport={(imported) => setGlobalSettings((v) => ({ ...v, ...imported }))} /><Button variant="outline" onClick={handleResetDefaults} disabled={saving} className="h-[32px] text-[12px] font-semibold" title="Stage calculator fallback defaults — Save to persist"><RotateCcw className="w-4 h-4 mr-1.5" /> Reset to defaults</Button><Button onClick={saveAll} disabled={saving || dirtyCount === 0} className="h-[32px] bg-[#454545] hover:bg-[#353535] text-white text-[12px] font-semibold disabled:opacity-50"><Save className="w-4 h-4 mr-1.5" /> {saving ? "Saving…" : `Save${dirtyCount ? ` (${dirtyCount})` : ""}`}</Button></div>
        </div>

        <div className="bg-white border border-gray-200 rounded-md px-4 py-3 flex items-center gap-3">
          <div className="w-9 h-9 rounded bg-teal-100 text-teal-700 flex items-center justify-center"><Wrench className="w-5 h-5" /></div>
          <div className="min-w-0 flex-1">
            <h1 className="text-[18px] font-bold text-gray-900">Sign Maintenance Settings</h1>
            <p className="text-[10px] text-gray-500">Edits the existing Maintenance Settings and the persisted 123-row sign-type/action labor matrix. Opening this page does not create records.</p>
          </div>
          <div className="hidden md:block text-right text-[10px] text-gray-500">Action-rate rows<br /><b className="text-[14px] text-gray-900">{rates.length}</b></div>
        </div>

        {message && <div className="px-3 py-2 rounded border border-green-200 bg-green-50 text-[11px] text-green-700">{message}</div>}
        {error && <div className="px-3 py-2 rounded border border-red-200 bg-red-50 text-[11px] text-red-700">{error}</div>}

        <Tabs defaultValue="rates" className="space-y-4">
          <TabsList className="grid grid-cols-2 md:grid-cols-6 h-auto bg-white border border-gray-200 p-1">
            <TabsTrigger value="rates" className="text-[11px] py-2"><Clock className="w-3.5 h-3.5 mr-1.5" /> Action Rates</TabsTrigger>
            <TabsTrigger value="materials" className="text-[11px] py-2"><Package className="w-3.5 h-3.5 mr-1.5" /> Material Rules</TabsTrigger>
            <TabsTrigger value="labor" className="text-[11px] py-2"><DollarSign className="w-3.5 h-3.5 mr-1.5" /> Labor</TabsTrigger>
            <TabsTrigger value="travel" className="text-[11px] py-2"><MapPin className="w-3.5 h-3.5 mr-1.5" /> Travel</TabsTrigger>
            <TabsTrigger value="minimums" className="text-[11px] py-2">Minimums</TabsTrigger>
            <TabsTrigger value="site" className="text-[11px] py-2">Site Conditions</TabsTrigger>
          </TabsList>

          <TabsContent value="rates" className="mt-0">
            <RatesBySignTypeTab
              rateMap={rateMap}
              isLocked={false}
              onChangeRate={changeRate}
              globalSettings={globalSettings}
              setGlobalSettings={setGlobalSettings}
            />
          </TabsContent>

          <TabsContent value="materials" className="mt-0">
            <MaintenanceMaterialRulesTab />
          </TabsContent>

          <TabsContent value="labor" className="mt-0">
            <section className="bg-white border border-gray-200 rounded-xl overflow-hidden">
              <div className="px-4 py-3 bg-gray-50 border-b border-gray-200">
                <div className="text-[11px] font-bold uppercase tracking-wide text-gray-700">Active Labor Rates</div>
                <div className="text-[10px] text-gray-500 mt-0.5">Service Tech drives action labor. Crew Lead / Helper are used by the Personnel selector.</div>
              </div>
              <div className="p-4 grid sm:grid-cols-3 gap-4">
                {LABOR_FIELDS.map((field) => <Field key={field.key} {...field} value={globalSettings[field.key]} onChange={(value) => setGlobalSettings((prev) => ({ ...prev, [field.key]: value }))} />)}
              </div>
            </section>
          </TabsContent>

          <TabsContent value="travel" className="mt-0">
            <TravelTab globalSettings={globalSettings} setGlobalSettings={setGlobalSettings} isLocked={false} />
          </TabsContent>

          <TabsContent value="minimums" className="mt-0 space-y-3">
            <InactiveNotice text="These migrated minimum-hour values are preserved in Settings, but the current Maintenance calculation engine does not apply them yet. They are shown read-only so they are not mistaken for active pricing controls." />
            <MinimumsTab globalSettings={globalSettings} setGlobalSettings={setGlobalSettings} isLocked />
          </TabsContent>

          <TabsContent value="site" className="mt-0 space-y-3">
            <InactiveNotice text="These migrated site-condition adjustments are preserved, but the current Maintenance service-item model does not currently collect/apply these conditions. They remain read-only until that workflow is deliberately integrated." />
            <SiteConditionsTab globalSettings={globalSettings} setGlobalSettings={setGlobalSettings} isLocked />
          </TabsContent>
        </Tabs>

        <div className="text-[10px] text-gray-400 pb-3">Loaded {settingsRows.length} Maintenance Settings records and {rates.length} MaintenanceActionRate records. Only changed, editable records are written on Save.</div>
      </div>
    </div>
  );
}

function Field({ label, suffix, value, onChange }) {
  return <label className="text-[10px] text-gray-500"><span className="block mb-1">{label}</span><div className="relative"><Input type="number" step="0.01" min="0" value={value ?? ""} onChange={(e) => onChange(e.target.value)} className="h-[32px] text-[11px] pr-14" /><span className="absolute right-2 top-1/2 -translate-y-1/2 text-[9px] text-gray-400">{suffix}</span></div></label>;
}

function InactiveNotice({ text }) {
  return <div className="px-3 py-2.5 rounded border border-amber-200 bg-amber-50 text-[10px] text-amber-800 flex gap-2"><Info className="w-4 h-4 flex-shrink-0 mt-0.5" /><span>{text}</span></div>;
}

