import { useState, useEffect, useRef } from "react";
import { Input } from "@/components/ui/input";
import { MapPin, Loader2 } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { ESTIMATOR_AI_MODEL } from "../../../base44/shared/estimatorAiModelPolicy.js";
import { getSessionToken } from "@/components/auth/EmailGate";

const SCHEMA = {
  type: "object",
  properties: {
    suggestions: {
      type: "array",
      items: {
        type: "object",
        properties: {
          full_address: { type: "string", description: "Complete formatted address: street, city, state, zip" },
          label: { type: "string", description: "Short display label (street + city)" }
        },
        required: ["full_address"]
      }
    }
  }
};

export default function AddressAutocomplete({ value, onChange, placeholder, className, id }) {
  const [query, setQuery] = useState(value || "");
  const [suggestions, setSuggestions] = useState([]);
  const [loading, setLoading] = useState(false);
  const [open, setOpen] = useState(false);
  const [highlight, setHighlight] = useState(-1);
  const debounceRef = useRef(null);
  const containerRef = useRef(null);
  const lastFetchedRef = useRef("");

  // Keep local query in sync if parent changes value externally
  useEffect(() => {
    setQuery(value || "");
  }, [value]);

  // Close on outside click
  useEffect(() => {
    const handler = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) {
        setOpen(false);
      }
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, []);

  const fetchSuggestions = async (q) => {
    if (!q || q.trim().length < 4) {
      setSuggestions([]);
      return;
    }
    if (lastFetchedRef.current === q) return;
    lastFetchedRef.current = q;
    setLoading(true);
    const llmFallback = async () => {
      const llm = await base44.integrations.Core.InvokeLLM({
        prompt: `Return up to 5 plausible US street-address autocomplete completions for: "${q}".
Each must look like a real mailing address (street number + street, city, state abbr, ZIP).
Prefer well-known streets/cities. Be FAST — do not search the web. JSON only.`,
        response_json_schema: SCHEMA,
        model: ESTIMATOR_AI_MODEL
      });
      return llm?.suggestions || [];
    };
    let list = null;
    try {
      // Primary: real Google Places autocomplete (backend proxy).
      const res = await base44.functions.invoke("placesAutocomplete", {
        input: q,
        session_token: getSessionToken(),
      });
      list = res?.data?.suggestions || null;
    } catch (e) {
      list = null;
    }
    if (!list) list = await llmFallback().catch(() => []);
    setSuggestions(list);
    setOpen(true);
    setHighlight(-1);
    setLoading(false);
  };

  const handleInput = (e) => {
    const v = e.target.value;
    setQuery(v);
    onChange(v);
    setOpen(true);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => fetchSuggestions(v), 250);
  };

  const selectSuggestion = (s) => {
    const addr = s.full_address;
    setQuery(addr);
    onChange(addr);
    setSuggestions([]);
    setOpen(false);
  };

  const handleKeyDown = (e) => {
    if (!open || suggestions.length === 0) return;
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setHighlight((h) => Math.min(h + 1, suggestions.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setHighlight((h) => Math.max(h - 1, 0));
    } else if (e.key === "Enter" && highlight >= 0) {
      e.preventDefault();
      selectSuggestion(suggestions[highlight]);
    } else if (e.key === "Escape") {
      setOpen(false);
    }
  };

  return (
    <div ref={containerRef} className={`relative ${className || ""}`}>
      <Input
        id={id}
        value={query}
        onChange={handleInput}
        onFocus={() => suggestions.length > 0 && setOpen(true)}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
        autoComplete="off"
      />
      {loading && (
        <Loader2 className="absolute right-2 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-400 animate-spin" />
      )}
      {open && suggestions.length > 0 && (
        <div className="absolute left-0 right-0 top-full mt-1 z-50 bg-white border border-slate-200 rounded-lg shadow-lg overflow-hidden max-h-72 overflow-y-auto">
          {suggestions.map((s, i) => (
            <button type="button"
              key={i}
              type="button"
              onMouseDown={(e) => { e.preventDefault(); selectSuggestion(s); }}
              onMouseEnter={() => setHighlight(i)}
              className={`w-full text-left px-3 py-2 text-sm flex items-start gap-2 transition-colors ${
                highlight === i ? "bg-purple-50" : "hover:bg-slate-50"
              }`}
            >
              <MapPin className="w-3.5 h-3.5 text-purple-600 mt-0.5 flex-shrink-0" />
              <span className="min-w-0">
                <span className="block text-slate-800 truncate">{s.label || s.full_address}</span>
                {s.secondary && <span className="block text-xs text-slate-500 truncate">{s.secondary}</span>}
              </span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

import React, { useState } from "react";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Checkbox } from "@/components/ui/checkbox";
import { Button } from "@/components/ui/button";
import { ChevronDown } from "lucide-react";

const OPTIONS = [
  { value: "flush_mount", label: "Flush Mount" },
  { value: "halo_lit", label: "Halo-Lit" },
  { value: "raceway", label: "Raceway" },
  { value: "dimensional_lettering", label: "Dimensional Lettering" },
];

// Multi-select dropdown for the "Applies To" field on inventory items.
// Empty array means "applies to all".
export default function AppliesToMultiSelect({ value, onChange }) {
  const [open, setOpen] = useState(false);
  const list = Array.isArray(value) ? value : [];

  const toggle = (v) => {
    if (list.includes(v)) onChange(list.filter(x => x !== v));
    else onChange([...list, v]);
  };

  const summary = list.length === 0
    ? "All"
    : list.length === OPTIONS.length
      ? "All"
      : list.map(v => OPTIONS.find(o => o.value === v)?.label || v).join(", ");

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          className="h-8 w-full justify-between font-normal text-xs px-2 mt-0.5"
        >
          <span className="truncate">{summary}</span>
          <ChevronDown className="w-3.5 h-3.5 opacity-60 flex-shrink-0" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-56 p-2" align="start">
        <div className="space-y-1">
          {OPTIONS.map(opt => (
            <label
              key={opt.value}
              className="flex items-center gap-2 px-2 py-1.5 rounded hover:bg-slate-50 cursor-pointer text-sm"
            >
              <Checkbox
                checked={list.includes(opt.value)}
                onCheckedChange={() => toggle(opt.value)}
              />
              <span>{opt.label}</span>
            </label>
          ))}
          <div className="border-t pt-1 mt-1">
            <button
              type="button"
              onClick={() => onChange([])}
              className="text-xs text-slate-500 hover:text-slate-700 px-2 py-1"
            >
              Clear (apply to all)
            </button>
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
}

import React, { useEffect, useRef } from "react";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

/**
 * AutoGrowNotes — a textarea that grows in height to fit its content.
 * Used inline next to small numeric fields where the user wants to leave
 * a free-form note about how/why that value was set.
 *
 * Resize approach: reset height to 'auto' before reading scrollHeight so the
 * textarea can SHRINK as well as grow.
 */
export default function AutoGrowNotes({
  value,
  onChange,
  disabled,
  placeholder = "Notes…",
  className,
  minHeightPx = 36,
}) {
  const ref = useRef(null);

  const resize = () => {
    const el = ref.current;
    if (!el) return;
    el.style.height = "auto";
    const next = Math.max(minHeightPx, el.scrollHeight);
    el.style.height = `${next}px`;
  };

  // Resize on value change (e.g. when settings load from DB) and on mount.
  useEffect(() => {
    resize();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value]);

  return (
    <Textarea
      ref={ref}
      rows={1}
      value={value || ""}
      placeholder={placeholder}
      disabled={disabled}
      onChange={(e) => {
        onChange(e.target.value);
        resize();
      }}
      onInput={resize}
      className={cn(
        "resize-none overflow-hidden leading-snug py-1.5 px-2 text-xs bg-white border-slate-200 focus:border-slate-400 focus:ring-0 transition-colors",
        className
      )}
      style={{ minHeight: `${minHeightPx}px` }}
    />
  );
}

