              <div className="flex justify-between items-center">
                <span className="text-sm text-slate-300">Total ({purchase?.qty || 1} letters)</span>
                <span className="text-2xl font-bold tabular-nums">{fmt(computed.unit_total_cost * (parseFloat(purchase?.qty) || 1))}</span>
              </div>
            </div>
          </div>
        )}

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button>
          <Button onClick={handleSave} className="bg-emerald-600 hover:bg-emerald-700 text-white">
            <Sparkles className="w-4 h-4 mr-1" /> Apply Fab Cost
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

const Section = ({ icon: Icon, title, color, children }) => (
  <div className="border border-slate-200 rounded-xl p-3 space-y-3 bg-white">
    <div className="flex items-center gap-2">
      <div className={`w-7 h-7 rounded-lg ${color} flex items-center justify-center`}>
        <Icon className="w-4 h-4" />
      </div>
      <span className="font-semibold text-slate-800 text-sm">{title}</span>
    </div>
    {children}
  </div>
);

const PreviewRow = ({ label, value, subtitle }) => (
  <div className="flex justify-between items-center text-sm">
    <div>
      <span className="text-slate-300">{label}</span>
      {subtitle && <span className="ml-2 text-[10px] text-slate-500">{subtitle}</span>}
    </div>
    <span className="tabular-nums font-medium">{fmt(value)}</span>
  </div>
);

import { useState, useEffect, useMemo, useCallback } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import {
  Box, Paintbrush, Calculator, AlertCircle,
  Link as LinkIcon, RefreshCw, Router, Zap, Trash2, Search,
} from "lucide-react";
import { Link } from "react-router-dom";
import { createPageUrl } from "@/utils";
import { DimensionalLetterMaterial, Settings as SettingsEntity } from "@/api/gatedEntities";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import {
  calcDimensionalUnitCost,
  materialCostPerSqin,
  emptyFabConfig,
  getActiveRates,
  getPaintRates,
  lookupCutSpeed,
  lookupCutMultiplier,
  PAINT_SIDES_LABELS,
  CUTTING_METHOD_LABELS,
} from "./dimensionalFabCalculator";
import CuttingMethodSlider from "./CuttingMethodSlider";
import PaintCoverageHelper from "./PaintCoverageHelper";
import { estimateAverageLetterWidth } from "./letterWidthCalculator";
import DimensionalMaterialPickerDialog from "./DimensionalMaterialPickerDialog";
import { channelDraftValue } from "./channelLetterPricingAvailability";

const fmt = (v) => (Number.isFinite(v) ? `$${v.toFixed(2)}` : "—");

/**
 * Inline replacement for DimensionalFabModal.
 * Renders all material + cutting + paint controls directly on the row.
 * Removed (per request): Thickness, Cut Length Override, Cut Speed, Setup Time, Material Cut Multiplier.
 * Thickness is shown in the Sheet Material picker (read-only inline display).
 * Cutting method is a segmented slider (CNC | Laser).
 * Paint mask + Approx Coverage Helper appear when multi-color is used.
 */
export default function DimensionalFabPanel({ purchase, onUpdate, onReset }) {
  const [materials, setMaterials] = useState([]);
  const [settings, setSettings] = useState({});
  const [fab, setFab] = useState(() => ({ ...emptyFabConfig(), ...(purchase?.fab_config || {}) }));
  const [loading, setLoading] = useState(true);
  const [pickerOpen, setPickerOpen] = useState(false);

  const loadSettings = useCallback(async () => {
    try {
      const list = await loadAllEntityRows({ entity: SettingsEntity, sort: "created_date", label: "Estimator Settings" });
      const map = {};
      list.forEach((s) => { map[s.setting_name] = s.setting_value; });
      setSettings(map);
      return map;
    } catch (e) {
      console.error("Failed to load settings:", e);
      return {};
    }
  }, []);

  useEffect(() => {
    (async () => {
      setLoading(true);
      try {
        const [mats] = await Promise.all([
          loadAllEntityRows({ entity: DimensionalLetterMaterial, query: { is_active: true }, sort: "sort_order", label: "Dimensional Letter materials" }),
          loadSettings(),
        ]);
        setMaterials(mats);

        const seed = { ...emptyFabConfig(), ...(purchase?.fab_config || {}) };
        // back-compat
        if (seed.cnc_cut_speed_ipm && !seed.cut_speed_ipm) seed.cut_speed_ipm = seed.cnc_cut_speed_ipm;
        // width_override defaults to false — width is auto-calculated unless toggled on
        if (seed.width_override === undefined) seed.width_override = false;
        setFab(seed);
      } catch (e) {
        console.error("Failed to load fab inputs:", e);
      }
      setLoading(false);
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [purchase?.id]);

  const update = (patch) => setFab((prev) => ({ ...prev, ...patch }));

  // Currently-selected material record (used to gate laser availability)
  const selectedMaterial = useMemo(
    () => materials.find((x) => x.id === fab.material_id) || null,
    [materials, fab.material_id]
  );
  const laserDisallowed = selectedMaterial ? selectedMaterial.allow_laser === false : false;

  // When material changes, refresh thickness + per-sqin cost + auto-cut params.
  // If the new material disallows laser and the current method is laser, force CNC.
  const selectMaterial = (id) => {
    const m = materials.find((x) => x.id === id);
    if (!m) return;
    const matType = m.material_type || "";
    const forceCnc = m.allow_laser === false && fab.cutting_method === "laser";
    const nextMethod = forceCnc ? "cnc" : fab.cutting_method;
    const speedFromSettings = lookupCutSpeed(nextMethod, m.thickness_inches, settings);
    const multiplierFromSettings = lookupCutMultiplier(nextMethod, matType, settings);
    setFab((prev) => ({
      ...prev,
      material_id: m.id,
      material_name: m.material_name,
      material_type: matType,
      material_thickness_inches: m.thickness_inches,
      material_cost_per_sqin: materialCostPerSqin(m),
      sheet_yield_factor: m.yield_factor,
      paint_letters: !!m.needs_painting,
      cutting_method: nextMethod,
      cut_speed_ipm: speedFromSettings ?? prev.cut_speed_ipm,
      cut_multiplier: multiplierFromSettings,
    }));
  };

  const setCuttingMethod = (method) => {
    if (method === "laser" && laserDisallowed) return; // hard-gate

    const speedFromSettings = lookupCutSpeed(method, fab.material_thickness_inches, settings);
    const multiplierFromSettings = lookupCutMultiplier(method, fab.material_type, settings);
    setFab((prev) => ({
      ...prev,
      cutting_method: method,
      cut_speed_ipm: speedFromSettings ?? prev.cut_speed_ipm,
      cut_multiplier: multiplierFromSettings,
    }));
  };

  const qty = parseFloat(purchase?.qty) || 1;
  const computed = useMemo(() => calcDimensionalUnitCost(fab, qty, settings), [fab, qty, settings]);
  const activeRates = useMemo(() => getActiveRates(fab.cutting_method, settings), [fab.cutting_method, settings]);
  const paintR = useMemo(() => getPaintRates(settings), [settings]);

  // Persist whenever fab changes (debounced via effect — only after first load).
  // We DO NOT touch unit_cost_override here — the user controls that via the
  // override checkbox on the Per-Letter Cost field. The dimensional pricing
  // path in lettersCalculator reads fab_config.unit_total_cost directly when
  // unit_cost_override is false.
  useEffect(() => {
    if (loading) return;
    const final = calcDimensionalUnitCost(fab, qty, settings);
    onUpdate({
      fab_config: {
        material_id: final.material_id,
        material_name: final.material_name,
        material_type: final.material_type,
        material_thickness_inches: final.material_thickness_inches,
        material_cost_per_sqin: final.material_cost_per_sqin,
        sheet_yield_factor: final.sheet_yield_factor,
        letter_height_inches: final.letter_height_inches,
        letter_width_inches: final.letter_width_inches,
        width_override: !!fab.width_override,
        letter_perimeter_inches: final.letter_perimeter_inches,
        cutting_method: final.cutting_method,
        cut_speed_ipm: final.cut_speed_ipm,
        cut_multiplier: final.cut_multiplier,
        paint_letters: final.paint_letters,
        paint_sides: final.paint_sides,
        num_paint_colors: final.num_paint_colors,
        paint_colors: final.paint_colors || [],
        paint_mask_sqft: final.paint_mask_sqft || 0,
        approx_coverage_factor: final.approx_coverage_factor || "1/4",
        unit_material_cost: final.unit_material_cost,
        unit_cut_cost: final.unit_cut_cost,
        unit_paint_cost: final.unit_paint_cost,
        unit_total_cost: final.unit_total_cost,
      },
      size_value: (final.face_area_sqin || 1) / 144,
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fab, qty, settings, loading]);

  const isLaser = fab.cutting_method === "laser";
  const cutSettingsPage = "EstimatorSettings";

  // Face area in sqft for mask helper
  const faceAreaSqft = (computed.face_area_sqin || 0) / 144;
  const paintColors = Array.isArray(fab.paint_colors) ? fab.paint_colors : [];
  const numColors = paintColors.length || fab.num_paint_colors || 1;

  const updateColor = (idx, val) => {
    const list = [...paintColors];
    list[idx] = val;
    update({ paint_colors: list, num_paint_colors: list.length });
  };
  const addColor = () => {
    const list = [...paintColors, ""];
    update({ paint_colors: list, num_paint_colors: list.length });
  };
  const removeColor = (idx) => {
    const list = paintColors.filter((_, i) => i !== idx);
    update({ paint_colors: list, num_paint_colors: Math.max(1, list.length) });
  };

  // Auto-fill width from height unless oversize-override is on.
  // Reacts every render: if user changes height and width is not overridden, width is recalculated.
  const oversize = !!fab.width_override;
  useEffect(() => {
    if (loading) return;
    if (oversize) return;
    const h = parseFloat(fab.letter_height_inches) || 0;
    if (h <= 0) return;
    const autoW = estimateAverageLetterWidth(h);
    if (autoW !== fab.letter_width_inches) {
      setFab((prev) => ({ ...prev, letter_width_inches: autoW }));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fab.letter_height_inches, oversize, loading]);

  if (loading) {
    return (
      <div className="rounded-xl p-4 text-center text-slate-500">
        Loading material library…
      </div>
    );
  }

  return (
    <div className="space-y-3">
      <DimensionalMaterialPickerDialog
        open={pickerOpen}
        onClose={() => setPickerOpen(false)}
        materials={materials}
        selectedId={fab.material_id}
        onSelect={selectMaterial}
      />
      {/* 1. Material — sheet, height, width all on ONE row */}
      <Section icon={Box} title="1. Material" color="bg-blue-50 text-blue-700">
        {materials.length === 0 ? (
          <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 flex items-start gap-2">
            <AlertCircle className="w-4 h-4 text-amber-600 flex-shrink-0 mt-0.5" />
            <div className="flex-1 text-xs text-amber-800">
              <p className="font-medium mb-1">No sheet materials in your library yet.</p>
              <Link to={createPageUrl("MasterInventory")} className="inline-flex items-center gap-1 underline">
                <LinkIcon className="w-3 h-3" /> Open Inventory → Dimensional Sheets tab
              </Link>
            </div>
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 md:grid-cols-12 gap-3">
              <div className="md:col-span-6">
                <Label className="text-xs">Sheet Material</Label>
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setPickerOpen(true)}
                  className="h-9 mt-1 w-full justify-between bg-white font-normal"
                >
                  <span className="truncate">
                    {fab.material_id
                      ? `${fab.material_name} — ${fab.material_thickness_inches}"`
                      : <span className="text-slate-400">Select material...</span>}
                  </span>
                  <Search className="w-4 h-4 text-slate-400 flex-shrink-0" />
                </Button>
              </div>
              <div className="md:col-span-3">
                <Label className="text-xs">Letter Height (in)</Label>
                <Input
                  type="number" min="0" step="0.5"
                  value={fab.letter_height_inches}
                  onFocus={(e) => e.target.select()}
                  onChange={(e) => update({ letter_height_inches: channelDraftValue(e.target.value) })}
                  className="h-9 mt-1 bg-white tabular-nums"
                />
              </div>
              <div className="md:col-span-3">
                <Label className="text-xs flex items-center justify-between gap-1">
                  <span>Letter Width (avg, in)</span>
                  <label className="flex items-center gap-1 text-[10px] text-slate-500 font-normal cursor-pointer">
                    <Checkbox
                      checked={oversize}
                      onCheckedChange={(c) => update({ width_override: !!c })}
                      className="h-3 w-3"
                    />
                    Oversize
                  </label>
                </Label>
                <Input
                  type="number" min="0" step="0.5"
                  value={fab.letter_width_inches}
                  onFocus={(e) => e.target.select()}
                  disabled={!oversize}
                  onChange={(e) => update({ letter_width_inches: channelDraftValue(e.target.value) })}
                  className={`h-9 mt-1 tabular-nums ${oversize ? "bg-white" : "bg-slate-50 text-slate-600"}`}
                />
              </div>
            </div>
            {fab.material_id && (
              <p className="text-[11px] text-slate-500">
                Thickness: <strong>{fab.material_thickness_inches}"</strong> · ≈ {fmt(fab.material_cost_per_sqin * 144)}/sqft after {Math.round(fab.sheet_yield_factor * 100)}% yield
                {!oversize && (
                  <span className="ml-2 text-slate-400">· Width auto-calculated from height (avg of 10 fonts). Check <strong>Oversize</strong> to edit.</span>
                )}
              </p>
            )}
          </>
        )}
      </Section>

      {/* 2. Cutting */}
      <Section
        icon={isLaser ? Zap : Router}
        title="2. Cutting"
        color={isLaser ? "bg-red-50 text-red-700" : "bg-green-50 text-green-700"}
      >
        <CuttingMethodSlider value={fab.cutting_method} onChange={setCuttingMethod} disableLaser={laserDisallowed} />
        {laserDisallowed && (
          <div className="bg-amber-50 border border-amber-200 rounded-md px-2 py-1.5 text-[11px] text-amber-800 flex items-start gap-1.5">
            <AlertCircle className="w-3.5 h-3.5 flex-shrink-0 mt-0.5" />
            <span>
              <strong>{selectedMaterial?.material_name}</strong> is not laser-cuttable — CNC is being used. (Change in Inventory → Dimensional Sheets if this is wrong.)
            </span>
          </div>
        )}
        <div className="flex items-center justify-between gap-2 text-[11px] text-slate-500 bg-slate-50 rounded-md px-2 py-1.5">
          <span>
            Machine: <strong>${activeRates.machine_rate.toFixed(0)}/hr</strong> · Operator: <strong>${activeRates.labor_rate.toFixed(0)}/hr</strong>
            {fab.cut_speed_ipm ? <> · Speed: <strong>{Math.round(fab.cut_speed_ipm)} in/min</strong></> : null}
          </span>
          <span className="flex items-center gap-2">
            <Link to={createPageUrl(cutSettingsPage)} className="underline">Edit {isLaser ? "Laser" : "CNC"} settings</Link>
            <button
              type="button"
              onClick={loadSettings}
              title="Refresh rates from settings"
              className="inline-flex items-center gap-1 text-slate-500 hover:text-slate-800"
            >
              <RefreshCw className="w-3 h-3" /> Refresh
            </button>
          </span>
        </div>
      </Section>

      {/* 3. Paint */}
      <Section icon={Paintbrush} title="3. Paint" color="bg-purple-50 text-purple-700">
        <label className="flex items-center gap-2 cursor-pointer text-sm">
          <Checkbox checked={!!fab.paint_letters} onCheckedChange={(c) => update({ paint_letters: !!c })} />
          <span className="font-medium">Paint these letters</span>
        </label>

        {fab.paint_letters && (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              <div>
                <Label className="text-xs">Paint Sides</Label>
                <Select value={fab.paint_sides} onValueChange={(v) => update({ paint_sides: v })}>
                  <SelectTrigger className="h-9 mt-1 bg-white"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {Object.entries(PAINT_SIDES_LABELS).map(([v, l]) => (
                      <SelectItem key={v} value={v}>{l}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label className="text-xs">Paint Colors</Label>
                <div className="space-y-1.5 mt-1">
                  {paintColors.length === 0 ? (
                    <Input
                      placeholder="e.g., PMS 186C, Black, White"
                      onChange={(e) => update({ paint_colors: [e.target.value], num_paint_colors: 1 })}
                      className="h-9 bg-white"
                    />
                  ) : (
                    paintColors.map((c, i) => (
                      <div key={i} className="flex items-center gap-2">
                        <Input
                          value={c}
                          onChange={(e) => updateColor(i, e.target.value)}
                          placeholder="e.g., PMS 186C, Black, White"
                          className="h-9 bg-white"
                        />
                        {paintColors.length > 1 && (
                          <Button variant="ghost" size="icon" className="h-8 w-8 text-red-500 hover:bg-red-50" onClick={() => removeColor(i)}>
                            <Trash2 className="w-3.5 h-3.5" />
                          </Button>
                        )}
                      </div>
                    ))
                  )}
                  <Button type="button" variant="outline" size="sm" onClick={addColor} className="h-7 text-xs">
                    + Add Color
                  </Button>
                </div>
              </div>
            </div>

            {/* Paint mask helper only shown when there's more than one color */}
            {numColors > 1 && (
              <div className="bg-white border border-purple-200 rounded-lg p-3">
                <p className="text-xs font-semibold text-purple-900 mb-2">Paint Mask (multi-color)</p>
                <PaintCoverageHelper
                  faceAreaSqft={faceAreaSqft}
                  bothSides={fab.paint_sides === "all"}
                  value={fab.paint_mask_sqft}
                  factor={fab.approx_coverage_factor || "1/4"}
                  onChange={(patch) => update(patch)}
                />
              </div>
            )}
          </>
        )}

        <p className="text-[11px] text-slate-500">
          Labor: ${paintR.labor_rate.toFixed(0)}/hr · Supplies: ${paintR.supplies_per_sqft.toFixed(2)}/sqft · Liquid: ${paintR.liquid_paint_per_sqft.toFixed(2)}/sqft
          {" "}<Link to={createPageUrl("EstimatorSettings")} className="underline ml-1">Edit Paint settings</Link>
        </p>
      </Section>

      {/* Live preview — uses the EXACT same calc as the stand-alone CNC + Paint estimators */}
      <div className="bg-gradient-to-r from-slate-900 to-slate-800 text-white rounded-xl p-3 space-y-1.5">
        <div className="flex items-center gap-2 mb-1">
          <Calculator className="w-4 h-4" />
          <span className="font-semibold text-sm">Per-Letter Breakdown</span>
          <Badge className="ml-auto bg-white/10 text-white border-0">{qty} letter{qty === 1 ? "" : "s"}</Badge>
        </div>
        <PreviewRow label="Material" value={computed.unit_material_cost} subtitle={`${(computed.face_area_sqin || 0).toFixed(1)} sqin/letter`} />
        <PreviewRow
          label={CUTTING_METHOD_LABELS[fab.cutting_method] || "Cutting"}
          value={computed.unit_cut_cost}
          subtitle={`${(computed.cut_length_inches || 0).toFixed(0)}" cut/letter`}
        />
        {fab.paint_letters && (
          <PreviewRow label="Paint" value={computed.unit_paint_cost} subtitle={PAINT_SIDES_LABELS[fab.paint_sides]} />
        )}
        <div className="border-t border-white/20 pt-2 space-y-1">
          <div className="flex justify-between items-center text-[11px] text-slate-400">
            <span>Row totals (from {isLaser ? "Laser" : "CNC"} + Paint settings)</span>
            <span className="tabular-nums">
              Mat ${(computed.row_total_material_cost || 0).toFixed(2)} ·
              Cut ${(computed.row_total_cut_cost || 0).toFixed(2)}
              {fab.paint_letters && (
                <> · Paint ${((computed.row_total_paint_mask_cost || 0) + (computed.row_total_paint_supplies_cost || 0) + (computed.row_total_paint_labor_cost || 0)).toFixed(2)}</>
              )}
            </span>
          </div>
          <div className="flex justify-between items-center">
            <span className="text-sm text-slate-300">Total ({qty} letter{qty === 1 ? "" : "s"})</span>
            <span className="text-xl font-bold tabular-nums">{fmt(computed.unit_total_cost * qty)}</span>
          </div>
        </div>
      </div>
    </div>
  );
}

const Section = ({ icon: Icon, title, color, children }) => (
  <div className="border border-slate-200 rounded-lg p-3 space-y-3 bg-white">
    <div className="flex items-center gap-2">
      <div className={`w-7 h-7 rounded-lg ${color} flex items-center justify-center`}>
        <Icon className="w-4 h-4" />
      </div>
      <span className="font-semibold text-slate-800 text-sm">{title}</span>
    </div>
    {children}
  </div>
);

const PreviewRow = ({ label, value, subtitle }) => (
  <div className="flex justify-between items-center text-sm">
    <div>
      <span className="text-slate-300">{label}</span>
      {subtitle && <span className="ml-2 text-[10px] text-slate-500">{subtitle}</span>}
    </div>
    <span className="tabular-nums font-medium">{fmt(value)}</span>
  </div>
);

import React, { useState, useMemo } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Search, Check, ArrowUpDown } from "lucide-react";
import { materialCostPerSqin } from "./dimensionalFabCalculator";

const MATERIAL_TYPE_LABELS = {
  acrylic: "Acrylic",
  pvc: "PVC / Sintra",
  aluminum_composite: "ACM (Aluminum Composite)",
  aluminum_solid: "Solid Aluminum",
  aluminum_sheet: "Aluminum Sheet",
  steel_sheet: "Steel Sheet",
  stainless_sheet: "Stainless Sheet",
  galvanized_sheet: "Galvanized Sheet",
  polycarbonate: "Polycarbonate",
  styrene: "Styrene",
  coroplast: "Coroplast",
  gatorboard: "Gatorboard",
  wood: "Wood",
  mdf: "MDF",
  hdu: "HDU Foam",
  foam: "EPS Foam",
  other: "Other",
};

const TYPE_COLORS = {
  acrylic: "bg-cyan-100 text-cyan-800",
  pvc: "bg-blue-100 text-blue-800",
  aluminum_composite: "bg-slate-100 text-slate-800",
  aluminum_solid: "bg-zinc-100 text-zinc-800",
  wood: "bg-amber-100 text-amber-800",
  mdf: "bg-orange-100 text-orange-800",
  hdu: "bg-pink-100 text-pink-800",
  foam: "bg-purple-100 text-purple-800",
  other: "bg-slate-100 text-slate-800",
};

const fmt = (v) => `$${(parseFloat(v) || 0).toFixed(2)}`;

const SORT_OPTIONS = {
  name: { label: "Name (A–Z)", fn: (a, b) => (a.material_name || "").localeCompare(b.material_name || "") },
  type: { label: "Material Type", fn: (a, b) => (a.material_type || "").localeCompare(b.material_type || "") },
  thickness: { label: "Thickness (low→high)", fn: (a, b) => (a.thickness_inches || 0) - (b.thickness_inches || 0) },
  cost_low: { label: "$/sqft (low→high)", fn: (a, b) => materialCostPerSqin(a) - materialCostPerSqin(b) },
  cost_high: { label: "$/sqft (high→low)", fn: (a, b) => materialCostPerSqin(b) - materialCostPerSqin(a) },
};

export default function DimensionalMaterialPickerDialog({ open, onClose, materials = [], selectedId, onSelect }) {
  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState("all");
  const [paintFilter, setPaintFilter] = useState("all");
  const [laserFilter, setLaserFilter] = useState("all");
  const [sortKey, setSortKey] = useState("name");

  const availableTypes = useMemo(() => {
    const set = new Set(materials.map((m) => m.material_type).filter(Boolean));
    return Array.from(set);
  }, [materials]);

  const filtered = useMemo(() => {
    let list = materials.filter((m) => {
      if (typeFilter !== "all" && m.material_type !== typeFilter) return false;
      if (paintFilter === "yes" && !m.needs_painting) return false;
      if (paintFilter === "no" && m.needs_painting) return false;
      if (laserFilter === "yes" && m.allow_laser === false) return false;
      if (laserFilter === "no" && m.allow_laser !== false) return false;
      if (search) {
        const hay = `${m.material_name} ${m.color || ""} ${m.supplier || ""} ${MATERIAL_TYPE_LABELS[m.material_type] || ""}`.toLowerCase();
        if (!hay.includes(search.toLowerCase())) return false;
      }
      return true;
    });
    return list.sort(SORT_OPTIONS[sortKey].fn);
  }, [materials, typeFilter, paintFilter, laserFilter, search, sortKey]);

  return (
    <Dialog open={open} onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="max-w-4xl max-h-[85vh] flex flex-col p-0">
        <DialogHeader className="p-4 pb-2 border-b">
          <DialogTitle>Select Sheet Material</DialogTitle>
        </DialogHeader>

        {/* Search + filter + sort bar */}
        <div className="px-4 py-3 border-b space-y-2 bg-slate-50">
          <div className="relative">
            <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <Input
              autoFocus
              placeholder="Search by name, color, supplier, type..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-9 h-9 bg-white"
            />
          </div>
          <div className="flex flex-wrap gap-2">
            <Select value={typeFilter} onValueChange={setTypeFilter}>
              <SelectTrigger className="h-8 w-44 text-xs bg-white"><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Types</SelectItem>
                {availableTypes.map((t) => (
                  <SelectItem key={t} value={t}>{MATERIAL_TYPE_LABELS[t] || t}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Select value={paintFilter} onValueChange={setPaintFilter}>
              <SelectTrigger className="h-8 w-36 text-xs bg-white"><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Paint: Any</SelectItem>
                <SelectItem value="yes">Needs Paint</SelectItem>
                <SelectItem value="no">Pre-finished</SelectItem>
              </SelectContent>
            </Select>
            <Select value={laserFilter} onValueChange={setLaserFilter}>
              <SelectTrigger className="h-8 w-36 text-xs bg-white"><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Laser: Any</SelectItem>
                <SelectItem value="yes">Laser OK</SelectItem>
                <SelectItem value="no">CNC Only</SelectItem>
              </SelectContent>
            </Select>
            <Select value={sortKey} onValueChange={setSortKey}>
              <SelectTrigger className="h-8 w-48 text-xs bg-white">
                <ArrowUpDown className="w-3.5 h-3.5 mr-1 text-slate-400" />
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {Object.entries(SORT_OPTIONS).map(([k, o]) => (
                  <SelectItem key={k} value={k}>{o.label}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            <span className="text-xs text-slate-500 self-center ml-auto">{filtered.length} of {materials.length}</span>
          </div>
        </div>

        {/* Results */}
        <div className="flex-1 overflow-y-auto p-3 space-y-1.5">
          {filtered.length === 0 ? (
            <div className="text-center py-12 text-slate-400 text-sm">No materials match your filters.</div>
          ) : (
            filtered.map((m) => {
              const isSel = m.id === selectedId;
              const sqin = materialCostPerSqin(m);
              return (
                <button type="button"
                  key={m.id}
                  onClick={() => { onSelect(m.id); onClose(); }}
                  className={`w-full text-left border rounded-lg p-3 transition-colors flex items-center gap-3 ${
                    isSel ? "border-blue-400 bg-blue-50" : "border-slate-200 hover:bg-slate-50"
                  }`}
                >
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-medium text-sm text-slate-900 truncate">{m.material_name}</span>
                      <Badge className={`${TYPE_COLORS[m.material_type] || TYPE_COLORS.other} text-[10px]`}>
                        {MATERIAL_TYPE_LABELS[m.material_type] || m.material_type}
                      </Badge>
                      {m.allow_laser === false && (
                        <Badge variant="outline" className="text-[10px] text-amber-700 border-amber-300">CNC only</Badge>
                      )}
                    </div>
                    <div className="text-[11px] text-slate-500 mt-0.5 flex flex-wrap gap-x-3">
                      <span>{m.thickness_inches}" thick</span>
                      {m.color && <span>{m.color}</span>}
                      {m.supplier && <span>{m.supplier}</span>}
                      <span>{Math.round((m.yield_factor || 0.7) * 100)}% yield</span>
                    </div>
                  </div>
                  <div className="text-right flex-shrink-0">
                    <div className="text-sm font-semibold tabular-nums text-slate-900">{fmt(sqin * 144)}<span className="text-[10px] text-slate-400">/sqft</span></div>
                  </div>
                  {isSel && <Check className="w-4 h-4 text-blue-600 flex-shrink-0" />}
                </button>
              );
            })
          )}
        </div>

        <div className="p-3 border-t flex justify-end bg-slate-50">
          <Button variant="outline" onClick={onClose}>Close</Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect, useMemo, useRef } from "react";
import { DimensionalLetterMaterial } from "@/api/gatedEntities";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { Plus, Trash2, Copy, Save, Layers, Search } from "lucide-react";
import { useToast } from "@/components/ui/use-toast";
import { materialCostPerSqin } from "./dimensionalFabCalculator";
import { deleteEntityIfUnchanged, expectedEntityFields, replaceEntityFieldsIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";

const MATERIAL_TYPE_LABELS = {
  acrylic: "Acrylic",
  pvc: "PVC / Sintra",
  aluminum_composite: "ACM (Aluminum Composite)",
  aluminum_solid: "Solid Aluminum",
  wood: "Wood",
  mdf: "MDF",
  hdu: "HDU Foam",
  foam: "EPS Foam",
  other: "Other",
};

const TYPE_COLORS = {
  acrylic: "bg-cyan-100 text-cyan-800",
  pvc: "bg-blue-100 text-blue-800",
  aluminum_composite: "bg-slate-100 text-slate-800",
  aluminum_solid: "bg-zinc-100 text-zinc-800",
  wood: "bg-amber-100 text-amber-800",
  mdf: "bg-orange-100 text-orange-800",
  hdu: "bg-pink-100 text-pink-800",
  foam: "bg-purple-100 text-purple-800",
  other: "bg-slate-100 text-slate-800",
};

const fmt = (v) => `$${(parseFloat(v) || 0).toFixed(2)}`;

const stripMaterialMeta = (row = {}) => {
  const data = { ...row };
  ["id", "_isNew", "created_date", "updated_date", "created_by_id", "created_by", "is_sample"].forEach((key) => delete data[key]);
  return data;
};

const materialSnapshot = (row) => JSON.stringify(stripMaterialMeta(row));
const sameStoredValue = (a, b) => {
  const emptyA = a === undefined || a === null || a === "";
  const emptyB = b === undefined || b === null || b === "";
  if (emptyA && emptyB) return true;
  if (!emptyA && !emptyB && Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
    return Math.abs(Number(a) - Number(b)) <= 0.000001;
  }
  return JSON.stringify(a) === JSON.stringify(b);
};
const materialMatchesPayload = (row, payload) => !!row && Object.entries(payload || {}).every(([field, value]) => sameStoredValue(row[field], value));

// Filters substrates by which pages they're enabled for in Master Inventory.
// scope = "install"     → show items with show_in_dimensional_letters OR show_in_lobby_sign_backer
// scope = "maintenance" → show items with show_in_vinyl_replacement OR show_in_replace_returns OR show_in_replace_face
// scope = undefined     → show all (used by Master Inventory itself)
const matchesVisibility = (m, scope) => {
  if (!scope) return true;
  if (scope === "install") {
    return m.show_in_dimensional_letters === true || m.show_in_lobby_sign_backer === true;
  }
  if (scope === "maintenance") {
    return m.show_in_vinyl_replacement === true ||
           m.show_in_replace_returns === true ||
           m.show_in_replace_face === true;
  }
  return true;
};

export default function DimensionalMaterialsTab({ visibilityScope } = {}) {
  const [materials, setMaterials] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState("all");
  const [dirty, setDirty] = useState(false);
  const [loadError, setLoadError] = useState("");
  const [originalById, setOriginalById] = useState({});
  const saveRef = useRef(false);
  const deleteRef = useRef(new Set());
  const { toast } = useToast();

  useEffect(() => { load(); }, []);

  const load = async () => {
    setLoading(true);
    setLoadError("");
    try {
      const data = await loadAllEntityRows({ entity: DimensionalLetterMaterial, sort: "sort_order", label: "Dimensional Letter materials" });
      setMaterials(data || []);
      setOriginalById(Object.fromEntries((data || []).filter((row) => row.id).map((row) => [row.id, materialSnapshot(row)])));
      setDirty(false);
    } catch (e) {
      console.error(e);
      setLoadError(e?.message || "Dimensional material inventory could not be verified.");
    } finally {
      setLoading(false);
    }
  };

  const addMaterial = () => {
    setMaterials(prev => [
      ...prev,
      {
        _isNew: true,
        material_name: "New Material",
        material_type: "pvc",
        thickness_inches: 0.5,
        sheet_length_inches: 96,
        sheet_width_inches: 48,
        cost_per_sheet: 0,
        yield_factor: 0.7,
        color: "",
        supplier: "",
        needs_painting: true,
        allow_laser: true,
        notes: "",
        is_active: true,
        sort_order: prev.length,
      },
    ]);
    setDirty(true);
  };

  const updateMaterial = (idx, patch) => {
    setMaterials(prev => {
      const arr = [...prev];
      arr[idx] = { ...arr[idx], ...patch };
      return arr;
    });
    setDirty(true);
  };

  const duplicate = (idx) => {
    setMaterials(prev => {
      const arr = [...prev];
      const copy = { ...arr[idx] };
      delete copy.id;
      copy._isNew = true;
      copy.material_name = `${copy.material_name} (Copy)`;
      arr.splice(idx + 1, 0, copy);
      return arr;
    });
    setDirty(true);
  };

  const removeMaterial = async (idx) => {
    const m = materials[idx];
    const lockKey = m.id || `new:${idx}`;
    if (loadError || deleteRef.current.has(lockKey)) return;
    deleteRef.current.add(lockKey);
    if (!confirm(`Delete "${m.material_name}"?`)) {
      deleteRef.current.delete(lockKey);
      return;
    }
    try {
      if (m.id) {
        const live = await DimensionalLetterMaterial.get(m.id);
        if (m.updated_date && live?.updated_date && m.updated_date !== live.updated_date) {
          toast({ variant: "destructive", description: "This material changed in another session and was not deleted. Reloading the latest inventory." });
          await load();
          return;
        }
        await deleteEntityIfUnchanged({
          entity: DimensionalLetterMaterial,
          record: live,
          label: `Dimensional material “${m.material_name || "Item"}”`,
        });
      }
      setMaterials(prev => prev.filter((_, i) => i !== idx));
      if (m.id) setOriginalById((prev) => { const next = { ...prev }; delete next[m.id]; return next; });
    } catch (e) {
      toast({ variant: "destructive", description: "Delete failed: " + e.message });
    } finally {
      deleteRef.current.delete(lockKey);
    }
  };

  const changedMaterials = useMemo(() => materials.filter((m) =>
    m._isNew || !m.id || materialSnapshot(m) !== originalById[m.id]
  ), [materials, originalById]);

  const saveAll = async () => {
    if (saveRef.current || loadError || changedMaterials.length === 0) return;
    saveRef.current = true;
    setSaving(true);
    let confirmed = 0;
    try {
      const existingChanged = changedMaterials.filter((m) => m.id && !m._isNew);
      const liveRows = await Promise.all(existingChanged.map((m) => DimensionalLetterMaterial.get(m.id)));
      const conflicts = existingChanged.filter((m, index) => {
        const live = liveRows[index];
        if (!live) return true;
        const versionChanged = !!(m.updated_date && live.updated_date && m.updated_date !== live.updated_date);
        const loadedSnapshot = originalById[m.id];
        return versionChanged || (loadedSnapshot !== undefined && materialSnapshot(live) !== loadedSnapshot);
      });
      if (conflicts.length) {
        throw new Error(`These materials changed in another session: ${conflicts.map((m) => m.material_name).join(", ")}. Reload before saving.`);
      }

      const liveById = new Map(existingChanged.map((m, index) => [m.id, liveRows[index]]));
      const completed = [];
      for (const m of changedMaterials) {
        const data = stripMaterialMeta(m);
        try {
          let saved;
          if (m.id && !m._isNew) {
            const live = liveById.get(m.id);
            saved = await replaceEntityFieldsIfUnchanged({
              entity: DimensionalLetterMaterial,
              id: m.id,
              expectedUpdatedAt: live?.updated_date || "",
              expectedFields: expectedEntityFields(live || {}, data),
              nextFields: data,
              label: `Dimensional material “${m.material_name || "Item"}”`,
            });
          } else {
            saved = await DimensionalLetterMaterial.create(data);
            if (!saved?.id) throw new Error(`Created material “${m.material_name || "Item"}” could not be verified.`);
          }
          confirmed += 1;
          completed.push({ id: saved.id, data, name: m.material_name || "Material" });
        } catch (error) {
          throw new Error(`Save stopped after ${confirmed} of ${changedMaterials.length} changed materials were confirmed. Reloading the catalog; remaining materials were not skipped automatically. ${error?.message || ""}`.trim());
        }
      }

      const finalRows = await loadAllEntityRows({ entity: DimensionalLetterMaterial, sort: "sort_order", label: "Dimensional Letter materials final verification" });
      const finalById = new Map(finalRows.map((row) => [row.id, row]));
      const failedVerification = completed.filter((entry) => !materialMatchesPayload(finalById.get(entry.id), entry.data));
      if (failedVerification.length) {
        throw new Error(`Final verification found ${failedVerification.length} saved material${failedVerification.length === 1 ? "" : "s"} whose live values no longer match this save: ${failedVerification.map((entry) => entry.name).join(", ")}. Reload and review before retrying.`);
      }

      toast({ description: `Saved ${changedMaterials.length} material${changedMaterials.length === 1 ? "" : "s"}` });
      await load();
    } catch (e) {
      toast({ variant: "destructive", description: "Save failed: " + e.message });
      if (confirmed > 0) await load();
    } finally {
      saveRef.current = false;
      setSaving(false);
    }
  };

  const filtered = materials.filter(m => {
    if (!matchesVisibility(m, visibilityScope)) return false;
    if (filter !== "all" && m.material_type !== filter) return false;
    if (search && !`${m.material_name} ${m.color || ""} ${m.supplier || ""}`.toLowerCase().includes(search.toLowerCase())) return false;
    return true;
  });

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-3 flex-wrap">
        <div className="flex-1 min-w-[200px]">
          <p className="text-sm text-slate-600">Sheet material library used for dimensional letter fabrication (CNC + Paint cost build-up).</p>
        </div>
        <Button onClick={addMaterial} variant="outline" disabled={!!loadError}>
          <Plus className="w-4 h-4 mr-1" /> Add Material
        </Button>
        <Button onClick={saveAll} disabled={saving || !dirty || !!loadError || changedMaterials.length === 0} className="bg-slate-900 hover:bg-slate-800 text-white">
          {saving ? "Saving…" : <><Save className="w-4 h-4 mr-1" /> Save All</>}
        </Button>
      </div>

      <Card>
        <CardContent className="p-3 flex gap-2 items-center flex-wrap">
          <div className="relative flex-1 min-w-[200px]">
            <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <Input
              placeholder="Search by name, color, supplier..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-9 h-9"
            />
          </div>
          <Select value={filter} onValueChange={setFilter}>
            <SelectTrigger className="w-48 h-9"><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Material Types</SelectItem>
              {Object.entries(MATERIAL_TYPE_LABELS).map(([v, l]) => (
                <SelectItem key={v} value={v}>{l}</SelectItem>
              ))}
            </SelectContent>
          </Select>
          <span className="text-xs text-slate-500">{filtered.length} of {materials.length}</span>
        </CardContent>
      </Card>

      {loading ? (
        <div className="text-center py-12 text-slate-500">Loading…</div>
      ) : loadError ? (
        <Card className="border-red-200 bg-red-50"><CardContent className="p-8 text-center text-red-700"><div className="font-semibold">Dimensional material inventory could not be verified.</div><div className="text-xs mt-1">{loadError}</div><Button variant="outline" size="sm" className="mt-3" onClick={load}>Retry</Button></CardContent></Card>
      ) : filtered.length === 0 ? (
        <Card className="border-2 border-dashed">
          <CardContent className="p-12 text-center text-slate-500">
            <Layers className="w-12 h-12 mx-auto mb-3 text-slate-300" />
            <p className="mb-3 font-medium">No materials yet</p>
            <Button onClick={addMaterial} disabled={!!loadError} className="bg-emerald-600 hover:bg-emerald-700 text-white disabled:opacity-50">
              <Plus className="w-4 h-4 mr-1" /> Add First Material
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-2">
          {filtered.map((m) => {
            const idx = materials.indexOf(m);
            const sqin = materialCostPerSqin(m);
            return (
              <Card key={m.id || idx} className={`${m._isNew ? "border-emerald-300 bg-emerald-50/30" : ""}`}>
                <CardContent className="p-3 space-y-3">
                  <div className="flex items-center gap-2 flex-wrap">
                    <Badge className={TYPE_COLORS[m.material_type] || TYPE_COLORS.other}>
                      {MATERIAL_TYPE_LABELS[m.material_type]}
                    </Badge>
                    {m._isNew && <Badge variant="outline" className="text-emerald-700 border-emerald-300">New</Badge>}
                    <Badge variant="outline" className="bg-slate-50 text-xs">
                      ≈ {fmt(sqin * 144)}/sqft
                    </Badge>
                    <div className="ml-auto flex gap-1">
                      <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => duplicate(idx)}>
                        <Copy className="w-3.5 h-3.5" />
                      </Button>
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-red-500" onClick={() => removeMaterial(idx)}>
                        <Trash2 className="w-3.5 h-3.5" />
                      </Button>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 md:grid-cols-6 gap-2">
                    <div className="md:col-span-2">
                      <Label className="text-xs">Material Name</Label>
                      <Input
                        value={m.material_name}
                        onChange={(e) => updateMaterial(idx, { material_name: e.target.value })}
                        className="h-8 mt-1"
                      />
                    </div>
                    <div>
                      <Label className="text-xs">Type</Label>
                      <Select value={m.material_type} onValueChange={(v) => updateMaterial(idx, { material_type: v })}>
                        <SelectTrigger className="h-8 mt-1"><SelectValue /></SelectTrigger>
                        <SelectContent>
                          {Object.entries(MATERIAL_TYPE_LABELS).map(([v, l]) => (
                            <SelectItem key={v} value={v}>{l}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div>
                      <Label className="text-xs">Thickness (in)</Label>
                      <Input
                        type="number" step="0.0625" min="0"
                        value={m.thickness_inches}
                        onChange={(e) => updateMaterial(idx, { thickness_inches: parseFloat(e.target.value) || 0 })}
                        className="h-8 mt-1 tabular-nums"
                      />
                    </div>
                    <div>
                      <Label className="text-xs">Color</Label>
                      <Input
                        value={m.color || ""}
                        onChange={(e) => updateMaterial(idx, { color: e.target.value })}
                        className="h-8 mt-1"
                        placeholder="White"
                      />
                    </div>
                    <div>
                      <Label className="text-xs">Supplier</Label>
                      <Input
                        value={m.supplier || ""}
                        onChange={(e) => updateMaterial(idx, { supplier: e.target.value })}
                        className="h-8 mt-1"
                      />
                    </div>
                  </div>

                  <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
                    <div>
                      <Label className="text-xs">Sheet L (in)</Label>
                      <Input
                        type="number" step="1" min="0"
                        value={m.sheet_length_inches}
                        onChange={(e) => updateMaterial(idx, { sheet_length_inches: parseFloat(e.target.value) || 0 })}
                        className="h-8 mt-1 tabular-nums"
                      />
                    </div>
                    <div>
                      <Label className="text-xs">Sheet W (in)</Label>
                      <Input
                        type="number" step="1" min="0"
                        value={m.sheet_width_inches}
                        onChange={(e) => updateMaterial(idx, { sheet_width_inches: parseFloat(e.target.value) || 0 })}
                        className="h-8 mt-1 tabular-nums"
                      />
                    </div>
                    <div>
                      <Label className="text-xs">Cost / Sheet</Label>
                      <div className="relative mt-1">
                        <span className="absolute left-2 top-1/2 -translate-y-1/2 text-slate-400 text-xs">$</span>
                        <Input
                          type="number" step="0.01" min="0"
                          value={m.cost_per_sheet}
                          onChange={(e) => updateMaterial(idx, { cost_per_sheet: parseFloat(e.target.value) || 0 })}
                          className="h-8 pl-5 tabular-nums"
                        />
                      </div>
                    </div>
                    <div>
                      <Label className="text-xs" title="Usable yield after nesting waste">
                        Yield (0–1)
                      </Label>
                      <Input
                        type="number" step="0.05" min="0.05" max="1"
                        value={m.yield_factor}
                        onChange={(e) => updateMaterial(idx, { yield_factor: parseFloat(e.target.value) || 0.7 })}
                        className="h-8 mt-1 tabular-nums"
                      />
                    </div>
                    <div className="flex items-end gap-3 pb-1 flex-wrap">
                      <label className="flex items-center gap-1.5 text-xs text-slate-700 cursor-pointer">
                        <Checkbox
                          checked={!!m.needs_painting}
                          onCheckedChange={(c) => updateMaterial(idx, { needs_painting: !!c })}
                        />
                        Needs Paint
                      </label>
                      <label
                        className="flex items-center gap-1.5 text-xs text-slate-700 cursor-pointer"
                        title="If unchecked, this material cannot be cut on the laser (e.g., PVC, ACM) — only CNC will be available."
                      >
                        <Checkbox
                          checked={m.allow_laser !== false}
                          onCheckedChange={(c) => updateMaterial(idx, { allow_laser: !!c })}
                        />
                        Allow Laser
                      </label>
                      <label className="flex items-center gap-1.5 text-xs text-slate-700 cursor-pointer">
                        <Checkbox
                          checked={m.is_active !== false}
                          onCheckedChange={(c) => updateMaterial(idx, { is_active: !!c })}
                        />
                        Active
                      </label>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useMemo } from "react";
import { ChannelLetterInstallEquipment } from "@/api/gatedEntities";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Plus, Trash2, Save, Home, Building2, Fuel, ArrowUpFromLine } from "lucide-react";

const EQUIPMENT_TYPES = [
  { value: "ladder", label: "Ladder" },
  { value: "scissor_lift", label: "Scissor Lift" },
  { value: "boom_lift", label: "Boom Lift" },
  { value: "boom_truck", label: "Boom Truck" },
  { value: "scaffold", label: "Scaffold" },
  { value: "truck", label: "Truck" },
  { value: "car", label: "Car" },
  { value: "van", label: "Van" },
  { value: "flatbed", label: "Flatbed" },
  { value: "hand_tool", label: "Hand Tool" },
  { value: "power_tool", label: "Power Tool" },
  { value: "safety", label: "Safety" },
  { value: "other", label: "Other" },
];

const VEHICLE_TYPES = ["truck", "car", "van", "flatbed", "boom_truck"];
const BOOM_TYPES = ["boom_lift", "boom_truck"];
// Lift-type equipment that can be marked as the "primary owned" go-to lift.
const LIFT_TYPES = ["ladder", "scissor_lift", "boom_lift", "boom_truck", "scaffold"];

const FUEL_TYPES = [
  { value: "na", label: "N/A" },
  { value: "gasoline", label: "Gasoline" },
  { value: "diesel", label: "Diesel" },
];

const OWNED_PRICING_MODES = [
  { value: "owned_flat", label: "Flat Day Rate" },
  { value: "per_hour", label: "Per Hour" },
  { value: "per_project_flat", label: "Per Project Flat" },
];

const RENTED_PRICING_MODES = [
  { value: "per_hour", label: "Per Hour" },
  { value: "per_day", label: "Per Day" },
  { value: "per_week", label: "Per Week" },
  { value: "per_month", label: "Per Month" },
];

// Migrate: older records without `ownership` are inferred from pricing_mode.
const isOwned = (item) => {
  if (item.ownership) return item.ownership === "owned";
  return item.pricing_mode === "owned_flat" || item.pricing_mode === "per_project_flat";
};

const emptyItem = (mode = "owned", scope = "construction") => ({
  equipment_name: "",
  equipment_type: scope === "boom"
    ? "boom_lift"
    : (mode === "owned" ? "truck" : "scissor_lift"),
  ownership: mode,
  max_height_feet: 0,
  total_boom_height_feet: 0,
  horizontal_boom_reach_feet: 0,
  deployed_truck_width_feet: 0,
  vertical_reach_safety_margin_feet: 2,
  is_default_for_height: false,
  is_primary_owned: false,
  default_height_min_feet: 0,
  default_height_max_feet: 0,
  idle_running_cost_per_hour: 0,
  pricing_mode: mode === "owned" ? "owned_flat" : "per_day",
  cost_per_hour: 0,
  cost_per_day: 0,
  cost_per_week: 0,
  cost_per_month: 0,
  cost_flat: 0,
  delivery_pickup_cost: 0,
  mpg: 0,
  fuel_type: mode === "owned" ? "gasoline" : "na",
  rental_company: "",
  notes: "",
  is_active: true,
  sort_order: 0,
});

// Which equipment types belong to the "Boom Lifts" tab vs "Construction Equipment".
const isBoomItem = (it) => BOOM_TYPES.includes(it.equipment_type);

export default function EquipmentInventoryTab({ scope = "construction" }) {
  // scope="construction" → everything that is NOT a boom lift/truck
  // scope="boom"         → only boom lifts / boom trucks
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [activeTab, setActiveTab] = useState("owned");

  const load = async () => {
    setLoading(true);
    const data = await loadAllEntityRows({ entity: ChannelLetterInstallEquipment, sort: "sort_order", label: "Channel Letter equipment inventory" });
    setItems(data);
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  // Restrict the records shown in this instance to the current scope.
  const scopedItems = useMemo(
    () => items.filter((it) => (scope === "boom" ? isBoomItem(it) : !isBoomItem(it))),
    [items, scope]
  );

  const ownedItems = useMemo(() => scopedItems.filter(isOwned), [scopedItems]);
  const rentedItems = useMemo(() => scopedItems.filter((it) => !isOwned(it)), [scopedItems]);

  const update = (origIndex, patch) => {
    const next = [...items];
    next[origIndex] = { ...next[origIndex], ...patch };
    setItems(next);
  };

  const addItem = (mode) => {
    setItems([...items, { ...emptyItem(mode, scope), _new: true }]);
    setActiveTab(mode);
  };

  const removeItem = async (origIndex) => {
    const item = items[origIndex];
    if (item.id) {
      if (!confirm(`Delete "${item.equipment_name}"?`)) return;
      try {
        await ChannelLetterInstallEquipment.delete(item.id);
      } catch (e) {
        console.error("Delete failed:", e);
        alert("Delete failed: " + (e.message || "unknown error"));
        return;
      }
    }
    const next = [...items];
    next.splice(origIndex, 1);
    setItems(next);
  };

  const saveAll = async () => {
    setSaving(true);
    try {
      for (const it of items) {
        const { _new, id, ...payload } = it;
        // Ensure ownership is always persisted (back-fills legacy records)
        if (!payload.ownership) {
          payload.ownership = isOwned(it) ? "owned" : "rented";
        }
        if (id) await ChannelLetterInstallEquipment.update(id, payload);
        else await ChannelLetterInstallEquipment.create(payload);
      }
      await load();
    } catch (e) {
      console.error("Save failed:", e);
      alert("Save failed: " + (e.message || "unknown error"));
    }
    setSaving(false);
  };

  const costField = (it, i) => {
    switch (it.pricing_mode) {
      case "per_hour":
        return <Input type="number" step="0.01" value={it.cost_per_hour || 0} onFocus={e => e.target.select()} onChange={(e) => update(i, { cost_per_hour: parseFloat(e.target.value) || 0 })} className="h-8 mt-0.5" />;
      case "per_day":
        return <Input type="number" step="0.01" value={it.cost_per_day} onFocus={e => e.target.select()} onChange={(e) => update(i, { cost_per_day: parseFloat(e.target.value) || 0 })} className="h-8 mt-0.5" />;
      case "per_week":
        return <Input type="number" step="0.01" value={it.cost_per_week} onFocus={e => e.target.select()} onChange={(e) => update(i, { cost_per_week: parseFloat(e.target.value) || 0 })} className="h-8 mt-0.5" />;
      case "per_month":
        return <Input type="number" step="0.01" value={it.cost_per_month} onFocus={e => e.target.select()} onChange={(e) => update(i, { cost_per_month: parseFloat(e.target.value) || 0 })} className="h-8 mt-0.5" />;
      case "owned_flat":
      case "per_project_flat":
        return <Input type="number" step="0.01" value={it.cost_flat} onFocus={e => e.target.select()} onChange={(e) => update(i, { cost_flat: parseFloat(e.target.value) || 0 })} className="h-8 mt-0.5" />;
      default:
        return null;
    }
  };

  // In the Boom Lifts tab only boom types are selectable; otherwise hide booms.
  const typeOptions = scope === "boom"
    ? EQUIPMENT_TYPES.filter((t) => BOOM_TYPES.includes(t.value))
    : EQUIPMENT_TYPES.filter((t) => !BOOM_TYPES.includes(t.value));

  const renderRow = (it, origIndex, mode) => {
    const isVehicle = VEHICLE_TYPES.includes(it.equipment_type);
    const showFuel = mode === "owned" && isVehicle;
    const showBoomFields = BOOM_TYPES.includes(it.equipment_type);
    const pricingOptions = mode === "owned" ? OWNED_PRICING_MODES : RENTED_PRICING_MODES;
    const accent = mode === "owned" ? "bg-emerald-50/40 border-emerald-100" : "bg-blue-50/40 border-blue-100";

    return (
      <div key={origIndex} className={`border rounded-lg p-3 ${accent}`}>
        <div className="grid md:grid-cols-12 gap-2 items-end">
          <div className="md:col-span-3">
            <Label className="text-xs">Equipment Name</Label>
            <Input value={it.equipment_name} onChange={(e) => update(origIndex, { equipment_name: e.target.value })} className="h-8 mt-0.5" placeholder="e.g. 26ft Scissor Lift" />
          </div>
          <div className="md:col-span-2">
            <Label className="text-xs">Type</Label>
            <Select value={it.equipment_type} onValueChange={(v) => update(origIndex, { equipment_type: v })}>
              <SelectTrigger className="h-8 mt-0.5"><SelectValue /></SelectTrigger>
              <SelectContent>
                {typeOptions.map(c => <SelectItem key={c.value} value={c.value}>{c.label}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
          <div className="md:col-span-1">
            <Label className="text-xs">Max Ht (ft)</Label>
            <Input type="number" value={it.max_height_feet} onFocus={e => e.target.select()} onChange={(e) => update(origIndex, { max_height_feet: parseFloat(e.target.value) || 0 })} className="h-8 mt-0.5" />
          </div>
          <div className="md:col-span-2">
            <Label className="text-xs">Pricing Mode</Label>
            <Select value={it.pricing_mode} onValueChange={(v) => update(origIndex, { pricing_mode: v })}>
              <SelectTrigger className="h-8 mt-0.5"><SelectValue /></SelectTrigger>
              <SelectContent>
                {pricingOptions.map(c => <SelectItem key={c.value} value={c.value}>{c.label}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
          <div className={mode === "owned" ? "md:col-span-3" : "md:col-span-2"}>
            <Label className="text-xs">Cost</Label>
            {costField(it, origIndex)}
          </div>
          {mode === "rented" && (
            <div className="md:col-span-1">
              <Label className="text-xs">Delivery</Label>
              <Input type="number" step="0.01" value={it.delivery_pickup_cost} onFocus={e => e.target.select()} onChange={(e) => update(origIndex, { delivery_pickup_cost: parseFloat(e.target.value) || 0 })} className="h-8 mt-0.5" />
            </div>
          )}
          <div className="md:col-span-1 flex items-end">
            <label className="flex items-center gap-1 cursor-pointer text-xs mb-2">
              <Checkbox checked={it.is_active} onCheckedChange={(c) => update(origIndex, { is_active: !!c })} />
              <span>Active</span>
            </label>
          </div>
        </div>
        {/* Primary owned go-to lift — for owned ladder / scissor / scaffold (booms handle this in their own block below) */}
        {mode === "owned" && LIFT_TYPES.includes(it.equipment_type) && !showBoomFields && (
          <div className="mt-2">
            <label className="flex items-center gap-1.5 cursor-pointer text-xs bg-emerald-100/40 border border-emerald-200/60 rounded-md px-2 py-1.5 w-fit">
              <Checkbox
                checked={!!it.is_primary_owned}
                onCheckedChange={(c) => update(origIndex, { is_primary_owned: !!c })}
              />
              <span className="font-semibold text-emerald-800">⭐ Primary owned lift (my go-to for normal use)</span>
              <span className="text-emerald-700/70 font-normal">— auto-selected on any job it can reach</span>
            </label>
          </div>
        )}
        {showBoomFields && (
          <div className="grid md:grid-cols-12 gap-2 mt-2 p-2 rounded-md bg-purple-100/40 border border-purple-200/60">
            <div className="md:col-span-12 flex items-center gap-1.5 text-[11px] font-semibold text-purple-900 mb-0.5">
              <ArrowUpFromLine className="w-3 h-3" />
              {it.equipment_type === "boom_truck" ? "Boom Truck Reach Specs" : "Boom Lift Reach Specs"}
              <span className="text-purple-700/70 font-normal">— used by the install height reach chart</span>
            </div>
            <div className="md:col-span-3">
              <Label className="text-xs">Horizontal Reach (ft)</Label>
              <Input
                type="number"
                step="0.5"
                value={it.horizontal_boom_reach_feet || 0}
                onFocus={(e) => e.target.select()}
                onChange={(e) => update(origIndex, { horizontal_boom_reach_feet: parseFloat(e.target.value) || 0 })}
                className="h-8 mt-0.5"
              />
            </div>
            <div className="md:col-span-3">
              <Label className="text-xs">Total Boom Height (ft)</Label>
              <Input
                type="number"
                step="0.5"
                value={it.total_boom_height_feet || 0}
                onFocus={(e) => e.target.select()}
                onChange={(e) => update(origIndex, { total_boom_height_feet: parseFloat(e.target.value) || 0 })}
                className="h-8 mt-0.5"
              />
            </div>
            <div className="md:col-span-3">
              <Label className="text-xs">Deployed Truck Width (ft)</Label>
              <Input
                type="number"
                step="0.1"
                value={it.deployed_truck_width_feet || 0}
                onFocus={(e) => e.target.select()}
                onChange={(e) => update(origIndex, { deployed_truck_width_feet: parseFloat(e.target.value) || 0 })}
                className="h-8 mt-0.5"
              />
            </div>
            <div className="md:col-span-3">
              <Label className="text-xs">Vert Safety Margin (ft)</Label>
              <Input
                type="number"
                step="0.5"
                value={it.vertical_reach_safety_margin_feet ?? 2}
                onFocus={(e) => e.target.select()}
                onChange={(e) => update(origIndex, { vertical_reach_safety_margin_feet: parseFloat(e.target.value) || 0 })}
                className="h-8 mt-0.5"
              />
            </div>

            {/* Primary owned go-to lift (owned booms only) */}
            {mode === "owned" && (
              <div className="md:col-span-12 -mb-1">
                <label className="flex items-center gap-1.5 cursor-pointer text-xs">
                  <Checkbox
                    checked={!!it.is_primary_owned}
                    onCheckedChange={(c) => update(origIndex, { is_primary_owned: !!c })}
                  />
                  <span className="font-semibold text-emerald-800">⭐ Primary owned lift (my go-to for normal use)</span>
                  <span className="text-emerald-700/70 font-normal">— auto-selected on any job it can reach</span>
                </label>
              </div>
            )}

            {/* Auto-pick-by-height + idle running cost */}
            <div className="md:col-span-12 mt-1 pt-2 border-t border-purple-200/50 grid md:grid-cols-12 gap-2 items-end">
              <div className="md:col-span-3 flex items-end">
                <label className="flex items-center gap-1.5 cursor-pointer text-xs mb-2">
                  <Checkbox
                    checked={!!it.is_default_for_height}
                    onCheckedChange={(c) => update(origIndex, { is_default_for_height: !!c })}
                  />
                  <span className="font-medium text-purple-900">Default pick for height range</span>
                </label>
              </div>
              <div className="md:col-span-2">
                <Label className="text-xs">Min Install Ht (ft)</Label>
                <Input
                  type="number"
                  value={it.default_height_min_feet || 0}
                  disabled={!it.is_default_for_height}
                  onFocus={(e) => e.target.select()}
                  onChange={(e) => update(origIndex, { default_height_min_feet: parseFloat(e.target.value) || 0 })}
                  className="h-8 mt-0.5"
                />
              </div>
              <div className="md:col-span-2">
                <Label className="text-xs">Max Install Ht (ft)</Label>
                <Input
                  type="number"
                  value={it.default_height_max_feet || 0}
                  disabled={!it.is_default_for_height}
                  onFocus={(e) => e.target.select()}
                  onChange={(e) => update(origIndex, { default_height_max_feet: parseFloat(e.target.value) || 0 })}
                  className="h-8 mt-0.5"
                />
              </div>
              <div className="md:col-span-3">
                <Label className="text-xs">Idle Running $/hr (on-site)</Label>
                <Input
                  type="number"
                  step="0.01"
                  value={it.idle_running_cost_per_hour || 0}
                  onFocus={(e) => e.target.select()}
                  onChange={(e) => update(origIndex, { idle_running_cost_per_hour: parseFloat(e.target.value) || 0 })}
                  className="h-8 mt-0.5"
                />
              </div>
              <div className="md:col-span-2 text-[10px] text-purple-700/80 pb-1.5">
                Charged on top of rental — fuel + wear while running idle on-site.
              </div>
            </div>
          </div>
        )}
        {showFuel && (
          <div className="grid md:grid-cols-12 gap-2 mt-2 p-2 rounded-md bg-emerald-100/40 border border-emerald-200/60">
            <div className="md:col-span-3">
              <Label className="text-xs flex items-center gap-1"><Fuel className="w-3 h-3 text-emerald-700" /> Fuel Type</Label>
              <Select value={it.fuel_type || "gasoline"} onValueChange={(v) => update(origIndex, { fuel_type: v })}>
                <SelectTrigger className="h-8 mt-0.5"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {FUEL_TYPES.map(c => <SelectItem key={c.value} value={c.value}>{c.label}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="md:col-span-2">
              <Label className="text-xs">MPG</Label>
              <Input type="number" step="0.1" value={it.mpg || 0} onFocus={e => e.target.select()} onChange={(e) => update(origIndex, { mpg: parseFloat(e.target.value) || 0 })} className="h-8 mt-0.5" />
            </div>
            <div className="md:col-span-7 flex items-end">
              <p className="text-[11px] text-emerald-800/70 mb-1.5">Used to calculate travel fuel cost from the shop to the job site.</p>
            </div>
          </div>
        )}
        <div className="grid md:grid-cols-12 gap-2 mt-2">
          {mode === "rented" && (
            <div className="md:col-span-3">
              <Label className="text-xs">Rental Company</Label>
              <Input value={it.rental_company || ""} onChange={(e) => update(origIndex, { rental_company: e.target.value })} className="h-7 text-xs mt-0.5" placeholder="Sunbelt, United, etc." />
            </div>
          )}
          <div className={mode === "rented" ? "md:col-span-8" : "md:col-span-11"}>
            <Label className="text-xs">Notes</Label>
            <Input value={it.notes || ""} onChange={(e) => update(origIndex, { notes: e.target.value })} className="h-7 text-xs mt-0.5" />
          </div>
          <div className="md:col-span-1 flex items-end justify-end">
            <Button size="sm" variant="ghost" onClick={() => removeItem(origIndex)} className="text-red-500 hover:bg-red-50 h-7 w-7 p-0">
              <Trash2 className="w-3.5 h-3.5" />
            </Button>
          </div>
        </div>
      </div>
    );
  };

  if (loading) return <div className="p-8 text-slate-600">Loading...</div>;

  const renderSection = (list, mode) => (
    <div className="space-y-3">
      <div className="flex justify-end">
        <Button onClick={() => addItem(mode)} variant="outline" size="sm">
          <Plus className="w-4 h-4 mr-1" /> Add {mode === "owned" ? "Owned" : "Rented"} Equipment
        </Button>
      </div>
      {list.length === 0 ? (
        <div className="text-center py-10 text-slate-400 border-2 border-dashed border-slate-200 rounded-lg">
          No {mode} equipment yet.
        </div>
      ) : list.map((it) => {
        const origIndex = items.indexOf(it);
        return renderRow(it, origIndex, mode);
      })}
    </div>
  );

  return (
    <Card className="bg-white border-0 shadow-sm">
      <CardHeader className="flex flex-row items-center justify-between">
        <div>
          <CardTitle>
            {scope === "boom" ? "Boom Lifts" : "Construction Equipment"} ({scopedItems.length})
          </CardTitle>
          <CardDescription className="mt-1">
            {scope === "boom"
              ? "Boom lifts & boom trucks. Reach specs feed the install height reach chart. Owned items use flat rates; rented use daily/weekly/monthly."
              : "Owned equipment uses flat rates. Rented equipment uses daily/weekly/monthly. Trucks (owned) can have an MPG for travel fuel calculations."}
          </CardDescription>
        </div>
        <Button onClick={saveAll} disabled={saving} className="bg-purple-600 hover:bg-purple-700 text-white">
          <Save className="w-4 h-4 mr-1" /> {saving ? "Saving..." : "Save All"}
        </Button>
      </CardHeader>
      <CardContent>
        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <TabsList className="grid grid-cols-2 w-full max-w-md mb-4">
            <TabsTrigger value="owned" className="gap-2">
              <Home className="w-4 h-4" /> Owned ({ownedItems.length})
            </TabsTrigger>
            <TabsTrigger value="rented" className="gap-2">
              <Building2 className="w-4 h-4" /> Rented ({rentedItems.length})
            </TabsTrigger>
          </TabsList>

          <TabsContent value="owned">{renderSection(ownedItems, "owned")}</TabsContent>
          <TabsContent value="rented">{renderSection(rentedItems, "rented")}</TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  );
}

import React, { useMemo } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Plus, Trash2, Sparkles, HardHat, AlertCircle, Clock } from "lucide-react";

const BOOM_TYPES = new Set(["boom_lift", "boom_truck"]);
// Held/blank values render an em-dash instead of laundering into $0.00.
const fmtMoney = (v) => (Number.isFinite(v) ? `$${v.toFixed(2)}` : "—");
import {
  suggestEquipmentForProject,
  selectedEquipmentFromInventory,
  recalcEquipmentRow,
  durationUnitLabel,
  isOwnedEquipment,
  suggestCrewSize,
} from "./equipmentSuggester";
import { channelDraftValue, channelNumber, issuesForField } from "./channelLetterPricingAvailability";

const fmt = (v) => (Number.isFinite(v) ? `$${v.toFixed(2)}` : "—");

export default function EquipmentSelector({
  selectedEquipment = [],
  onChange,
  equipmentInventory = [],
  items = [],
  projectLaborHours = 0,
  crewSize = 0,
  issues = [],
}) {
  // On-site crew size — the actual assigned crew wins, otherwise the suggested crew.
  // Used to convert man-hours into on-site clock time for rental durations.
  const effectiveCrewSize = crewSize > 0 ? crewSize : suggestCrewSize(items);

  const activeInventory = useMemo(
    () => equipmentInventory.filter((e) => e.is_active !== false),
    [equipmentInventory]
  );

  const suggestions = useMemo(
    () => suggestEquipmentForProject(items, activeInventory),
    [items, activeInventory]
  );

  const selectedIds = new Set(selectedEquipment.map((e) => e.equipment_id));

  const handleAdd = (inv) => {
    if (!inv || selectedIds.has(inv.id)) return;
    const row = selectedEquipmentFromInventory(inv, projectLaborHours, effectiveCrewSize);
    onChange([...selectedEquipment, row]);
  };

  const handleAcceptSuggestion = (inv) => handleAdd(inv);

  const handleAcceptAllSuggestions = () => {
    const toAdd = suggestions
      .filter((s) => !selectedIds.has(s.id))
      .map((s) => selectedEquipmentFromInventory(s, projectLaborHours, effectiveCrewSize));
    if (toAdd.length === 0) return;
    onChange([...selectedEquipment, ...toAdd]);
  };

  const handleUpdate = (idx, patch) => {
    const next = [...selectedEquipment];
    next[idx] = recalcEquipmentRow({ ...next[idx], ...patch });
    onChange(next);
  };

  // Pricing diagnostics — per-field aria-invalid + inline message.
  const rowIssues = (idx, field) => issuesForField(issues, field, null, idx);
  const rowInvalid = (idx, field) => rowIssues(idx, field).length > 0;
  const rowAria = (idx, field) => (rowInvalid(idx, field)
    ? { "aria-invalid": true, "aria-describedby": `cle-${idx}-${field}-issue` }
    : {});
  const RowIssue = ({ idx, field }) => {
    const fi = rowIssues(idx, field);
    if (!fi.length) return null;
    return (
      <p id={`cle-${idx}-${field}-issue`} className="text-[10px] text-red-600 mt-0.5" role="alert">
        {fi[0].message}
      </p>
    );
  };

  const handleRemove = (idx) => {
    if (!confirm(`Remove "${selectedEquipment[idx]?.equipment_name || "this equipment"}"?`)) return;
    const next = [...selectedEquipment];
    next.splice(idx, 1);
    onChange(next);
  };

  const totalCost = selectedEquipment.reduce(
    (s, e) => {
      if (s === null) return null;
      const v = channelNumber(e.total_cost);
      return v === null ? null : s + v;
    },
    0
  );

  // Inventory items not yet selected — used for the "Add" dropdown
  const addableInventory = activeInventory.filter((e) => !selectedIds.has(e.id));

  const newSuggestions = suggestions.filter((s) => !selectedIds.has(s.id));

  return (
    <div className="space-y-3">
      {/* Suggestions card */}
      {newSuggestions.length > 0 && (
        <Card className="bg-amber-50 border-amber-200">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm flex items-center gap-2 text-amber-900">
              <Sparkles className="w-4 h-4" /> Suggested Equipment
            </CardTitle>
            <p className="text-xs text-amber-800">
              Based on your line items, we recommend the following equipment.
            </p>
          </CardHeader>
          <CardContent className="space-y-2">
            {newSuggestions.map((s) => (
              <div
                key={s.id}
                className="flex items-center justify-between bg-white rounded-md border border-amber-200 px-3 py-2"
              >
                <div className="text-sm">
                  <div className="font-medium">{s.equipment_name}</div>
                  <div className="text-xs text-slate-500 capitalize">
                    {s.equipment_type?.replace("_", " ")}
                    {s.max_height_feet ? ` · ${s.max_height_feet}ft max` : ""}
                    {s.ownership ? ` · ${s.ownership}` : ""}
                  </div>
                </div>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => handleAcceptSuggestion(s)}
                  className="h-8 text-xs bg-white"
                >
                  <Plus className="w-3 h-3 mr-1" /> Add
                </Button>
              </div>
            ))}
            {newSuggestions.length > 1 && (
              <Button
                size="sm"
                onClick={handleAcceptAllSuggestions}
                className="w-full bg-amber-600 hover:bg-amber-700 text-white"
              >
                Accept All Suggestions
              </Button>
            )}
          </CardContent>
        </Card>
      )}

      {/* Selected equipment list */}
      <Card className="bg-white border-0 shadow-sm">
        <CardHeader className="pb-3 flex flex-row items-center justify-between flex-wrap gap-2">
          <div>
            <CardTitle className="text-lg flex items-center gap-2">
              <HardHat className="w-5 h-5 text-purple-600" />
              Selected Equipment ({selectedEquipment.length})
            </CardTitle>
            <p className="text-xs text-slate-500 mt-1">
              At least one piece of equipment is required.
            </p>
          </div>
          {addableInventory.length > 0 ? (
            <Select
              key={selectedEquipment.length}
              onValueChange={(val) => {
                const inv = activeInventory.find((e) => e.id === val);
                if (inv) handleAdd(inv);
              }}
            >
              <SelectTrigger className="w-60 h-9 text-sm bg-purple-50 border-purple-300 text-purple-800 font-semibold hover:bg-purple-100">
                <Plus className="w-4 h-4 mr-1" />
                <SelectValue placeholder="Add another piece of equipment..." />
              </SelectTrigger>
              <SelectContent>
                {addableInventory.map((e) => (
                  <SelectItem key={e.id} value={e.id}>
                    {e.equipment_name}
                    {e.max_height_feet ? ` (${e.max_height_feet}ft)` : ""}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          ) : (
            <span className="text-xs text-slate-400 italic">
              All inventory equipment has been added
            </span>
          )}
        </CardHeader>
        <CardContent>
          {selectedEquipment.length === 0 ? (
            <div className="border-2 border-dashed border-red-200 bg-red-50/30 rounded-lg p-8 text-center">
              <AlertCircle className="w-8 h-8 text-red-400 mx-auto mb-2" />
              <p className="text-sm text-red-700 font-medium">No equipment selected</p>
              <p className="text-xs text-red-600 mt-1">
                Add equipment from the dropdown above or accept a suggestion.
              </p>
              {activeInventory.length === 0 && (
                <p className="text-xs text-slate-500 mt-3">
                  Your equipment inventory is empty. Add equipment in the Inventory page first.
                </p>
              )}
            </div>
          ) : (
            <div className="space-y-2">
              {selectedEquipment.map((row, idx) => (
                <div
                  key={idx}
                  className="border border-slate-200 rounded-lg p-3 bg-slate-50/50"
                >
                  <div className="grid md:grid-cols-12 gap-2 items-end">
                    <div className="md:col-span-4">
                      <Label className="text-xs">Equipment</Label>
                      <div className="text-sm font-medium mt-0.5">{row.equipment_name}</div>
                      <div className="text-xs text-slate-500 capitalize">
                        {row.equipment_type?.replace("_", " ")} · {row.pricing_mode?.replace(/_/g, " ")}
                      </div>
                    </div>
                    <div className="md:col-span-2">
                      <Label className="text-xs">Duration ({durationUnitLabel(row.pricing_mode)})</Label>
                      <Input
                        type="number"
                        step="0.5"
                        value={row.duration}
                        onFocus={(e) => e.target.select()}
                        onChange={(e) =>
                          handleUpdate(idx, { duration: channelDraftValue(e.target.value) })
                        }
                        className={`h-8 mt-0.5 ${rowInvalid(idx, "duration") ? "border-red-500" : ""}`}
                        disabled={
                          row.pricing_mode === "owned_flat" ||
                          row.pricing_mode === "per_project_flat"
                        }
                        {...rowAria(idx, "duration")}
                      />
                      <RowIssue idx={idx} field="duration" />
                    </div>
                    <div className="md:col-span-2">
                      <Label className="text-xs">Unit Cost</Label>
                      <Input
                        type="number"
                        step="0.01"
                        value={row.unit_cost}
                        onFocus={(e) => e.target.select()}
                        onChange={(e) =>
                          handleUpdate(idx, { unit_cost: channelDraftValue(e.target.value) })
                        }
                        className={`h-8 mt-0.5 ${rowInvalid(idx, "unit_cost") ? "border-red-500" : ""}`}
                        {...rowAria(idx, "unit_cost")}
                      />
                      <RowIssue idx={idx} field="unit_cost" />
                    </div>
                    <div className="md:col-span-3">
                      {isOwnedEquipment(row) ? (
                        <span className="text-[11px] text-emerald-700 bg-emerald-50 border border-emerald-200 rounded px-2 py-1 inline-block">
                          Owned — no delivery fee
                        </span>
                      ) : (
                        <label className="flex items-center gap-1.5 cursor-pointer text-xs mb-1">
                          <Checkbox
                            checked={!!row.include_delivery}
                            onCheckedChange={(c) => handleUpdate(idx, { include_delivery: !!c })}
                          />
                          <span>Delivery/Pickup ({fmt(row.delivery_pickup_cost)})</span>
                        </label>
                      )}
                    </div>
                    <div className="md:col-span-1 flex items-end justify-end">
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => handleRemove(idx)}
                        className="text-red-500 hover:bg-red-50 h-8 w-8 p-0"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </Button>
                    </div>
                  </div>
                  {BOOM_TYPES.has(row.equipment_type) && (parseFloat(row.idle_running_cost_per_hour) || 0) > 0 && (
                    <div className="mt-2 pt-2 border-t border-slate-200 grid md:grid-cols-12 gap-2 items-end bg-amber-50/50 -mx-3 -mb-3 px-3 py-2 rounded-b-lg">
                      <div className="md:col-span-5 flex items-center gap-1.5 text-xs text-amber-900">
                        <Clock className="w-3.5 h-3.5" />
                        <span className="font-medium">Idle running on-site</span>
                        <span className="text-amber-700/80">— added to rental rate</span>
                      </div>
                      <div className="md:col-span-2">
                        <Label className="text-xs">Idle Hours</Label>
                        <Input
                          type="number"
                          step="0.25"
                          value={row.idle_hours || 0}
                          onFocus={(e) => e.target.select()}
                          onChange={(e) =>
                            handleUpdate(idx, { idle_hours: channelDraftValue(e.target.value) })
                          }
                          className={`h-8 mt-0.5 ${rowInvalid(idx, "idle_hours") ? "border-red-500" : ""}`}
                          {...rowAria(idx, "idle_hours")}
                        />
                      </div>
                      <div className="md:col-span-2">
                        <Label className="text-xs">$/hr Idle</Label>
                        <Input
                          type="number"
                          step="0.01"
                          value={row.idle_running_cost_per_hour || 0}
                          onFocus={(e) => e.target.select()}
                          onChange={(e) =>
                            handleUpdate(idx, { idle_running_cost_per_hour: channelDraftValue(e.target.value) })
                          }
                          className={`h-8 mt-0.5 ${rowInvalid(idx, "idle_running_cost_per_hour") ? "border-red-500" : ""}`}
                          {...rowAria(idx, "idle_running_cost_per_hour")}
                        />
                      </div>
                      <div className="md:col-span-3 text-right">
                        <div className="text-[10px] text-amber-800">Idle Cost</div>
                        <div className="text-sm font-semibold tabular-nums text-amber-900">
                          {fmtMoney(row.idle_cost)}
                        </div>
                      </div>
                    </div>
                  )}
                  <div className="flex justify-end mt-2 pt-2 border-t border-slate-200 text-sm">
                    <span className="text-slate-600 mr-2">Line Total:</span>
                    <span className="font-semibold tabular-nums">{fmt(row.total_cost)}</span>
                  </div>
                </div>
              ))}
              <div className="flex justify-end pt-2 border-t border-slate-200">
                <div className="text-right">
                  <div className="text-xs text-slate-500">Total Equipment Cost</div>
                  <div className="text-lg font-bold tabular-nums">{fmt(totalCost)}</div>
                </div>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState } from "react";
import { Slider } from "@/components/ui/slider";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { AlertTriangle, AlertCircle, CheckCircle2, BarChart3, ChevronDown, ChevronUp } from "lucide-react";
import BoomLiftReachChart from "./BoomLiftReachChart";

// Dynamic-color install height slider.
//   <= 39 ft  -> green (safe / ladders or small lifts)
//   40-54 ft  -> yellow ("Can we reach from our parking location?")
//   >= 55 ft  -> red   ("Rental Boom Lift Required")
const MAX_FT = 180;

const getZone = (h) => {
  if (h >= 55) return {
    key: "red",
    label: "Rental Boom Lift Required",
    Icon: AlertCircle,
    track: "bg-red-500",
    range: "bg-red-500",
    thumb: "border-red-600 bg-red-50",
    bg: "bg-red-50 border-red-200",
    text: "text-red-800",
  };
  if (h >= 40) return {
    key: "yellow",
    label: "Can we reach from our parking location?",
    Icon: AlertTriangle,
    track: "bg-yellow-400",
    range: "bg-yellow-400",
    thumb: "border-yellow-500 bg-yellow-50",
    bg: "bg-yellow-50 border-yellow-200",
    text: "text-yellow-800",
  };
  return {
    key: "green",
    label: "Standard reach — ladders / small lift",
    Icon: CheckCircle2,
    track: "bg-emerald-500",
    range: "bg-emerald-500",
    thumb: "border-emerald-600 bg-emerald-50",
    bg: "bg-emerald-50 border-emerald-200",
    text: "text-emerald-800",
  };
};

export default function InstallHeightSlider({ value, onChange }) {
  const h = parseFloat(value) || 0;
  const zone = getZone(h);
  const Icon = zone.Icon;
  const [showChart, setShowChart] = useState(false);

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-2">
        <Input
          type="number"
          value={value}
          onFocus={(e) => e.target.select()}
          onChange={(e) => onChange(parseFloat(e.target.value) || 0)}
          className="h-9 w-24"
        />
        <span className="text-xs text-slate-500">ft</span>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={() => setShowChart((s) => !s)}
          className="ml-auto h-8 text-xs gap-1.5"
          title="Show / hide boom lift reach chart"
        >
          <BarChart3 className="w-3.5 h-3.5 text-purple-600" />
          Reach Chart
          {showChart ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
        </Button>
      </div>
      <div className="px-1">
        <Slider
          value={[Math.min(h, MAX_FT)]}
          min={0}
          max={MAX_FT}
          step={1}
          onValueChange={(v) => onChange(v[0])}
          colorClass={zone.range}
        />
        <div className="flex justify-between text-[10px] text-slate-400 mt-1 px-0.5">
          <span>0</span>
          <span className="text-emerald-600">40</span>
          <span className="text-yellow-600">55</span>
          <span>120</span>
          <span>{MAX_FT}+</span>
        </div>
      </div>
      <div className={`flex items-center gap-2 px-2.5 py-1.5 rounded-md border text-xs ${zone.bg} ${zone.text}`}>
        <Icon className="w-3.5 h-3.5 shrink-0" />
        <span className="font-medium">{zone.label}</span>
      </div>

      {showChart && (
        <div className="border border-purple-200 bg-purple-50/30 rounded-lg p-3">
          <BoomLiftReachChart installationHeightFeet={h} />
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ChevronDown, ChevronRight, Copy, Trash2, Sliders } from "lucide-react";
import MaterialsList from "./MaterialsList";
import InstallTypePicker from "./InstallTypePicker";
import LetterSizePicker from "./LetterSizePicker";
import ConditionPicker from "./ConditionPicker";
import WallMaterialPicker from "./WallMaterialPicker";
import CostBreakdownBar from "./CostBreakdownBar";
import InstallHeightSlider from "./InstallHeightSlider";
import { TYPE_LABELS } from "./installCalculator";
import { WALL_MATERIAL_MAP } from "./wallMaterials";
import { channelDraftValue, issuesForField } from "./channelLetterPricingAvailability";

// Held/blank values render an em-dash instead of laundering into $0.00.
const fmt = (v) => (Number.isFinite(v) ? `$${v.toFixed(2)}` : "—");

const TYPE_BADGE_COLOR = {
  flush_mount: "bg-blue-50 text-blue-700 border-blue-200",
  halo_lit: "bg-amber-50 text-amber-700 border-amber-200",
  raceway: "bg-purple-50 text-purple-700 border-purple-200",
  dimensional_lettering: "bg-teal-50 text-teal-700 border-teal-200",
};

export default function InstallLineItem({ item, index, inventory, settings = {}, onUpdate, onRemove, onDuplicate, compact = false, issues = [] }) {
  const [expanded, setExpanded] = useState(!compact);
  const [advancedOpen, setAdvancedOpen] = useState(false);
  const isRaceway = item.installation_type === "raceway";

  // Pricing diagnostics — per-field aria-invalid + inline message. Item-level
  // issues carry index = item index; material issues on this item use
  // different field names (unit_cost/quantity) so they never collide here.
  const fieldIssues = (field) => issuesForField(issues, field, null, index);
  const invalidCls = (field) => (fieldIssues(field).length ? "border-red-500" : "");
  const ariaFor = (field) => (fieldIssues(field).length
    ? { "aria-invalid": true, "aria-describedby": `cli-${index}-${field}-issue` }
    : {});
  const FieldIssue = ({ field }) => {
    const fi = fieldIssues(field);
    if (!fi.length) return null;
    return (
      <p id={`cli-${index}-${field}-issue`} className="text-[10px] text-red-600 mt-0.5" role="alert">
        {fi[0].message}
      </p>
    );
  };

  // Count active "advanced" toggles to show on the collapsed header
  const activeConditionsCount = [
    item.thick_hollow_walls, item.parapet, item.poor_electrical_access,
    item.escort_required, item.badging_checkin, item.after_hours_weekend,
    item.set_hours_installation, item.poor_site_access
  ].filter(Boolean).length;

  // Sync expanded state when parent toggles compact mode globally
  useEffect(() => {
    setExpanded(!compact);
  }, [compact]);

  const update = (patch) => onUpdate({ ...item, ...patch });

  const wallMat = WALL_MATERIAL_MAP[item.wall_material];

  const conditionBadges = [];
  if (wallMat) conditionBadges.push({ label: wallMat.label, color: "bg-purple-50 text-purple-700 border-purple-200" });
  if (item.thick_hollow_walls) conditionBadges.push({ label: "Thick Walls", color: "bg-orange-50 text-orange-700 border-orange-200" });
  if (item.parapet) conditionBadges.push({ label: "Parapet", color: "bg-red-50 text-red-700 border-red-200" });
  if (item.poor_electrical_access) conditionBadges.push({ label: "Poor Electrical", color: "bg-yellow-50 text-yellow-800 border-yellow-200" });
  if (item.escort_required) conditionBadges.push({ label: "Escort Req'd", color: "bg-sky-50 text-sky-700 border-sky-200" });
  if (item.badging_checkin) conditionBadges.push({ label: "Badging/Check-in", color: "bg-indigo-50 text-indigo-700 border-indigo-200" });
  if (item.after_hours_weekend) conditionBadges.push({ label: "After-Hours", color: "bg-violet-50 text-violet-700 border-violet-200" });
  if (item.set_hours_installation) conditionBadges.push({ label: "Set-Hours", color: "bg-teal-50 text-teal-700 border-teal-200" });
  if (item.poor_site_access) conditionBadges.push({ label: "Poor Site Access", color: "bg-rose-50 text-rose-700 border-rose-200" });

  return (
    <Card className="border border-slate-200 shadow-sm overflow-hidden">
      {/* Header */}
      <div className="flex items-center gap-2 px-4 py-3 bg-slate-50 border-b border-slate-100 flex-wrap">
        <button type="button" onClick={() => setExpanded(e => !e)} className="text-slate-500 hover:text-slate-900">
          {expanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
        </button>
        <span className="text-xs font-semibold text-slate-500 w-6">#{index + 1}</span>
        <Input
          value={item.description || ""}
          onChange={(e) => update({ description: e.target.value })}
          placeholder={`${TYPE_LABELS[item.installation_type]} — describe this line...`}
          className="h-8 text-sm flex-1 bg-white min-w-[160px]"
          onClick={(e) => e.stopPropagation()}
        />
        <Badge variant="outline" className={`capitalize ${TYPE_BADGE_COLOR[item.installation_type]}`}>
          {TYPE_LABELS[item.installation_type]}
        </Badge>
        {item.__held && (
          <Badge variant="outline" className="text-[10px] text-amber-700 border-amber-300 bg-amber-50">
            Saved value — not repriced
          </Badge>
        )}
        {conditionBadges.map((b, i) => (
          <Badge key={i} variant="outline" className={`text-[10px] ${b.color}`}>
            {b.label}
          </Badge>
        ))}
        <Badge variant="outline" className="bg-slate-100 text-slate-700 font-semibold tabular-nums">
          {fmt(item.item_total_cost)}
        </Badge>
        <Button variant="ghost" size="sm" onClick={onDuplicate} className="h-7 w-7 p-0 text-slate-500 hover:bg-slate-200" title="Duplicate">
          <Copy className="w-3.5 h-3.5" />
        </Button>
        <Button variant="ghost" size="sm" onClick={onRemove} className="h-7 w-7 p-0 text-red-500 hover:bg-red-50" title="Remove">
          <Trash2 className="w-3.5 h-3.5" />
        </Button>
      </div>

      {/* Cost breakdown bar — always visible */}
      <div className="px-4 py-2 border-b border-slate-100 bg-white">
        <CostBreakdownBar
          labor={item.labor_cost || 0}
          materials={item.materials_cost || 0}
        />
      </div>

      {expanded && (
        <CardContent className="p-4 space-y-4">
          {/* Quick summary */}
          <div className="text-xs text-slate-500">
            {isRaceway
              ? `${item.qty_letters} letters · ${item.raceway_length_feet} ft raceway · ${item.installation_height_feet} ft high`
              : `${item.qty_letters} letters · ${item.installation_height_feet} ft high`
            }
          </div>

          {/* Interior / Exterior override — defaults to project setting */}
          <div className="bg-slate-50 rounded-lg p-3 border border-slate-200">
            <div className="flex items-center gap-2 mb-2">
              <Label className="text-xs font-semibold text-slate-700">Installation Environment</Label>
              <span className="text-[10px] text-slate-400">(overrides project default for this line item)</span>
            </div>
