import { useState, useEffect, useMemo, useCallback } from "react";
import { ChannelLetterInstallInventory, ChannelLetterInstallation } from "@/api/gatedEntities";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { User } from "@/api/entities";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { Plus, Save, Search, Package2, X, Lock } from "lucide-react";
import MaterialItemCard from "./MaterialItemCard";
import BulkActionsBar from "./BulkActionsBar";
import BulkPriceAdjustDialog from "./BulkPriceAdjustDialog";
import PriceHistoryDialog from "./PriceHistoryDialog";
import { APPLIES_TO_GROUPS, ALL_INSTALL_TYPES, emptyMaterialItem } from "./materialsConstants";
import {
  extractPriceSnapshot, buildPriceHistoryUpdate,
  countInventoryUsage, adjustItemPricing,
} from "./materialsHelpers";

const APPLIES_TO_FILTER = [
  { value: "any", label: "All Groups" },
  ...APPLIES_TO_GROUPS,
];

// Resolve which "applies to" groups an item belongs to.
// Items with no specific applies_to_list (or legacy "all") show in EVERY type section.
const groupsForItem = (it) => {
  const list = Array.isArray(it.applies_to_list) && it.applies_to_list.length > 0
    ? it.applies_to_list
    : (it.applies_to && it.applies_to !== "all" ? [it.applies_to] : []);
  return list.length > 0 ? list : ALL_INSTALL_TYPES;
};

export default function MaterialsInventoryTab() {
  const [items, setItems] = useState([]);
  const [savedSnapshots, setSavedSnapshots] = useState({}); // id -> last saved price snapshot
  const [usageCounts, setUsageCounts] = useState({});
  const [currentUser, setCurrentUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  // Filters
  const [search, setSearch] = useState("");
  const [appliesFilter, setAppliesFilter] = useState("any");

  // State tracking
  const [dirtyIds, setDirtyIds] = useState(new Set());
  const [selectedKeys, setSelectedKeys] = useState(new Set());

  // Dialogs
  const [historyItem, setHistoryItem] = useState(null);
  const [showAdjustDialog, setShowAdjustDialog] = useState(false);

  const isAdmin = currentUser?.role === "admin";
  const readOnly = currentUser && !isAdmin;

  const keyFor = (it) => it.id || it._localKey;

  const load = useCallback(async () => {
    setLoading(true);
    const [data, user, projects] = await Promise.all([
      loadAllEntityRows({ entity: ChannelLetterInstallInventory, sort: "sort_order", label: "Channel Letter installation inventory" }),
      User.me().catch(() => null),
      loadAllEntityRows({ entity: ChannelLetterInstallation, sort: "created_date", label: "Channel Letter projects" }).catch(() => []),
    ]);
    setItems(data);
    setCurrentUser(user);
    setUsageCounts(countInventoryUsage(projects));
    // Snapshot current pricing on load (baseline for change detection)
    const snaps = {};
    for (const it of data) {
      if (it.id) snaps[it.id] = extractPriceSnapshot(it);
    }
    setSavedSnapshots(snaps);
    setDirtyIds(new Set());
    setSelectedKeys(new Set());
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const markDirty = (idx) => {
    setDirtyIds(prev => {
      const next = new Set(prev);
      next.add(idx);
      return next;
    });
  };

  const update = (idx, patch) => {
    if (readOnly) return;
    const next = [...items];
    next[idx] = { ...next[idx], ...patch };
    setItems(next);
    markDirty(idx);
  };

  const addItem = () => {
    if (readOnly) return;
    const newItem = { ...emptyMaterialItem(), _new: true, _localKey: `new-${Date.now()}` };
    const next = [...items, newItem];
    setItems(next);
    markDirty(next.length - 1);
  };

  const duplicateItem = (idx) => {
    if (readOnly) return;
    const original = items[idx];
    const { id, _new, _localKey, price_history, ...rest } = original;
    const copy = {
      ...rest,
      item_name: `${original.item_name || "Item"} (Copy)`,
      _new: true,
      _localKey: `new-${Date.now()}`,
      price_history: [],
    };
    const next = [...items, copy];
    setItems(next);
    markDirty(next.length - 1);
  };

  const removeItem = async (idx) => {
    if (readOnly) return;
    const item = items[idx];
    if (item.id) {
      if (!confirm(`Delete "${item.item_name || "this item"}"?`)) return;
      try {
        await ChannelLetterInstallInventory.delete(item.id);
      } catch (e) {
        console.error("Delete failed:", e);
        alert("Delete failed: " + (e.message || "unknown error"));
        return;
      }
    }
    const next = [...items];
    next.splice(idx, 1);
    setItems(next);
    // re-index dirty set
    const newDirty = new Set();
    dirtyIds.forEach(i => {
      if (i < idx) newDirty.add(i);
      else if (i > idx) newDirty.add(i - 1);
    });
    setDirtyIds(newDirty);
    // remove from selection
    const newSel = new Set(selectedKeys);
    newSel.delete(keyFor(item));
    setSelectedKeys(newSel);
  };

  const saveOne = async (idx) => {
    if (readOnly) return;
    try {
      const it = items[idx];
      const { _new, _localKey, id, ...payload } = it;
      // Append price history if pricing changed
      const prevSnap = id ? savedSnapshots[id] : null;
      const updatedHistory = buildPriceHistoryUpdate(payload, prevSnap, currentUser?.email);
      if (updatedHistory) payload.price_history = updatedHistory;

      let saved;
      if (id) saved = await ChannelLetterInstallInventory.update(id, payload);
      else saved = await ChannelLetterInstallInventory.create(payload);

      // Update local row with returned id and clear dirty flag
      setItems(prev => {
        const next = [...prev];
        next[idx] = { ...saved };
        return next;
      });
      setSavedSnapshots(prev => ({
        ...prev,
        [saved.id]: extractPriceSnapshot(saved),
      }));
      setDirtyIds(prev => {
        const next = new Set(prev);
        next.delete(idx);
        return next;
      });
    } catch (e) {
      console.error("Save failed:", e);
      alert("Save failed: " + (e.message || "unknown error"));
    }
  };

  const saveAll = async () => {
    if (readOnly) return;
    setSaving(true);
    const toSave = [...dirtyIds];
    for (const idx of toSave) {
      // eslint-disable-next-line no-await-in-loop
      await saveOne(idx);
    }
    setSaving(false);
  };

  // Bulk actions ----------------------------------------------------
  const toggleSelect = (it, on) => {
    const k = keyFor(it);
    setSelectedKeys(prev => {
      const next = new Set(prev);
      if (on) next.add(k); else next.delete(k);
      return next;
    });
  };

  const selectedIndices = useMemo(() => {
    const idxs = [];
    items.forEach((it, idx) => {
      if (selectedKeys.has(keyFor(it))) idxs.push(idx);
    });
    return idxs;
  }, [items, selectedKeys]);

  const clearSelection = () => setSelectedKeys(new Set());

  const bulkDuplicate = () => {
    if (readOnly || selectedIndices.length === 0) return;
    let next = [...items];
    const newDirty = new Set(dirtyIds);
    for (const idx of selectedIndices) {
      const original = next[idx];
      const { id, _new, _localKey, price_history, ...rest } = original;
      next.push({
        ...rest,
        item_name: `${original.item_name || "Item"} (Copy)`,
        _new: true,
        _localKey: `new-${Date.now()}-${idx}`,
        price_history: [],
      });
      newDirty.add(next.length - 1);
    }
    setItems(next);
    setDirtyIds(newDirty);
    clearSelection();
  };

  const bulkDelete = async () => {
    if (readOnly || selectedIndices.length === 0) return;
    if (!confirm(`Delete ${selectedIndices.length} item(s)? This cannot be undone.`)) return;
    const idsToDelete = selectedIndices.map(i => items[i].id).filter(Boolean);
    try {
      await Promise.all(idsToDelete.map(id => ChannelLetterInstallInventory.delete(id)));
    } catch (e) {
      console.error("Bulk delete failed:", e);
      alert("Delete failed: " + (e.message || "unknown error"));
      return;
    }
    // Rebuild items array
    const next = items.filter((_, idx) => !selectedIndices.includes(idx));
    setItems(next);
    setDirtyIds(new Set());
    clearSelection();
  };

  const bulkToggleAuto = (value) => {
    if (readOnly || selectedIndices.length === 0) return;
    const next = [...items];
    const newDirty = new Set(dirtyIds);
    for (const idx of selectedIndices) {
      next[idx] = { ...next[idx], is_default: value };
      newDirty.add(idx);
    }
    setItems(next);
    setDirtyIds(newDirty);
  };

  const bulkAdjustPrices = (percent) => {
    if (readOnly || selectedIndices.length === 0) return;
    const next = [...items];
    const newDirty = new Set(dirtyIds);
    for (const idx of selectedIndices) {
      const patch = adjustItemPricing(next[idx], percent);
      next[idx] = { ...next[idx], ...patch };
      newDirty.add(idx);
    }
    setItems(next);
    setDirtyIds(newDirty);
  };

  // Auto-save when a card is collapsed
  const handleCardCollapse = (idx) => {
    if (dirtyIds.has(idx) && !readOnly) {
      saveOne(idx);
    }
  };

  // Filtering -------------------------------------------------------
  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    return items
      .map((it, idx) => ({ it, idx }))
      .filter(({ it }) => {
        if (appliesFilter !== "any") {
          const groups = groupsForItem(it);
          if (!groups.includes(appliesFilter)) return false;
        }
        if (q) {
          const haystack = `${it.item_name || ""} ${it.supplier || ""} ${it.notes || ""}`.toLowerCase();
          if (!haystack.includes(q)) return false;
        }
        return true;
      });
  }, [items, search, appliesFilter]);

  // Group items by APPLIES_TO_GROUPS — items can appear in multiple groups.
  const grouped = useMemo(() => {
    const map = new Map();
    for (const { it, idx } of filtered) {
      const groups = groupsForItem(it);
      for (const g of groups) {
        if (!map.has(g)) map.set(g, []);
        map.get(g).push({ it, idx });
      }
    }
    return APPLIES_TO_GROUPS
      .map(g => ({ group: g, rows: map.get(g.value) || [] }))
      .filter(g => g.rows.length > 0);
  }, [filtered]);

  const hasFilters = search || appliesFilter !== "any";
  const clearFilters = () => { setSearch(""); setAppliesFilter("any"); };

  // Count unique filtered items (filtered may contain duplicates if regrouped)
  const uniqueFiltered = useMemo(() => {
    const seen = new Set();
    const out = [];
    for (const row of filtered) {
      const k = keyFor(row.it);
      if (seen.has(k)) continue;
      seen.add(k);
      out.push(row);
    }
    return out;
  }, [filtered]);

  const allFilteredSelected = uniqueFiltered.length > 0 && uniqueFiltered.every(({ it }) => selectedKeys.has(keyFor(it)));
  const toggleSelectAll = (on) => {
    const next = new Set(selectedKeys);
    for (const { it } of uniqueFiltered) {
      if (on) next.add(keyFor(it));
      else next.delete(keyFor(it));
    }
    setSelectedKeys(next);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20 text-slate-500">
        <div className="w-6 h-6 border-2 border-slate-300 border-t-purple-600 rounded-full animate-spin mr-3" />
        Loading materials...
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {readOnly && (
        <div className="bg-amber-50 border border-amber-200 rounded-xl p-3 flex items-center gap-2 text-sm text-amber-800">
          <Lock className="w-4 h-4" />
          <span>
            <strong>View-only mode.</strong> Only administrators can edit the materials inventory.
          </span>
        </div>
      )}

      {/* Sticky toolbar */}
      <div className="sticky top-0 z-30 bg-slate-50 -mx-2 px-2 pt-2 pb-1">
        <div className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm">
          <div className="flex flex-wrap items-center gap-3">
            <div className="flex-1 min-w-[200px] relative">
              <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <Input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search by name, supplier, or notes..."
                className="pl-9 h-10"
              />
            </div>

            <Select value={appliesFilter} onValueChange={setAppliesFilter}>
              <SelectTrigger className="h-10 w-[220px]">
                <SelectValue placeholder="All Groups" />
              </SelectTrigger>
              <SelectContent>
                {APPLIES_TO_FILTER.map(o => (
                  <SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>
                ))}
              </SelectContent>
            </Select>

            {hasFilters && (
              <Button variant="ghost" size="sm" onClick={clearFilters} className="text-slate-500">
                <X className="w-3.5 h-3.5 mr-1" /> Clear
              </Button>
            )}

            {!readOnly && (
              <div className="ml-auto flex items-center gap-2">
                <Button onClick={addItem} variant="outline" className="h-10">
                  <Plus className="w-4 h-4 mr-1" /> Add Material
                </Button>
                <Button
                  onClick={saveAll}
                  disabled={saving || dirtyIds.size === 0}
                  className="bg-purple-600 hover:bg-purple-700 text-white h-10"
                >
                  <Save className="w-4 h-4 mr-1" />
                  {saving ? "Saving..." : dirtyIds.size > 0 ? `Save ${dirtyIds.size} Change${dirtyIds.size !== 1 ? "s" : ""}` : "Saved"}
                </Button>
              </div>
            )}
          </div>

          <div className="flex items-center gap-3 mt-3 text-xs text-slate-500">
            {uniqueFiltered.length > 0 && !readOnly && (
              <label className="flex items-center gap-1.5 cursor-pointer">
                <Checkbox
                  checked={allFilteredSelected}
                  onCheckedChange={(c) => toggleSelectAll(!!c)}
                />
                <span>Select all visible</span>
              </label>
            )}
            <span><strong className="text-slate-700">{items.length}</strong> total materials</span>
            {hasFilters && (
              <span>· Showing <strong className="text-slate-700">{uniqueFiltered.length}</strong> filtered</span>
            )}
            {dirtyIds.size > 0 && (
              <Badge variant="outline" className="bg-amber-50 text-amber-700 border-amber-200 text-[10px]">
                {dirtyIds.size} unsaved — auto-saves when card is collapsed
              </Badge>
            )}
          </div>
        </div>

        <div className="mt-2">
          <BulkActionsBar
            selectedCount={selectedIndices.length}
            onClear={clearSelection}
            onDuplicate={bulkDuplicate}
            onDelete={bulkDelete}
            onToggleAuto={bulkToggleAuto}
            onAdjustPrices={() => setShowAdjustDialog(true)}
            disabled={readOnly}
          />
        </div>
      </div>

      {/* Content */}
      {items.length === 0 ? (
        <div className="bg-white border border-dashed border-slate-300 rounded-xl py-16 text-center">
          <Package2 className="w-12 h-12 text-slate-300 mx-auto mb-3" />
          <h3 className="font-semibold text-slate-700 mb-1">No materials yet</h3>
          <p className="text-sm text-slate-500 mb-4">
            Add your first material to start building your installation inventory.
          </p>
          {!readOnly && (
            <Button onClick={addItem} className="bg-purple-600 hover:bg-purple-700 text-white">
              <Plus className="w-4 h-4 mr-1" /> Add Your First Material
            </Button>
          )}
        </div>
      ) : uniqueFiltered.length === 0 ? (
        <div className="bg-white border border-slate-200 rounded-xl py-12 text-center">
          <p className="text-slate-500 mb-3">No materials match your filters.</p>
          <Button variant="outline" onClick={clearFilters}>
            <X className="w-3.5 h-3.5 mr-1" /> Clear Filters
          </Button>
        </div>
      ) : (
        <div className="space-y-6">
          {grouped.map(({ group, rows }) => (
            <div key={group.value}>
              <div className="flex items-center gap-2 mb-2 px-1">
                <Badge variant="outline" className={`${group.color} text-xs`}>
                  {group.label}
                </Badge>
                <span className="text-xs text-slate-400">
                  {rows.length} item{rows.length !== 1 ? "s" : ""}
                </span>
              </div>
              <div className="space-y-2">
                {rows.map(({ it, idx }) => (
                  <MaterialItemCard
                    key={`${group.value}-${keyFor(it)}`}
                    item={it}
                    isDirty={dirtyIds.has(idx)}
                    isNew={!!it._new}
                    defaultExpanded={!!it._new}
                    selected={selectedKeys.has(keyFor(it))}
                    onSelectChange={(on) => toggleSelect(it, on)}
                    usageCount={it.id ? (usageCounts[it.id] || 0) : 0}
                    readOnly={readOnly}
                    onChange={(patch) => update(idx, patch)}
                    onRemove={() => removeItem(idx)}
                    onDuplicate={() => duplicateItem(idx)}
                    onCollapse={() => handleCardCollapse(idx)}
                    onViewHistory={() => setHistoryItem(it)}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      )}

      <PriceHistoryDialog
        open={!!historyItem}
        onOpenChange={(o) => !o && setHistoryItem(null)}
        item={historyItem}
      />

      <BulkPriceAdjustDialog
        open={showAdjustDialog}
        onOpenChange={setShowAdjustDialog}
        selectedCount={selectedIndices.length}
        onApply={bulkAdjustPrices}
      />
    </div>
  );
}

import React, { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Plus, Trash2, Package, Loader2, ImageIcon } from "lucide-react";
import { materialFromInventory } from "./installCalculator";
import { channelDraftValue, channelNumber, issuesForField } from "./channelLetterPricingAvailability";
import { GenerateImage } from "@/api/integrations";

// Held/blank values render an em-dash instead of laundering into $0.00.
const fmt = (v) => (Number.isFinite(v) ? `$${v.toFixed(2)}` : "—");

export default function MaterialsList({ item, itemIndex = null, inventory, onChange, issues = [] }) {
  const materials = item.materials || [];
  const [generatingIdx, setGeneratingIdx] = useState(null);
  // Material issues carry index = install-item index, itemIndex = material index.
  const matIssues = (field, mi) => issuesForField(issues, field, mi, itemIndex);
  const matInvalid = (field, mi) => matIssues(field, mi).length > 0;

  // Build options of inventory items applicable to this line
  const eligibleInventory = (inventory || []).filter(inv => {
    if (inv.applies_to === "all") return true;
    return inv.applies_to === item.installation_type;
  });

  const addMaterial = (invId) => {
    const inv = inventory.find(i => i.id === invId);
    if (!inv) return;
    if (materials.some(m => m.inventory_item_id === invId)) return;
    const newMat = materialFromInventory(inv, item);
    // pull image from inventory if it exists
    if (inv.image_url) newMat.image_url = inv.image_url;
    onChange([...materials, newMat]);
  };

  const addCustomMaterial = () => {
    onChange([
      ...materials,
      {
        inventory_item_id: null,
        item_name: "Custom item",
        pricing_mode: "custom",
        unit_cost: 0,
        quantity: 1,
        total_cost: 0,
        is_custom: true,
        image_url: "",
      },
    ]);
  };

  const removeMaterial = (idx) => {
    if (!confirm(`Remove "${materials[idx]?.item_name || "this material"}"?`)) return;
    const next = [...materials];
    next.splice(idx, 1);
    onChange(next);
  };

  const updateMaterial = (idx, patch) => {
    const next = [...materials];
    next[idx] = { ...next[idx], ...patch };
    // Null-propagating: a blank/malformed input makes the row total
    // unavailable instead of laundering it to $0.
    const u = channelNumber(next[idx].unit_cost);
    const q = channelNumber(next[idx].quantity);
    next[idx].total_cost = (u === null || q === null) ? null : u * q;
    onChange(next);
  };

  const generateImageForMaterial = async (idx) => {
    const mat = materials[idx];
    const name = (mat.item_name || "").trim();
    if (!name || name === "Custom item") {
      alert("Please name the material first.");
      return;
    }
    setGeneratingIdx(idx);
    try {
      const res = await GenerateImage({
        prompt: `Photograph of "${name}" — a signage installation material or hardware item used by professional sign installers. Product is centered in the frame, full item clearly visible, neutral light background, professional product photography, sharp focus, no people, no text overlay.`,
      });
      if (res?.url) {
        updateMaterial(idx, { image_url: res.url });
      }
    } catch (e) {
      console.error("Image generation failed:", e);
      alert("Image generation failed: " + (e.message || "unknown error"));
    }
    setGeneratingIdx(null);
  };

  const totalMaterials = materials.reduce((s, m) => {
    if (s === null) return null;
    const v = channelNumber(m.total_cost);
    return v === null ? null : s + v;
  }, 0);

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Package className="w-4 h-4 text-slate-500" />
          <span className="text-sm font-medium text-slate-700">Materials</span>
          <span className="text-xs text-slate-400">({materials.length})</span>
        </div>
        <div className="flex items-center gap-2">
          <Select value="" onValueChange={addMaterial}>
            <SelectTrigger className="h-8 text-xs w-auto min-w-[160px]">
              <SelectValue placeholder="+ Add material..." />
            </SelectTrigger>
            <SelectContent>
              {eligibleInventory.length === 0 ? (
                <div className="px-2 py-1.5 text-xs text-slate-500">No inventory items match this install type</div>
              ) : eligibleInventory.map(inv => (
                <SelectItem
                  key={inv.id}
                  value={inv.id}
                  disabled={materials.some(m => m.inventory_item_id === inv.id)}
                >
                  {inv.item_name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={addCustomMaterial}
            className="h-8 text-xs"
          >
            <Plus className="w-3 h-3 mr-1" /> Custom
          </Button>
        </div>
      </div>

      {materials.length === 0 ? (
        <div className="text-xs text-slate-400 italic px-2 py-3 text-center border border-dashed border-slate-200 rounded">
          No materials added. Use the dropdown to add from inventory.
        </div>
      ) : (
        <div className="border border-slate-200 rounded-lg overflow-hidden">
          <table className="w-full text-xs">
            <thead className="bg-slate-50 text-slate-600">
              <tr>
                <th className="text-left px-2 py-1.5 font-medium w-12">Img</th>
                <th className="text-left px-2 py-1.5 font-medium">Item</th>
                <th className="text-right px-2 py-1.5 font-medium w-20">Unit $</th>
                <th className="text-right px-2 py-1.5 font-medium w-16">Qty</th>
                <th className="text-right px-2 py-1.5 font-medium w-20">Total</th>
                <th className="w-8"></th>
              </tr>
            </thead>
            <tbody>
              {materials.map((m, idx) => (
                <tr key={idx} className="border-t border-slate-100">
                  <td className="px-2 py-1">
                    {m.image_url ? (
                      <img
                        src={m.image_url}
                        alt={m.item_name}
                        className="w-10 h-10 object-contain rounded border border-slate-200 bg-white"
                      />
                    ) : (
                      <button
                        type="button"
                        onClick={() => generateImageForMaterial(idx)}
                        disabled={generatingIdx === idx}
                        title="Generate image with AI"
                        className="w-10 h-10 rounded border border-dashed border-slate-300 flex items-center justify-center text-slate-400 hover:bg-slate-50 hover:text-purple-600 disabled:opacity-50"
                      >
                        {generatingIdx === idx ? (
                          <Loader2 className="w-4 h-4 animate-spin" />
                        ) : (
                          <ImageIcon className="w-4 h-4" />
                        )}
                      </button>
                    )}
                  </td>
                  <td className="px-2 py-1">
                    {m.is_custom ? (
                      <Input
                        value={m.item_name || ""}
                        onChange={(e) => updateMaterial(idx, { item_name: e.target.value })}
                        onBlur={() => {
                          // auto-generate image when user finishes naming, if no image yet
                          const name = (m.item_name || "").trim();
                          if (!m.image_url && name && name !== "Custom item" && generatingIdx === null) {
                            generateImageForMaterial(idx);
                          }
                        }}
                        className="h-7 text-xs"
                        placeholder="Custom item name"
                      />
                    ) : (
                      m.item_name
                    )}
                  </td>
                  <td className="px-2 py-1">
                    <Input
                      type="number"
                      step="0.01"
                      value={m.unit_cost ?? ""}
                      onFocus={(e) => e.target.select()}
                      onChange={(e) => updateMaterial(idx, { unit_cost: channelDraftValue(e.target.value) })}
                      className={`h-7 text-xs text-right ${matInvalid("unit_cost", idx) ? "border-red-500" : ""}`}
                      aria-invalid={matInvalid("unit_cost", idx) || undefined}
                      aria-describedby={matInvalid("unit_cost", idx) ? `cli-${itemIndex}-mat-${idx}-unit-issue` : undefined}
                      title={matIssues("unit_cost", idx)[0]?.message}
                    />
                    {matInvalid("unit_cost", idx) && (
                      <p id={`cli-${itemIndex}-mat-${idx}-unit-issue`} className="text-[10px] text-red-600" role="alert">
                        {matIssues("unit_cost", idx)[0].message}
                      </p>
                    )}
                  </td>
                  <td className="px-2 py-1">
                    <Input
                      type="number"
                      step="0.01"
                      value={m.quantity ?? ""}
                      onFocus={(e) => e.target.select()}
                      onChange={(e) => updateMaterial(idx, { quantity: channelDraftValue(e.target.value) })}
                      className={`h-7 text-xs text-right ${matInvalid("quantity", idx) ? "border-red-500" : ""}`}
                      aria-invalid={matInvalid("quantity", idx) || undefined}
                      aria-describedby={matInvalid("quantity", idx) ? `cli-${itemIndex}-mat-${idx}-qty-issue` : undefined}
                      title={matIssues("quantity", idx)[0]?.message}
                    />
                    {matInvalid("quantity", idx) && (
                      <p id={`cli-${itemIndex}-mat-${idx}-qty-issue`} className="text-[10px] text-red-600" role="alert">
                        {matIssues("quantity", idx)[0].message}
                      </p>
                    )}
                  </td>
                  <td className="px-2 py-1 text-right font-medium tabular-nums">{fmt(m.total_cost)}</td>
                  <td className="px-1 py-1">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => removeMaterial(idx)}
                      className="h-6 w-6 p-0 text-red-500 hover:bg-red-50"
                    >
                      <Trash2 className="w-3 h-3" />
                    </Button>
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot className="bg-slate-50 border-t border-slate-200">
              <tr>
                <td colSpan="4" className="px-2 py-1.5 text-right font-medium">Materials Total</td>
                <td className="px-2 py-1.5 text-right font-semibold tabular-nums">{fmt(totalMaterials)}</td>
                <td></td>
              </tr>
            </tfoot>
          </table>
        </div>
      )}
    </div>
  );
}

import React from "react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

// Helper fractions: percentage of face area that needs masking.
// e.g. "1/4" = 25% of the face area gets masked.
export const COVERAGE_FACTORS = [
  "1/8", "1/4", "3/8", "1/2", "5/8", "3/4", "7/8",
  "1", "1-1/8", "1-1/4", "1-3/8", "1-1/2", "1-5/8", "1-3/4", "1-7/8", "2",
];

export const parseImperialFraction = (s) => {
  if (typeof s !== "string") return parseFloat(s) || 0;
  let total = 0;
  let rest = s;
  const [whole, fracPart] = s.split("-");
  if (fracPart !== undefined) {
    total += parseFloat(whole) || 0;
    rest = fracPart;
  }
  const [num, den] = rest.split("/");
  if (den !== undefined) {
    const n = parseFloat(num);
    const d = parseFloat(den);
    if (d) total += n / d;
  } else {
    total += parseFloat(rest) || 0;
  }
  return total;
};

/**
 * Reusable paint-mask + coverage helper input pair.
 *  - faceAreaSqft: the face area to compute coverage from (caller must compute & pass).
 *  - bothSides:    if true, multiplies the helper result by 2.
 *  - value:        current paint_mask_sqft
 *  - factor:       current coverage factor string ("1/4", etc.)
 *  - onChange({ paint_mask_sqft, approx_coverage_factor })
 */
export default function PaintCoverageHelper({
  faceAreaSqft = 0,
  bothSides = false,
  value = 0,
  factor = "1/4",
  onChange,
  className = "",
}) {
  const setFactor = (f) => {
    const frac = parseImperialFraction(f);
    const sides = bothSides ? 2 : 1;
    const calculated = (parseFloat(faceAreaSqft) || 0) * frac * sides;
    onChange({
      paint_mask_sqft: Number.isFinite(calculated) ? calculated : 0,
      approx_coverage_factor: f,
    });
  };

  const setManual = (v) => {
    onChange({
      paint_mask_sqft: parseFloat(v) || 0,
      approx_coverage_factor: factor,
    });
  };

  return (
    <div className={`grid grid-cols-1 md:grid-cols-2 gap-3 ${className}`}>
      <div>
        <Label className="text-xs">Paint Mask Square Feet</Label>
        <Input
          type="number"
          min="0"
          step="0.25"
          value={value || ""}
          onFocus={(e) => e.target.select()}
          onChange={(e) => setManual(e.target.value)}
          className="mt-1"
        />
        <p className="text-[11px] text-slate-500 mt-1">Manually enter sqft or use the helper.</p>
      </div>
      <div>
        <Label className="text-xs">Approx. Coverage Helper</Label>
        <Select value={factor || "1/4"} onValueChange={setFactor}>
          <SelectTrigger className="mt-1">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {COVERAGE_FACTORS.map((f) => (
              <SelectItem key={f} value={f}>{f}</SelectItem>
            ))}
          </SelectContent>
        </Select>
        <p className="text-[11px] text-slate-500 mt-1">
          {faceAreaSqft > 0
            ? <>Face area: <strong>{faceAreaSqft.toFixed(2)} sqft</strong>{bothSides ? " × 2 sides" : ""}</>
            : <>Calculates mask sqft based on face area.</>}
        </p>
      </div>
    </div>
  );
}

import React from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Plus, Trash2, Users, Wand2 } from "lucide-react";
import { recalcPersonnelRow, suggestPersonnelForProject } from "./equipmentSuggester";
import { channelDraftValue, channelNumber, issuesForField } from "./channelLetterPricingAvailability";

// Held/blank values render an em-dash instead of laundering into $0.00.
const fmt = (v) => (Number.isFinite(v) ? `$${v.toFixed(2)}` : "—");

const ROLE_OPTIONS = ["Crew Lead", "Installer", "Helper"];

const emptyRow = () => ({
  name: "",
  role: "Installer",
  hourly_rate: 0,
  hours: 0,
  total_cost: 0,
});

export default function PersonnelSelector({
  personnel = [],
  onChange,
  projectLaborHours = 0,
  roleRates = {},
  items = [],
  issues = [],
}) {
  // Resolve the rate for a given role (fallback to Installer rate, then 0)
  const rateForRole = (role) => {
    const r = parseFloat(roleRates[role]);
    if (!isNaN(r) && r > 0) return r;
    const fallback = parseFloat(roleRates.Installer);
    return !isNaN(fallback) ? fallback : 0;
  };

  const handleAdd = () => {
    const row = emptyRow();
    row.hourly_rate = rateForRole(row.role);
    onChange([...personnel, row]);
  };

  const handleUpdate = (idx, patch) => {
    const next = [...personnel];
    const merged = { ...next[idx], ...patch };
    // When the role changes, auto-fill the rate from the role's setting
    if ("role" in patch && patch.role !== next[idx].role) {
      merged.hourly_rate = rateForRole(patch.role);
    }
    next[idx] = recalcPersonnelRow(merged);
    onChange(next);
  };

  const handleRemove = (idx) => {
    if (!confirm(`Remove "${personnel[idx]?.name || "this person"}"?`)) return;
    const next = [...personnel];
    next.splice(idx, 1);
    onChange(next);
  };

  // Quick-fill: build a suggested crew from project height & letter count.
  // Uses the shared suggestPersonnelForProject helper so the auto-trigger and
  // the manual button produce the exact same crew.
  const handleAutoFillCrew = () => {
    const newCrew = suggestPersonnelForProject(items, projectLaborHours, rateForRole);
    onChange(newCrew);
  };

  // Pricing diagnostics — per-field aria-invalid + inline message.
  const rowIssues = (idx, field) => issuesForField(issues, field, null, idx);
  const rowInvalid = (idx, field) => rowIssues(idx, field).length > 0;
  const rowAria = (idx, field) => (rowInvalid(idx, field)
    ? { "aria-invalid": true, "aria-describedby": `clp-crew-${idx}-${field}-issue` }
    : {});
  const RowIssue = ({ idx, field }) => {
    const fi = rowIssues(idx, field);
    if (!fi.length) return null;
    return (
      <p id={`clp-crew-${idx}-${field}-issue`} className="text-[10px] text-red-600 mt-0.5" role="alert">
        {fi[0].message}
      </p>
    );
  };

  const totalCost = personnel.reduce(
    (s, p) => {
      if (s === null) return null;
      const v = channelNumber(p.total_cost);
      return v === null ? null : s + v;
    },
    0
  );
  const totalHours = personnel.reduce(
    (s, p) => {
      if (s === null) return null;
      const v = channelNumber(p.hours);
      return v === null ? null : s + v;
    },
    0
  );

  return (
    <Card className="bg-white border-0 shadow-sm">
      <CardHeader className="pb-3 flex flex-row items-center justify-between flex-wrap gap-2">
        <div>
          <CardTitle className="text-lg flex items-center gap-2">
            <Users className="w-5 h-5 text-purple-600" />
            Personnel ({personnel.length})
          </CardTitle>
          <p className="text-xs text-slate-500 mt-1">
            Assign crew members and their hours for this job.
          </p>
        </div>
        <div className="flex gap-2">
          <Button
            size="sm"
            variant="outline"
            onClick={handleAutoFillCrew}
            className="h-9 text-xs"
            title="Auto-suggest crew based on project size & height"
          >
            <Wand2 className="w-3.5 h-3.5 mr-1" /> Auto-Suggest Crew
          </Button>
          <Button
            size="sm"
            onClick={handleAdd}
            className="bg-purple-600 hover:bg-purple-700 text-white"
          >
            <Plus className="w-4 h-4 mr-1" /> Add Person
          </Button>
        </div>
      </CardHeader>
      <CardContent>
        {personnel.length === 0 ? (
          <div className="border-2 border-dashed border-slate-300 bg-slate-50/50 rounded-lg p-8 text-center">
            <Users className="w-8 h-8 text-slate-400 mx-auto mb-2" />
            <p className="text-sm text-slate-600 font-medium">No personnel assigned</p>
            <p className="text-xs text-slate-500 mt-1">
              Add crew members or use Auto-Suggest to populate based on the project.
            </p>
          </div>
        ) : (
          <div className="space-y-2">
            {personnel.map((row, idx) => (
              <div
                key={idx}
                className="border border-slate-200 rounded-lg p-3 bg-slate-50/50"
              >
                <div className="grid md:grid-cols-12 gap-2 items-end">
                  <div className="md:col-span-3">
                    <Label className="text-xs">Name</Label>
                    <Input
                      value={row.name}
                      onChange={(e) => handleUpdate(idx, { name: e.target.value })}
                      placeholder="e.g. Mike"
                      className="h-8 mt-0.5"
                    />
                  </div>
                  <div className="md:col-span-3">
                    <Label className="text-xs">Role</Label>
                    <select
                      value={row.role || "Installer"}
                      onChange={(e) => handleUpdate(idx, { role: e.target.value })}
                      className="h-8 mt-0.5 w-full border border-slate-200 rounded-md px-2 text-sm bg-white"
                    >
                      {ROLE_OPTIONS.map((r) => (
                        <option key={r} value={r}>{r}</option>
                      ))}
                    </select>
                  </div>
                  <div className="md:col-span-2">
                    <Label className="text-xs">Rate $/hr</Label>
                    <Input
                      type="number"
                      step="0.01"
                      value={row.hourly_rate}
                      onFocus={(e) => e.target.select()}
                      onChange={(e) =>
                        handleUpdate(idx, { hourly_rate: channelDraftValue(e.target.value) })
                      }
                      className={`h-8 mt-0.5 ${rowInvalid(idx, "hourly_rate") ? "border-red-500" : ""}`}
                      {...rowAria(idx, "hourly_rate")}
                    />
                    <RowIssue idx={idx} field="hourly_rate" />
                  </div>
                  <div className="md:col-span-2">
                    <Label className="text-xs">Hours</Label>
                    <Input
                      type="number"
                      step="0.25"
                      value={row.hours}
                      onFocus={(e) => e.target.select()}
                      onChange={(e) =>
                        handleUpdate(idx, { hours: channelDraftValue(e.target.value) })
                      }
                      className={`h-8 mt-0.5 ${rowInvalid(idx, "hours") ? "border-red-500" : ""}`}
                      {...rowAria(idx, "hours")}
                    />
                    <RowIssue idx={idx} field="hours" />
                  </div>
                  <div className="md:col-span-1">
                    <Label className="text-xs">Total</Label>
                    <div className="h-8 mt-0.5 text-sm font-medium flex items-center tabular-nums">
                      {fmt(row.total_cost)}
                    </div>
                  </div>
                  <div className="md:col-span-1 flex items-end justify-end">
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => handleRemove(idx)}
                      className="text-red-500 hover:bg-red-50 h-8 w-8 p-0"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </Button>
                  </div>
                </div>
              </div>
            ))}
            <div className="flex justify-between pt-2 border-t border-slate-200 text-sm">
              <div>
                <span className="text-slate-500">Total Hours:</span>{" "}
                <span className="font-semibold tabular-nums">{Number.isFinite(totalHours) ? totalHours.toFixed(2) : "—"}</span>
                {projectLaborHours > 0 && (
                  <span className="text-xs text-slate-400 ml-2">
                    (calculated: {projectLaborHours.toFixed(2)} hrs)
                  </span>
                )}
              </div>
              <div className="text-right">
                <span className="text-xs text-slate-500">Total Personnel Cost: </span>
                <span className="text-lg font-bold tabular-nums">{fmt(totalCost)}</span>
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Camera, Loader2, Upload, Wand2 } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { ESTIMATOR_AI_MODEL } from "../../../base44/shared/estimatorAiModelPolicy.js";

const SCHEMA = {
  type: "object",
  properties: {
    estimated_height_feet: { type: "number", description: "Estimated install height from ground in feet" },
    wall_material: {
      type: "string",
      enum: ["eifs", "stucco", "brick", "concrete", "metal", "wood", "glass", "drywall"],
      description: "Best guess of the wall material"
    },
    recommended_install_type: {
      type: "string",
      enum: ["flush_mount", "halo_lit", "raceway", "dimensional_lettering"]
    },
    site_conditions: {
      type: "object",
      properties: {
        parapet: { type: "boolean" },
        poor_electrical_access: { type: "boolean" },
        thick_hollow_walls: { type: "boolean" }
      }
    },
    confidence: { type: "string", enum: ["low", "medium", "high"] },
    reasoning: { type: "string", description: "Brief explanation of what was observed" }
  }
};

export default function PhotoEstimateModal({ open, onClose, onApply }) {
  const [file, setFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);

  const handleFile = (f) => {
    if (!f) return;
    setFile(f);
    setPreviewUrl(URL.createObjectURL(f));
    setResult(null);
    setError(null);
  };

  const analyze = async () => {
    if (!file) return;
    setLoading(true);
    setError(null);
    try {
      const { file_url } = await base44.integrations.Core.UploadFile({ file });
      const res = await base44.integrations.Core.InvokeLLM({
        model: ESTIMATOR_AI_MODEL,
        prompt: `You're a sign installer reviewing a photo of a site where channel letters will be installed.
Analyze the photo and estimate:
- The install height (feet from ground to where letters will go)
- The wall material (eifs, stucco, brick, concrete, metal, wood, glass, drywall)
- Recommended install type (flush_mount, halo_lit, raceway, dimensional_lettering)
- Site conditions: is there a parapet? poor electrical access? thick hollow walls?
- Your confidence level (low/medium/high)

Be specific and practical — these will be used in an estimate.`,
        file_urls: [file_url],
        response_json_schema: SCHEMA
      });
      setResult(res);
    } catch (e) {
      setError(e.message || "Analysis failed");
    }
    setLoading(false);
  };

  const apply = () => {
    if (!result) return;
    onApply(result);
    handleClose();
  };

  const handleClose = () => {
    setFile(null);
    setPreviewUrl(null);
    setResult(null);
    setError(null);
    onClose();
  };

  const confidenceColor = {
    high: "bg-green-100 text-green-800 border-green-200",
    medium: "bg-amber-100 text-amber-800 border-amber-200",
    low: "bg-red-100 text-red-800 border-red-200",
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Camera className="w-5 h-5 text-purple-600" />
            Photo → Estimate
          </DialogTitle>
          <p className="text-xs text-slate-500">Upload a photo of the install site — AI will estimate height, wall material, and conditions.</p>
        </DialogHeader>

        <div className="space-y-3">
          {!previewUrl ? (
            <label className="flex flex-col items-center justify-center border-2 border-dashed border-slate-300 rounded-lg p-8 cursor-pointer hover:border-purple-400 hover:bg-purple-50/50 transition-colors">
              <Upload className="w-8 h-8 text-slate-400 mb-2" />
              <span className="text-sm font-medium text-slate-700">Click to upload a site photo</span>
              <span className="text-xs text-slate-500 mt-1">JPG, PNG, or HEIC</span>
              <input
                type="file"
                accept="image/*"
                className="hidden"
                onChange={(e) => handleFile(e.target.files?.[0])}
              />
            </label>
          ) : (
            <div className="relative">
              <img src={previewUrl} alt="Site preview" className="w-full max-h-64 object-contain rounded-lg border border-slate-200 bg-slate-50" />
              <Button
                variant="outline"
                size="sm"
                onClick={() => { setFile(null); setPreviewUrl(null); setResult(null); }}
                className="absolute top-2 right-2 h-7 text-xs bg-white"
              >
                Change
              </Button>
            </div>
          )}

          {error && (
            <div className="text-xs text-red-700 bg-red-50 border border-red-200 rounded p-2">{error}</div>
          )}

          {result && (
            <div className="border border-purple-200 bg-purple-50/40 rounded-lg p-3 space-y-2">
              <div className="flex items-center justify-between">
                <div className="text-xs font-semibold text-purple-900 flex items-center gap-1">
                  <Wand2 className="w-3.5 h-3.5" />
                  AI Analysis
                </div>
                {result.confidence && (
                  <span className={`text-[10px] px-1.5 py-0.5 rounded border ${confidenceColor[result.confidence]}`}>
                    {result.confidence} confidence
                  </span>
                )}
              </div>
              <div className="grid grid-cols-2 gap-2 text-xs">
                <Field label="Install Height" value={`${result.estimated_height_feet || 0} ft`} />
                <Field label="Wall Material" value={result.wall_material || "—"} />
                <Field label="Recommended" value={result.recommended_install_type?.replace(/_/g, " ") || "—"} />
                <Field
                  label="Conditions"
                  value={[
                    result.site_conditions?.parapet && "parapet",
                    result.site_conditions?.poor_electrical_access && "poor electrical",
                    result.site_conditions?.thick_hollow_walls && "thick walls"
                  ].filter(Boolean).join(", ") || "none noted"}
                />
              </div>
              {result.reasoning && (
                <div className="text-[11px] text-slate-600 italic border-t border-purple-200 pt-1.5">
                  {result.reasoning}
                </div>
              )}
            </div>
          )}
        </div>

        <DialogFooter className="gap-2">
          <Button variant="outline" onClick={handleClose} disabled={loading}>Cancel</Button>
          {!result ? (
            <Button onClick={analyze} disabled={!file || loading} className="bg-purple-600 hover:bg-purple-700 text-white">
              {loading ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Analyzing...</> : <><Camera className="w-4 h-4 mr-2" /> Analyze Photo</>}
            </Button>
          ) : (
            <Button onClick={apply} className="bg-green-600 hover:bg-green-700 text-white">
              <Wand2 className="w-4 h-4 mr-2" /> Apply to New Line Item
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

const Field = ({ label, value }) => (
  <div className="bg-white rounded border border-purple-100 px-2 py-1.5">
    <div className="text-[10px] uppercase tracking-wide text-slate-500">{label}</div>
    <div className="font-medium text-slate-800 capitalize">{value}</div>
  </div>
);

import React from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { History, TrendingUp, TrendingDown, Minus } from "lucide-react";
import { formatRelative } from "./materialsHelpers";
import { CRITERIA_MAP } from "./materialsConstants";

const PRICE_FIELDS = [
  "cost_per_letter", "cost_extra_small", "cost_small", "cost_medium",
  "cost_large", "cost_extra_large", "cost_extra_extra_large",
  "cost_per_foot", "cost_flat",
];

const currentHeadlinePrice = (item) => {
  switch (item.pricing_mode) {
    case "per_letter_flat": return parseFloat(item.cost_per_letter) || 0;
    case "per_raceway_foot": return parseFloat(item.cost_per_foot) || 0;
    case "per_project_flat": return parseFloat(item.cost_flat) || 0;
    case "per_letter_by_size": {
      const vals = ["cost_extra_small", "cost_small", "cost_medium", "cost_large", "cost_extra_large", "cost_extra_extra_large"]
        .map(k => parseFloat(item[k]) || 0).filter(v => v > 0);
      return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : 0;
    }
    default: return 0;
  }
};

const snapshotHeadline = (snap) => {
  if (!snap) return 0;
  switch (snap.pricing_mode) {
    case "per_letter_flat": return parseFloat(snap.cost_per_letter) || 0;
    case "per_raceway_foot": return parseFloat(snap.cost_per_foot) || 0;
    case "per_project_flat": return parseFloat(snap.cost_flat) || 0;
    case "per_letter_by_size": {
      const vals = ["cost_extra_small", "cost_small", "cost_medium", "cost_large", "cost_extra_large", "cost_extra_extra_large"]
        .map(k => parseFloat(snap[k]) || 0).filter(v => v > 0);
      return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : 0;
    }
    default: return 0;
  }
};

export default function PriceHistoryDialog({ open, onOpenChange, item }) {
  if (!item) return null;
  const history = Array.isArray(item.price_history) ? [...item.price_history].reverse() : [];
  const currentPrice = currentHeadlinePrice(item);
  const crit = CRITERIA_MAP[item.pricing_mode];

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <History className="w-5 h-5 text-purple-600" />
            Price History — {item.item_name}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-3">
          <div className="bg-purple-50 border border-purple-200 rounded-lg p-3">
            <div className="text-xs text-purple-700 font-medium">Current Price</div>
            <div className="text-2xl font-bold text-purple-900 mt-1">
              ${currentPrice.toFixed(2)}
              <span className="text-sm font-normal text-purple-700 ml-2">{crit?.short}</span>
            </div>
          </div>

          {history.length === 0 ? (
            <div className="text-center py-8 text-slate-500 text-sm">
              No price history yet. Future price changes will be recorded here.
            </div>
          ) : (
            <div className="space-y-2">
              {history.map((entry, idx) => {
                const oldPrice = snapshotHeadline(entry.snapshot);
                const newer = idx === 0 ? currentPrice : snapshotHeadline(history[idx - 1].snapshot);
                const delta = newer - oldPrice;
                const pct = oldPrice > 0 ? (delta / oldPrice) * 100 : 0;
                const TrendIcon = delta > 0 ? TrendingUp : delta < 0 ? TrendingDown : Minus;
                const trendColor = delta > 0 ? "text-red-600" : delta < 0 ? "text-green-600" : "text-slate-500";

                return (
                  <div key={idx} className="border border-slate-200 rounded-lg p-3 flex items-center gap-3">
                    <div className="flex-1">
                      <div className="text-sm font-medium text-slate-700">
                        ${oldPrice.toFixed(2)} <span className="text-slate-400 text-xs">→ ${newer.toFixed(2)}</span>
                      </div>
                      <div className="text-xs text-slate-500 mt-0.5">
                        {formatRelative(entry.changed_at)} · by {entry.changed_by}
                      </div>
                    </div>
                    <Badge variant="outline" className={`gap-1 ${trendColor}`}>
                      <TrendIcon className="w-3 h-3" />
                      {delta >= 0 ? "+" : ""}{pct.toFixed(1)}%
                    </Badge>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

import React from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Plus, Trash2, Layers } from "lucide-react";

// Optional volume-discount tier table. Empty tiers means: use the standard headline price.
export default function QuantityTiersEditor({ tiers, onChange, disabled }) {
  const list = Array.isArray(tiers) ? tiers : [];

  const addTier = () => {
    const last = list[list.length - 1];
    const nextMin = last ? (parseFloat(last.max_qty) || 0) + 1 : 1;
    onChange([...list, { min_qty: nextMin, max_qty: nextMin + 9, unit_cost: 0 }]);
  };

  const updateTier = (idx, patch) => {
    const next = list.map((t, i) => i === idx ? { ...t, ...patch } : t);
    onChange(next);
  };

  const removeTier = (idx) => {
    if (!confirm("Remove this price tier?")) return;
    onChange(list.filter((_, i) => i !== idx));
  };

  return (
    <div className="bg-white border border-slate-200 rounded-lg p-3">
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-1.5 text-xs font-medium text-slate-700">
          <Layers className="w-3.5 h-3.5 text-slate-500" />
          Volume Discount Tiers
          <span className="text-[10px] text-slate-400 font-normal">(optional)</span>
        </div>
        <Button
          type="button"
          size="sm"
          variant="ghost"
          onClick={addTier}
          disabled={disabled}
          className="h-6 px-2 text-xs"
        >
          <Plus className="w-3 h-3 mr-1" /> Add Tier
        </Button>
      </div>

      {list.length === 0 ? (
        <p className="text-[11px] text-slate-400 italic">
          No tiers set. Standard pricing applies for all quantities.
        </p>
      ) : (
        <div className="space-y-1.5">
          <div className="grid grid-cols-12 gap-2 text-[10px] font-semibold uppercase tracking-wide text-slate-500 px-1">
            <div className="col-span-4">Min Qty</div>
            <div className="col-span-4">Max Qty</div>
            <div className="col-span-3">Unit $</div>
            <div className="col-span-1"></div>
          </div>
          {list.map((t, idx) => (
            <div key={idx} className="grid grid-cols-12 gap-2 items-center">
              <Input
                type="number" value={t.min_qty ?? ""}
                onFocus={e => e.target.select()}
                onChange={(e) => updateTier(idx, { min_qty: parseFloat(e.target.value) || 0 })}
                disabled={disabled}
                className="h-8 text-xs col-span-4"
              />
              <Input
                type="number" value={t.max_qty ?? ""}
                onFocus={e => e.target.select()}
                onChange={(e) => updateTier(idx, { max_qty: parseFloat(e.target.value) || 0 })}
                disabled={disabled}
                className="h-8 text-xs col-span-4"
              />
              <Input
                type="number" step="0.01" value={t.unit_cost ?? ""}
                onFocus={e => e.target.select()}
                onChange={(e) => updateTier(idx, { unit_cost: parseFloat(e.target.value) || 0 })}
                disabled={disabled}
                className="h-8 text-xs col-span-3"
              />
              <Button
                type="button"
                size="sm"
                variant="ghost"
                onClick={() => removeTier(idx)}
                disabled={disabled}
                className="h-7 w-7 p-0 text-red-500 hover:bg-red-50 col-span-1"
              >
                <Trash2 className="w-3 h-3" />
              </Button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

