import { useState, useMemo, useEffect } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Sliders, AlertTriangle } from "lucide-react";

import VinylMaterialPicker from "./VinylMaterialPicker";
import VinylMachinePicker from "./VinylMachinePicker";
import VinylPartsTable from "./VinylPartsTable";
import VinylRollVisualizer from "./VinylRollVisualizer";
import VinylPresetBar from "./VinylPresetBar";
import VinylStockWarning from "./VinylStockWarning";
import VinylAlternativeCompare from "./VinylAlternativeCompare";
import VinylWorkflowTemplatesDialog from "./VinylWorkflowTemplatesDialog";
import VinylWorkflowCardHeader, { COLOR_SWATCHES } from "./VinylWorkflowCardHeader";
import VinylCuttingExtrasCard from "./VinylCuttingExtrasCard";
import VinylWorkflowPersonnel from "./VinylWorkflowPersonnel";
import VinylRollWidthRecommender from "./VinylRollWidthRecommender";
import { calcVinylWorkflow, hasIssueFor } from "./vinylPricingAvailability";
import { applyPresetToWorkflow } from "./vinylWorkflowPresets";
import {
  computePerPartCosts, computeWorkflowMetrics, computeStockUsage,
} from "./vinylCostHelpers";
import { loadVinylLaborRoles, MACHINE_AUTO_ROLES, suggestedHoursForRole } from "./vinylLaborRoles";

const num = (v) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : 0;
};

export default function VinylWorkflowCard({
  workflow, index, vinyls, machines,
  onChange, onRemove, onDuplicate, onMovePartToWorkflow,
  installEnvironment = "exterior",
  defaultOpen = true,
  pricing: pricingProp, // optional shared { calc, issues, held, resolved }
}) {
  const [open, setOpen] = useState(defaultOpen);
  const [templatesOpen, setTemplatesOpen] = useState(false);
  const [templatesMode, setTemplatesMode] = useState("apply");
  const [recommendOnly, setRecommendOnly] = useState(false);
  const [showCompare, setShowCompare] = useState(false);
  const [roleOptions, setRoleOptions] = useState([]);

  // Respond to parent expand/collapse-all toggle
  useEffect(() => { setOpen(defaultOpen); }, [defaultOpen]);

  // Load vinyl labor roles (rates) from the Labor Inventory once.
  useEffect(() => { loadVinylLaborRoles().then(setRoleOptions).catch((e) => console.error("Vinyl labor roles failed to load:", e)); }, []);

  const set = (patch) => onChange({ ...workflow, ...patch });

  // Pricing-availability wrap: the same calculation the card has always run,
  // now with strict input validation. `pricing.calc` is the held/poisoned
  // result when any consumed input is unavailable; `pricing.issues` carries
  // the structured diagnostics. The page may share one computation across
  // every workflow via the `pricing` prop — otherwise the card computes its
  // own so it stays self-contained.
  const pricing = useMemo(
    () => pricingProp ?? calcVinylWorkflow({ workflow, vinyls, machines, index }),
    [pricingProp, workflow, vinyls, machines, index],
  );
  const calc = pricing.calc;
  const pricingIssues = pricing.issues || [];
  const held = !!pricing.held;

  const { printer, cutter, laminator, vinyl, laminate, transferTape } = pricing.resolved;
  const operatorRate = printer?.operator_hourly_rate ?? cutter?.operator_hourly_rate ?? laminator?.operator_hourly_rate ?? 45;

  // Drag-and-drop: a per-item manual x override that the calculator doesn't know about
  // but we apply on the placed shelves directly for visual rendering. Stored in a
  // workflow.items[].manual_layout = { x } map.
  const calcWithManualPositions = useMemo(() => {
    if (!workflow.manual_positions) return calc;
    const shelves = calc.shelves.map((sh, sIdx) => ({
      ...sh,
      items: sh.items.map((it, iIdx) => {
        const key = `${sIdx}-${iIdx}`;
        const override = workflow.manual_positions[key];
        return override !== undefined ? { ...it, x: override } : it;
      }),
    }));
    return { ...calc, shelves };
  }, [calc, workflow.manual_positions]);

  const handleItemMove = ({ shelfIdx, itemIdx, x }) => {
    const key = `${shelfIdx}-${itemIdx}`;
    set({
      manual_positions: { ...(workflow.manual_positions || {}), [key]: x },
    });
  };

  // Per-part cost rollup — Feature #19. Held calcs keep the parts but the
  // costs are unavailable — don't paint $0 allocations on real rows.
  const perPartCosts = useMemo(
    () => (held ? {} : computePerPartCosts(calc, workflow.items || [])),
    [held, calc, workflow.items],
  );
  // Yield / cost metrics — Feature #20, #21
  const metrics    = useMemo(() => computeWorkflowMetrics(calc), [calc]);
  // Stock usage — Feature #6, #37
  const stockUsage = useMemo(() => computeStockUsage(calc, vinyl), [calc, vinyl]);

  // Surface calc back up so the project rollup can sum across workflows.
  // _hasIssues now also covers pricing-availability issues — the tab badge
  // and the save guard both read it.
  useEffect(() => {
    const hasIssues = pricingIssues.length > 0 || calc.partsUnplaced > 0 || !workflow.vinyl_id;
    if (workflow._calc?.totalCost !== calc.totalCost
     || workflow._calc?.materialCost !== calc.materialCost
     || workflow._hasIssues !== hasIssues) {
      onChange({ ...workflow, _calc: calc, _hasIssues: hasIssues });
    }
  }, [calc.totalCost, calc.materialCost, calc.machineCost, calc.laborCost, calc.partsUnplaced, workflow.vinyl_id, pricingIssues.length]);

  // Auto-select operator roles when machines are applied. Adds any missing role
  // for the active machines and auto-fills its hours from the calculator. Runs
  // after roles are loaded and recomputes hours as the calc changes.
  useEffect(() => {
    if (roleOptions.length === 0) return;
    const wanted = new Set();
    if (workflow.apply_print && workflow.printer_id)      MACHINE_AUTO_ROLES.printer.forEach(r => wanted.add(r));
    if (workflow.apply_cut && workflow.cutter_id)         MACHINE_AUTO_ROLES.cutter.forEach(r => wanted.add(r));
    if (workflow.apply_laminate && workflow.laminator_id) MACHINE_AUTO_ROLES.laminator.forEach(r => wanted.add(r));
    if (wanted.size === 0) return;

    const current = workflow.personnel || [];
    let changed = false;
    const next = [...current];
    wanted.forEach((role) => {
      const opt = roleOptions.find(r => r.role === role);
      if (!opt) return;
      const existing = next.find(p => p.role === role);
      const hrs = suggestedHoursForRole(role, calc);
      if (!existing) {
        next.push({ role, hourly_rate: opt.hourly_rate, hours: hrs, total_cost: opt.hourly_rate * hrs, _auto: true });
        changed = true;
      } else if (existing._auto && Math.abs(num(existing.hours) - hrs) > 0.001) {
        // Keep auto-added rows in sync with the calculator until the user edits.
        existing.hours = hrs;
        existing.total_cost = num(existing.hourly_rate) * hrs;
        changed = true;
      }
    });
    if (changed) set({ personnel: next });
  }, [
    roleOptions, workflow.apply_print, workflow.apply_cut, workflow.apply_laminate,
    workflow.printer_id, workflow.cutter_id, workflow.laminator_id,
    calc.printMinutes, calc.cutMinutes, calc.laminateMinutes, calc.weedingMinutes, calc.installMinutes,
  ]);

  const colorTag = workflow.color_tag || COLOR_SWATCHES[index % COLOR_SWATCHES.length];

  return (
    <Card
      className="bg-white border border-slate-200 shadow-sm hover:shadow-md transition-shadow overflow-hidden"
      style={{ borderLeft: `4px solid ${colorTag}` }}
    >
      <VinylWorkflowCardHeader
        workflow={workflow}
        index={index}
        vinyl={vinyl}
        calc={calc}
        metrics={metrics}
        colorTag={colorTag}
        open={open}
        onToggleOpen={() => setOpen(!open)}
        onChange={set}
        onSaveTemplate={() => { setTemplatesMode("save"); setTemplatesOpen(true); }}
        onDuplicate={onDuplicate}
        onRemove={onRemove}
      />

      {open && (
        <CardContent className="space-y-4 pt-2 border-t border-slate-100">
          {/* Pricing-availability diagnostics — calculation rows stay visible;
              tainted totals show "Not saved" instead of a laundered $0. */}
          {pricingIssues.length > 0 && (
            <div
              role="status"
              id={`vinyl-wf-${index}-issues`}
              className="flex items-start gap-2 text-xs text-amber-900 bg-amber-50 border border-amber-200 rounded px-3 py-2"
            >
              <AlertTriangle className="w-3.5 h-3.5 mt-0.5 flex-shrink-0 text-amber-600" />
              <div>
                <div className="font-semibold">Pricing unavailable — {pricingIssues.length} value{pricingIssues.length === 1 ? "" : "s"} need attention</div>
                <ul className="mt-1 space-y-0.5 list-disc list-inside">
                  {pricingIssues.slice(0, 6).map((it, i) => <li key={i}>{it.message}</li>)}
                  {pricingIssues.length > 6 && <li>…and {pricingIssues.length - 6} more</li>}
                </ul>
              </div>
            </div>
          )}

          {/* Preset bar — Feature #5 */}
          <VinylPresetBar
            activePresetKey={workflow.preset_key}
            onApply={(preset) => set({ ...applyPresetToWorkflow(preset) })}
          />

          <VinylMaterialPicker
            vinyls={vinyls}
            vinylId={workflow.vinyl_id}
            laminateId={workflow.laminate_id}
            applyLaminate={!!workflow.apply_laminate}
            presetKey={workflow.preset_key}
            installEnvironment={installEnvironment}
            recommendOnly={recommendOnly}
            issues={pricingIssues}
            issuesId={`vinyl-wf-${index}-issues`}
            onChange={({ vinylId, laminateId, applyLaminate, recommendOnly: ro }) => {
              if (ro !== undefined) setRecommendOnly(ro);
              if (vinylId !== undefined || laminateId !== undefined || applyLaminate !== undefined) {
                set({
                  vinyl_id: vinylId,
                  laminate_id: laminateId || "",
                  apply_laminate: !!applyLaminate,
                });
              }
            }}
          />

          {/* Stock check — Feature #6 & #37 */}
          {stockUsage && <VinylStockWarning stockUsage={stockUsage} vinyl={vinyl} />}

          {/* Compare to other vinyls — Feature #22 */}
          {vinyl && calc.vinylCost > 0 && (
            <div>
              <button type="button" onClick={() => setShowCompare(s => !s)} className="text-[11px] underline text-blue-600">
                {showCompare ? "Hide" : "Show"} cost comparison vs other vinyls
              </button>
              {showCompare && (
                <div className="mt-2">
                  <VinylAlternativeCompare calc={calc} currentVinyl={vinyl} vinyls={vinyls} />
                </div>
              )}
            </div>
          )}

          {/* Roll-width recommender (#10) */}
          <VinylRollWidthRecommender
            workflow={workflow}
            vinyl={vinyl}
            vinyls={vinyls}
            printer={printer}
            cutter={cutter}
            laminator={laminator}
            laminate={laminate}
            transferTape={transferTape}
            operatorRate={operatorRate}
            currentCalc={calc}
            onPick={(id) => set({ vinyl_id: id })}
          />

          <VinylMachinePicker
            machines={machines}
            issues={pricingIssues}
            issuesId={`vinyl-wf-${index}-issues`}
            value={{
              printer_id:   workflow.printer_id,
              cutter_id:    workflow.cutter_id,
              laminator_id: workflow.laminator_id,
              applyPrint:    !!workflow.apply_print,
              applyCut:      !!workflow.apply_cut,
              applyLaminate: !!workflow.apply_laminate,
              printQuality:  workflow.print_quality || printer?.default_print_quality || "high_quality",
            }}
            onChange={(v) => {
              const patch = {};
              if (v.printer_id   !== undefined) patch.printer_id   = v.printer_id;
              if (v.cutter_id    !== undefined) patch.cutter_id    = v.cutter_id;
              if (v.laminator_id !== undefined) patch.laminator_id = v.laminator_id;
              if (v.applyPrint    !== undefined) patch.apply_print    = v.applyPrint;
              if (v.applyCut      !== undefined) patch.apply_cut      = v.applyCut;
              if (v.applyLaminate !== undefined) patch.apply_laminate = v.applyLaminate;
              if (v.printQuality  !== undefined) patch.print_quality  = v.printQuality;
              set(patch);
            }}
          />

          {/* Workflow-level cost knobs: spoilage buffer + setup fee floor */}
          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm">Workflow Cost Controls</CardTitle>
            </CardHeader>
            <CardContent className="grid md:grid-cols-2 gap-4 text-xs">
              <div>
                <label className="text-[10px] uppercase tracking-wider text-slate-500">Spoilage / Reprint Buffer (%)</label>
                <Input
                  type="number" step="1" min="0"
                  value={workflow.spoilage_buffer_percent ?? ""}
                  placeholder="0"
                  onChange={(e) => set({ spoilage_buffer_percent: e.target.value })}
                  aria-invalid={hasIssueFor(pricingIssues, "spoilage_buffer_percent") || undefined}
                  aria-describedby={hasIssueFor(pricingIssues, "spoilage_buffer_percent") ? `vinyl-wf-${index}-issues` : undefined}
                  className="h-8 tabular-nums"
                />
                <p className="text-[10px] text-slate-500 mt-1">Adds N% extra qty to every part before nesting.</p>
              </div>
              <div>
                <label className="text-[10px] uppercase tracking-wider text-slate-500">Setup-Fee Floor ($)</label>
                <Input
                  type="number" step="1" min="0"
                  value={workflow.setup_fee_floor ?? ""}
                  placeholder="0"
                  onChange={(e) => set({ setup_fee_floor: e.target.value })}
                  aria-invalid={hasIssueFor(pricingIssues, "setup_fee_floor") || undefined}
                  aria-describedby={hasIssueFor(pricingIssues, "setup_fee_floor") ? `vinyl-wf-${index}-issues` : undefined}
                  className="h-8 tabular-nums"
                />
                <p className="text-[10px] text-slate-500 mt-1">
                  {(calc.setupFeeApplied ?? 0) > 0
                    ? <span className="text-amber-700 font-medium">Floor adding ${calc.setupFeeApplied.toFixed(2)} to this workflow.</span>
                    : "Workflow minimum charge."}
                </p>
              </div>
            </CardContent>
          </Card>

          {/* Cutting-only extras: transfer tape + weeding difficulty + install labor */}
          {workflow.apply_cut && (
            <VinylCuttingExtrasCard
              vinyls={vinyls}
              transferTapeId={workflow.transfer_tape_id}
              applyTransferTape={!!workflow.apply_transfer_tape}
              weedingDifficulty={workflow.weeding_difficulty}
              weedingMinutesPerPartOverride={workflow.weeding_minutes_per_part_override}
              installMinutesPerPart={workflow.install_minutes_per_part}
              partsPlaced={calc.partsPlaced ?? 0}
              issues={pricingIssues}
              issuesId={`vinyl-wf-${index}-issues`}
              onChange={(p) => {
                const patch = {};
                if (p.transferTapeId   !== undefined) patch.transfer_tape_id   = p.transferTapeId;
                if (p.applyTransferTape !== undefined) patch.apply_transfer_tape = p.applyTransferTape;
                if (p.weedingDifficulty !== undefined) patch.weeding_difficulty = p.weedingDifficulty;
                if (p.weedingMinutesPerPartOverride !== undefined) patch.weeding_minutes_per_part_override = p.weedingMinutesPerPartOverride;
                if (p.installMinutesPerPart !== undefined) patch.install_minutes_per_part = p.installMinutesPerPart;
                set(patch);
              }}
            />
          )}

          {/* Per-personnel labor rates */}
          <VinylWorkflowPersonnel
            personnel={workflow.personnel || []}
            roleOptions={roleOptions}
            onChange={(personnel) => set({ personnel })}
            issues={pricingIssues}
            issuesId={`vinyl-wf-${index}-issues`}
            suggestedHours={held ? 0 : (calc.machineRunMinutes + calc.weedingMinutes + calc.installMinutes) / 60}
          />

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm">Parts in this workflow</CardTitle>
            </CardHeader>
            <CardContent>
              <VinylPartsTable
                items={workflow.items || []}
                onChange={(items) => set({ items, manual_positions: {} })}
                perPartCosts={perPartCosts}
                issues={pricingIssues}
                issuesId={`vinyl-wf-${index}-issues`}
                usableWidth={calc.usableWidth}
                defaultBleed={workflow.apply_cut ? 0 : 0.125}
                onMoveToWorkflow={onMovePartToWorkflow ? (partIdx) => onMovePartToWorkflow(partIdx) : null}
              />
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <div className="flex items-center justify-between flex-wrap gap-2">
                <CardTitle className="text-sm">Roll Layout</CardTitle>
                <div className="flex items-center gap-2 text-xs">
                  <Sliders className="w-3.5 h-3.5 text-slate-400" />
                  <span className="text-slate-500">Gutter H</span>
                  <Input
                    type="number" step="0.0625"
                    placeholder={String(calc.gutterH)}
                    value={workflow.gutter_h_override ?? ""}
                    onChange={(e) => set({ gutter_h_override: e.target.value })}
                    aria-invalid={hasIssueFor(pricingIssues, "gutter_h_override") || undefined}
                    aria-describedby={hasIssueFor(pricingIssues, "gutter_h_override") ? `vinyl-wf-${index}-issues` : undefined}
                    className="h-7 w-16 text-xs tabular-nums"
                  />
                  <span className="text-slate-500">V</span>
                  <Input
                    type="number" step="0.0625"
                    placeholder={String(calc.gutterV)}
                    value={workflow.gutter_v_override ?? ""}
                    onChange={(e) => set({ gutter_v_override: e.target.value })}
                    aria-invalid={hasIssueFor(pricingIssues, "gutter_v_override") || undefined}
                    aria-describedby={hasIssueFor(pricingIssues, "gutter_v_override") ? `vinyl-wf-${index}-issues` : undefined}
                    className="h-7 w-16 text-xs tabular-nums"
                  />
                  {(workflow.gutter_h_override || workflow.gutter_v_override || workflow.manual_positions) && (
                    <Button size="sm" variant="ghost" className="h-7 text-xs" onClick={() => set({ gutter_h_override: "", gutter_v_override: "", manual_positions: {} })}>
                      Reset
                    </Button>
                  )}
                </div>
              </div>
            </CardHeader>
            <CardContent>
              <VinylRollVisualizer
                calc={calcWithManualPositions}
                showRegistrationMarks={workflow.apply_print && workflow.apply_cut}
                onItemMove={handleItemMove}
              />
            </CardContent>
          </Card>
        </CardContent>
      )}

      <VinylWorkflowTemplatesDialog
        open={templatesOpen}
        onClose={() => setTemplatesOpen(false)}
        mode={templatesMode}
        currentWorkflow={workflow}
        onApply={(patch) => set(patch)}
      />
    </Card>
  );
}

// Header for one VinylWorkflowCard.
// Clean two-row layout:
//   Row 1: chevron + color dot + editable name + total cost (big, right-aligned)
//   Row 2: status badges (parts, vinyl, yield, unplaced) + actions (template / duplicate / delete)
// Color tag picker lives in a popover so it doesn't clutter the body.

import { useState, useRef, useEffect } from "react";
import { CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  ChevronDown, ChevronRight, Trash2, Copy, Bookmark,
  AlertTriangle, Pencil, Check, X, Palette,
} from "lucide-react";
import VinylWorkflowMetricsBadge from "./VinylWorkflowMetricsBadge";

const fmt = (v) => `$${(parseFloat(v) || 0).toFixed(2)}`;

export const COLOR_SWATCHES = [
  "#3b82f6", "#10b981", "#f59e0b", "#ef4444",
  "#8b5cf6", "#ec4899", "#14b8a6", "#0ea5e9",
];

function NameEditor({ value, placeholder, onSave }) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(value || "");
  const inputRef = useRef(null);

  useEffect(() => { if (editing) inputRef.current?.focus(); }, [editing]);
  useEffect(() => { setDraft(value || ""); }, [value]);

  const commit = () => { onSave(draft.trim()); setEditing(false); };
  const cancel = () => { setDraft(value || ""); setEditing(false); };

  if (!editing) {
    return (
      <button
        type="button"
        onClick={(e) => { e.stopPropagation(); setEditing(true); }}
        className="group flex items-center gap-1.5 min-w-0 max-w-full text-left rounded px-1.5 py-0.5 hover:bg-slate-100 transition-colors"
        title="Click to rename"
      >
        <CardTitle className="text-base truncate">
          {value || <span className="text-slate-400 font-normal">{placeholder}</span>}
        </CardTitle>
        <Pencil className="w-3 h-3 text-slate-300 group-hover:text-slate-500 flex-shrink-0" />
      </button>
    );
  }

  return (
    <div className="flex items-center gap-1 min-w-0" onClick={(e) => e.stopPropagation()}>
      <input
        ref={inputRef}
        value={draft}
        onChange={(e) => setDraft(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter") commit();
          else if (e.key === "Escape") cancel();
        }}
        onBlur={commit}
        placeholder={placeholder}
        className="h-7 text-base font-semibold px-1.5 rounded border border-blue-400 focus:outline-none focus:ring-2 focus:ring-blue-200 min-w-0 flex-1"
      />
      <Button size="icon" variant="ghost" className="h-6 w-6" onMouseDown={(e) => { e.preventDefault(); commit(); }}>
        <Check className="w-3.5 h-3.5 text-green-600" />
      </Button>
      <Button size="icon" variant="ghost" className="h-6 w-6" onMouseDown={(e) => { e.preventDefault(); cancel(); }}>
        <X className="w-3.5 h-3.5 text-slate-500" />
      </Button>
    </div>
  );
}

function ColorTagPicker({ value, onChange }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="relative">
      <button
        type="button"
        onClick={(e) => { e.stopPropagation(); setOpen(o => !o); }}
        className="w-5 h-5 rounded-full ring-2 ring-white shadow border border-slate-200 hover:scale-110 transition-transform flex-shrink-0"
        style={{ background: value }}
        title="Change color tag"
      />
      {open && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setOpen(false)} />
          <div
            className="absolute top-7 left-0 z-50 bg-white border border-slate-200 rounded-lg shadow-lg p-2"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center gap-1 mb-1.5 text-[10px] text-slate-500 font-medium">
              <Palette className="w-3 h-3" /> COLOR TAG
            </div>
            <div className="grid grid-cols-4 gap-1.5">
              {COLOR_SWATCHES.map(c => (
                <button type="button"
                  key={c}
                  onClick={() => { onChange(c); setOpen(false); }}
                  className={`w-6 h-6 rounded-full transition-all ${value === c ? "ring-2 ring-slate-900 ring-offset-1" : "hover:scale-110"}`}
                  style={{ background: c }}
                  aria-label={`Set color ${c}`}
                />
              ))}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

export default function VinylWorkflowCardHeader({
  workflow, index, vinyl, calc, metrics, colorTag,
  open, onToggleOpen, onChange,
  onSaveTemplate, onDuplicate, onRemove,
}) {
  const partCount = (workflow.items || []).length;
  const placeholderName = `Workflow ${index + 1}`;

  return (
    <CardHeader className="pb-2.5 pt-3">
      {/* Row 1 — title + total */}
      <div className="flex items-center gap-2 min-w-0">
        <button type="button"
          onClick={onToggleOpen}
          className="flex items-center justify-center w-6 h-6 rounded hover:bg-slate-100 flex-shrink-0 text-slate-500"
          title={open ? "Collapse" : "Expand"}
        >
          {open ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
        </button>

        <ColorTagPicker
          value={colorTag}
          onChange={(c) => onChange({ color_tag: c })}
        />

        <div className="flex-1 min-w-0">
          <NameEditor
            value={workflow.name}
            placeholder={placeholderName}
            onSave={(v) => onChange({ name: v })}
          />
        </div>

        {/* Total cost — prominent. Held pricing shows "Not saved" instead of
            a laundered $0 so an unavailable price can never masquerade as real. */}
        <div className="flex-shrink-0 text-right">
          <div className="text-[10px] uppercase tracking-wide text-slate-400 leading-none">Total</div>
          {calc.__held ? (
            <div className="text-sm font-semibold text-amber-700 leading-tight" title="Pricing unavailable — fix the flagged inputs">Not saved</div>
          ) : (
            <div className="text-base font-bold tabular-nums text-slate-900 leading-tight">{fmt(calc.totalCost)}</div>
          )}
        </div>

        {/* Actions */}
        <div className="flex items-center gap-0.5 flex-shrink-0 pl-1 border-l border-slate-200 ml-1">
          <Button
            variant="ghost" size="icon"
            onClick={onSaveTemplate}
            className="h-7 w-7 text-slate-500 hover:text-blue-600"
            title="Save / apply template"
          >
            <Bookmark className="w-3.5 h-3.5" />
          </Button>
          <Button
            variant="ghost" size="icon"
            onClick={onDuplicate}
            className="h-7 w-7 text-slate-500 hover:text-blue-600"
            title="Duplicate workflow"
          >
            <Copy className="w-3.5 h-3.5" />
          </Button>
          <Button
            variant="ghost" size="icon"
            onClick={onRemove}
            className="h-7 w-7 text-slate-400 hover:text-red-600 hover:bg-red-50"
            title="Delete workflow"
          >
            <Trash2 className="w-3.5 h-3.5" />
          </Button>
        </div>
      </div>

      {/* Row 2 — status badges */}
      <div className="flex items-center gap-1.5 flex-wrap pl-8 mt-1.5">
        <Badge variant="outline" className="text-[10px] font-normal h-5">
          {partCount} {partCount === 1 ? "part" : "parts"}
        </Badge>
        {vinyl ? (
          <Badge variant="outline" className="text-[10px] font-normal h-5 max-w-[200px] truncate" title={vinyl.vinyl_name}>
            {vinyl.vinyl_name}
          </Badge>
        ) : (
          <Badge className="text-[10px] font-normal h-5 bg-amber-50 text-amber-800 border-amber-200">
            <AlertTriangle className="w-2.5 h-2.5 mr-0.5" /> No vinyl selected
          </Badge>
        )}
        {calc.partsUnplaced > 0 && (
          <Badge className="text-[10px] font-normal h-5 bg-red-100 text-red-800 border-red-200">
            <AlertTriangle className="w-2.5 h-2.5 mr-0.5" /> {calc.partsUnplaced} unplaced
          </Badge>
        )}
        {calc.__held && (calc.issues || []).length > 0 && (
          <Badge className="text-[10px] font-normal h-5 bg-amber-50 text-amber-800 border-amber-200">
            <AlertTriangle className="w-2.5 h-2.5 mr-0.5" /> {calc.issues.length} pricing {calc.issues.length === 1 ? "issue" : "issues"}
          </Badge>
        )}
        <VinylWorkflowMetricsBadge metrics={metrics} />
      </div>
    </CardHeader>
  );
}

// Inline per-workflow margin / yield meter shown in the card header. Feature #20, #21.



export default function VinylWorkflowMetricsBadge({ metrics }) {
  if (!metrics || metrics.sqFtPulled <= 0) return null;
  const yieldPct = metrics.yieldPercent;
  const tone =
    yieldPct >= 75 ? "bg-emerald-100 text-emerald-800 border-emerald-200" :
    yieldPct >= 50 ? "bg-amber-100 text-amber-800 border-amber-200" :
                     "bg-red-100 text-red-800 border-red-200";

  return (
    <div className="flex flex-col gap-1">
      <div className={`flex items-center gap-2 text-[10px] px-2 py-0.5 rounded border ${tone}`}>
        <span>Yield: <b className="tabular-nums">{yieldPct.toFixed(0)}%</b></span>
        <span className="text-slate-500">·</span>
        <span>{Number.isFinite(metrics.costPerSqFt) ? `$${metrics.costPerSqFt.toFixed(2)}/sqft` : "—/sqft"}</span>
      </div>
      {/* Yield bar */}
      <div className="w-32 h-1 rounded-full overflow-hidden bg-slate-200" title={`${yieldPct.toFixed(1)}% used, ${metrics.wastePercent.toFixed(1)}% waste`}>
        <div
          className={`h-full transition-all ${yieldPct >= 75 ? "bg-emerald-500" : yieldPct >= 50 ? "bg-amber-500" : "bg-red-500"}`}
          style={{ width: `${Math.min(100, yieldPct)}%` }}
        />
      </div>
    </div>
  );
}

// Per-workflow personnel (Designer / Printer Operator / Weeder, etc.)
// Roles + rates are sourced from the Labor Inventory (shop_labor rows) and
// passed in via `roleOptions`. When ANY row has hours > 0, the calculator uses
// these rows for labor cost INSTEAD of operator_rate × minutes.


import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Users, Plus, X, AlertTriangle } from "lucide-react";
import { hasIssueFor, vinylDraftValue, vinylNumber } from "./vinylPricingAvailability";

const num = (v) => parseFloat(v) || 0;

export default function VinylWorkflowPersonnel({ personnel = [], onChange, suggestedHours = 0, roleOptions = [], issues = [], issuesId }) {
  const update = (idx, patch) => {
    const next = [...personnel];
    // User edited this row — stop the auto-sync from overwriting it.
    next[idx] = { ...next[idx], ...patch, _auto: false };
    // Strict: a malformed rate/hour produces no total instead of a laundered
    // $0 — the issue checker flags the row so it can't slip a silent zero in.
    const r = vinylNumber(next[idx].hourly_rate);
    const h = vinylNumber(next[idx].hours);
    next[idx].total_cost = (r !== null && h !== null) ? r * h : null;
    onChange(next);
  };
  const remove = (idx) => {
    if (!confirm(`Remove role "${personnel[idx]?.role || "this role"}" from this workflow?`)) return;
    onChange(personnel.filter((_, i) => i !== idx));
  };
  const add = (role) => {
    const preset = roleOptions.find(r => r.role === role) || { role, hourly_rate: 50 };
    onChange([...(personnel || []), {
      role: preset.role,
      hourly_rate: preset.hourly_rate,
      hours: 0,
      total_cost: 0,
    }]);
  };

  const totalCost  = personnel.reduce((s, p) => s + num(p.total_cost), 0);
  const totalHours = personnel.reduce((s, p) => s + num(p.hours), 0);

  return (
    <Card>
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-base flex items-center gap-2">
            <Users className="w-4 h-4 text-indigo-600" /> Workflow Personnel
          </CardTitle>
          <div className="flex items-center gap-2">
            <Select value="" onValueChange={(v) => v && add(v)}>
              <SelectTrigger className="h-8 w-52 text-xs">
                <SelectValue placeholder="+ Add role…" />
              </SelectTrigger>
              <SelectContent>
                {roleOptions.map(r => (
                  <SelectItem key={r.role} value={r.role}>{r.role} · ${r.hourly_rate}/hr</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
      </CardHeader>
      <CardContent className="space-y-2">
        {personnel.length === 0 ? (
          <div className="text-xs text-slate-500 bg-slate-50 border border-slate-200 rounded p-3">
            No per-role personnel set. Labor is being calculated at the printer's operator rate
            ({suggestedHours.toFixed(2)} hr machine + weeding + install). Add roles above for
            granular Designer / Printer Operator / Application costing.
          </div>
        ) : (
          <>
            <div className="grid grid-cols-12 gap-2 text-[10px] uppercase tracking-wider text-slate-500">
              <div className="col-span-5">Role</div>
              <div className="col-span-3 text-right">$/hr</div>
              <div className="col-span-2 text-right">Hours</div>
              <div className="col-span-2 text-right">Total</div>
            </div>
            {personnel.map((p, idx) => {
              const rowIssues = issues.filter(i => i.itemIndex === idx);
              return (
              <div key={idx}>
                <div className="grid grid-cols-12 gap-2 items-center">
                <div className="col-span-5">
                  <Input value={p.role || ""} onChange={(e) => update(idx, { role: e.target.value })} className="h-8 text-sm" />
                </div>
                <div className="col-span-3">
                  <Input type="number" step="0.5" value={p.hourly_rate ?? ""}
                    onChange={(e) => update(idx, { hourly_rate: vinylDraftValue(e.target.value) })}
                    aria-invalid={hasIssueFor(issues, "hourly_rate", idx) || undefined}
                    aria-describedby={hasIssueFor(issues, "hourly_rate", idx) ? `${issuesId || "vinyl-wf-issues"}-role-${idx}` : undefined}
                    className="h-8 text-sm text-right tabular-nums" />
                </div>
                <div className="col-span-2">
                  <Input type="number" step="0.25" value={p.hours ?? ""}
                    onChange={(e) => update(idx, { hours: vinylDraftValue(e.target.value) })}
                    aria-invalid={hasIssueFor(issues, "hours", idx) || undefined}
                    aria-describedby={hasIssueFor(issues, "hours", idx) ? `${issuesId || "vinyl-wf-issues"}-role-${idx}` : undefined}
                    className="h-8 text-sm text-right tabular-nums" />
                </div>
                <div className="col-span-1 text-right text-sm tabular-nums">
                  {vinylNumber(p.total_cost) !== null ? `$${num(p.total_cost).toFixed(2)}` : "—"}
                </div>
                <div className="col-span-1 text-right">
                  <Button size="icon" variant="ghost" className="h-7 w-7" onClick={() => remove(idx)}>
                    <X className="w-3.5 h-3.5 text-red-600" />
                  </Button>
                </div>
                </div>
                {rowIssues.length > 0 && (
                  <div role="status" id={`${issuesId || "vinyl-wf-issues"}-role-${idx}`}
                    className="flex items-start gap-2 text-[11px] text-amber-900 bg-amber-50 border border-amber-200 rounded px-2 py-1 mt-1">
                    <AlertTriangle className="w-3 h-3 mt-0.5 flex-shrink-0" />
                    <div className="space-y-0.5">
                      {rowIssues.map((it, i2) => <div key={i2}>{it.message}</div>)}
                    </div>
                  </div>
                )}
              </div>
              );
            })}
            <div className="flex justify-between text-xs pt-2 border-t border-slate-100">
              <span className="text-slate-500">{totalHours.toFixed(2)} hr total</span>
              <span className="font-semibold tabular-nums">${totalCost.toFixed(2)}</span>
            </div>
          </>
        )}
        {personnel.length === 0 && roleOptions.length > 0 && (
          <div className="flex flex-wrap gap-1 pt-1">
            <span className="text-[10px] text-slate-500 mr-1">Quick add:</span>
            {["Designer", "Printer Operator", "Application Technician"].map(role => (
              roleOptions.some(r => r.role === role) && (
                <Button key={role} size="sm" variant="outline" className="h-6 text-xs" onClick={() => add(role)}>
                  <Plus className="w-3 h-3 mr-1" /> {role}
                </Button>
              )
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

// Save & apply workflow templates. Feature #16.
// "3M IJ180 + 8508 on HP360+Graphtec" → one click to populate a new workflow.

import { useEffect, useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { VinylWorkflowTemplate } from "@/entities/all";
import { Bookmark, Plus, Trash2 } from "lucide-react";
import { createVinylTemplateWithRecovery, deleteVinylTemplateIfUnchanged } from "./vinylTemplatePersistence";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";

export default function VinylWorkflowTemplatesDialog({
  open, onClose, mode = "apply", currentWorkflow, onApply,
}) {
  const [templates, setTemplates] = useState([]);
  const [newName, setNewName] = useState("");
  const [isMutating, setIsMutating] = useState(false);
  const [mutationError, setMutationError] = useState("");

  const load = async () => setTemplates(await loadAllEntityRows({ entity: VinylWorkflowTemplate, sort: "sort_order", label: "Vinyl workflow templates" }));
  useEffect(() => { if (open) load(); }, [open]);

  const handleSave = async () => {
    if (!newName.trim() || isMutating) return;
    setIsMutating(true);
    setMutationError("");
    try {
      await createVinylTemplateWithRecovery({
        entity: VinylWorkflowTemplate,
        data: {
          name: newName.trim(),
          vinyl_id:     currentWorkflow.vinyl_id     || "",
          laminate_id:  currentWorkflow.laminate_id  || "",
          printer_id:   currentWorkflow.printer_id   || "",
          cutter_id:    currentWorkflow.cutter_id    || "",
          laminator_id: currentWorkflow.laminator_id || "",
          apply_print:    currentWorkflow.apply_print,
          apply_cut:      currentWorkflow.apply_cut,
          apply_laminate: currentWorkflow.apply_laminate,
          preset_key:     currentWorkflow.preset_key || "",
          color_tag:      currentWorkflow.color_tag  || "",
        },
        label: "Vinyl workflow template",
      });
      setNewName("");
      await load();
    } catch (error) {
      console.error("Vinyl workflow template create blocked:", error);
      setMutationError(error?.message || "The workflow template could not be created. Reload before retrying.");
    } finally {
      setIsMutating(false);
    }
  };

  const handleDelete = async (template) => {
    if (!template?.id || isMutating || !confirm("Delete this template?")) return;
    setIsMutating(true);
    setMutationError("");
    try {
      await deleteVinylTemplateIfUnchanged({
        entity: VinylWorkflowTemplate,
        template,
        label: `Vinyl workflow template ${template.name || template.id} deletion`,
      });
      await load();
    } catch (error) {
      console.error("Vinyl workflow template deletion blocked:", error);
      setMutationError(error?.message || "This workflow template changed in another session. Reload before deleting it.");
    } finally {
      setIsMutating(false);
    }
  };

  const handleApply = (t) => {
    onApply({
      vinyl_id:     t.vinyl_id     || "",
      laminate_id:  t.laminate_id  || "",
      printer_id:   t.printer_id   || "",
      cutter_id:    t.cutter_id    || "",
      laminator_id: t.laminator_id || "",
      apply_print:    !!t.apply_print,
      apply_cut:      !!t.apply_cut,
      apply_laminate: !!t.apply_laminate,
      preset_key:     t.preset_key || "",
      color_tag:      t.color_tag  || "",
    });
    onClose();
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Bookmark className="w-5 h-5 text-blue-600" /> Workflow Templates
          </DialogTitle>
        </DialogHeader>
        <div className="space-y-3">
          {templates.length === 0 ? (
            <div className="text-xs text-slate-400 text-center py-4">No templates saved yet.</div>
          ) : (
            <div className="border border-slate-200 rounded divide-y divide-slate-100 max-h-64 overflow-auto">
              {templates.map(t => (
                <div key={t.id} className="flex items-center gap-2 p-2 hover:bg-slate-50">
                  {t.color_tag && <span className="w-3 h-3 rounded-full" style={{ background: t.color_tag }} />}
                  <button type="button" onClick={() => handleApply(t)} className="flex-1 text-left text-sm">
                    <div className="font-medium">{t.name}</div>
                    <div className="text-[10px] text-slate-500">
                      {t.preset_key || "custom"} · {[t.apply_print && "print", t.apply_cut && "cut", t.apply_laminate && "lam"].filter(Boolean).join(" + ")}
                    </div>
                  </button>
                  <Button size="icon" variant="ghost" onClick={() => handleApply(t)} className="h-7 w-7 text-blue-600" title="Apply">
                    <Plus className="w-3.5 h-3.5" />
                  </Button>
                  <Button size="icon" variant="ghost" onClick={() => handleDelete(t)} className="h-7 w-7 text-red-500">
                    <Trash2 className="w-3.5 h-3.5" />
                  </Button>
                </div>
              ))}
            </div>
          )}

          {mutationError && <div className="text-xs text-red-600">{mutationError}</div>}

          {mode === "save" && currentWorkflow && (
            <div className="border-t border-slate-200 pt-3 space-y-2">
              <Label className="text-xs">Save current workflow as template</Label>
              <div className="flex gap-2">
                <Input value={newName} onChange={(e) => setNewName(e.target.value)} placeholder="e.g. 3M IJ180 + 8508 on HP360" className="h-8 text-sm" />
                <Button size="sm" onClick={handleSave} disabled={!newName.trim() || isMutating} className="h-8">Save</Button>
              </div>
            </div>
          )}
        </div>
        <DialogFooter><Button variant="outline" onClick={onClose}>Close</Button></DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

// Helpers for per-part costing + roll-stock comparisons.
// Feature #6 (stock check), #19 (per-part), #21 (yield), #22 (vinyl compare).

const num = (v, d = 0) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : d;
};

// --- Per-part cost rollup. Allocates workflow cost down to each placed part
// by its share of total used area (so a 24x24 sticker gets ~4x the cost of a 12x12).
// Returns: { byPartIdx: { idx: { partsPlaced, sqFt, vinylCost, inkCost, cutCost, machineCost, laborCost, totalCost, costEach } } }
export const computePerPartCosts = (calc, items) => {
  const byPartIdx = {};
  // Held calcs null the tainted fields — a null usedSqFt must not slip
  // through `<= 0` semantics, so require a real positive number.
  if (!calc || !calc.shelves || !(calc.usedSqFt > 0)) return byPartIdx;

  const totalUsedSqIn = calc.shelves.reduce(
    (s, sh) => s + sh.items.reduce((ss, it) => ss + it.w * it.h, 0), 0
  );
  if (totalUsedSqIn <= 0) return byPartIdx;

  // Aggregate placed area + count per source item idx
  calc.shelves.forEach(sh => sh.items.forEach(it => {
    const k = it.itemIdx;
    if (!byPartIdx[k]) {
      byPartIdx[k] = { partsPlaced: 0, sqIn: 0, perimeterIn: 0 };
    }
    byPartIdx[k].partsPlaced += 1;
    byPartIdx[k].sqIn += it.w * it.h;
    byPartIdx[k].perimeterIn += 2 * (it.w + it.h);
  }));

  const totalPerimeter = Object.values(byPartIdx).reduce((s, p) => s + p.perimeterIn, 0);

  Object.entries(byPartIdx).forEach(([k, p]) => {
    const areaShare = p.sqIn / totalUsedSqIn;
    const perimShare = totalPerimeter > 0 ? p.perimeterIn / totalPerimeter : areaShare;
    p.sqFt = p.sqIn / 144;
    p.vinylCost    = (calc.vinylCost    || 0) * areaShare;
    p.laminateCost = (calc.laminateCost || 0) * areaShare;
    p.inkCost      = (calc.inkCost      || 0) * areaShare;
    // Cut-related cost is driven by perimeter, not area
    p.cutCost      = (calc.cutMachineCost || 0) * perimShare + (calc.bladeCost || 0) * perimShare;
    // Print machine cost is area-driven; laminator is length-driven (approximate by area share)
    p.machineCost  = (calc.printMachineCost || 0) * areaShare + (calc.laminateMachineCost || 0) * areaShare;
    p.laborCost    = (calc.laborCost   || 0) * areaShare;
    p.totalCost    = p.vinylCost + p.laminateCost + p.inkCost + p.cutCost + p.machineCost + p.laborCost;
    p.costEach     = p.partsPlaced > 0 ? p.totalCost / p.partsPlaced : 0;
    // Tie back to original item description for display
    const sourceItem = items?.[parseInt(k)];
    p.description = sourceItem?.description || `Item ${parseInt(k) + 1}`;
  });

  return byPartIdx;
};

// --- Workflow margin / yield metrics. Feature #20, #21.
// Held calcs carry null for tainted fields — propagate that instead of
// laundering it into 0 so the header badge shows "—" rather than a fake $0.
export const computeWorkflowMetrics = (calc) => {
  const used = num(calc?.usedSqFt);
  const pulled = num(calc?.totalRollSqFtPulled);
  const totalCost = calc?.totalCost;       // may be null when held
  const materialCost = calc?.materialCost; // may be null when held

  return {
    sqFtUsed: used,
    sqFtPulled: pulled,
    yieldPercent: pulled > 0 ? (used / pulled) * 100 : 0,
    wastePercent: pulled > 0 ? Math.max(0, (1 - used / pulled) * 100) : 0,
    costPerSqFt: used > 0 && Number.isFinite(totalCost) ? totalCost / used : null,
    materialPercent: Number.isFinite(totalCost) && totalCost > 0 && Number.isFinite(materialCost)
      ? (materialCost / totalCost) * 100 : null,
  };
};

// --- Stock check vs VinylInventory. Feature #6.
// One full roll = roll_width × (roll_length_yards × 36) inches.
export const computeStockUsage = (calc, vinyl) => {
  if (!calc || !vinyl) return null;
  const rollLengthIn = num(vinyl.roll_length_yards) * 36;
  if (rollLengthIn <= 0) return null;
  // Held calcs null the consumed length — no honest stock check.
  if (!Number.isFinite(calc.lengthConsumedIn)) return null;
  const consumedIn = calc.lengthConsumedIn;
  const rollsNeeded = consumedIn / rollLengthIn;
  return {
    rollLengthIn,
    consumedIn,
    rollsNeeded,
    exceedsOneRoll: rollsNeeded > 1.0,
    fullRollsNeeded: Math.ceil(rollsNeeded),
    percentOfRoll: rollsNeeded * 100,
  };
};

// --- "If you used vinyl B instead" comparison. Feature #22.
// Just recomputes vinylCost using vinyl B's $/sqft × actual pulled area × waste factor.
export const computeAlternativeVinylCost = (calc, altVinyl) => {
  if (!calc || !altVinyl) return null;
  const widthFt = num(altVinyl.roll_width_inches) / 12;
  const lenFt = num(altVinyl.roll_length_yards) * 3;
  const rollSqFt = widthFt * lenFt;
  let altRate = 0;
  if (altVinyl.pricing_mode === "per_sqft")        altRate = num(altVinyl.cost_per_sqft);
  else if (altVinyl.pricing_mode === "per_linear_foot") altRate = num(altVinyl.cost_per_linear_foot) / Math.max(widthFt, 0.01);
  else                                              altRate = rollSqFt > 0 ? num(altVinyl.cost_per_roll) / rollSqFt : 0;
  const altWasteMult = 1 + num(altVinyl.waste_factor_percent, 0) / 100;
  return num(calc.totalRollSqFtPulled) * altRate * altWasteMult;
};

// --- Lifetime / outdoor compatibility warning. Feature #27 (bundled).
export const computeLifetimeWarning = (vinyl, environment) => {
  if (!vinyl || environment !== "exterior") return null;
  const yrs = num(vinyl.expected_life_years_outdoor);
  if (yrs > 0 && yrs < 3) {
    return { severity: "high", message: `Outdoor life only ${yrs} years — consider a longer-life vinyl for exterior installs.` };
  }
  if (vinyl.indoor_outdoor === "indoor_only") {
    return { severity: "high", message: "This vinyl is marked indoor-only but the project is exterior." };
  }
  return null;
};

// Canonical vinyl labor roles + the rules tying them to machines and to the
// calculator's suggested hours.
//
// Roles live in Master Inventory → Labor & Services as `shop_labor` rows whose
// `service_name` is one of VINYL_ROLE_NAMES. We load those rows and resolve a
// rate per role (shop_rate_per_hour → default_rate fallback). If a role row is
// missing, we fall back to DEFAULT_ROLE_RATE so the dropdown still works.

import { base44 } from "@/api/base44Client";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { staffEntities } from "@/components/staff/staffEntities";

// Full, non-abbreviated role names. NOTE: no "Installer".
export const VINYL_ROLE_NAMES = [
  "Designer",
  "Pre-Press",
  "Printer Operator",
  "Cutter Operator",
  "Laminator Operator",
  "Weeder",
  "Application Technician",
  "Helper",
];

// Used only if a role isn't found in the labor inventory.
export const DEFAULT_ROLE_RATE = {
  "Designer": 65,
  "Pre-Press": 55,
  "Printer Operator": 55,
  "Cutter Operator": 50,
  "Laminator Operator": 45,
  "Weeder": 38,
  "Application Technician": 45,
  "Helper": 32,
};

const num = (v, d = 0) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : d;
};

// Load vinyl labor roles from the labor inventory, keyed by role name.
// Returns [{ role, hourly_rate }] in VINYL_ROLE_NAMES order.
export async function loadVinylLaborRoles() {
  const rows = await loadAllEntityRows({
    entity: staffEntities.LaborServiceInventory,
    query: { service_category: "shop_labor" },
    sort: "service_name",
    label: "Vinyl labor roles",
  });
  const byName = {};
  rows.forEach((r) => {
    if (VINYL_ROLE_NAMES.includes(r.service_name)) {
      byName[r.service_name] = num(r.shop_rate_per_hour, num(r.default_rate, DEFAULT_ROLE_RATE[r.service_name] || 0));
    }
  });
  return VINYL_ROLE_NAMES.map((role) => ({
    role,
    hourly_rate: byName[role] ?? DEFAULT_ROLE_RATE[role] ?? 0,
  }));
}

// Which roles each machine auto-selects.
//   printer    → Printer Operator
//   laminator  → Laminator Operator
//   cutter     → Printer Operator + Weeder  (per spec)
export const MACHINE_AUTO_ROLES = {
  printer: ["Printer Operator"],
  laminator: ["Laminator Operator"],
  cutter: ["Printer Operator", "Weeder"],
};

// Suggested hours for a given role, derived from the calculator breakdown.
// calc carries machineRunMinutes split + weeding/install minutes; we map the
// relevant slice to each operator role.
export function suggestedHoursForRole(role, calc) {
  if (!calc) return 0;
  const min = (v) => (Number.isFinite(v) ? v : 0);
  switch (role) {
    case "Printer Operator":   return (min(calc.printMinutes)) / 60;
    case "Cutter Operator":    return (min(calc.cutMinutes)) / 60;
    case "Laminator Operator": return (min(calc.laminateMinutes)) / 60;
    case "Weeder":             return (min(calc.weedingMinutes)) / 60;
    case "Application Technician": return (min(calc.installMinutes)) / 60;
    default:                   return 0; // Designer / Pre-Press / Helper → manual
  }
}

// Vinyl Estimator — shelf packing + cost engine.
//
// Algorithm: Next Fit Decreasing Height (NFDH).
//   1. Expand items into rectangles (one per qty), add bleed all around.
//      A project-level `spoilageBufferPercent` inflates qty BEFORE expansion.
//   2. Sort by height descending.
//   3. Greedily pack across shelves (rows) inside roll usable width.
//      Try rotated orientation if it fits and reduces shelf height.
//   4. Compute roll length consumed (incl. leading/trailing edges + cut pull-off).
//   5. Derive: vinyl, laminate, transfer-tape, ink, machine time, blade wear,
//      operator labor, weeding labor (per-part), install labor (per-part),
//      and per-personnel labor (designer/printer-op/installer).
//   6. Apply a per-workflow `setupFeeFloor` minimum.

import { WEEDING_LABOR_MINUTES_PER_PART, inkCostPerSqIn } from "@/components/vinylInventory/vinylConstants";

const num = (v, d = 0) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : d;
};

const sqInToSqFt = (sqIn) => sqIn / 144;

const computeRollSqFtCost = (vinyl) => {
  if (!vinyl) return 0;
  const widthFt = num(vinyl.roll_width_inches) / 12;
  const lenFt = num(vinyl.roll_length_yards) * 3;
  const rollSqFt = widthFt * lenFt;

  if (vinyl.pricing_mode === "per_sqft")        return num(vinyl.cost_per_sqft);
  if (vinyl.pricing_mode === "per_linear_foot") return num(vinyl.cost_per_linear_foot) / Math.max(widthFt, 0.01);
  return rollSqFt > 0 ? num(vinyl.cost_per_roll) / rollSqFt : 0; // per_roll
};

/**
 * @param {object} args
 * @param {Array}  args.items
 * @param {object} args.printer | args.cutter | args.laminator
 * @param {object} args.vinyl | args.laminate | args.transferTape
 * @param {number} args.operatorHourlyRate
 * @param {boolean} args.applyPrint | args.applyCut | args.applyLaminate | args.applyTransferTape
 * @param {number} args.overrideGutterH | args.overrideGutterV
 * @param {string} args.printQuality       — "draft" | "production" | "high_quality" (default)
 * @param {string} args.weedingDifficulty  — drives per-part weeding minutes
 * @param {number} args.weedingMinutesPerPartOverride
 * @param {number} args.installMinutesPerPart — application/install minutes per part
 * @param {Array}  args.personnel          — [{ role, hourly_rate, hours }]
 * @param {number} args.spoilageBufferPercent — N% extra qty for reprint waste (pre-nesting)
 * @param {number} args.setupFeeFloor      — workflow minimum charge
 */
export function calculateVinylProject({
  items = [],
  printer = null, cutter = null, laminator = null,
  vinyl = null, laminate = null, transferTape = null,
  operatorHourlyRate = 45,
  applyPrint = true, applyCut = true, applyLaminate = false, applyTransferTape = false,
  overrideGutterH, overrideGutterV,
  printQuality = "high_quality",
  weedingDifficulty = "moderate",
  weedingMinutesPerPartOverride,
  installMinutesPerPart = 0,
  personnel = [],
  spoilageBufferPercent = 0,
  setupFeeFloor = 0,
} = {}) {

  // --- Roll geometry — driven by the leading machine (printer > cutter > laminator).
  const leadingMachine = (applyPrint && printer) || (applyCut && cutter) || (applyLaminate && laminator) || printer || cutter || laminator;

  const rollWidth = num(vinyl?.roll_width_inches, 54);
  const leftMargin   = num(leadingMachine?.left_margin_inches, 0.5);
  const rightMargin  = num(leadingMachine?.right_margin_inches, 0.5);
  const leadingEdge  = num(leadingMachine?.leading_edge_inches, 4);
  const trailingEdge = num(leadingMachine?.trailing_edge_inches, 2);

  const machineWidthCap = Math.min(
    applyPrint && printer ? num(printer.max_media_width_inches, 999) : 999,
    applyCut && cutter ? num(cutter.max_media_width_inches, 999) : 999,
    applyLaminate && laminator ? num(laminator.max_media_width_inches, 999) : 999,
  );
  const effectiveRollWidth = Math.min(rollWidth, machineWidthCap);
  const usableWidth = Math.max(0, effectiveRollWidth - leftMargin - rightMargin);

  const gutterH = overrideGutterH ?? num(leadingMachine?.default_gutter_horizontal_inches, 0.25);
  const gutterV = overrideGutterV ?? num(leadingMachine?.default_gutter_vertical_inches, 0.25);

  // --- Spoilage buffer (#4): inflate qty by N% (rounded up) before expansion.
  const spoilMult = 1 + Math.max(0, num(spoilageBufferPercent, 0)) / 100;

  // --- Expand items into rectangles.
  const rects = [];
  items.forEach((it, itemIdx) => {
    const baseBleed = num(it.bleed_inches, num(leadingMachine?.default_bleed_inches, 0));
    const partW = num(it.width_inches);
    const partH = num(it.height_inches);
    const w0 = partW + baseBleed * 2;
    const h0 = partH + baseBleed * 2;
    const rawQty = Math.max(1, Math.floor(num(it.quantity, 1)));
    const qty = Math.max(rawQty, Math.ceil(rawQty * spoilMult));
    if (partW <= 0 || partH <= 0) return;

    for (let i = 0; i < qty; i++) {
      rects.push({
        id: `${it.id || itemIdx}-${i}`,
        itemId: it.id || `idx-${itemIdx}`,
        itemIdx,
        description: it.description || `Item ${itemIdx + 1}`,
        w: w0, h: h0,
        partW, partH,
        bleed: baseBleed,
        allow_rotation: it.allow_rotation === true,
        rotated: false,
      });
    }
  });

  rects.sort((a, b) => b.h - a.h);

  const shelves = [];
  let yCursor = 0;
  let currentShelf = null;

  const orientedDims = (r) => {
    if (r.allow_rotation) return { w: r.h, h: r.w, partW: r.partH, partH: r.partW, rotated: true };
    return { w: r.w, h: r.h, partW: r.partW, partH: r.partH, rotated: false };
  };

  const placeOnNewShelf = (r) => {
    const { w, h, partW: pw, partH: ph, rotated } = orientedDims(r);
    if (w > usableWidth) return false;
    currentShelf = { y: yCursor, height: h, items: [] };
    shelves.push(currentShelf);
    currentShelf.items.push({ ...r, x: 0, y: yCursor, w, h, partW: pw, partH: ph, rotated });
    yCursor += h + gutterV;
    return true;
  };

  for (const r of rects) {
    if (!currentShelf) {
      if (!placeOnNewShelf(r)) continue;
      continue;
    }
    const { w, h, partW: pw, partH: ph, rotated } = orientedDims(r);
    const lastItem = currentShelf.items[currentShelf.items.length - 1];
    const nextX = lastItem ? lastItem.x + lastItem.w + gutterH : 0;
    let placed = false;
    if (w <= usableWidth - nextX && h <= currentShelf.height) {
      currentShelf.items.push({ ...r, x: nextX, y: currentShelf.y, w, h, partW: pw, partH: ph, rotated });
      placed = true;
    }
    if (!placed) placeOnNewShelf(r);
  }

  // --- Layout metrics
  const contentLengthIn = shelves.length === 0
    ? 0
    : (shelves[shelves.length - 1].y + shelves[shelves.length - 1].height);
  const totalLengthIn = contentLengthIn;

  const cutPullOff = applyCut && cutter ? num(cutter.cut_pull_off_inches_per_job, 0) : 0;
  const lengthConsumedIn = leadingEdge + contentLengthIn + trailingEdge + cutPullOff;
  const lengthConsumedFt = lengthConsumedIn / 12;

  const usedSqIn = shelves.reduce((s, sh) => s + sh.items.reduce((ss, it) => {
    const pw = it.partW ?? it.w;
    const ph = it.partH ?? it.h;
    return ss + pw * ph;
  }, 0), 0);
  const usedSqFt = sqInToSqFt(usedSqIn);

  const totalRollSqFtPulled = sqInToSqFt(lengthConsumedIn * effectiveRollWidth);
  const wastedSqFt = Math.max(0, totalRollSqFtPulled - usedSqFt);

  const partsPlaced = shelves.reduce((s, sh) => s + sh.items.length, 0);
  const partsRequested = rects.length;
  const partsUnplaced = partsRequested - partsPlaced;

  // --- Vinyl cost
  const vinylSqFtRate = computeRollSqFtCost(vinyl);
  const vinylWasteMult = 1 + num(vinyl?.waste_factor_percent, 0) / 100;
  const vinylCost = totalRollSqFtPulled * vinylSqFtRate * vinylWasteMult;

  // --- Laminate
  let laminateSqFt = 0, laminateCost = 0, laminateMinutes = 0;
  if (applyLaminate && laminate) {
    const lamWidth = Math.min(num(laminate.roll_width_inches, effectiveRollWidth), effectiveRollWidth);
    const lamLengthIn = lengthConsumedIn + num(laminator?.leading_edge_inches, 0) + num(laminator?.trailing_edge_inches, 0);
    laminateSqFt = sqInToSqFt(lamLengthIn * lamWidth);
    const lamSqFtRate = computeRollSqFtCost(laminate);
    const lamWasteMult = 1 + num(laminate.waste_factor_percent, 0) / 100;
    laminateCost = laminateSqFt * lamSqFtRate * lamWasteMult;

    const ipm = Math.max(1, num(laminator?.laminator_speed_inches_per_minute, 100));
    laminateMinutes = (lamLengthIn / ipm) + num(laminator?.laminator_setup_minutes_per_job, 0);
  }

  // --- Print: ink uses TIERED $/sqin by print quality.
  let inkCost = 0, printMinutes = 0, printMachineCost = 0;
  const inkRatePerSqIn = applyPrint && printer ? inkCostPerSqIn(printer, printQuality) : 0;
  if (applyPrint && printer) {
    inkCost = (usedSqFt * 144) * inkRatePerSqIn;
    const sph = Math.max(1, num(printer.print_speed_sqft_per_hour, 100));
    printMinutes =
      (usedSqFt / sph) * 60 +
      num(printer.warmup_minutes, 0) +
      num(printer.media_load_minutes, 0) +
      num(printer.calibration_minutes_per_job, 0);
    printMachineCost = (printMinutes / 60) * num(printer.machine_hourly_rate, 0);
  }

  // --- Cut
  let cutDistanceIn = 0, cutMinutes = 0, cutMachineCost = 0, bladeCost = 0;
  if (applyCut && cutter) {
    cutDistanceIn = shelves.reduce((s, sh) => s + sh.items.reduce((ss, it) => {
      const pw = it.partW ?? it.w;
      const ph = it.partH ?? it.h;
      return ss + 2 * (pw + ph);
    }, 0), 0);
    const ips = Math.max(0.1, num(cutter.cut_speed_inches_per_second, 30));
    cutMinutes = (cutDistanceIn / ips) / 60 + num(cutter.cut_setup_minutes_per_job, 0);
    cutMachineCost = (cutMinutes / 60) * num(cutter.machine_hourly_rate, 0);
    const bladeLife = Math.max(1, num(cutter.cut_blade_life_minutes, 6000));
    bladeCost = (cutMinutes / bladeLife) * num(cutter.cut_blade_cost, 0);
  }

  const laminateMachineCost = applyLaminate && laminator
    ? (laminateMinutes / 60) * num(laminator.laminator_hourly_rate, 0)
    : 0;

  // --- Transfer Tape
  let transferTapeSqFt = 0, transferTapeCost = 0;
  if (applyTransferTape && transferTape) {
    const ttWidth = Math.min(num(transferTape.roll_width_inches, effectiveRollWidth), effectiveRollWidth);
    transferTapeSqFt = sqInToSqFt(lengthConsumedIn * ttWidth);
    const ttSqFtRate = computeRollSqFtCost(transferTape);
    const ttWasteMult = 1 + num(transferTape.waste_factor_percent, 0) / 100;
    transferTapeCost = transferTapeSqFt * ttSqFtRate * ttWasteMult;
  }

  const machineCost = printMachineCost + cutMachineCost + laminateMachineCost;

  // --- Machine-operator labor (running the printer/cutter/laminator)
  const machineRunMinutes = (applyPrint ? printMinutes : 0) + (applyCut ? cutMinutes : 0) + (applyLaminate ? laminateMinutes : 0);

  // --- Weeding labor (per placed part) — only meaningful when cutting
  const weedMinPerPart = Number.isFinite(parseFloat(weedingMinutesPerPartOverride))
    ? parseFloat(weedingMinutesPerPartOverride)
    : (WEEDING_LABOR_MINUTES_PER_PART[weedingDifficulty] ?? WEEDING_LABOR_MINUTES_PER_PART.moderate);
  const weedingMinutes = applyCut ? weedMinPerPart * partsPlaced : 0;

  // --- Install/application labor (per placed part)
  const installMinPerPart = Math.max(0, num(installMinutesPerPart, 0));
  const installMinutes = installMinPerPart * partsPlaced;

  // --- Per-personnel labor (designer / printer op / installer / ...)
  // If personnel rows are given, those drive the labor cost. Otherwise we fall
  // back to the operator rate × (machine + weeding + install) minutes.
  let perPersonnelCost = 0;
  let perPersonnelMinutes = 0;
  (personnel || []).forEach((p) => {
    const hrs = num(p?.hours, 0);
    const rate = num(p?.hourly_rate, 0);
    if (hrs > 0 && rate > 0) {
      perPersonnelCost += hrs * rate;
      perPersonnelMinutes += hrs * 60;
    }
  });

  const fallbackLaborMinutes = machineRunMinutes + weedingMinutes + installMinutes;
  const fallbackLaborCost    = (fallbackLaborMinutes / 60) * num(operatorHourlyRate, 45);

  const laborMinutes = perPersonnelMinutes > 0 ? perPersonnelMinutes : fallbackLaborMinutes;
  const laborHours   = laborMinutes / 60;
  const laborCost    = perPersonnelCost > 0 ? perPersonnelCost : fallbackLaborCost;

  const materialCost = vinylCost + laminateCost + transferTapeCost + inkCost + bladeCost;
  const preFloorTotal = materialCost + machineCost + laborCost;

  // --- Setup-fee floor (#3): workflow minimum
  const floor = Math.max(0, num(setupFeeFloor, 0));
  const setupFeeApplied = preFloorTotal < floor ? (floor - preFloorTotal) : 0;
  const totalCost = preFloorTotal + setupFeeApplied;

  return {
    // geometry
    usableWidth, effectiveRollWidth, leadingEdge, trailingEdge, gutterH, gutterV,
    shelves, partsPlaced, partsRequested, partsUnplaced,
    totalLengthIn, lengthConsumedIn, lengthConsumedFt,
    usedSqFt, totalRollSqFtPulled, wastedSqFt,
    // cost breakdown
    vinylCost, laminateCost, laminateSqFt,
    transferTapeCost, transferTapeSqFt,
    inkCost, inkRatePerSqIn, printQuality,
    printMinutes, printMachineCost,
    cutDistanceIn, cutMinutes, cutMachineCost, bladeCost,
    laminateMinutes, laminateMachineCost,
    machineCost,
    // labor split
    machineRunMinutes, weedingMinutes, installMinutes,
    weedMinPerPart, installMinPerPart,
    perPersonnelCost, perPersonnelMinutes,
    laborMinutes, laborHours, laborCost,
    // floor
    preFloorTotal, setupFeeApplied,
    materialCost, totalCost,
  };
}

// Vinyl pricing-availability layer.
//
// Wraps calculateVinylProject with strict finite-number input validation so a
// missing, malformed, or unusable pricing input can no longer silently become
// $0, a hidden default, or a dropped part. Mirrors the Foundation hardening
// convention:
//   - strict parsers (vinylNumber / vinylNonNegativeNumber / vinylPositiveNumber)
//   - structured issue records { kind, index, itemIndex, inventoryId, field,
//     code, message, hold }
//   - "layout" availability poisons the whole workflow calc; narrower holds
//     only poison the cost groups they feed, and derived aggregates
//     (materialCost / machineCost / preFloorTotal / setupFeeApplied / totalCost)
//     are re-derived null-propagating afterwards.
//   - explicit 0 stays valid where the calculator already treats it as a real
//     free/zero price; quantities and dimensions of 0 are invalid.
//   - raw rows are never mutated — the calculator reads the original records
//     exactly as VinylWorkflowCard has always passed them.
//
// Valid inputs take the exact same code path as before: the calc object the
// card receives for a clean workflow is bit-identical to today's result
// (plus __held / pricingUnavailable / issues metadata flags).

import { calculateVinylProject } from "./vinylNestingCalculator";
import {
  WEEDING_LABOR_MINUTES_PER_PART,
} from "@/components/vinylInventory/vinylConstants";

// ---------- strict parsers ----------
// Finite number or null. Accepts real numbers and trimmed numeric strings;
// rejects "", "abc", Infinity, NaN, null, undefined, objects.
export const vinylNumber = (v) => {
  if (typeof v === "number") return Number.isFinite(v) ? v : null;
  if (typeof v === "string") {
    const t = v.trim();
    if (t === "") return null;
    if (!/^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/.test(t)) return null;
    const n = Number(t);
    return Number.isFinite(n) ? n : null;
  }
  return null;
};
export const vinylNonNegativeNumber = (v) => {
  const n = vinylNumber(v);
  return n !== null && n >= 0 ? n : null;
};
export const vinylPositiveNumber = (v) => {
  const n = vinylNumber(v);
  return n !== null && n > 0 ? n : null;
};
// Positive whole number (quantities). "2.7" is invalid — floor() would have
// silently repriced it.
export const vinylPositiveInteger = (v) => {
  const n = vinylNumber(v);
  return n !== null && n > 0 && Math.floor(n) === n ? n : null;
};

// A value that was actually recorded on the record (not absent/blank).
const recorded = (v) => v !== undefined && v !== null && v !== "";

// Saved acknowledged pricing snapshot — only a real finite number counts.
// This is the gate for "Saved amounts (not current pricing)" display.
export const hasVinylCostSnapshot = (v) => typeof v === "number" && Number.isFinite(v);

// Blank-preserving input helper for number fields (Foundation heightInput
// pattern): "" stays "" so the input does not fight the user mid-typing;
// parseable text becomes a number; anything else stays raw so validation can
// flag it instead of laundering it into 0.
export const vinylDraftValue = (raw) => {
  if (raw === "") return "";
  const n = Number(raw);
  return Number.isFinite(n) ? n : raw;
};

// ---------- issue records ----------
const issue = (kind, { index = null, itemIndex = null, inventoryId = null, field, code, message, hold = "layout" }) => ({
  kind, index, itemIndex, inventoryId, field, code, message, hold,
});

// Which calc output fields each hold poisons. Aggregates are always re-derived.
const HOLD_FIELDS = {
  // Layout problems make every derived number untrustworthy (geometry is wrong).
  layout: [
    "vinylCost", "laminateCost", "transferTapeCost", "inkCost", "bladeCost",
    "printMachineCost", "cutMachineCost", "laminateMachineCost",
    "perPersonnelCost", "laborCost", "laborHours", "laborMinutes",
    "perPersonnelMinutes",
    "inkRatePerSqIn",
    "usedSqFt", "totalRollSqFtPulled", "wastedSqFt", "laminateSqFt",
    "transferTapeSqFt", "lengthConsumedIn", "lengthConsumedFt", "totalLengthIn",
    "cutDistanceIn",
    "printMinutes", "cutMinutes", "laminateMinutes", "machineRunMinutes",
    "weedingMinutes", "installMinutes", "weedMinPerPart", "installMinPerPart",
  ],
  vinylPrice:      ["vinylCost"],
  laminatePrice:   ["laminateCost", "laminateSqFt"],
  ttPrice:         ["transferTapeCost", "transferTapeSqFt"],
  inkPrice:        ["inkCost", "inkRatePerSqIn"],
  printerMachine:  ["printMachineCost"],
  cutterMachine:   ["cutMachineCost", "bladeCost"],
  laminatorMachine:["laminateMachineCost"],
  labor:           [
    "perPersonnelCost", "perPersonnelMinutes",
    "laborCost", "laborMinutes", "laborHours",
    "weedingMinutes", "installMinutes", "weedMinPerPart", "installMinPerPart",
  ],
  floor:           ["setupFeeApplied"],
};

// ---------- catalog (VinylInventory) validation ----------
const MATERIAL_LABEL = { vinyl: "Vinyl", laminate: "Laminate", transfer_tape: "Transfer tape" };
const MATERIAL_PRICE_HOLD = { vinyl: "vinylPrice", laminate: "laminatePrice", transfer_tape: "ttPrice" };

// Validate the catalog fields a selected material record contributes to the
// calc. role: "vinyl" | "laminate" | "transfer_tape". Geometry fields are the
// "layout" hold; price fields use the role's price hold.
export const vinylMaterialIssues = (row, role, wfIdx, wfId) => {
  const issues = [];
  const label = MATERIAL_LABEL[role] || "Material";
  const priceHold = MATERIAL_PRICE_HOLD[role] || "layout";
  const invId = row?.id ?? null;
  const add = (field, code, message, hold) =>
    issues.push(issue("vinyl_catalog", { index: wfIdx, componentId: wfId, inventoryId: invId, field, code, message, hold }));

  // roll_width_inches — vinyl: usable roll width + per_roll/per_linear_foot
  // denominators; laminate/tt: material sqft width. Positive required.
  if (vinylPositiveNumber(row?.roll_width_inches) === null) {
    add("roll_width_inches", `vinyl_${role}_roll_width_unavailable`,
      `record a positive, finite ${label} roll width (inches) in Vinyl Inventory before repricing`,
      role === "vinyl" ? "layout" : priceHold);
  }

  // pricing_mode — drives which cost field is consumed.
  const mode = recorded(row?.pricing_mode) ? row.pricing_mode : "per_roll";
  if (!["per_roll", "per_sqft", "per_linear_foot"].includes(mode)) {
    add("pricing_mode", `vinyl_${role}_pricing_mode_unavailable`,
      `set a supported ${label} pricing mode (per_roll / per_sqft / per_linear_foot) in Vinyl Inventory before repricing`, priceHold);
  } else if (mode === "per_sqft") {
    if (vinylNonNegativeNumber(row?.cost_per_sqft) === null) {
      add("cost_per_sqft", `vinyl_${role}_price_unavailable`,
        `record a finite, nonnegative ${label} cost per sq ft — a missing price is not free`, priceHold);
    }
  } else if (mode === "per_linear_foot") {
    if (vinylNonNegativeNumber(row?.cost_per_linear_foot) === null) {
      add("cost_per_linear_foot", `vinyl_${role}_price_unavailable`,
        `record a finite, nonnegative ${label} cost per linear foot — a missing price is not free`, priceHold);
    }
  } else { // per_roll
    if (vinylNonNegativeNumber(row?.cost_per_roll) === null) {
      add("cost_per_roll", `vinyl_${role}_price_unavailable`,
        `record a finite, nonnegative ${label} cost per roll — a missing price is not free`, priceHold);
    }
    if (vinylPositiveNumber(row?.roll_length_yards) === null) {
      add("roll_length_yards", `vinyl_${role}_roll_length_unavailable`,
        `record a positive, finite ${label} roll length (yards) in Vinyl Inventory before repricing`,
        role === "vinyl" ? "layout" : priceHold);
    }
  }

  // waste_factor_percent — dormant when absent; recorded must parse >= 0.
  if (recorded(row?.waste_factor_percent) && vinylNonNegativeNumber(row.waste_factor_percent) === null) {
    add("waste_factor_percent", `vinyl_${role}_waste_factor_unavailable`,
      `record a finite, nonnegative ${label} waste factor % or clear it in Vinyl Inventory`, priceHold);
  }
  return issues;
};

// ---------- machine (VinylMachine) validation ----------
const machineAdd = (issues, wfIdx, machine, field, code, message, hold) =>
  issues.push(issue("vinyl_catalog", { index: wfIdx, inventoryId: machine?.id ?? null, field, code, message, hold }));

// Fields every applied machine contributes to roll layout when it leads.
const leadingMachineIssues = (issues, wfIdx, machine, label, overrides) => {
  const { gutterHOverridden, gutterVOverridden } = overrides;
  for (const [field, human] of [
    ["left_margin_inches", "left margin (inches)"],
    ["right_margin_inches", "right margin (inches)"],
    ["leading_edge_inches", "leading edge (inches)"],
    ["trailing_edge_inches", "trailing edge (inches)"],
  ]) {
    if (recorded(machine?.[field]) && vinylNonNegativeNumber(machine[field]) === null) {
      machineAdd(issues, wfIdx, machine, field, "vinyl_machine_margin_unavailable",
        `record a finite, nonnegative ${label} ${human} in Vinyl Settings before repricing`, "layout");
    }
  }
  if (!gutterHOverridden && recorded(machine?.default_gutter_horizontal_inches)
      && vinylNonNegativeNumber(machine.default_gutter_horizontal_inches) === null) {
    machineAdd(issues, wfIdx, machine, "default_gutter_horizontal_inches", "vinyl_machine_gutter_unavailable",
      `record a finite, nonnegative ${label} default horizontal gutter in Vinyl Settings or set a workflow override`, "layout");
  }
  if (!gutterVOverridden && recorded(machine?.default_gutter_vertical_inches)
      && vinylNonNegativeNumber(machine.default_gutter_vertical_inches) === null) {
    machineAdd(issues, wfIdx, machine, "default_gutter_vertical_inches", "vinyl_machine_gutter_unavailable",
      `record a finite, nonnegative ${label} default vertical gutter in Vinyl Settings or set a workflow override`, "layout");
  }
  // default_bleed_inches is consumed whenever an item leaves bleed blank.
  if (recorded(machine?.default_bleed_inches) && vinylNonNegativeNumber(machine.default_bleed_inches) === null) {
    machineAdd(issues, wfIdx, machine, "default_bleed_inches", "vinyl_machine_bleed_unavailable",
      `record a finite, nonnegative ${label} default bleed (inches) in Vinyl Settings`, "layout");
  }
  if (recorded(machine?.max_media_width_inches) && vinylPositiveNumber(machine.max_media_width_inches) === null) {
    machineAdd(issues, wfIdx, machine, "max_media_width_inches", "vinyl_machine_max_width_unavailable",
      `record a positive, finite ${label} max media width in Vinyl Settings before repricing`, "layout");
  }
};

const printerIssues = (issues, wfIdx, printer) => {
  if (vinylNonNegativeNumber(printer?.machine_hourly_rate) === null) {
    machineAdd(issues, wfIdx, printer, "machine_hourly_rate", "vinyl_machine_rate_unavailable",
      "record a finite, nonnegative printer machine hourly rate in Vinyl Settings — a missing rate is not free", "printerMachine");
  }
  if (recorded(printer?.print_speed_sqft_per_hour) && vinylPositiveNumber(printer.print_speed_sqft_per_hour) === null) {
    machineAdd(issues, wfIdx, printer, "print_speed_sqft_per_hour", "vinyl_machine_speed_unavailable",
      "record a positive, finite printer speed (sq ft/hour) in Vinyl Settings before repricing", "printerMachine");
  }
  for (const field of ["warmup_minutes", "media_load_minutes", "calibration_minutes_per_job"]) {
    if (recorded(printer?.[field]) && vinylNonNegativeNumber(printer[field]) === null) {
      machineAdd(issues, wfIdx, printer, field, "vinyl_machine_minutes_unavailable",
        `record a finite, nonnegative printer ${field.replace(/_/g, " ")} in Vinyl Settings before repricing`, "printerMachine");
    }
  }
};

const cutterIssues = (issues, wfIdx, cutter) => {
  if (vinylNonNegativeNumber(cutter?.machine_hourly_rate) === null) {
    machineAdd(issues, wfIdx, cutter, "machine_hourly_rate", "vinyl_machine_rate_unavailable",
      "record a finite, nonnegative cutter machine hourly rate in Vinyl Settings — a missing rate is not free", "cutterMachine");
  }
  if (vinylNonNegativeNumber(cutter?.cut_blade_cost) === null) {
    machineAdd(issues, wfIdx, cutter, "cut_blade_cost", "vinyl_machine_blade_unavailable",
      "record a finite, nonnegative cutter blade cost in Vinyl Settings — a missing blade cost is not free", "cutterMachine");
  }
  if (recorded(cutter?.cut_speed_inches_per_second) && vinylPositiveNumber(cutter.cut_speed_inches_per_second) === null) {
    machineAdd(issues, wfIdx, cutter, "cut_speed_inches_per_second", "vinyl_machine_speed_unavailable",
      "record a positive, finite cut speed (inches/second) in Vinyl Settings before repricing", "cutterMachine");
  }
  if (recorded(cutter?.cut_setup_minutes_per_job) && vinylNonNegativeNumber(cutter.cut_setup_minutes_per_job) === null) {
    machineAdd(issues, wfIdx, cutter, "cut_setup_minutes_per_job", "vinyl_machine_minutes_unavailable",
      "record a finite, nonnegative cut setup minutes in Vinyl Settings before repricing", "cutterMachine");
  }
  if (recorded(cutter?.cut_blade_life_minutes) && vinylPositiveNumber(cutter.cut_blade_life_minutes) === null) {
    machineAdd(issues, wfIdx, cutter, "cut_blade_life_minutes", "vinyl_machine_blade_unavailable",
      "record a positive, finite blade life (minutes) in Vinyl Settings before repricing", "cutterMachine");
  }
  // Pull-off feeds roll length consumed → layout hold.
  if (recorded(cutter?.cut_pull_off_inches_per_job) && vinylNonNegativeNumber(cutter.cut_pull_off_inches_per_job) === null) {
    machineAdd(issues, wfIdx, cutter, "cut_pull_off_inches_per_job", "vinyl_machine_pull_off_unavailable",
      "record a finite, nonnegative cut pull-off (inches/job) in Vinyl Settings before repricing", "layout");
  }
};

const laminatorIssues = (issues, wfIdx, laminator, isLeading) => {
  if (vinylNonNegativeNumber(laminator?.laminator_hourly_rate) === null) {
    machineAdd(issues, wfIdx, laminator, "laminator_hourly_rate", "vinyl_machine_rate_unavailable",
      "record a finite, nonnegative laminator hourly rate in Vinyl Settings — a missing rate is not free", "laminatorMachine");
  }
  if (recorded(laminator?.laminator_speed_inches_per_minute) && vinylPositiveNumber(laminator.laminator_speed_inches_per_minute) === null) {
    machineAdd(issues, wfIdx, laminator, "laminator_speed_inches_per_minute", "vinyl_machine_speed_unavailable",
      "record a positive, finite laminator speed (inches/minute) in Vinyl Settings before repricing", "laminatorMachine");
  }
  if (recorded(laminator?.laminator_setup_minutes_per_job) && vinylNonNegativeNumber(laminator.laminator_setup_minutes_per_job) === null) {
    machineAdd(issues, wfIdx, laminator, "laminator_setup_minutes_per_job", "vinyl_machine_minutes_unavailable",
      "record a finite, nonnegative laminator setup minutes in Vinyl Settings before repricing", "laminatorMachine");
  }
  // Laminator edges extend laminate length even when it isn't the leading
  // layout machine (laminator-specific consumption) → laminatePrice hold.
  if (!isLeading) {
    for (const field of ["leading_edge_inches", "trailing_edge_inches"]) {
      if (recorded(laminator?.[field]) && vinylNonNegativeNumber(laminator[field]) === null) {
        machineAdd(issues, wfIdx, laminator, field, "vinyl_machine_edge_unavailable",
          `record a finite, nonnegative laminator ${field.replace(/_/g, " ")} in Vinyl Settings before repricing`, "laminatePrice");
      }
    }
  }
};

// ---------- workflow-level issue scan ----------
// workflow: raw workflow record. resolved: { vinyl, laminate, transferTape,
//   printer, cutter, laminator } catalog rows found by id (null when missing).
// Returns issues in stable order: selection → parts → catalog → authored.
export const vinylWorkflowIssues = (workflow, resolved, index = 0) => {
  const issues = [];
  const wfId = workflow?.id ?? null;
  const items = workflow?.items || [];
  const hasItems = items.length > 0;
  const applyPrint = !!workflow?.apply_print;
  const applyCut = !!workflow?.apply_cut;
  const applyLaminate = !!workflow?.apply_laminate;
  const applyTT = !!workflow?.apply_transfer_tape;
  const { vinyl, laminate, transferTape, printer, cutter, laminator } = resolved;
  const add = (field, code, message, hold, itemIndex = null) =>
    issues.push(issue("vinyl", { index, itemIndex, field, code, message, hold }));

  // --- selection availability (only when the workflow actually has work) ---
  if (hasItems) {
    if (!recorded(workflow?.vinyl_id)) {
      add("vinyl_id", "vinyl_material_unassigned",
        `Workflow ${index + 1}: select a base vinyl before repricing — an unselected material prices as $0`, "layout");
    } else if (!vinyl) {
      issues.push(issue("vinyl", { index, inventoryId: workflow.vinyl_id, field: "vinyl_id",
        code: "vinyl_material_unavailable", hold: "layout",
        message: `Workflow ${index + 1}: the selected vinyl record is no longer available — reselect it` }));
    }
    if (applyLaminate) {
      if (!recorded(workflow?.laminate_id)) {
        add("laminate_id", "vinyl_laminate_unassigned",
          `Workflow ${index + 1}: laminate is applied but no laminate roll is selected`, "laminatePrice");
      } else if (!laminate) {
        issues.push(issue("vinyl", { index, inventoryId: workflow.laminate_id, field: "laminate_id",
          code: "vinyl_laminate_unavailable", hold: "laminatePrice",
          message: `Workflow ${index + 1}: the selected laminate record is no longer available — reselect it` }));
      }
    }
    if (applyTT) {
      if (!recorded(workflow?.transfer_tape_id)) {
        add("transfer_tape_id", "vinyl_transfer_tape_unassigned",
          `Workflow ${index + 1}: transfer tape is applied but no tape roll is selected`, "ttPrice");
      } else if (!transferTape) {
        issues.push(issue("vinyl", { index, inventoryId: workflow.transfer_tape_id, field: "transfer_tape_id",
          code: "vinyl_transfer_tape_unavailable", hold: "ttPrice",
          message: `Workflow ${index + 1}: the selected transfer tape record is no longer available — reselect it` }));
      }
    }
    for (const [flag, id, row, label] of [
      [applyPrint, workflow?.printer_id, printer, "printer"],
      [applyCut, workflow?.cutter_id, cutter, "cutter"],
      [applyLaminate, workflow?.laminator_id, laminator, "laminator"],
    ]) {
      if (!flag) continue;
      const field = `${label}_id`;
      if (!recorded(id)) {
        add(field, "vinyl_machine_unassigned",
          `Workflow ${index + 1}: ${label} is applied but no ${label} is selected — machine time would price as $0`, "layout");
      } else if (!row) {
        issues.push(issue("vinyl", { index, inventoryId: id, field,
          code: "vinyl_machine_unavailable", hold: "layout",
          message: `Workflow ${index + 1}: the selected ${label} record is no longer available — reselect it` }));
      }
    }
  }

  // --- part rows: dimensions must be positive, quantities whole+positive ---
  items.forEach((it, itemIndex) => {
    const where = `Part ${itemIndex + 1}${it?.description ? ` "${it.description}"` : ""} (workflow ${index + 1})`;
    for (const [field, human] of [["width_inches", "width"], ["height_inches", "height"]]) {
      if (vinylPositiveNumber(it?.[field]) === null) {
        add(field, "vinyl_part_dimension_unavailable",
          `${where}: record a positive, finite ${human} (inches) — a blank or zero dimension drops the part silently`, "layout", itemIndex);
      }
    }
    // Blank quantity defaults to 1 (ported behavior). Recorded must be a
    // positive whole number — floor() would silently reprice 2.7 → 2.
    if (recorded(it?.quantity) && vinylPositiveInteger(it.quantity) === null) {
      add("quantity", "vinyl_part_quantity_unavailable",
        `${where}: record a positive whole-number quantity`, "layout", itemIndex);
    }
    if (recorded(it?.bleed_inches) && vinylNonNegativeNumber(it.bleed_inches) === null) {
      add("bleed_inches", "vinyl_part_bleed_unavailable",
        `${where}: record a finite, nonnegative bleed (inches) or clear it`, "layout", itemIndex);
    }
  });

  // --- catalog field validation on selected records ---
  if (vinyl && hasItems) {
    vinylMaterialIssues(vinyl, "vinyl", index, wfId).forEach(i => issues.push(i));
  }
  if (laminate && applyLaminate && hasItems) {
    vinylMaterialIssues(laminate, "laminate", index, wfId).forEach(i => issues.push(i));
  }
  if (transferTape && applyTT && hasItems) {
    vinylMaterialIssues(transferTape, "transfer_tape", index, wfId).forEach(i => issues.push(i));
  }

  const leadingMachine = (applyPrint && printer) || (applyCut && cutter)
    || (applyLaminate && laminator) || printer || cutter || laminator;
  if (leadingMachine && hasItems) {
    const label = leadingMachine.machine_name || "machine";
    leadingMachineIssues(issues, index, leadingMachine, label, {
      gutterHOverridden: recorded(workflow?.gutter_h_override),
      gutterVOverridden: recorded(workflow?.gutter_v_override),
    });
  }
  if (applyPrint && printer) printerIssues(issues, index, printer);
  if (applyCut && cutter) cutterIssues(issues, index, cutter);
  if (applyLaminate && laminator) {
    laminatorIssues(issues, index, laminator, leadingMachine === laminator);
  }

  // --- ink rate (resolved exactly like the calculator does) ---
  if (applyPrint && printer && hasItems) {
    const quality = workflow?.print_quality || printer?.default_print_quality || "high_quality";
    if (!["draft", "production", "high_quality"].includes(quality)) {
      const srcField = recorded(workflow?.print_quality) ? "print_quality" : "default_print_quality";
      if (srcField === "print_quality") {
        add("print_quality", "vinyl_print_quality_unavailable",
          `Workflow ${index + 1}: set a supported print quality (draft / production / high_quality)`, "inkPrice");
      } else {
        machineAdd(issues, index, printer, "default_print_quality", "vinyl_print_quality_unavailable",
          "set a supported default print quality on the printer in Vinyl Settings", "inkPrice");
      }
    }
    const tierField = { draft: "print_cost_per_sqin_draft", production: "print_cost_per_sqin_production", high_quality: "print_cost_per_sqin_high_quality" }[quality];
    const tiered = vinylNonNegativeNumber(printer?.[tierField]);
    if (!(tiered !== null && tiered > 0)) {
      // Same fallback the calculator uses — legacy flat rate.
      if (vinylNonNegativeNumber(printer?.print_cost_per_sqin) === null) {
        machineAdd(issues, index, printer, recorded(printer?.[tierField]) ? tierField : "print_cost_per_sqin",
          "vinyl_ink_rate_unavailable",
          `record a finite, nonnegative printer ink cost per sq in (${quality.replace(/_/g, " ")} tier or the flat rate) in Vinyl Settings — a missing ink rate is not free`, "inkPrice");
      }
    }
  }

  // --- authored workflow inputs ---
  for (const [field, human] of [["gutter_h_override", "horizontal gutter"], ["gutter_v_override", "vertical gutter"]]) {
    if (hasItems && recorded(workflow?.[field]) && vinylNonNegativeNumber(workflow[field]) === null) {
      add(field, "vinyl_gutter_override_unavailable",
        `Workflow ${index + 1}: record a finite, nonnegative ${human} override (inches) or clear it`, "layout");
    }
  }
  if (hasItems && recorded(workflow?.spoilage_buffer_percent) && vinylNonNegativeNumber(workflow.spoilage_buffer_percent) === null) {
    add("spoilage_buffer_percent", "vinyl_spoilage_unavailable",
      `Workflow ${index + 1}: record a finite, nonnegative spoilage buffer % or clear it`, "layout");
  }
  // setup_fee_floor is consumed even for an empty workflow (floor applies to total).
  if (recorded(workflow?.setup_fee_floor) && vinylNonNegativeNumber(workflow.setup_fee_floor) === null) {
    add("setup_fee_floor", "vinyl_setup_fee_unavailable",
      `Workflow ${index + 1}: record a finite, nonnegative setup-fee floor ($) or clear it`, "floor");
  }
  if (applyCut && hasItems) {
    const wd = workflow?.weeding_difficulty;
    if (recorded(wd) && !(wd in WEEDING_LABOR_MINUTES_PER_PART)) {
      add("weeding_difficulty", "vinyl_weeding_difficulty_unavailable",
        `Workflow ${index + 1}: choose a supported weeding difficulty`, "labor");
    }
    if (recorded(workflow?.weeding_minutes_per_part_override)
        && vinylNonNegativeNumber(workflow.weeding_minutes_per_part_override) === null) {
      add("weeding_minutes_per_part_override", "vinyl_weeding_override_unavailable",
        `Workflow ${index + 1}: record a finite, nonnegative weeding minutes/part override or clear it`, "labor");
    }
  }
  if (hasItems && recorded(workflow?.install_minutes_per_part)
      && vinylNonNegativeNumber(workflow.install_minutes_per_part) === null) {
    add("install_minutes_per_part", "vinyl_install_minutes_unavailable",
      `Workflow ${index + 1}: record a finite, nonnegative application minutes/part or clear it`, "labor");
  }

  // --- workflow personnel rows ---
  (workflow?.personnel || []).forEach((p, itemIndex) => {
    const hrs = recorded(p?.hours) ? vinylNumber(p.hours) : null;
    const rate = recorded(p?.hourly_rate) ? vinylNumber(p.hourly_rate) : null;
    const role = p?.role || `role ${itemIndex + 1}`;
    const hasHours = hrs !== null && hrs > 0;
    if (recorded(p?.hours) && (hrs === null || hrs < 0)) {
      add("hours", "vinyl_personnel_hours_unavailable",
        `Role "${role}" (workflow ${index + 1}): record a finite, nonnegative hours value or clear it`, "labor", itemIndex);
    }
    if (recorded(p?.hourly_rate) && (rate === null || rate < 0)) {
      add("hourly_rate", "vinyl_personnel_rate_unavailable",
        `Role "${role}" (workflow ${index + 1}): record a finite, nonnegative hourly rate`, "labor", itemIndex);
    }
    // A row with hours but no usable rate is skipped by the calculator —
    // the hours silently bill $0. Flag it.
    if (hasHours && (rate === null || rate <= 0)) {
      add("hourly_rate", "vinyl_personnel_rate_unavailable",
        `Role "${role}" (workflow ${index + 1}): record a positive hourly rate or clear the hours — ${hrs} hr would bill $0`, "labor", itemIndex);
    }
  });

  // --- fallback operator rate (consumed only when no usable personnel rows) ---
  const usablePersonnel = (workflow?.personnel || []).some(
    (p) => vinylPositiveNumber(p?.hours) !== null && vinylPositiveNumber(p?.hourly_rate) !== null
  );
  if (hasItems && !usablePersonnel) {
    const resolved = printer?.operator_hourly_rate ?? cutter?.operator_hourly_rate ?? laminator?.operator_hourly_rate;
    const resolvedFrom = printer?.operator_hourly_rate != null ? printer
      : cutter?.operator_hourly_rate != null ? cutter
      : laminator?.operator_hourly_rate != null ? laminator : null;
    if (resolved != null && vinylNonNegativeNumber(resolved) === null && resolvedFrom) {
      machineAdd(issues, index, resolvedFrom, "operator_hourly_rate", "vinyl_operator_rate_unavailable",
        `record a finite, nonnegative operator hourly rate on ${resolvedFrom.machine_name || "the leading machine"} in Vinyl Settings, or add workflow personnel`, "labor");
    }
  }

  return issues;
};

// ---------- calc wrapper ----------
// Replicates VinylWorkflowCard's exact argument construction so a clean
// workflow produces a bit-identical calc. Returns:
//   { calc, issues, held, resolved }
// `calc` is the real result when held=false; when held=true every field a
// flagged input could have tainted is null and aggregates are re-derived
// null-propagating. shelves/partsPlaced/partsUnplaced and the geometry the
// visualizer needs stay real so layout rows never disappear.
const num = (v) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : 0;
};

export const calcVinylWorkflow = ({ workflow, vinyls = [], machines = [], index = 0 }) => {
  const printer   = machines.find(m => m.id === workflow?.printer_id)   || null;
  const cutter    = machines.find(m => m.id === workflow?.cutter_id)    || null;
  const laminator = machines.find(m => m.id === workflow?.laminator_id) || null;
  const vinyl        = vinyls.find(v => v.id === workflow?.vinyl_id)         || null;
  const laminate     = vinyls.find(v => v.id === workflow?.laminate_id)      || null;
  const transferTape = vinyls.find(v => v.id === workflow?.transfer_tape_id) || null;
  const resolved = { vinyl, laminate, transferTape, printer, cutter, laminator };

  const issues = vinylWorkflowIssues(workflow, resolved, index);

  // Byte-identical argument construction to VinylWorkflowCard's useMemo.
  const operatorRate = printer?.operator_hourly_rate ?? cutter?.operator_hourly_rate ?? laminator?.operator_hourly_rate ?? 45;
  const calc = calculateVinylProject({
    items: workflow?.items || [],
    printer, cutter, laminator,
    vinyl, laminate, transferTape,
    operatorHourlyRate: operatorRate,
    applyPrint: !!workflow?.apply_print,
    applyCut: !!workflow?.apply_cut,
    applyLaminate: !!workflow?.apply_laminate,
    applyTransferTape: !!workflow?.apply_transfer_tape,
    overrideGutterH: workflow?.gutter_h_override === "" || workflow?.gutter_h_override == null ? undefined : num(workflow.gutter_h_override),
    overrideGutterV: workflow?.gutter_v_override === "" || workflow?.gutter_v_override == null ? undefined : num(workflow.gutter_v_override),
    printQuality: workflow?.print_quality || printer?.default_print_quality || "high_quality",
    weedingDifficulty: workflow?.weeding_difficulty || "moderate",
    weedingMinutesPerPartOverride: workflow?.weeding_minutes_per_part_override,
    installMinutesPerPart: workflow?.install_minutes_per_part,
    personnel: workflow?.personnel || [],
    spoilageBufferPercent: num(workflow?.spoilage_buffer_percent),
    setupFeeFloor: num(workflow?.setup_fee_floor),
  });

  if (calc.partsUnplaced > 0) {
    issues.push(issue("vinyl", {
      index, field: "items", code: "vinyl_parts_unplaced", hold: "layout",
      message: `Workflow ${index + 1}: ${calc.partsUnplaced} part(s) do not fit on the usable roll width — rotate, split, or choose a wider roll`,
    }));
  }

  const held = issues.length > 0;
  if (!held) {
    calc.__held = false;
    calc.pricingUnavailable = false;
    calc.issues = [];
    return { calc, issues, held, resolved };
  }

  const out = { ...calc };
  const poisoned = new Set();
  issues.forEach(i => (HOLD_FIELDS[i.hold] || HOLD_FIELDS.layout).forEach(f => poisoned.add(f)));
  for (const f of poisoned) out[f] = null;

  // Re-derive aggregates null-propagating from possibly-nulled bases.
  const sumOrNull = (...xs) => xs.every(v => Number.isFinite(v)) ? xs.reduce((s, v) => s + v, 0) : null;
  out.materialCost = sumOrNull(out.vinylCost, out.laminateCost, out.transferTapeCost, out.inkCost, out.bladeCost);
  out.machineCost = sumOrNull(out.printMachineCost, out.cutMachineCost, out.laminateMachineCost);
  out.preFloorTotal = sumOrNull(out.materialCost, out.machineCost, out.laborCost);
  out.setupFeeApplied = (poisoned.has("setupFeeApplied") || !Number.isFinite(out.preFloorTotal))
    ? null : calc.setupFeeApplied;
  out.totalCost = (Number.isFinite(out.preFloorTotal) && Number.isFinite(out.setupFeeApplied))
    ? out.preFloorTotal + out.setupFeeApplied : null;

  out.__held = true;
  out.pricingUnavailable = true;
  out.issues = issues;
  return { calc: out, issues, held, resolved };
};

// ---------- project-level issue scan ----------
// Covers everything rollupVinylProject consumes outside the workflow calcs:
// equipment/personnel totals, travel, supplies %, markup %, and the shared
// install settings the rows were priced from.
export const vinylProjectInputIssues = (project, { settings = {}, equipmentInventory = [] } = {}) => {
  const issues = [];
  const add = (field, code, message) =>
    issues.push(issue("vinyl", { field, code, message, hold: "project" }));
  const addCat = (field, code, message, inventoryId = null) =>
    issues.push(issue("vinyl_catalog", { field, code, message, hold: "project", inventoryId }));

  // --- selected equipment rows: total_cost is the consumed value ---
  (project?.selected_equipment || []).forEach((e, itemIndex) => {
    const name = e?.equipment_name || `row ${itemIndex + 1}`;
    if (recorded(e?.equipment_id) && !equipmentInventory.some(inv => inv.id === e.equipment_id)) {
      addCat("selected_equipment", "vinyl_equipment_unavailable",
        `Equipment "${name}": the selected equipment record is no longer available — reselect it`, e.equipment_id);
    }
    if (vinylNonNegativeNumber(e?.total_cost) === null) {
      add("total_cost", "vinyl_equipment_cost_unavailable",
        `Equipment "${name}": record a finite, nonnegative total cost — a missing cost is not free`);
    }
  });

  // --- install personnel rows: total_cost is the consumed value ---
  (project?.personnel || []).forEach((p, itemIndex) => {
    const role = p?.role || p?.name || `row ${itemIndex + 1}`;
    if (vinylNonNegativeNumber(p?.total_cost) === null) {
      add("total_cost", "vinyl_personnel_cost_unavailable",
        `Crew "${role}": record a finite, nonnegative total cost — a missing cost is not free`);
    }
  });
  // The role-rate settings are consumed whenever install crew rows exist;
  // a malformed one silently reprices future rows at $0 or the wrong default.
  if ((project?.personnel || []).length > 0) {
    const roleMap = {
      "Crew Lead": "install_crew_lead_rate",
      "Installer": "install_installer_rate",
      "Helper": "install_helper_rate",
    };
    const rolesPresent = new Set((project.personnel || []).map(p => p?.role).filter(r => r in roleMap));
    rolesPresent.forEach((role) => {
      const field = roleMap[role];
      if (vinylPositiveNumber(settings?.[field]) === null) {
        addCat(field, "vinyl_install_rate_unavailable",
          `Setting ${field}: record a positive, finite ${role} rate in Installation Settings — crew pricing is unavailable`);
      }
    });
  }

  // --- travel ---
  const miles = project?.travel_miles_round_trip;
  const milesNum = recorded(miles) && miles !== 0 ? vinylNonNegativeNumber(miles) : 0;
  if (recorded(miles) && miles !== "" && vinylNonNegativeNumber(miles) === null) {
    add("travel_miles_round_trip", "vinyl_travel_miles_unavailable",
      "record a finite, nonnegative round-trip mileage — travel pricing is unavailable");
  }
  if (recorded(project?.total_travel_cost) && project.total_travel_cost !== ""
      && vinylNonNegativeNumber(project.total_travel_cost) === null) {
    add("total_travel_cost", "vinyl_travel_cost_unavailable",
      "recorded travel cost is not a finite, nonnegative number — recalculate travel before repricing");
  }
  if (milesNum !== null && milesNum > 0) {
    // TravelCostCard consumes these settings when mileage is set.
    for (const [field, human] of [
      ["install_gasoline_price_per_gallon", "gasoline price per gallon"],
      ["install_diesel_price_per_gallon", "diesel price per gallon"],
      ["install_travel_labor_rate", "travel labor rate"],
      ["install_travel_avg_speed_mph", "travel average speed (mph)"],
    ]) {
      if (vinylPositiveNumber(settings?.[field]) === null) {
        addCat(field, "vinyl_travel_setting_unavailable",
          `Setting ${field}: record a positive, finite ${human} in Installation Settings — travel pricing is unavailable`);
      }
    }
    for (const [field, human] of [
      ["install_travel_overhead_per_mile", "travel overhead per mile"],
      ["install_min_travel_charge", "minimum travel charge"],
    ]) {
      if (recorded(settings?.[field]) && vinylNonNegativeNumber(settings[field]) === null) {
        addCat(field, "vinyl_travel_setting_unavailable",
          `Setting ${field}: record a finite, nonnegative ${human} in Installation Settings — travel pricing is unavailable`);
      }
    }
    // Owned vehicle fuel economy is consumed for fuel cost.
    (project?.selected_equipment || []).forEach((e) => {
      if (!recorded(e?.equipment_id)) return;
      const inv = equipmentInventory.find(r => r.id === e.equipment_id);
      if (!inv) return; // dangling id already flagged
      const owned = inv.ownership === "owned" || inv.pricing_mode === "owned_flat";
      const isVehicle = ["van", "truck", "vehicle", "suv", "car"].includes(String(inv.equipment_type || "").toLowerCase());
      if (owned && isVehicle && vinylPositiveNumber(inv.mpg) === null) {
        addCat("mpg", "vinyl_vehicle_mpg_unavailable",
          `Equipment "${inv.equipment_name || e.equipment_name}": record a positive, finite MPG in inventory — travel fuel pricing is unavailable`, inv.id);
      }
    });
  }

  // --- project cost knobs ---
  if (recorded(project?.supplies_percent_of_materials) && vinylNonNegativeNumber(project.supplies_percent_of_materials) === null) {
    add("supplies_percent_of_materials", "vinyl_supplies_percent_unavailable",
      "record a finite, nonnegative supplies % of materials or clear it");
  }
  if (recorded(project?.extra_supplies_cost) && vinylNonNegativeNumber(project.extra_supplies_cost) === null) {
    add("extra_supplies_cost", "vinyl_extra_supplies_unavailable",
      "record a finite, nonnegative extra supplies cost ($) or clear it");
  }
  if (recorded(project?.markup_percent) && vinylNonNegativeNumber(project.markup_percent) === null) {
    add("markup_percent", "vinyl_markup_unavailable",
      "record a finite, nonnegative markup % or clear it");
  }

  return issues;
};

// ---------- UI helpers ----------
// All issues attached to a single field (optionally a single row).
export const issuesForField = (issues = [], field, itemIndex = null) =>
  issues.filter(i => i.field === field && (itemIndex === null || i.itemIndex === itemIndex));
export const hasIssueFor = (issues = [], field, itemIndex = null) =>
  issuesForField(issues, field, itemIndex).length > 0;

// Helpers for building a blank Vinyl project + blank workflow + rolling up
// totals across all workflows.

import { hasVinylCostSnapshot, vinylNonNegativeNumber, vinylNumber } from "./vinylPricingAvailability";

export const blankWorkflow = (index = 0) => ({
  id: `wf-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
  name: `Workflow ${index + 1}`,
  vinyl_id: "",
  laminate_id: "",
  transfer_tape_id: "",
  printer_id: "",
  cutter_id: "",
  laminator_id: "",
  apply_print: true,
  apply_cut: true,
  apply_laminate: false,
  apply_transfer_tape: false,
  // Leave blank so the selected printer's VinylMachine.default_print_quality
