                <SelectField label="Indoor / Outdoor" value={draft.indoor_outdoor || "both"} disabled={!isAdmin}
                  options={[{id:"indoor_only",label:"Indoor Only"},{id:"outdoor",label:"Outdoor"},{id:"both",label:"Both"}]}
                  onChange={(v) => patch({ indoor_outdoor: v })} />
                <NumberField label="Outdoor Life (yrs)" value={draft.expected_life_years_outdoor} disabled={!isAdmin} onChange={(v) => patch({ expected_life_years_outdoor: v })} />
              </SectionGrid>
              <SectionGrid cols={4}>
                <NumberField label="Min Letter Height (in)" step="0.25" value={draft.min_recommended_letter_height_inches} disabled={!isAdmin} onChange={(v) => patch({ min_recommended_letter_height_inches: v })} />
                <ToggleField label="Removable" value={!!draft.removable} disabled={!isAdmin} onChange={(v) => patch({ removable: v })} />
                <ToggleField label="Needs Lamination" value={!!draft.requires_lamination} disabled={!isAdmin} onChange={(v) => patch({ requires_lamination: v })} />
                <ToggleField label="Needs Transfer Tape" value={draft.requires_transfer_tape !== false} disabled={!isAdmin} onChange={(v) => patch({ requires_transfer_tape: v })} />
              </SectionGrid>

              <Field label="Application Surfaces (multi-select)">
                <ChipGroup
                  options={APPLICATION_SURFACES}
                  selected={draft.application_surface || []}
                  onToggle={(v) => toggleArr("application_surface", v)}
                  disabled={!isAdmin}
                  activeColor="blue"
                />
              </Field>
            </TabsContent>

            {/* PRINTING */}
            <TabsContent value="printing" className="mt-0 space-y-5">
              <ToggleField label="Printable Media" value={!!draft.supports_printing} disabled={!isAdmin}
                onChange={(v) => patch({ supports_printing: v })} />

              {draft.supports_printing ? (
                <Field label="Printer Compatibility">
                  <ChipGroup
                    options={PRINTER_CHEMISTRIES}
                    selected={draft.printer_compatibility || []}
                    onToggle={(v) => toggleArr("printer_compatibility", v)}
                    disabled={!isAdmin}
                    activeColor="purple"
                  />
                </Field>
              ) : (
                <div className="text-sm text-slate-400 italic bg-slate-50 border border-slate-200 rounded-lg px-4 py-3">
                  Toggle "Printable Media" on to choose compatible printer chemistries.
                </div>
              )}
            </TabsContent>

            {/* VISIBILITY */}
            <TabsContent value="visibility" className="mt-0 space-y-3">
              <SectionGrid cols={2}>
                <ToggleField label="Show in Channel & Dim. Letters"
                  value={draft.show_in_channel_letters !== false} disabled={!isAdmin}
                  onChange={(v) => patch({ show_in_channel_letters: v })} />
                <ToggleField label="Show in Sign Maintenance"
                  value={draft.show_in_sign_maintenance !== false} disabled={!isAdmin}
                  onChange={(v) => patch({ show_in_sign_maintenance: v })} />
                <ToggleField label="Show in Vinyl Estimator"
                  value={draft.show_in_vinyl_estimator !== false} disabled={!isAdmin}
                  onChange={(v) => patch({ show_in_vinyl_estimator: v })} />
                <ToggleField label="Is Laminate / Overlam"
                  value={!!draft.is_laminate} disabled={!isAdmin}
                  onChange={(v) => patch({ is_laminate: v })} />
                <ToggleField label="Master-only (hide from modules)"
                  value={!!draft.show_in_master_only} disabled={!isAdmin}
                  onChange={(v) => patch({ show_in_master_only: v })} />
                <ToggleField label="Active"
                  value={draft.is_active !== false} disabled={!isAdmin}
                  onChange={(v) => patch({ is_active: v })} />
              </SectionGrid>
            </TabsContent>

            {/* NOTES */}
            <TabsContent value="notes" className="mt-0">
              <Field label="Notes">
                <Textarea
                  value={draft.notes || ""}
                  disabled={!isAdmin}
                  onChange={(e) => patch({ notes: e.target.value })}
                  className="min-h-40 text-sm"
                  placeholder="Color matching notes, edge sealing tips, ordering quirks, etc."
                />
              </Field>
            </TabsContent>
          </div>
        </Tabs>

        {/* Footer — Save / Cancel */}
        <DialogFooter className="border-t border-slate-200 bg-slate-50 px-6 py-3 flex-row justify-between sm:justify-between">
          <div className="text-xs text-slate-500">
            {!isAdmin ? "View only — only admins can edit." : "Changes are saved when you click Save."}
          </div>
          <div className="flex gap-2">
            <Button variant="outline" onClick={handleClose} disabled={saving}>Cancel</Button>
            {isAdmin && (
              <Button onClick={handleSave} disabled={saving || nameMissing} className="bg-blue-600 hover:bg-blue-700 text-white">
                <Save className="w-4 h-4 mr-1.5" />
                {saving ? "Saving…" : "Save Changes"}
              </Button>
            )}
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

// ---------- presentational helpers ----------

function TabPill({ value, icon: Icon, label }) {
  return (
    <TabsTrigger
      value={value}
      className="data-[state=active]:bg-white data-[state=active]:text-slate-900 data-[state=active]:shadow-sm
                 data-[state=inactive]:text-slate-500 data-[state=inactive]:hover:text-slate-700
                 gap-1.5 text-sm h-9 px-3 rounded-md"
    >
      <Icon className="w-3.5 h-3.5" />
      {label}
    </TabsTrigger>
  );
}

function Stat({ label, value, highlight }) {
  return (
    <div className="text-right">
      <div className="text-[10px] uppercase tracking-wider text-slate-300">{label}</div>
      <div className={`font-semibold tabular-nums ${highlight ? "text-emerald-300" : "text-white"}`}>{value}</div>
    </div>
  );
}

function Field({ label, required, children }) {
  return (
    <div className="space-y-1.5">
      <Label className="text-[11px] uppercase tracking-wider text-slate-600 font-medium">
        {label}{required && <span className="text-red-500 ml-0.5">*</span>}
      </Label>
      {children}
    </div>
  );
}

function SectionGrid({ cols = 4, children }) {
  const gridClass = cols === 2 ? "md:grid-cols-2"
                  : cols === 3 ? "md:grid-cols-3"
                  : "md:grid-cols-4";
  return <div className={`grid grid-cols-1 ${gridClass} gap-4`}>{children}</div>;
}

function NumberField({ label, value, disabled, onChange, step = "1" }) {
  return (
    <Field label={label}>
      <Input type="number" step={step}
        value={value ?? ""}
        disabled={disabled}
        onChange={(e) => onChange(e.target.value === "" ? 0 : parseFloat(e.target.value))}
        className="h-9 text-sm tabular-nums" />
    </Field>
  );
}

function SelectField({ label, value, disabled, onChange, options }) {
  return (
    <Field label={label}>
      <Select value={value || ""} onValueChange={onChange} disabled={disabled}>
        <SelectTrigger className="h-9 text-sm"><SelectValue placeholder="Select..." /></SelectTrigger>
        <SelectContent>
          {options.map(o => <SelectItem key={o.id} value={o.id}>{o.label}</SelectItem>)}
        </SelectContent>
      </Select>
    </Field>
  );
}

function ToggleField({ label, value, disabled, onChange }) {
  return (
    <div className="flex items-center justify-between gap-2 bg-white rounded-md border border-slate-200 px-3 h-9">
      <span className="text-xs text-slate-700 truncate">{label}</span>
      <Switch checked={!!value} onCheckedChange={onChange} disabled={disabled} />
    </div>
  );
}

function ChipGroup({ options, selected = [], onToggle, disabled, activeColor = "blue" }) {
  const onClass = activeColor === "purple"
    ? "bg-purple-600 border-purple-600 text-white"
    : "bg-blue-600 border-blue-600 text-white";
  const hoverClass = activeColor === "purple" ? "hover:border-purple-300" : "hover:border-blue-300";
  return (
    <div className="flex flex-wrap gap-1.5">
      {options.map(s => {
        const on = selected.includes(s);
        return (
          <button type="button"
            key={s}
            type="button"
            disabled={disabled}
            onClick={() => onToggle(s)}
            className={`text-[11px] px-3 py-1.5 rounded-full border transition-colors ${
              on ? onClass : `bg-white border-slate-200 text-slate-700 ${hoverClass}`
            } ${disabled ? "opacity-60 cursor-not-allowed" : ""}`}
          >
            {s.replace(/_/g, " ")}
          </button>
        );
      })}
    </div>
  );
}

// The full Vinyl Inventory tab. Used in three places:
//   - Master Inventory (scope="master")        → shows everything
//   - Channel & Dimensional Letters Inventory  → scope="channel_letters"
//   - Sign Maintenance Inventory               → scope="sign_maintenance"
//   - Dedicated Vinyl Inventory page (under Vinyl Estimator)
//
// Editing flow:
//   - "Add Vinyl"  → creates a blank record, immediately opens VinylEditDialog.
//   - Row "Edit"   → opens VinylEditDialog populated with that row.
//   - Save in dialog persists the full draft through guarded VinylInventory persistence.

import { useEffect, useState, useMemo, useRef } from "react";
import { VinylInventory, User } from "@/api/gatedEntities";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Plus, Search, Droplets, Lock } from "lucide-react";
import VinylRowCard from "./VinylRowCard";
import VinylEditDialog from "./VinylEditDialog";
import { VINYL_CATEGORIES, VINYL_USE_CASES, filterVinylForScope } from "./vinylConstants";
import { createVinylRecordWithRecovery, deleteVinylIfUnchanged, duplicateVinylSafely, stripVinylRecordMeta, updateVinylIfUnchanged } from "./vinylInventoryPersistence";

const SCOPE_META = {
  master:           { label: "All Vinyl", color: "text-blue-600",    accent: "bg-blue-50 border-blue-200" },
  channel_letters:  { label: "Channel & Dimensional Letters", color: "text-purple-600", accent: "bg-purple-50 border-purple-200" },
  sign_maintenance: { label: "Sign Maintenance",  color: "text-cyan-600", accent: "bg-cyan-50 border-cyan-200" },
};

const blankVinyl = (scope) => ({
  vinyl_name: "New Vinyl",
  vinyl_category: "calendered",
  vinyl_use_case: "cut_graphics",
  finish: "gloss",
  roll_width_inches: 24,
  roll_length_yards: 50,
  thickness_mil: 2,
  pricing_mode: "per_roll",
  cost_per_roll: 0,
  waste_factor_percent: 15,
  yield_factor: 0.85,
  adhesive_type: "permanent",
  application_method: "either",
  indoor_outdoor: "both",
  weeding_difficulty: "moderate",
  is_active: true,
  show_in_channel_letters: scope !== "sign_maintenance",
  show_in_sign_maintenance: scope !== "channel_letters",
  show_in_vinyl_estimator: true,
});

export default function VinylInventoryTab({ scope = "master" }) {
  const meta = SCOPE_META[scope] || SCOPE_META.master;
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [user, setUser] = useState(null);
  const [search, setSearch] = useState(() => {
    try { return new URLSearchParams(window.location.search).get("q") || ""; } catch { return ""; }
  });
  const [categoryFilter, setCategoryFilter] = useState(() => {
    try { return new URLSearchParams(window.location.search).get("category") || "all"; } catch { return "all"; }
  });
  const [useCaseFilter, setUseCaseFilter] = useState(() => {
    try { return new URLSearchParams(window.location.search).get("use_case") || "all"; } catch { return "all"; }
  });
  const writeParam = (key, value, defaultValue = "all") => {
    try {
      const next = new URLSearchParams(window.location.search);
      if (value && value !== defaultValue) next.set(key, value); else next.delete(key);
      window.history.replaceState(null, "", `${window.location.pathname}?${next}`);
    } catch {}
  };
  const [editingVinyl, setEditingVinyl] = useState(null);
  const [loadError, setLoadError] = useState("");
  const [persistenceError, setPersistenceError] = useState("");
  const itemActionRef = useRef(new Set());
  const addRef = useRef(false);
  const isAdmin = user?.role === "admin";

  const load = async () => {
    setLoading(true);
    setLoadError("");
    try {
      const all = await loadAllEntityRows({ entity: VinylInventory, sort: "sort_order", label: "Vinyl inventory" });
      setItems(all);
    } catch (e) {
      console.error("Failed to load VinylInventory:", e);
      setLoadError(e?.message || "Vinyl inventory could not be verified.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    User.me().then(setUser).catch(() => setUser(null));
    load();
  }, []);

  const filtered = useMemo(() => {
    let list = filterVinylForScope(items, scope);
    if (categoryFilter !== "all") list = list.filter(v => v.vinyl_category === categoryFilter);
    if (useCaseFilter !== "all")  list = list.filter(v => v.vinyl_use_case === useCaseFilter);
    if (search.trim()) {
      const q = search.toLowerCase();
      list = list.filter(v =>
        [v.vinyl_name, v.manufacturer, v.product_series, v.color_name, v.supplier, v.supplier_sku, v.notes]
          .filter(Boolean).some(s => String(s).toLowerCase().includes(q))
      );
    }
    return list;
  }, [items, scope, search, categoryFilter, useCaseFilter]);

  const handleAdd = async () => {
    if (!isAdmin || loadError || addRef.current) return;
    addRef.current = true;
    setPersistenceError("");
    try {
      const result = await createVinylRecordWithRecovery({
        entity: VinylInventory,
        data: { ...blankVinyl(scope), sort_order: items.length + 1 },
        label: "New vinyl inventory record",
      });
      setItems(prev => [result.record, ...prev.filter((row) => row.id !== result.record.id)]);
      setEditingVinyl(result.record);
    } catch (e) {
      console.error(e);
      setPersistenceError(e?.message || "The new vinyl record could not be created safely.");
    } finally {
      addRef.current = false;
    }
  };

  const handleDialogSave = async (draft) => {
    if (!draft?.id || itemActionRef.current.has(draft.id)) return;
    itemActionRef.current.add(draft.id);
    setPersistenceError("");
    try {
      const baseline = items.find((row) => row.id === draft.id);
      if (!baseline) throw new Error("This vinyl is no longer in the loaded inventory. Reload before saving.");
      const patch = stripVinylRecordMeta(draft);
      const saved = await updateVinylIfUnchanged({
        entity: VinylInventory,
        record: baseline,
        nextFields: patch,
        label: `Vinyl ${baseline.vinyl_name || baseline.id}`,
      });
      setItems(prev => prev.map(v => v.id === saved.id ? saved : v));
      setEditingVinyl(null);
    } catch (e) {
      console.error(e);
      const live = await VinylInventory.get(draft.id).catch(() => null);
      if (live?.id) {
        setItems(prev => prev.map(v => v.id === draft.id ? live : v));
        setEditingVinyl(live);
      }
      setPersistenceError(e?.message || "This vinyl changed in another session. The latest record was reloaded and your stale save was blocked.");
    } finally {
      itemActionRef.current.delete(draft.id);
    }
  };

  const handleDelete = async (vinyl) => {
    if (!isAdmin || !vinyl?.id || itemActionRef.current.has(vinyl.id)) return;
    itemActionRef.current.add(vinyl.id);
    if (!confirm("Delete this vinyl?")) {
      itemActionRef.current.delete(vinyl.id);
      return;
    }
    setPersistenceError("");
    try {
      await deleteVinylIfUnchanged({
        entity: VinylInventory,
        record: vinyl,
        label: `Vinyl ${vinyl.vinyl_name || vinyl.id} deletion`,
      });
      setItems(prev => prev.filter(v => v.id !== vinyl.id));
    } catch (e) {
      console.error(e);
      const live = await VinylInventory.get(vinyl.id).catch(() => null);
      if (live?.id) setItems(prev => prev.map(v => v.id === vinyl.id ? live : v));
      setPersistenceError(e?.message || "This vinyl changed in another session and was not deleted.");
    } finally {
      itemActionRef.current.delete(vinyl.id);
    }
  };

  // #13 Quick-duplicate. Auto-links rows into a product group so the roll-width
  // recommender can find them. If the source has no product_group_key, we
  // generate one and stamp it on both rows.
  const handleDuplicate = async (source) => {
    if (!isAdmin || !source?.id || itemActionRef.current.has(source.id)) return;
    itemActionRef.current.add(source.id);
    setPersistenceError("");
    try {
      const groupKey = source.product_group_key || `grp-${source.id}`;
      const copy = {
        ...stripVinylRecordMeta(source),
        product_group_key: groupKey,
        vinyl_name: `${source.vinyl_name || "Vinyl"} (copy)`,
        sort_order: (source.sort_order || 0) + 0.1,
      };
      const result = await duplicateVinylSafely({
        entity: VinylInventory,
        source,
        copyData: copy,
        groupKey,
        label: `Duplicate vinyl ${source.vinyl_name || source.id}`,
      });
      setItems(prev => [
        result.copy,
        ...prev.filter(v => v.id !== result.copy.id).map(v => v.id === result.source.id ? result.source : v),
      ]);
      setEditingVinyl(result.copy);
    } catch (e) {
      console.error(e);
      const live = await VinylInventory.get(source.id).catch(() => null);
      if (live?.id) setItems(prev => prev.map(v => v.id === source.id ? live : v));
      setPersistenceError(e?.message || "This vinyl could not be duplicated safely. Reload before retrying.");
    } finally {
      itemActionRef.current.delete(source.id);
    }
  };

  return (
    <Card className="bg-white border-0 shadow-sm">
      <CardHeader className="pb-3">
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-3">
          <CardTitle className="flex items-center gap-2 text-lg">
            <Droplets className={`w-5 h-5 ${meta.color}`} />
            Vinyl Inventory
            <Badge variant="outline" className={`ml-1 text-[10px] ${meta.accent}`}>{meta.label}</Badge>
            <Badge variant="outline" className="ml-1 font-normal">{filtered.length} of {items.length}</Badge>
          </CardTitle>

          <div className="flex flex-col sm:flex-row gap-2 w-full lg:w-auto">
            <div className="relative w-full sm:w-64">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
              <Input
                placeholder="Search vinyl…"
                value={search}
                onChange={(e) => { const v = e.target.value; setSearch(v); writeParam("q", v, ""); }}
                className="pl-9 h-9 text-sm"
              />
            </div>
            <Select value={categoryFilter} onValueChange={(v) => { setCategoryFilter(v); writeParam("category", v); }}>
              <SelectTrigger className="h-9 text-sm w-40"><SelectValue placeholder="Category" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Categories</SelectItem>
                {VINYL_CATEGORIES.map(c => <SelectItem key={c.id} value={c.id}>{c.label}</SelectItem>)}
              </SelectContent>
            </Select>
            <Select value={useCaseFilter} onValueChange={(v) => { setUseCaseFilter(v); writeParam("use_case", v); }}>
              <SelectTrigger className="h-9 text-sm w-44"><SelectValue placeholder="Use Case" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Use Cases</SelectItem>
                {VINYL_USE_CASES.map(c => <SelectItem key={c.id} value={c.id}>{c.label}</SelectItem>)}
              </SelectContent>
            </Select>
            {isAdmin ? (
              <Button onClick={handleAdd} disabled={!!loadError} className="bg-blue-600 hover:bg-blue-700 text-white h-9 disabled:opacity-50">
                <Plus className="w-4 h-4 mr-1" /> Add Vinyl
              </Button>
            ) : (
              <Badge variant="outline" className="self-center text-[11px] inline-flex items-center gap-1">
                <Lock className="w-3 h-3" /> View only
              </Badge>
            )}
          </div>
        </div>
      </CardHeader>

      <CardContent className="p-4">
        {persistenceError && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800 flex items-start justify-between gap-3">
            <div>
              <div className="font-medium">Vinyl inventory update blocked</div>
              <div className="mt-1 text-xs">{persistenceError}</div>
            </div>
            <Button type="button" size="sm" variant="outline" className="shrink-0 border-red-300 bg-white text-red-800" onClick={async () => { setPersistenceError(""); await load(); }}>Reload latest</Button>
          </div>
        )}
        {loading ? (
          <div className="p-8 text-center text-slate-500">Loading vinyl inventory…</div>
        ) : loadError ? (
          <div className="p-8 text-center text-red-700 bg-red-50 border border-red-200 rounded-lg">
            <div className="font-semibold">Vinyl inventory could not be verified.</div>
            <div className="mt-1 text-xs">{loadError}</div>
            <Button variant="outline" size="sm" className="mt-3" onClick={load}>Retry</Button>
          </div>
        ) : filtered.length === 0 ? (
          <div className="p-8 text-center text-slate-400 text-sm border-2 border-dashed border-slate-200 rounded-lg">
            No vinyl in this view.
            {isAdmin && <div className="mt-3"><Button onClick={handleAdd} size="sm" className="bg-blue-600 text-white"><Plus className="w-4 h-4 mr-1" /> Add the first one</Button></div>}
          </div>
        ) : (
          <div className="space-y-2">
            {filtered.map(v => (
              <VinylRowCard
                key={v.id}
                vinyl={v}
                isAdmin={isAdmin}
                groupSiblings={items.filter(x => x.id !== v.id && v.product_group_key && x.product_group_key === v.product_group_key)}
                onEdit={() => setEditingVinyl(v)}
                onDelete={() => handleDelete(v)}
                onDuplicate={() => handleDuplicate(v)}
              />
            ))}
          </div>
        )}
      </CardContent>

      <VinylEditDialog
        open={!!editingVinyl}
        vinyl={editingVinyl}
        isAdmin={isAdmin}
        onSave={handleDialogSave}
        onClose={() => setEditingVinyl(null)}
      />
    </Card>
  );
}

// One compact vinyl row. No inline editor — clicking "Edit" opens the
// polished VinylEditDialog popup (handled by the parent tab).

import React from "react";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Trash2, Pencil, Droplets, Image as ImageIcon, Copy, Layers } from "lucide-react";
import { VINYL_CATEGORIES, vinylCostPerSqft } from "./vinylConstants";

const num = (v, fb = 0) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : fb;
};

export default function VinylRowCard({ vinyl, isAdmin, groupSiblings = [], onEdit, onDelete, onDuplicate }) {
  const dollarPerSqft = vinylCostPerSqft(vinyl);
  const categoryLabel = VINYL_CATEGORIES.find(c => c.id === vinyl.vinyl_category)?.label || vinyl.vinyl_category || "—";

  return (
    <Card className="border-slate-200 overflow-hidden hover:border-blue-300 hover:shadow-sm transition-all">
      <div className="p-3 grid md:grid-cols-12 gap-3 items-center bg-white">
        <div className="md:col-span-1 flex items-center justify-center">
          <div
            className="w-10 h-10 rounded-md border border-slate-200 flex items-center justify-center text-[10px] text-slate-400"
            style={{ background: vinyl.color_hex || "#fafafa" }}
            title={vinyl.color_name}
          >
            {vinyl.image_url
              ? <ImageIcon className="w-4 h-4 text-slate-500" />
              : <Droplets className="w-4 h-4 text-slate-400" />}
          </div>
        </div>

        <div className="md:col-span-3">
          <Label className="text-[10px] uppercase tracking-wider text-slate-500">Name</Label>
          <div className="h-9 flex items-center text-sm font-medium text-slate-800 truncate">
            {vinyl.vinyl_name || <span className="text-slate-400 italic">(unnamed)</span>}
          </div>
        </div>

        <div className="md:col-span-2">
          <Label className="text-[10px] uppercase tracking-wider text-slate-500">Brand / Series</Label>
          <Input
            value={`${vinyl.manufacturer || ""}${vinyl.product_series ? ` · ${vinyl.product_series}` : ""}`}
            disabled
            className="h-9 text-sm bg-slate-50"
          />
        </div>

        <div className="md:col-span-1">
          <Label className="text-[10px] uppercase tracking-wider text-slate-500">Width</Label>
          <div className="h-9 flex items-center text-sm tabular-nums text-slate-700">{num(vinyl.roll_width_inches)}"</div>
        </div>

        <div className="md:col-span-1">
          <Label className="text-[10px] uppercase tracking-wider text-slate-500">Length</Label>
          <div className="h-9 flex items-center text-sm tabular-nums text-slate-700">{num(vinyl.roll_length_yards)} yd</div>
        </div>

        <div className="md:col-span-1">
          <Label className="text-[10px] uppercase tracking-wider text-slate-500">$/sqft</Label>
          <div className="h-9 flex items-center text-sm font-semibold tabular-nums text-emerald-700">
            ${dollarPerSqft.toFixed(2)}
          </div>
        </div>

        <div className="md:col-span-3 flex items-center justify-end gap-2">
          <Badge variant="outline" className="text-[10px]">{categoryLabel}</Badge>
          {groupSiblings.length > 0 && (
            <Badge variant="outline" className="text-[10px] bg-blue-50 text-blue-700 inline-flex items-center gap-1" title={`Group: ${groupSiblings.map(s => `${s.roll_width_inches}"`).join(", ")}`}>
              <Layers className="w-3 h-3" /> {groupSiblings.length + 1} widths
            </Badge>
          )}
          <Button size="sm" variant="outline" onClick={onEdit}>
            <Pencil className="w-3.5 h-3.5 mr-1" />
            {isAdmin ? "Edit" : "View"}
          </Button>
          {isAdmin && onDuplicate && (
            <Button size="sm" variant="outline" onClick={onDuplicate} title="Duplicate (links to same product group)">
              <Copy className="w-3.5 h-3.5" />
            </Button>
          )}
          {isAdmin && (
            <Button size="sm" variant="outline" className="text-red-600 hover:bg-red-50" onClick={onDelete}>
              <Trash2 className="w-3.5 h-3.5" />
            </Button>
          )}
        </div>
      </div>
    </Card>
  );
}

