// Pick the right $/sqin for a printer + quality. Falls back to legacy
// `print_cost_per_sqin` if the tiered fields aren't populated.
export const inkCostPerSqIn = (printer, quality = "high_quality") => {
  if (!printer) return 0;
  const map = {
    draft:        parseFloat(printer.print_cost_per_sqin_draft),
    production:   parseFloat(printer.print_cost_per_sqin_production),
    high_quality: parseFloat(printer.print_cost_per_sqin_high_quality),
  };
  const tiered = map[quality];
  if (Number.isFinite(tiered) && tiered > 0) return tiered;
  return parseFloat(printer.print_cost_per_sqin) || 0;
};

// Compute the unit cost the estimator should use, in $/sqft, regardless of
// how the vinyl is priced.
export const vinylCostPerSqft = (v) => {
  if (!v) return 0;
  const w = parseFloat(v.roll_width_inches) || 0;
  const lYd = parseFloat(v.roll_length_yards) || 0;
  const rollSqFt = (w / 12) * (lYd * 3); // width(ft) × length(ft)
  switch (v.pricing_mode) {
    case "per_sqft":
      return parseFloat(v.cost_per_sqft) || 0;
    case "per_linear_foot": {
      const widthFt = w / 12;
      return widthFt > 0 ? (parseFloat(v.cost_per_linear_foot) || 0) / widthFt : 0;
    }
    case "per_roll":
    default:
      return rollSqFt > 0 ? (parseFloat(v.cost_per_roll) || 0) / rollSqFt : 0;
  }
};

// Filter helper — applies the same "scope" logic used by other estimator
// inventory tabs (substrates, equipment).
export const filterVinylForScope = (items, scope) => {
  if (!Array.isArray(items)) return [];
  return items.filter((v) => {
    if (v.is_active === false) return false;
    if (v.show_in_master_only) return scope === "master";
    if (scope === "channel_letters") return v.show_in_channel_letters !== false;
    if (scope === "sign_maintenance") return v.show_in_sign_maintenance !== false;
    return true; // master
  });
};

import {
  deleteEntityIfUnchanged,
  expectedEntityFields,
  replaceEntityFieldsIfUnchanged,
} from "@/components/estimator/builder/builderEntityPersistence";

function normalized(value) {
  if (Array.isArray(value)) return value.map(normalized);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    out[key] = normalized(value[key]);
    return out;
  }, {});
}

function sameValue(a, b) {
  return JSON.stringify(normalized(a)) === JSON.stringify(normalized(b));
}

function stripMeta(row = {}) {
  const payload = { ...row };
  ["id", "created_date", "updated_date", "created_by_id"].forEach((key) => delete payload[key]);
  return payload;
}

function rowMatchesData(row, data) {
  return Object.entries(data || {}).every(([key, value]) => sameValue(row?.[key], value));
}

export async function createVinylRecordWithRecovery({ entity, data, label = "Vinyl inventory record" } = {}) {
  const name = String(data?.vinyl_name || "").trim();
  if (!name || typeof entity?.filter !== "function" || typeof entity?.create !== "function") {
    throw new Error(`${label} could not initialize its retry-safe create.`);
  }

  const readMatches = async () => {
    const rows = await entity.filter({ vinyl_name: name });
    if (!Array.isArray(rows)) throw new Error(`${label} lookup did not return a record list.`);
    return rows.filter((row) => rowMatchesData(row, data));
  };

  const before = await readMatches();
  const beforeIds = new Set(before.map((row) => row.id));

  let created = null;
  let createError = null;
  try {
    created = await entity.create(data);
  } catch (error) {
    createError = error;
  }

  if (created?.id) {
    const saved = typeof entity.get === "function" ? await entity.get(created.id).catch(() => null) : null;
    return { record: saved?.id ? saved : created, status: "created", ownershipCertain: true };
  }

  const after = await readMatches();
  const newMatches = after.filter((row) => !beforeIds.has(row.id));
  if (newMatches.length === 1) {
    return { record: newMatches[0], status: "recovered", ownershipCertain: false };
  }
  if (newMatches.length > 1) {
    throw new Error(`${label} may have been created more than once while the create response was unavailable. No rows were deleted; reload and review the new matching records before retrying.`);
  }

  if (createError) throw createError;
  throw new Error(`${label} could not verify whether it was created. Reload before retrying.`);
}

export async function updateVinylIfUnchanged({ entity, record, nextFields, label = "Vinyl inventory record" } = {}) {
  if (!record?.id) throw new Error(`${label} is no longer loaded. Reload before saving.`);
  return replaceEntityFieldsIfUnchanged({
    entity,
    id: record.id,
    expectedUpdatedAt: record.updated_date || "",
    expectedFields: expectedEntityFields(record, nextFields),
    nextFields,
    guardFields: { vinyl_name: record.vinyl_name },
    label,
  });
}

export async function deleteVinylIfUnchanged({ entity, record, label = "Vinyl inventory record" } = {}) {
  if (!record?.id) throw new Error(`${label} is no longer loaded. Reload before deleting.`);
  return deleteEntityIfUnchanged({
    entity,
    record,
    guardFields: { vinyl_name: record.vinyl_name },
    label,
  });
}

export async function duplicateVinylSafely({
  entity,
  source,
  copyData,
  groupKey,
  label = "Vinyl inventory duplicate",
} = {}) {
  if (!source?.id) throw new Error(`${label} source is no longer loaded.`);
  if (typeof entity?.get !== "function") throw new Error(`${label} could not verify its source record.`);

  const live = await entity.get(source.id);
  if (!live?.id || String(live.updated_date || "") !== String(source.updated_date || "")) {
    throw new Error(`${label} was blocked because the source vinyl changed in another session.`);
  }

  const copyResult = await createVinylRecordWithRecovery({ entity, data: copyData, label });
  let savedSource = live;

  if (!live.product_group_key) {
    try {
      savedSource = await updateVinylIfUnchanged({
        entity,
        record: live,
        nextFields: { product_group_key: groupKey },
        label: `${label} source grouping`,
      });
    } catch (error) {
      if (copyResult.ownershipCertain) {
        try {
          await deleteVinylIfUnchanged({
            entity,
            record: copyResult.record,
            label: `${label} rollback copy`,
          });
        } catch (rollbackError) {
          throw new Error(`${error?.message || `${label} could not group the source.`} The new copy also could not be rolled back safely: ${rollbackError?.message || "rollback failed"}`);
        }
      } else {
        throw new Error(`${error?.message || `${label} could not group the source.`} The create response was ambiguous, so no uncertain copy was deleted; reload and review the matching vinyl records.`);
      }
      throw error;
    }
  }

  return { source: savedSource, copy: copyResult.record, copyStatus: copyResult.status };
}

export { stripMeta as stripVinylRecordMeta };

function normalize(value) {
  if (Array.isArray(value)) return value.map(normalize);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    out[key] = normalize(value[key]);
    return out;
  }, {});
}

function sameValue(a, b) {
  if (a !== null && a !== undefined && a !== "" && b !== null && b !== undefined && b !== "") {
    if (Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
      return Math.abs(Number(a) - Number(b)) <= 0.000001;
    }
  }
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));
}

function matchesPayload(row = {}, payload = {}) {
  return Object.entries(payload).every(([key, value]) => sameValue(row?.[key], value));
}

export async function createVinylMachineWithRecovery({ entity, data, label = "Vinyl machine" } = {}) {
  const machineType = String(data?.machine_type || "").trim();
  if (!machineType || !String(data?.machine_name || "").trim() || typeof entity?.filter !== "function" || typeof entity?.create !== "function") {
    throw new Error(`${label} could not initialize its retry-safe create.`);
  }

  const readMatches = async () => {
    const rows = await entity.filter({ machine_type: machineType });
    if (!Array.isArray(rows)) throw new Error(`${label} lookup did not return a record list.`);
    return rows.filter((row) => matchesPayload(row, data));
  };

  const before = await readMatches();
  const beforeIds = new Set(before.map((row) => row.id));

  let created = null;
  let createError = null;
  try {
    created = await entity.create(data);
  } catch (error) {
    createError = error;
  }

  if (created?.id) {
    const saved = typeof entity.get === "function" ? await entity.get(created.id).catch(() => null) : null;
    return { record: saved?.id ? saved : created, status: "created" };
  }

  const after = await readMatches();
  const newMatches = after.filter((row) => !beforeIds.has(row.id));
  if (newMatches.length === 1) {
    return { record: newMatches[0], status: "recovered" };
  }
  if (newMatches.length > 1) {
    throw new Error(`${label} may have been created more than once while the create response was unavailable. No rows were deleted; reload and review the new matching machines before retrying.`);
  }

  if (createError) throw createError;
  throw new Error(`${label} could not verify whether it was created. Reload before retrying.`);
}

import React from "react";
import { ACTIONS, ACTION_GROUPS } from "./constants";
import { Check } from "lucide-react";

// `enabledActions` is an array of action ids that the user has enabled for this
// sign type in Settings. When omitted, every action is shown (backward compat).
export default function ActionPicker({ signType, selected, onToggle, enabledActions }) {
  if (!signType) {
    return <div className="text-xs text-slate-400 italic">Pick a sign type first to see applicable maintenance actions.</div>;
  }

  const allowed = enabledActions || ACTIONS.map(a => a.id);
  const grouped = ACTION_GROUPS.map(group => ({
    group,
    actions: ACTIONS.filter(a => a.group === group && allowed.includes(a.id)),
  })).filter(g => g.actions.length > 0);

  if (grouped.length === 0) {
    return (
      <div className="text-xs text-slate-500 italic bg-amber-50 border border-amber-200 rounded-md p-2">
        No actions are enabled for this sign type. Enable them in Sign Maintenance Settings → Service Items.
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {grouped.map(g => (
        <div key={g.group}>
          <div className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider mb-1.5">{g.group}</div>
          <div className="flex flex-wrap gap-1.5">
            {g.actions.map(a => {
              const on = selected.includes(a.id);
              return (
                <button type="button"
                  key={a.id}
                  type="button"
                  onClick={() => onToggle(a.id)}
                  className={`text-xs px-2.5 py-1 rounded-full border transition-all flex items-center gap-1 ${
                    on
                      ? "bg-cyan-600 text-white border-cyan-600 shadow-sm"
                      : "bg-white text-slate-700 border-slate-200 hover:border-cyan-300"
                  }`}
                >
                  {on && <Check className="w-3 h-3" />}
                  {a.label}
                </button>
              );
            })}
          </div>
        </div>
      ))}
    </div>
  );
}

// Single (sign_type × action) rate card with an enable/disable toggle.
