// Single editable card for one MaintenanceInventory record.
// Used by both sub-tabs (Main Service Type / Action Items) of the Maintenance
// Materials tab. All applicability tagging is done here in one place.

import React, { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { Trash2, ChevronDown, ChevronRight, Copy } from "lucide-react";
import { SIGN_TYPES, ACTIONS, ACTION_GROUPS } from "./constants";

const PRICING_MODES = [
  { value: "per_letter_flat",      label: "Per Letter (Flat)" },
  { value: "per_letter_by_size",   label: "Per Letter (By Size)" },
  { value: "per_cabinet_flat",     label: "Per Cabinet (Flat)" },
  { value: "per_cabinet_by_size",  label: "Per Cabinet (By Size)" },
  { value: "per_linear_foot",      label: "Per Linear Foot" },
  { value: "per_sqft",             label: "Per Sq Ft" },
  { value: "per_project_flat",     label: "Per Service Item (Flat)" },
];

export default function MaintenanceMaterialItem({
  item, isDirty, defaultExpanded, onChange, onRemove, onDuplicate,
}) {
  const [expanded, setExpanded] = useState(!!defaultExpanded);

  const update = (patch) => onChange(patch);
  const types = Array.isArray(item.applies_to_item_types) ? item.applies_to_item_types : [];
  const actions = Array.isArray(item.applies_to_actions) ? item.applies_to_actions : [];

  const toggleInArray = (key, value) => {
    const arr = Array.isArray(item[key]) ? item[key] : [];
    const next = arr.includes(value) ? arr.filter(v => v !== value) : [...arr, value];
    update({ [key]: next });
  };

  const headlineCost = () => {
    switch (item.pricing_mode) {
      case "per_letter_flat":    return `$${(item.cost_per_letter || 0).toFixed(2)} / letter`;
      case "per_cabinet_flat":   return `$${(item.cost_per_cabinet || 0).toFixed(2)} / cabinet`;
      case "per_linear_foot":    return `$${(item.cost_per_foot || 0).toFixed(2)} / ft`;
      case "per_sqft":           return `$${(item.cost_per_sqft || 0).toFixed(2)} / sqft`;
      case "per_project_flat":   return `$${(item.cost_flat || 0).toFixed(2)} / item`;
      default:                   return "Variable pricing";
    }
  };

  return (
    <div className={`bg-white border rounded-xl ${isDirty ? "border-amber-300 ring-1 ring-amber-100" : "border-slate-200"}`}>
      <div className="flex items-center gap-3 px-4 py-3 hover:bg-slate-50">
        <button type="button" className="text-slate-400 hover:text-slate-700" onClick={() => setExpanded(x => !x)}>
          {expanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
        </button>
        <div className="flex-1 min-w-0 cursor-pointer" onClick={() => setExpanded(x => !x)}>
          <div className="flex items-center gap-2 flex-wrap">
            <span className="font-semibold text-slate-900 truncate">
              {item.item_name || <span className="text-slate-400 italic">Unnamed item</span>}
            </span>
            <Badge variant="outline" className="text-[10px] bg-slate-50">{headlineCost()}</Badge>
            {types.length > 0 && (
              <Badge variant="outline" className="text-[10px] bg-cyan-50 text-cyan-700 border-cyan-200">
                {types.length} sign type{types.length !== 1 ? "s" : ""}
              </Badge>
            )}
            {actions.length > 0 && (
              <Badge variant="outline" className="text-[10px] bg-violet-50 text-violet-700 border-violet-200">
                {actions.length} action{actions.length !== 1 ? "s" : ""}
              </Badge>
            )}
            {isDirty && <Badge variant="outline" className="text-[10px] bg-amber-50 text-amber-700 border-amber-200">Unsaved</Badge>}
          </div>
        </div>
        <div className="flex items-center gap-1">
          <Button size="sm" variant="ghost" onClick={(e) => { e.stopPropagation(); onDuplicate(); }} className="h-8 w-8 p-0 text-slate-500"><Copy className="w-4 h-4" /></Button>
          <Button size="sm" variant="ghost" onClick={(e) => { e.stopPropagation(); if (!confirm(`Delete "${item.item_name || "this item"}"?`)) return; onRemove(); }} className="h-8 w-8 p-0 text-red-500"><Trash2 className="w-4 h-4" /></Button>
        </div>
      </div>

      {expanded && (
        <div className="border-t border-slate-200 px-4 py-4 bg-slate-50/40 space-y-4">
          <div className="grid md:grid-cols-12 gap-3">
            <div className="md:col-span-6">
              <Label className="text-xs">Material Name</Label>
              <Input value={item.item_name || ""} onChange={(e) => update({ item_name: e.target.value })} placeholder="e.g. White Acrylic Face" className="h-9 mt-1" />
            </div>
            <div className="md:col-span-3">
              <Label className="text-xs">Supplier</Label>
              <Input value={item.supplier || ""} onChange={(e) => update({ supplier: e.target.value })} className="h-9 mt-1" />
            </div>
            <div className="md:col-span-3">
              <Label className="text-xs">Unit</Label>
              <Input value={item.unit || ""} onChange={(e) => update({ unit: e.target.value })} placeholder="ea, ft, sqft" className="h-9 mt-1" />
            </div>
          </div>

          {/* Applies to: Service types */}
          <div>
            <Label className="text-xs font-semibold text-slate-700">Applies to Service Types <span className="text-slate-400 font-normal">(leave empty for all)</span></Label>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-2 mt-2">
              {SIGN_TYPES.map(st => (
                <label key={st.id} className="flex items-center gap-2 text-xs bg-white border border-slate-200 rounded-lg px-2 py-1.5 cursor-pointer hover:bg-slate-50">
                  <Checkbox checked={types.includes(st.id)} onCheckedChange={() => toggleInArray("applies_to_item_types", st.id)} />
                  <span className="truncate">{st.label}</span>
                </label>
              ))}
            </div>
          </div>

          {/* Applies to: Actions, grouped */}
          <div>
            <Label className="text-xs font-semibold text-slate-700">Applies to Maintenance Actions <span className="text-slate-400 font-normal">(leave empty for all)</span></Label>
            <div className="space-y-3 mt-2">
              {ACTION_GROUPS.map(group => (
                <div key={group}>
                  <div className="text-[10px] uppercase tracking-wider text-slate-500 font-semibold mb-1">{group}</div>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                    {ACTIONS.filter(a => a.group === group).map(a => (
                      <label key={a.id} className="flex items-center gap-2 text-xs bg-white border border-slate-200 rounded-lg px-2 py-1.5 cursor-pointer hover:bg-slate-50">
                        <Checkbox checked={actions.includes(a.id)} onCheckedChange={() => toggleInArray("applies_to_actions", a.id)} />
                        <span className="truncate">{a.label}</span>
                      </label>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Pricing */}
          <div className="grid md:grid-cols-12 gap-3">
            <div className="md:col-span-4">
              <Label className="text-xs">Pricing Mode</Label>
              <Select value={item.pricing_mode || "per_letter_flat"} onValueChange={(v) => update({ pricing_mode: v })}>
                <SelectTrigger className="h-9 mt-1"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {PRICING_MODES.map(m => <SelectItem key={m.value} value={m.value}>{m.label}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="md:col-span-8">
              {item.pricing_mode === "per_letter_flat" && (
                <div><Label className="text-xs">Cost / Letter ($)</Label><Input type="number" step="0.01" value={item.cost_per_letter || 0} onChange={(e) => update({ cost_per_letter: parseFloat(e.target.value) || 0 })} className="h-9 mt-1 max-w-[200px]" /></div>
              )}
              {item.pricing_mode === "per_cabinet_flat" && (
                <div><Label className="text-xs">Cost / Cabinet ($)</Label><Input type="number" step="0.01" value={item.cost_per_cabinet || 0} onChange={(e) => update({ cost_per_cabinet: parseFloat(e.target.value) || 0 })} className="h-9 mt-1 max-w-[200px]" /></div>
              )}
              {item.pricing_mode === "per_linear_foot" && (
                <div><Label className="text-xs">Cost / Linear Foot ($)</Label><Input type="number" step="0.01" value={item.cost_per_foot || 0} onChange={(e) => update({ cost_per_foot: parseFloat(e.target.value) || 0 })} className="h-9 mt-1 max-w-[200px]" /></div>
              )}
              {item.pricing_mode === "per_sqft" && (
                <div><Label className="text-xs">Cost / Sq Ft ($)</Label><Input type="number" step="0.01" value={item.cost_per_sqft || 0} onChange={(e) => update({ cost_per_sqft: parseFloat(e.target.value) || 0 })} className="h-9 mt-1 max-w-[200px]" /></div>
              )}
              {item.pricing_mode === "per_project_flat" && (
                <div><Label className="text-xs">Flat Cost / Service Item ($)</Label><Input type="number" step="0.01" value={item.cost_flat || 0} onChange={(e) => update({ cost_flat: parseFloat(e.target.value) || 0 })} className="h-9 mt-1 max-w-[200px]" /></div>
              )}
              {(item.pricing_mode === "per_letter_by_size" || item.pricing_mode === "per_cabinet_by_size") && (
                <div className="text-xs text-slate-500 mt-1 italic">Size-based pricing matrix (advanced) — edit via Master Inventory.</div>
              )}
            </div>
          </div>

          <div>
            <Label className="text-xs">Notes</Label>
            <Input value={item.notes || ""} onChange={(e) => update({ notes: e.target.value })} className="h-9 mt-1" />
          </div>
        </div>
      )}
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { AlertTriangle, Boxes, Edit3, Link2, Plus, Save, ShieldCheck } from "lucide-react";
import { MaintenanceInventory } from "@/api/gatedEntities";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import MasterPartPickerModal from "@/components/estimator/parts/MasterPartPickerModal";
import { money } from "@/components/estimator/aioPricing";
import { SIGN_TYPES, ACTIONS } from "./constants";
import { expectedEntityFields, replaceEntityFieldsIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";
import { createMaintenanceMaterialRuleIfAbsent } from "./maintenanceMaterialRulePersistence";
import {
  isMaintenanceMaterialCatalogItem,
  legacyPricingModeForUsageBasis,
  loadMaintenanceMaterialRules,
  suggestedUsageBasis,
  suggestedUsageMultiplier,
} from "./maintenanceMaterialRules";

const SIZE_OPTIONS = [
  ["extra_small", "XS Letters"], ["small", "Small Letters"], ["medium", "Medium Letters"],
  ["large", "Large Letters"], ["extra_large", "XL Letters"], ["extra_extra_large", "XXL Letters"],
  ["cab_small", "Small Cabinet"], ["cab_medium", "Medium Cabinet"], ["cab_large", "Large Cabinet"], ["cab_extra_large", "XL Cabinet"],
];
const BASIS_OPTIONS = [
  ["per_letter", "Per letter"], ["per_cabinet", "Per cabinet"], ["per_linear_foot", "Per linear foot"],
  ["per_sqft", "Per square foot"], ["per_service_item", "Per service item"],
];

const emptyDraft = () => ({
  item_name: "",
  inventory_entity: "",
  inventory_item_id: "",
  inventory_item_name: "",
  usage_basis: "per_service_item",
  usage_multiplier: 1,
  usage_rounding: "none",
  applies_to_item_types: [],
  applies_to_sizes: [],
  applies_to_actions: [],
  pricing_mode: "per_project_flat",
  is_default: true,
  is_active: true,
  sort_order: 0,
  notes: "",
});

function toggle(list, value) {
  return list.includes(value) ? list.filter((item) => item !== value) : [...list, value];
}

function RuleEditor({ open, rule, catalog, onClose, onSaved }) {
  const [draft, setDraft] = useState(emptyDraft());
  const [pickerOpen, setPickerOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const saveRef = useRef(false);

  useEffect(() => {
    if (!open) return;
    setDraft({ ...emptyDraft(), ...(rule || {}) });
    setSaving(false);
    setError("");
  }, [open, rule?.id, rule?.updated_date]);

  const linked = catalog.find((item) => item.entity === draft.inventory_entity && item.inventoryId === draft.inventory_item_id) || null;
  const patch = (changes) => setDraft((current) => ({ ...current, ...changes }));

  const save = async () => {
    if (!draft.inventory_entity || !draft.inventory_item_id || !draft.item_name.trim() || saveRef.current) return;
    saveRef.current = true;
    setSaving(true);
    setError("");
    try {
      const payload = {
        item_name: draft.item_name.trim(),
        inventory_entity: draft.inventory_entity,
        inventory_item_id: draft.inventory_item_id,
        inventory_item_name: draft.inventory_item_name || linked?.name || draft.item_name.trim(),
        usage_basis: draft.usage_basis,
        usage_multiplier: Math.max(0, Number(draft.usage_multiplier || 0)),
        usage_rounding: draft.usage_rounding === "ceil_whole" ? "ceil_whole" : "none",
        applies_to_item_types: draft.applies_to_item_types || [],
        applies_to_sizes: draft.applies_to_sizes || [],
        applies_to_actions: draft.applies_to_actions || [],
        pricing_mode: legacyPricingModeForUsageBasis(draft.usage_basis),
        is_default: draft.is_default !== false,
        is_active: draft.is_active !== false,
        sort_order: Number(draft.sort_order || 0),
        notes: draft.notes || "",
      };
      if (rule?.id) {
        await replaceEntityFieldsIfUnchanged({
          entity: MaintenanceInventory,
          id: rule.id,
          expectedUpdatedAt: rule.updated_date || "",
          expectedFields: expectedEntityFields(rule, payload),
          nextFields: payload,
          label: `Maintenance material rule “${rule.item_name || payload.item_name || "Rule"}”`,
        });
      } else {
        const result = await createMaintenanceMaterialRuleIfAbsent({
          entity: MaintenanceInventory,
          data: payload,
          label: `Maintenance material rule “${payload.item_name || "Rule"}”`,
        });
        if (result.status === "existing" || result.status === "concurrent_duplicate_discarded") {
          throw new Error("An equivalent Maintenance material rule already exists for this Master Inventory resource, usage, and applicability. The existing rule was kept.");
        }
      }
      await onSaved?.();
      onClose?.();
    } catch (err) {
      if (rule?.id) {
        const latest = await MaintenanceInventory.get(rule.id).catch(() => null);
        if (latest?.id) setDraft({ ...emptyDraft(), ...latest });
      }
      setError(err?.message || "Maintenance material rule could not be saved.");
    } finally {
      saveRef.current = false;
      setSaving(false);
    }
  };

  return (
    <>
      <Dialog open={open} onOpenChange={(next) => !next && !saving && onClose?.()}>
        <DialogContent className="sm:max-w-[920px] p-0 overflow-hidden border-gray-300 shadow-2xl">
          <DialogHeader className="px-5 py-4 bg-[#3f3f3f] text-white border-b-4 border-lime-300">
            <DialogTitle className="text-white text-[17px] flex items-center gap-2"><Link2 className="w-5 h-5 text-lime-300" /> {rule?.id ? "Edit" : "Add"} Maintenance Material Rule</DialogTitle>
            <p className="text-[10px] text-gray-300 mt-1">Master Inventory owns the resource and cost. This rule only controls when and how much Maintenance uses.</p>
          </DialogHeader>
          <div className="p-5 bg-white space-y-4 max-h-[78vh] overflow-y-auto">
            <section className="rounded border border-gray-200 bg-gray-50 p-3">
              <div className="flex items-center justify-between gap-3">
                <div className="min-w-0">
                  <div className="text-[9px] font-bold tracking-widest text-gray-400">MASTER INVENTORY RESOURCE</div>
                  <div className="text-[12px] font-bold text-gray-900 mt-1">{linked?.name || draft.inventory_item_name || "No resource selected"}</div>
                  {linked && <div className="text-[9px] text-gray-500 mt-0.5">{linked.categoryLabel} · {String(linked.subtype || "").replaceAll("_", " ")} · {money(linked.unitCost)} / {linked.unit}</div>}
                </div>
                <Button type="button" variant="outline" className="h-[30px] text-[10px]" onClick={() => setPickerOpen(true)}><Boxes className="w-3.5 h-3.5 mr-1.5" /> {linked ? "Change Resource" : "Select Resource"}</Button>
              </div>
            </section>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
              <label className="md:col-span-2 text-[10px] font-bold tracking-wide text-gray-500">RULE NAME<Input value={draft.item_name} onChange={(e) => patch({ item_name: e.target.value })} className="mt-1 h-[33px] text-[11px]" placeholder="e.g. LED modules — medium channel letters" /></label>
              <label className="text-[10px] font-bold tracking-wide text-gray-500">USAGE BASIS<select value={draft.usage_basis} onChange={(e) => patch({ usage_basis: e.target.value })} className="mt-1 w-full h-[33px] border border-gray-300 rounded px-2 bg-white text-[11px]">{BASIS_OPTIONS.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>
              <label className="text-[10px] font-bold tracking-wide text-gray-500">MASTER UNITS / BASIS UNIT<Input type="number" min="0" step="any" value={draft.usage_multiplier} onChange={(e) => patch({ usage_multiplier: e.target.value })} className="mt-1 h-[33px] text-[11px]" /></label>
              <label className="text-[10px] font-bold tracking-wide text-gray-500">QUANTITY ROUNDING<select value={draft.usage_rounding} onChange={(e) => patch({ usage_rounding: e.target.value })} className="mt-1 w-full h-[33px] border border-gray-300 rounded px-2 bg-white text-[11px]"><option value="none">No rounding</option><option value="ceil_whole">Round up to whole Master unit</option></select></label>
