              <label className="text-[10px] font-bold tracking-wide text-gray-500">SORT ORDER<Input type="number" value={draft.sort_order || 0} onChange={(e) => patch({ sort_order: e.target.value })} className="mt-1 h-[33px] text-[11px]" /></label>
