// Hold-Down Advisor — decides whether the item needs enhanced workholding.
export function holdDownAdvice(item) {
  const reasons = [];
  const detail = num(item.smallest_detail_in);
  const cutter = num(item.cutter_diameter_in);
  const loose = item.item_type === "lettering" || item.creates_loose_pieces;
  const base = item.workholding_method || "none";

  if (loose) reasons.push("Cut releases loose pieces at cut-through");
  if (detail > 0 && cutter > 0 && detail < cutter * 2)
    reasons.push(`Fine detail (${detail}") is under 2× cutter diameter`);
  if (["none", "clamps", "screws"].includes(base) && loose)
    reasons.push(`Base workholding (${base.replace("_", " ")}) will not retain small pieces`);
  if (base === "vacuum_full" && detail > 0 && detail < 0.5)
    reasons.push("Vacuum alone loses grip on narrow strokes");

  const needed = item.force_enhanced || reasons.length > 0;
  return {
    needed,
    reasons,
    recommendation: needed
      ? loose
        ? "Add tape-and-glue or onion-skin tabs over the vacuum, and plan a manual release pass."
        : "Add supplemental tape/glue or zoned vacuum before the finish pass."
      : "Base workholding is sufficient.",
    extra_hours: needed ? 0.25 * num(item.quantity, 1) : 0,
  };
}

export function calcCNCProject(project) {
  const machineRate = num(project.machine_rate_per_hour, 75);
  const laborRate = num(project.labor_rate, 45);
  const setupPct = num(project.setup_time_percentage, 20);

  const items = (project.items || []).map((raw) => {
    const item = { ...raw };
    const qty = num(item.quantity, 1);

    let cutHours = 0;
    if (item.item_type === "3d_carving") {
      const rate = num(item.carve_speed_sqipm, 10);
      const passes = Math.max(1, Math.ceil(num(item.carve_depth) / 0.25));
      cutHours = rate > 0 ? (num(item.carve_area_sqin) * passes) / rate / 60 : 0;
    } else {
      const speed = num(item.cut_speed_ipm, 50);
      const perimeter =
        num(item.total_cut_length_inches) ||
        (item.item_type === "lettering"
          ? num(item.num_letters) * num(item.letter_height) * 4
          : (num(item.length) + num(item.width)) * 2);
      cutHours = speed > 0 ? perimeter / speed / 60 : 0;
    }

    const advice = holdDownAdvice(item);
    item.hold_down = advice;
    item.machine_time_hours = cutHours * qty;
    item.setup_time_hours = (item.machine_time_hours * setupPct) / 100 + advice.extra_hours;
    item.machine_cost = item.machine_time_hours * machineRate;
    item.labor_cost = item.setup_time_hours * laborRate;
    item.item_total_cost = item.machine_cost + item.labor_cost;
    return item;
  });

  const total_machine_hours = items.reduce((s, i) => s + i.machine_time_hours, 0);
  const total_machine_cost = items.reduce((s, i) => s + i.machine_cost, 0);
  const fixed_setup_cost = num(project.fixed_setup_hours) * laborRate;
  const total_labor_cost = items.reduce((s, i) => s + i.labor_cost, 0) + fixed_setup_cost;
  const total_setup_hours =
    items.reduce((s, i) => s + i.setup_time_hours, 0) + num(project.fixed_setup_hours);

  return {
    items,
    totals: {
      total_machine_hours,
      total_setup_hours,
      total_machine_cost,
      fixed_setup_cost,
      total_labor_cost,
      total_cost: total_machine_cost + total_labor_cost,
    },
  };
}

// CNC sell-price engine wire (F-23d) — module-side glue.
//
// The shared wire (base44/shared/cncPricingWire.ts) is intentionally
// import-free; this file is the composition root that injects the real engine
// functions and merges caller-supplied registries with the record-embedded
// engine context. Wired into customerPricing.sourceProjectEconomics for
// module_key "cnc" — when no CNC line carries pricing-engine config the
// resolution is a passthrough and the module sell price is returned verbatim
// (zero regression).
//
// Registry context (`pricingContext`) is OPTIONAL today: config embedded on
// the record/items (item pricing fields, engine_pricing blocks, embedded
// templates/tier rules) resolves without any entity reads. Callers that have
// PricingTierMatrix / PricingTemplate / GlobalPricingTier / MarkupTier rows
// loaded may pass them as { tierRules|tier_rules, templates, tiers,
// customerTier|customer_tier, defaultMarkupPct|default_markup_pct, now } to
// unlock registry-backed tier/template references.

import { pricePart, matrixRowsToRules } from "../../../../base44/shared/pricingEngine.ts";
import { resolveTemplatePrice, templatePartDescriptor } from "../../../../base44/shared/pricingTemplateModel.ts";
import {
  resolveCncSellPricing,
  cncConfigScan,
  cncPricingContextOf,
} from "../../../../base44/shared/cncPricingWire.ts";

const ENGINE = Object.freeze({ pricePart, resolveTemplatePrice, templatePartDescriptor });

/**
 * Full resolution — engine-priced sell for config-carrying CNC lines.
 * Never throws: malformed input/config degrades to a passthrough result.
 *
 * @param {object} record       CNCProject-like record
 * @param {object} opts
 * @param {number} opts.baselineSell  module sell price (record.total_cost)
 * @param {number} [opts.internalCost] module internal cost (record.total_cost)
 * @param {object} [opts.pricingContext] caller-loaded registries (optional)
 * @param {*}      [opts.now]    effective-window override (tests)
 * @returns {object} resolveCncSellPricing result ({applied, customer_price,
 *          passthrough, lines, chain, warnings, ...})
 */
export function resolveCncEngineSell(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  try {
    const caller = pricingContext && typeof pricingContext === "object" ? { ...pricingContext } : {};
    // Normalize caller chart rows through the engine's entity adapter so
    // PricingTierMatrix spellings (unit_breaks aliases, status windows) resolve
    // exactly like the pricing admin path.
    const rawRules = caller.tierRules ?? caller.tier_rules ?? caller.tier_matrix;
    if (Array.isArray(rawRules) && rawRules.length) {
      caller.tierRules = matrixRowsToRules(rawRules, { now: caller.now ?? now });
    }
    const context = cncPricingContextOf(record, caller);
    return resolveCncSellPricing({ record, baselineSell, internalCost, context, engine: ENGINE, now });
  } catch {
    // The sell-price seam must never break estimate rendering — a malformed
    // record or config degrades to the module baseline, not an exception.
    return { applied: false, passthrough: true, reason: "no_engine", customer_price: baselineSell, warnings: [] };
  }
}

/**
 * Seam helper — engine-owned economics for a CNC source record.
 * Returns null when no CNC line carries pricing config (the caller then
 * keeps today's numbers byte-identically); when config resolves the engine
 * owns the sell side — including over a legacy saved customer_pricing
 * snapshot (parity with the F-23a/F-23b channel+vinyl wires).
 */
export function cncEngineEconomics(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  const res = resolveCncEngineSell(record, { baselineSell, internalCost, pricingContext, now });
  return res && res.applied === true
    ? { internalCost, customerPrice: res.customer_price, resolution: res }
    : null;
}

/**
 * Convenience — the customer-facing sell price for a CNC source record.
 * Returns the engine total when config resolves, else `baselineSell` verbatim
 * (=== passthrough; the byte-identical zero-regression path).
 */
export function cncEngineCustomerPrice(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  const res = resolveCncEngineSell(record, { baselineSell, internalCost, pricingContext, now });
  return res && res.applied === true ? res.customer_price : baselineSell;
}

/**
 * Detection only — does any CNC line on this record carry pricing-engine
 * config? Useful for badges/tests without running the full resolution.
 */
export function cncHasEnginePricing(record) {
  try {
    return cncConfigScan(record).configured === true;
  } catch {
    return false;
  }
}

