import { base44 } from "@/api/base44Client";
import { applyMarkups, parseVolumeDiscountBrackets, parseVolumeDiscountCategories } from "./markupEngine";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;

function resolveTierNumber({ project, customer, requestedTierNumber, tiers }) {
  const candidates = [
    requestedTierNumber,
    project?.customer_pricing?.tier_number,
    project?.customer_pricing_tier,
    customer?.pricing_tier,
    1,
  ];
  for (const candidate of candidates) {
    const tierNumber = num(candidate, NaN);
    if (Number.isFinite(tierNumber) && (tiers || []).some((tier) => num(tier.tier_number) === tierNumber)) {
      return tierNumber;
    }
  }
  return num(tiers?.[0]?.tier_number, 1);
}

const isNotFoundError = (error) => Number(error?.response?.status || error?.status || error?.statusCode || 0) === 404;

export async function loadCustomerPricingConfig(project = {}) {
  try {
    const [tiers, categories, settings, customer] = await Promise.all([
      // Tier definitions and pricing Settings directly change customer selling
      // price, so a read failure must never masquerade as "not configured".
      loadAllEntityRows({ entity: base44.entities.MarkupTier, sort: "sort_order", label: "Customer pricing markup tiers" }),
      // Category records only provide display labels; pricing lines already carry
      // their category keys, so this metadata may remain non-blocking.
      loadAllEntityRows({ entity: base44.entities.MarkupCategory, sort: "sort_order", label: "Customer pricing markup categories" }).catch(() => []),
      loadAllEntityRows({ entity: base44.entities.Settings, query: { category: "pricing" }, sort: null, label: "Customer pricing settings" }),
      project?.customer_id
        ? base44.entities.Customer.get(project.customer_id).catch((error) => {
            // Preserve legacy projects whose historical Customer record no longer
            // exists, but fail closed on permission/network/service read errors.
            if (isNotFoundError(error)) return null;
            throw error;
          })
        : Promise.resolve(null),
    ]);

    const defaultTierNumber = resolveTierNumber({ project, customer, tiers });
    return { tiers: tiers || [], categories: categories || [], settings: settings || [], customer, defaultTierNumber };
  } catch (error) {
    throw new Error(`Customer pricing configuration could not be verified: ${error?.message || "unknown read error"}`);
  }
}

export function calculateCustomerPricingFromConfig({ project, categorize, tierNumber, tiers = [], settings = [], customer = null, categories = [] }) {
  if (!project || typeof categorize !== "function" || !tiers.length) return null;
  const resolvedTierNumber = resolveTierNumber({ project, customer, requestedTierNumber: tierNumber, tiers });
  const selectedTier = tiers.find((tier) => num(tier.tier_number) === resolvedTierNumber) || tiers[0];
  const lines = categorize(project) || [];
  if (!selectedTier || !lines.length) return null;

  const categoryFlags = Object.fromEntries(
    (categories || []).map((c) => [c?.category_key, c?.volume_discount_eligible]).filter(([k]) => k),
  );
  const result = applyMarkups(lines, selectedTier, {
    brackets: parseVolumeDiscountBrackets(settings),
    eligibleCategoryKeys: parseVolumeDiscountCategories(settings),
    categoryFlags,
  });

  return {
    applied: true,
    tier_number: num(selectedTier.tier_number, resolvedTierNumber),
    tier_name: selectedTier.tier_name || `Tier ${resolvedTierNumber}`,
    tier_updated_date: String(selectedTier?.updated_date || ""),
    customer_default_tier: num(customer?.pricing_tier, 1),
    raw_subtotal: num(result?.totals?.raw_subtotal),
    marked_subtotal: num(result?.totals?.marked_subtotal),
    eligible_subtotal: num(result?.totals?.eligible_subtotal),
    volume_discount_pct: num(result?.totals?.volume_discount_pct),
    total: num(result?.totals?.grand_total),
    saved_at: new Date().toISOString(),
    lines: (result?.lines || []).map((line) => ({
      module: line.module || "",
      label: line.label || "",
      category_key: line.category_key || "",
      cost: num(line.cost),
      markup_multiplier: num(line.markup_multiplier, 1),
      marked_up_cost: num(line.marked_up_cost),
      volume_discount_applied: num(line.volume_discount_applied),
      final_cost: num(line.final_cost),
    })),
  };
}

export async function calculateSavedCustomerPricing({ project, categorize, tierNumber }) {
  const config = await loadCustomerPricingConfig(project);
  return calculateCustomerPricingFromConfig({
    project,
    categorize,
    tierNumber,
    tiers: config.tiers,
    settings: config.settings,
    customer: config.customer,
    categories: config.categories,
  });
}

// Brick & Stone module pricing-engine wire (ESTIMATOR_MASTERPLAN F-23c) —
// pure TS, ZERO imports, NO IO. Bundles clean for Deno base44 functions and
// the Vite frontend (frontend-shared-modules allowlist).
//
// What this does: the brick module's COST math (estimator/brick/brickCalc.js
// calcBrickStoneProject — material_cost + mortar_cost + labor_cost -> subtotal
// -> markup_amount -> total_cost) stays authoritative. This wire only
// re-prices the SELL side of brick projects that carry an engine context
// block or component-scoped pricing config. The engine is INJECTED by the
// caller ({ pricePart, resolveTemplatePrice, templatePartDescriptor } from
// base44/shared/pricingEngine.ts + pricingTemplateModel.ts) so this file
// stays import-free per shared-model convention.
//
// ---------------------------------------------------------------------------
// ZERO-REGRESSION CONTRACT
// ---------------------------------------------------------------------------
// A BrickStoneProject record carrying no engine-vocab config resolves
// { applied:false, passthrough:true, customer_price === baselineSell } — the
// caller returns the module's own sell price VERBATIM (byte-identical, no
// float ops, at the customerPricing.sourceProjectEconomics seam). The record's
// own cost/rate/geometry fields (material_cost, mortar_cost, labor_cost,
// subtotal, markup_amount, markup_percent, mortar_bag_cost, bricks_per_hour,
// labor_rate_per_hour, waste_factor, mortar_gap, calculated_*, derived dims)
// are COST-side inputs — they are never scanned for engine config (reading
// them would mark every saved record "configured": markup_percent is the
// percent that produced markup_amount, so it only feeds the engine as the
// DEFAULT markup, exactly like the vinyl wire). A legacy saved
// customer_pricing Markup-Tier snapshot alone never engages — it only feeds
// the context block as the weakest customer-tier hint.
//
// ---------------------------------------------------------------------------
// Entity contract — BrickStoneProject.jsonc (module key 'brick_stone')
// ---------------------------------------------------------------------------
//   material_cost, mortar_cost, labor_cost, labor_hours,
//   mortar_bags_needed, calculated_bricks, calculated_surface_area,
//   subtotal, markup_amount, markup_percent, total_cost,
//   customer_pricing {applied, tier_number, tier_name, total, lines[] — the
//   saved Markup-Tier snapshot; never carries engine_context/pricing_engine}
//
//   Sum invariant: material_cost + mortar_cost + labor_cost == subtotal
//   (brickCalc.js) == the internalCost basis sourceProjectEconomics computes.
//
// Cost-line projection (brickCostLines) — granular mirror of
// categorizeBrickStoneProject (projectCategorizer.jsx): the categorizer rolls
// material_cost + mortar_cost into one 'outsourced_fab' materials line and
// labor_cost into 'outsourced_services'; the wire keeps per-component
// granularity so component-scoped config prices on its own:
//   'material'  cost=material_cost  qty=calculated_bricks   cat outsourced_fab
//   'mortar'    cost=mortar_cost    qty=mortar_bags_needed  cat outsourced_fab
//   'labor'     cost=labor_cost     qty=labor_hours         cat outsourced_services
// A component produces a line only when its cost field is FINITE (a present
// zero is a real line; absent/non-numeric drops the slot — a brand-new record
// with no computed costs yields no lines). qty honors an explicit 0
// (extension 0 — engine minimums never fire on extension <= 0, same as the
// vinyl wire); absent/non-finite qty fields fall back to 1, which keeps
// markup math identical because unitCost*qty == cost either way.
//
// ---------------------------------------------------------------------------
// Activation contract — what counts as engine config on a brick record
// ---------------------------------------------------------------------------
// 1. CONTEXT BLOCK (project-wide engagement — channel-wire parity):
//    record.pricing_engine | engine_pricing | pricing_tier_config |
//    pricing_context | engine_context, or
//    customer_pricing.engine_context | customer_pricing.pricing_engine.
//    Present-as-object => EVERY component line runs through the engine;
//    component descriptors override where present and unconfigured lines
//    price via the context chart / defaultMarkupPct (which defaults to
//    record.markup_percent — the same percent that produced the baseline
//    tail, so an unconfigured line lands back on its own baseline).
// 2. COMPONENT-SCOPED LINE CONFIG (no context block): only the configured
//    component reprices; every other component keeps its exact baseline
//    contribution. Descriptor merge per line key K in {material,mortar,labor}
//    (weakest -> strongest):
//      a. flat prefixed record fields   `${K}_<engineField>`
//         (labor_markup_pct, material_fixed_price, mortar_tier_ref,
//          material_market_retail, labor_pricing_template_id, ...)
//      b. an inline descriptor carried on an explicit input.lines[] row
//      c. context-block line map        block.items|lines|line_config|
//                                       item_config[K] (numeric index ok)
//      d. nested component blocks       ${K}_pricing | ${K}_price_config |
//                                       ${K}_engine_pricing |
//                                       ${K}_pricing_config |
//                                       ${K}_engine_price |
//                                       ${K}_tier_config | ${K}_sell_pricing
//    A top-level record.pricing|part|... descriptor is deliberately NOT
//    scanned — a flat aggregate record has no unambiguous line owner for a
//    pinned unit price, and scanning raw record fields would trip on legacy
//    cost fields.
//
// Engine vocabulary inside a descriptor (else it is NOT config -> the line
// passes through at baseline):
//   fixed_price|price_override|override_price|flat_price   >0 pinned unit sell
//   tier_ref|tier_ref_id|pricing_tier_ref|bound_tier|tier|tier_name
//   per_unit_breaks|unit_breaks|qty_breaks                 qty chart
//   pricing_template_id|template_id|margin_template_id|
//     pricing_template_name|template_name|pricing_template|template
//   global_pricing_tier_id|pricing_tier_id|tier_set_id|pricing_tier_set_id|
//     pricing_rule_set_id|global_tier_id|global_pricing_tier_name|
//     pricing_tier_name|tier_set_name                      tier-set refs
//   market_retail|retail|retail_price|list_price           >0 market retail
//   market_discount_pct|retail_discount_pct
//   markup_pct|markup|markup_percent                       any finite (0 sells at cost)
//   minimum_charge|min_charge|minimum|setup_fee_floor      extension floor
//   setup_fee|setupFee|setup_fee_flat                      flat sell fee
//   formula_modifiers|modifiers                            ordered unit-price ops
//   pricing_mode|price_mode|mode|active_mode               RECOGNIZED tokens
//     only ('market','market_based','market-based','retail',
//     'retail_minus_discount','fixed','fixed_price','flat','cost_plus',
//     'cost-plus','costplus','markup','tier','tier_markup','tiered') —
//     brick unit enums like 'per_brick'/'per_bag'/'per_hour' are NOT config
//   machine|machine_override|machine_pricing|equipment_pricing
//     (counts only when the descriptor itself carries engine fields)
//   customer_tier|customerTier                             line-scoped tier pin
//   tier_rules|tierRules|rules|matrix|matrix_rows|rows|pricing_matrix
//   templates|pricing_templates | tiers|tier_catalog|markup_tiers
//                                                          embedded registries
//   interpolate_breaks|interpolateBreaks|interpolate|
//     break_interpolation                                  qty-chart interpolation
//
// Caller-supplied `context` registries (tierRules, templates, tiers,
// customerTier, defaultMarkupPct, now) merge OVER the record-embedded block
// but never constitute engagement by themselves — engagement requires a
// record-carried context block or component-scoped config.
//
// Composition (vinyl remainder model — the module markup is linear over the
// aggregate subtotal, so each priced line's baseline contribution is exactly
// lineCost * (1 + markupPct/100)):
//   remainder      = baselineSell - Σ pricedLineCost * (1 + markupPct/100)
//   customer_price = round2(remainder + Σ pricedLine.subtotal)
// When a context block prices every line the remainder lands at ~0 and the
// engine owns the whole sell tail — including winning over a legacy saved
// customer_pricing snapshot (recorded in chain).
//
// The whole pipeline never throws; every step is echoed in `chain` and
// `warnings` for transparency. Configured lines without a finite cost base
// (possible only via an explicit input.lines[] override — brickCostLines only
// emits finite-cost components) are SKIPPED at baseline, never repriced blind.
//
// ---------------------------------------------------------------------------

const isRecord = (v: unknown): v is Record<string, unknown> =>
  v !== null && typeof v === 'object' && !Array.isArray(v);

const asString = (v: unknown): string => (v === null || v === undefined ? '' : String(v)).trim();

const lc = (v: unknown): string => asString(v).toLowerCase();

const toFiniteNumber = (v: unknown): number | null => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const num = (v: unknown, fallback = 0): number => toFiniteNumber(v) ?? fallback;

const firstField = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown => {
  if (!rec) return undefined;
  for (const f of fields) {
    const v = rec[f];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
};

const firstFinite = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): number | null => {
  const v = firstField(rec, fields);
  const n = toFiniteNumber(v);
  return n === null ? null : n;
};

const firstArray = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): unknown[] | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (Array.isArray(rec[f])) return rec[f] as unknown[];
  }
  return null;
};

const firstRecord = (rec: Record<string, unknown> | null | undefined, fields: readonly string[]): Record<string, unknown> | null => {
  if (!rec) return null;
  for (const f of fields) {
    if (isRecord(rec[f])) return rec[f] as Record<string, unknown>;
  }
  return null;
};

const round2 = (n: unknown): number => Math.round((num(n) + Number.EPSILON) * 100) / 100;

// ---------------------------------------------------------------------------
// field vocabularies
// ---------------------------------------------------------------------------

/** Module keys the brick record answers to (moduleRegistry key first). */
export const BRICK_MODULE_KEYS = Object.freeze([
  'brick_stone', 'brick', 'brickstone', 'brick_stone_project', 'masonry',
] as const);

/**
 * The three module-authored cost components (brickCalc.js aggregation;
 * category keys mirror categorizeBrickStoneProject).
 */
const BRICK_COMPONENTS = [
  {
    key: 'material',
    label: 'Brick / Stone Material',
    costFields: ['material_cost', 'materials_cost'],
    qtyFields: ['calculated_bricks', 'brick_count'],
    category_key: 'outsourced_fab',
  },
  {
    key: 'mortar',
    label: 'Mortar',
    costFields: ['mortar_cost'],
    qtyFields: ['mortar_bags_needed', 'mortar_bags'],
    category_key: 'outsourced_fab',
  },
  {
    key: 'labor',
    label: 'Masonry Labor',
    costFields: ['labor_cost'],
    qtyFields: ['labor_hours'],
    category_key: 'outsourced_services',
  },
] as const;

export const BRICK_COMPONENT_KEYS: readonly string[] = Object.freeze(
  BRICK_COMPONENTS.map((c) => c.key),
);

/** Record-level fields probed for the engine context block (in order). */
const CONTEXT_BLOCK_FIELDS = [
  'pricing_engine', 'engine_pricing', 'pricing_tier_config', 'pricing_context', 'engine_context',
] as const;

/** customer_pricing sub-fields also probed (saved tier snapshot block). */
const NESTED_CONTEXT_FIELDS = ['engine_context', 'pricing_engine'] as const;

/** Map inside the context block keyed by component key -> part descriptor. */
const ENGINE_LINE_MAP_FIELDS = ['items', 'lines', 'line_config', 'item_config'] as const;

/** Per-component nested descriptor spellings: `${key}_<suffix>`. */
const COMPONENT_BLOCK_SUFFIXES = [
  'pricing', 'price_config', 'engine_pricing', 'pricing_config',
  'engine_price', 'tier_config', 'sell_pricing',
] as const;

/** Recognized pricing-mode tokens (channel-wire superset — unit enums excluded). */
const ENGINE_MODE_TOKENS = new Set([
  'market', 'market_based', 'market-based', 'retail', 'retail_minus_discount',
  'fixed', 'fixed_price', 'flat',
  'cost_plus', 'cost-plus', 'costplus', 'markup', 'tier', 'tier_markup', 'tiered',
]);

const FIXED_FIELDS = ['fixed_price', 'price_override', 'override_price', 'flat_price'] as const;
const TIER_REF_FIELDS = ['tier_ref', 'tier_ref_id', 'pricing_tier_ref', 'bound_tier', 'tier', 'tier_name'] as const;
const BREAK_FIELDS = ['per_unit_breaks', 'unit_breaks', 'qty_breaks'] as const;
const TEMPLATE_REF_FIELDS = [
  'pricing_template_id', 'template_id', 'margin_template_id',
  'pricing_template_name', 'template_name', 'pricing_template', 'template',
] as const;
const TIER_SET_FIELDS = [
  'global_pricing_tier_id', 'pricing_tier_id', 'tier_set_id', 'pricing_tier_set_id',
  'pricing_rule_set_id', 'global_tier_id', 'global_pricing_tier_name',
  'pricing_tier_name', 'tier_set_name',
] as const;
const MARKET_FIELDS = ['market_retail', 'retail', 'retail_price', 'list_price'] as const;
const MARKET_DISCOUNT_FIELDS = ['market_discount_pct', 'retail_discount_pct'] as const;
const MARKUP_FIELDS = ['markup_pct', 'markup', 'markup_percent'] as const;
const MIN_FIELDS = ['minimum_charge', 'min_charge', 'minimum', 'setup_fee_floor'] as const;
const SETUP_FIELDS = ['setup_fee', 'setupFee', 'setup_fee_flat'] as const;
const FORMULA_FIELDS = ['formula_modifiers', 'modifiers'] as const;
const MODE_FIELDS = ['pricing_mode', 'price_mode', 'mode', 'active_mode'] as const;
const MACHINE_FIELDS = ['machine', 'machine_override', 'machine_pricing', 'equipment_pricing'] as const;
const TIER_CONTEXT_FIELDS = ['customer_tier', 'customerTier'] as const;
const EMBEDDED_RULE_FIELDS = ['tier_rules', 'tierRules', 'tier_matrix', 'rules', 'matrix', 'matrix_rows', 'rows', 'pricing_matrix'] as const;
const EMBEDDED_TEMPLATE_FIELDS = ['templates', 'pricing_templates'] as const;
const EMBEDDED_TIER_CATALOG_FIELDS = ['tiers', 'tier_catalog', 'markup_tiers'] as const;
const UNIT_FIELDS = ['unit', 'pricing_unit', 'pricingUnit', 'uom', 'unit_of_measure', 'unit_category'] as const;
const TAX_PCT_FIELDS = ['tax_percent', 'taxPercent'] as const;
const INTERPOLATE_FIELDS = ['interpolate_breaks', 'interpolateBreaks', 'interpolate', 'break_interpolation'] as const;
const DEFAULT_MARKUP_FIELDS = ['default_markup_pct', 'defaultMarkupPct', 'default_markup'] as const;

/**
 * Flat per-component engine spellings — on the record these ride the
 * `<component>_<field>` prefix; inside a nested/inline descriptor they are
 * the bare field names. Presence alone does not mark a line configured —
 * see descriptorHasPricingContent.
 */
export const BRICK_ENGINE_LINE_FIELDS: readonly string[] = Object.freeze([
  ...FIXED_FIELDS,
  ...TIER_REF_FIELDS,
  ...BREAK_FIELDS,
  ...TEMPLATE_REF_FIELDS,
  ...TIER_SET_FIELDS,
  ...MARKET_FIELDS,
  ...MARKET_DISCOUNT_FIELDS,
  ...MARKUP_FIELDS,
  ...MIN_FIELDS,
  ...SETUP_FIELDS,
  ...FORMULA_FIELDS,
  ...MODE_FIELDS,
  ...MACHINE_FIELDS,
  ...TIER_CONTEXT_FIELDS,
  ...EMBEDDED_RULE_FIELDS,
  ...EMBEDDED_TEMPLATE_FIELDS,
  ...EMBEDDED_TIER_CATALOG_FIELDS,
  ...UNIT_FIELDS,
  ...TAX_PCT_FIELDS,
  ...INTERPOLATE_FIELDS,
  'taxable',
]);

// ---------------------------------------------------------------------------
// config detection
// ---------------------------------------------------------------------------

const isEngineModeToken = (v: unknown): boolean => ENGINE_MODE_TOKENS.has(lc(v));

const nonEmptyArrayField = (rec: Record<string, unknown>, fields: readonly string[]): boolean =>
  fields.some((f) => Array.isArray(rec[f]) && (rec[f] as unknown[]).length > 0);

/** Machine descriptors count only when they carry override content themselves. */
const machineHasConfig = (v: unknown): boolean => {
  if (!isRecord(v)) return false;
  const fixed = firstFinite(v, FIXED_FIELDS);
  const retail = firstFinite(v, MARKET_FIELDS);
  const markup = firstFinite(v, MARKUP_FIELDS);
  return (fixed !== null && fixed > 0)
    || (retail !== null && retail > 0)
    || (markup !== null)
    || firstFinite(v, MIN_FIELDS) !== null
    || nonEmptyArrayField(v, [...BREAK_FIELDS, ...FORMULA_FIELDS])
    || MODE_FIELDS.some((f) => isEngineModeToken(v[f]))
    || TIER_REF_FIELDS.some((f) => asString(v[f]) !== '');
};

/**
 * Does this resolved descriptor actually carry pricing content the engine can
 * act on? Channel-wire thresholds: fixed_price must be POSITIVE, markup must
 * be FINITE (an explicit markup_pct:0 IS config — it pins the component at
 * cost, engine parity with vinyl/cnc), market retail must be
 * positive, chart/registry fields must be non-empty, mode tokens must be
 * recognized engine spellings. An empty pricing block, a unit-enum
 * pricing_mode ('per_brick'), or a bare machine name must NOT flip the
 * component out of baseline pricing.
 */
export function descriptorHasPricingContent(d: unknown): boolean {
  if (!isRecord(d)) return false;
  const fixed = firstFinite(d, FIXED_FIELDS);
  if (fixed !== null && fixed > 0) return true;
  if (TIER_REF_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (nonEmptyArrayField(d, BREAK_FIELDS)) return true;
  const retail = firstFinite(d, MARKET_FIELDS);
  if (retail !== null && retail > 0) return true;
  const discount = firstFinite(d, MARKET_DISCOUNT_FIELDS);
  if (discount !== null && discount !== 0) return true;
  if (MODE_FIELDS.some((f) => isEngineModeToken(d[f]))) return true;
  // Any finite markup is authored config — an explicit markup_pct:0 pins the
  // component at cost (0% markup), not "no config" (F-23 markup-0 signal).
  const markup = firstFinite(d, MARKUP_FIELDS);
  if (markup !== null) return true;
  if (nonEmptyArrayField(d, FORMULA_FIELDS)) return true;
  if (firstFinite(d, MIN_FIELDS) !== null) return true;
  if (firstFinite(d, SETUP_FIELDS) !== null) return true;
  if (TEMPLATE_REF_FIELDS.some((f) => {
    const v = d[f];
    return isRecord(v) ? true : asString(v) !== '';
  })) return true;
  if (TIER_SET_FIELDS.some((f) => asString(d[f]) !== '')) return true;
  if (nonEmptyArrayField(d, [...EMBEDDED_RULE_FIELDS, ...EMBEDDED_TEMPLATE_FIELDS, ...EMBEDDED_TIER_CATALOG_FIELDS])) return true;
  if (TIER_CONTEXT_FIELDS.some((f) => asString(firstField(d, [f])) !== '')) return true;
  if (MACHINE_FIELDS.some((f) => machineHasConfig(d[f]))) return true;
  return false;
}

// ---------------------------------------------------------------------------
// brick record -> normalized component lines
// ---------------------------------------------------------------------------

export interface BrickWireLine {
  /** Canonical component key — 'material' | 'mortar' | 'labor'. */
  key: string;
  index: number;
  label: string;
  qty: number;
  /** Module-authored component cost. null = unknown cost base. */
  cost: number | null;
  category_key: string;
  /** The component's raw record carrier (the project record itself). */
  item: Record<string, unknown> | null;
  /** Inline descriptor carried on an explicit input.lines[] override row. */
  descriptor?: Record<string, unknown> | null;
  /** 'components' = projected record fields; 'caller' = input.lines[]. */
  origin: 'components' | 'caller';
}

const componentOf = (key: unknown) =>
  BRICK_COMPONENTS.find((c) => c.key === lc(key)) ?? null;

/**
 * Project a BrickStoneProject-like record into granular component cost lines.
 * Component slots emit in canonical order (material, mortar, labor); a slot
 * produces a line only when its cost field is finite. Sum of line costs ==
 * the record's internalCost basis (material + mortar + labor == subtotal).
 */
export function brickCostLines(record: unknown): BrickWireLine[] {
  if (!isRecord(record)) return [];
  const lines: BrickWireLine[] = [];
  BRICK_COMPONENTS.forEach((comp) => {
    const cost = firstFinite(record, comp.costFields);
    if (cost === null) return;
    const qty = firstFinite(record, comp.qtyFields) ?? 1;
    lines.push({
      key: comp.key,
      index: lines.length,
      label: comp.label,
      qty,
      cost,
      category_key: comp.category_key,
      item: record,
      origin: 'components',
    });
  });
  return lines;
}

// ---------------------------------------------------------------------------
// project context carrier + per-component descriptor
// ---------------------------------------------------------------------------

const contextBlockOf = (record: unknown): { block: Record<string, unknown> | null; field: string } => {
  const rec = isRecord(record) ? record : {};
  for (const f of CONTEXT_BLOCK_FIELDS) {
    if (isRecord(rec[f])) return { block: rec[f] as Record<string, unknown>, field: f };
  }
  const cp = isRecord(rec.customer_pricing) ? rec.customer_pricing : null;
  if (cp) {
    for (const f of NESTED_CONTEXT_FIELDS) {
      if (isRecord(cp[f])) return { block: cp[f] as Record<string, unknown>, field: `customer_pricing.${f}` };
    }
  }
  return { block: null, field: '' };
};

export interface BrickPricingContext {
  /** Marker so callers can pass the normalized context back without a rescan. */
  __brickPricingContext?: true;
  /** True when the RECORD carries an engine context block (engagement gate —
   * caller-supplied registries alone never engage). */
  hasContextBlock: boolean;
  /** Which record field supplied the block ('' when none). */
  field: string;
  customerTier: unknown;
  tierRules: unknown[];
  templates: unknown[];
  tiers: unknown[];
  /** Shop fallback markup pct — defaults to record.markup_percent. */
  defaultMarkupPct: number;
  /** Context-level machine descriptor. */
  machine: unknown;
  /** Context-level floors/fees/tax applied to every engine-priced line. */
  taxable: boolean | undefined;
  taxPercent: number;
  setupFee: number;
  minimumCharge: number;
  modifiers: unknown[] | undefined;
  /** Line map inside the context block ({<component key>: descriptor}). */
  lineMap: Record<string, unknown> | null;
  now: unknown;
  /** The raw context block (audit echo). */
  raw: unknown;
}

/**
 * Merge the engine context: caller-supplied `context` (registries pre-loaded
 * by the seam's caller) > the record's pricing_engine-style block > the saved
 * Markup-Tier snapshot tier_number > record.markup_percent as the default
 * markup. `hasContextBlock` records whether the record itself carries a block
 * — that (or component-scoped config) is what engages the wire.
 */
export function brickPricingContextOf(record: unknown, callerContext: unknown = null): BrickPricingContext {
  const rec = isRecord(record) ? record : {};
  const caller = isRecord(callerContext) ? callerContext : {};
  if ((callerContext as BrickPricingContext)?.__brickPricingContext === true) {
    return callerContext as BrickPricingContext;
  }

  const { block, field } = contextBlockOf(rec);
  const blk = block ?? {};
  const cp = isRecord(rec.customer_pricing) ? rec.customer_pricing : {};

  const customerTier = firstField(caller, ['customerTier', 'customer_tier', 'tier'])
    ?? firstField(blk, [...TIER_CONTEXT_FIELDS, 'tier'])
    ?? firstField(cp, ['tier_number', 'tier', 'tier_name'])
    ?? null;

  const tierRules = firstArray(caller, EMBEDDED_RULE_FIELDS)
    ?? firstArray(blk, EMBEDDED_RULE_FIELDS)
    ?? [];
  const templates = firstArray(caller, EMBEDDED_TEMPLATE_FIELDS)
    ?? firstArray(blk, EMBEDDED_TEMPLATE_FIELDS)
    ?? [];
  const tiers = firstArray(caller, EMBEDDED_TIER_CATALOG_FIELDS)
    ?? firstArray(blk, EMBEDDED_TIER_CATALOG_FIELDS)
    ?? [];

  const defaultMarkupPct = firstFinite(caller, DEFAULT_MARKUP_FIELDS.concat('markup_pct' as const))
    ?? firstFinite(blk, DEFAULT_MARKUP_FIELDS.concat(MARKUP_FIELDS))
    ?? firstFinite(rec, ['markup_percent'])
    ?? 0;

  const taxable = typeof caller.taxable === 'boolean' ? caller.taxable
    : typeof blk.taxable === 'boolean' ? blk.taxable
    : lc(blk.taxable) === 'true' ? true
    : lc(blk.taxable) === 'false' ? false
    : undefined;

  const callerModifiers = firstArray(caller, FORMULA_FIELDS);
  const blockModifiers = firstArray(blk, FORMULA_FIELDS);

  return {
    __brickPricingContext: true,
    hasContextBlock: block !== null,
    field,
    customerTier,
    tierRules,
    templates,
    tiers,
    defaultMarkupPct: num(defaultMarkupPct),
    machine: firstField(blk, MACHINE_FIELDS) ?? firstField(caller, MACHINE_FIELDS) ?? null,
    taxable,
    taxPercent: num(firstFinite(caller, TAX_PCT_FIELDS) ?? firstFinite(blk, TAX_PCT_FIELDS)),
    setupFee: num(firstFinite(caller, SETUP_FIELDS) ?? firstFinite(blk, SETUP_FIELDS)),
    minimumCharge: num(firstFinite(caller, MIN_FIELDS) ?? firstFinite(blk, MIN_FIELDS)),
    modifiers: callerModifiers ?? blockModifiers ?? undefined,
    lineMap: firstRecord(blk, ENGINE_LINE_MAP_FIELDS),
    now: caller.now ?? blk.now,
    raw: block,
  };
}

// ---------------------------------------------------------------------------
// per-component descriptor resolution
// ---------------------------------------------------------------------------

const componentNestedBlock = (record: unknown, key: string): Record<string, unknown> | null => {
  const rec = isRecord(record) ? record : {};
  for (const suffix of COMPONENT_BLOCK_SUFFIXES) {
    const f = `${key}_${suffix}`;
    if (isRecord(rec[f])) return rec[f] as Record<string, unknown>;
  }
  return null;
};

/**
 * Copy engine-vocab fields off a source record. When `prefix` is given the
 * source fields are `<prefix>_<field>` (the flat `<component>_<field>`
 * spellings on the project record); otherwise the bare field names (inline /
 * nested descriptors).
 */
const engineFieldsFrom = (src: unknown, prefix = ''): Record<string, unknown> => {
  const out: Record<string, unknown> = {};
  if (!isRecord(src)) return out;
  for (const f of BRICK_ENGINE_LINE_FIELDS) {
    const k = prefix ? `${prefix}_${f}` : f;
    if (src[k] !== undefined && src[k] !== null && src[k] !== '') out[f] = src[k];
  }
  return out;
};

/**
 * Per-component merged part descriptor (weakest -> strongest):
 *   flat `${key}_<field>` record fields  <-  inline descriptor on an
 *   input.lines[] row  <-  context-block items/lines map entry  <-
 *   nested `${key}_pricing`-style component block.
 * Returns null when no config source exists.
 */
export function brickLineDescriptor(line: BrickWireLine | Record<string, unknown>, record: unknown = null): Record<string, unknown> | null {
  const key = lc((line as BrickWireLine)?.key);
  if (!componentOf(key)) return null;

  const rec = isRecord(record) ? record : {};
  const flat = engineFieldsFrom(rec, key);

  // An explicit input.lines[] row may carry its own config inline (bare field
  // spellings) or under .descriptor/.pricing — merged over the flat layer.
  const rawLine = isRecord(line) ? (line as Record<string, unknown>) : {};
  const ownInline = engineFieldsFrom(rawLine);
  const ownNested = firstRecord(rawLine, ['descriptor', 'pricing', 'price_config', 'engine_pricing', 'pricing_config', 'engine_price']);

  const { block } = contextBlockOf(rec);
  const lineMap = block ? firstRecord(block, ENGINE_LINE_MAP_FIELDS) : null;
  const mapEntry = lineMap
    ? (isRecord(lineMap[key]) ? lineMap[key] as Record<string, unknown>
      : isRecord(lineMap[asString((line as BrickWireLine)?.index)]) ? lineMap[asString((line as BrickWireLine)?.index)] as Record<string, unknown>
      : null)
    : null;

  const nested = componentNestedBlock(rec, key);

  const merged = {
    ...flat,
    ...ownInline,
    ...(ownNested ?? {}),
    ...(mapEntry ?? {}),
    ...(nested ?? {}),
  };
  if (!Object.keys(merged).length && !nested && !mapEntry && !ownNested) return null;
  return merged;
}

// ---------------------------------------------------------------------------
// config scan — the gate that makes no-config records byte-identical
// ---------------------------------------------------------------------------

export interface BrickConfigScan {
  configured: boolean;
  configuredCount: number;
  lineCount: number;
  /** per-line detection detail for the chain trace. */
  lines: Array<{ key: string; label: string; configured: boolean; hasCost: boolean }>;
}

/**
 * Detection only — which brick component lines carry pricing config. Cheap
 * and side-effect free; does NOT include context-block engagement (see
 * brickEngineConfigured for the full engagement probe).
 */
export function brickConfigScan(record: unknown, lines?: BrickWireLine[]): BrickConfigScan {
  const wireLines = Array.isArray(lines) ? lines : brickCostLines(record);
  const detail = wireLines.map((line) => {
    const descriptor = brickLineDescriptor(line, record);
    return {
      key: line.key,
      label: line.label,
      configured: descriptorHasPricingContent(descriptor),
      hasCost: line.cost !== null && Number.isFinite(line.cost),
    };
  });
  const configuredCount = detail.filter((d) => d.configured).length;
  return {
    configured: configuredCount > 0,
    configuredCount,
    lineCount: wireLines.length,
    lines: detail,
  };
}

/**
 * Full engagement probe: does this record carry engine config? — a
 * record-carried context block OR at least one configured component line.
 * (admin UI badge helper / tests).
 */
export function brickEngineConfigured(record: unknown, lines?: BrickWireLine[]): boolean {
  if (contextBlockOf(record).block) return true;
  return brickConfigScan(record, lines).configured;
}

// ---------------------------------------------------------------------------
// resolveBrickSellPricing
// ---------------------------------------------------------------------------

export interface BrickWireEngine {
  /** pricingEngine.pricePart — required; without it the wire passthroughs. */
  pricePart?: (input: any) => any;
  /** pricingTemplateModel.resolveTemplatePrice — optional template layer. */
  resolveTemplatePrice?: (input: any) => any;
  /** pricingTemplateModel.templatePartDescriptor — encodes a template hit. */
  templatePartDescriptor?: (part: any, resolution: any) => any;
}

export interface BrickSellLineResult {
  key: string;
  label: string;
  index: number;
  qty: number;
  cost: number;
  unit_cost: number;
  /** This line's baseline sell contribution (cost x (1+markupPct/100)). */
  baseline_sell: number;
  /** True when the line's own descriptor carries engine config. */
  configured: boolean;
  /** True when the engine priced the line (context engagement counts). */
  priced: boolean;
  /** 'context' = repriced by block engagement without own config. */
  priced_via: 'descriptor' | 'context' | null;
  skipped: string | null;
  engine: {
    unit_price: number;
    extended: number;
    setup_fee: number;
    subtotal: number;
    total: number;
    price_source: string;
    tier_source: string;
    minimum_applied: boolean;
    dangling_tier_ref: string | null;
    template_applied: boolean;
    template_reason: string | null;
    trace: unknown[];
  } | null;
}

export interface BrickSellPricingResult {
  applied: boolean;
  passthrough: boolean;
  reason:
    | 'no_record'
    | 'no_lines'
    | 'no_config'
    | 'no_engine'
    | 'no_priced_lines'
    | 'priced';
  /** Engine sell total when applied; baselineSell verbatim when passthrough. */
  customer_price: number;
  baseline_sell: number;
  internal_cost: number;
  markup_pct: number;
  /** True when a record-carried context block engaged the whole sell tail. */
  context_engaged: boolean;
  /** Baseline sell of engine-priced lines (removed from the aggregate). */
  configured_baseline: number;
  /** Baseline dollars that stayed module-priced (everything not repriced). */
  remainder_sell: number;
  /** Sum of engine line subtotals (extensions + setup fees, pre-tax). */
  engine_priced_total: number;
  lines: BrickSellLineResult[];
  chain: Array<{ layer: string; hit: boolean; won: boolean; detail: string }>;
  warnings: string[];
  context_used: {
    context_block: string;
    customer_tier: string;
    tier_rule_count: number;
    template_count: number;
    tier_count: number;
    default_markup_pct: number;
  };
}

const passthroughResult = (
  reason: BrickSellPricingResult['reason'],
  baselineSell: number,
  internalCost: number,
  markupPct: number,
  contextEngaged: boolean,
  lines: BrickSellLineResult[],
  chain: BrickSellPricingResult['chain'],
  warnings: string[],
  contextUsed: BrickSellPricingResult['context_used'],
): BrickSellPricingResult => ({
  applied: false,
  passthrough: true,
  reason,
  customer_price: baselineSell,
  baseline_sell: baselineSell,
  internal_cost: internalCost,
  markup_pct: markupPct,
  context_engaged: contextEngaged,
  configured_baseline: 0,
  remainder_sell: baselineSell,
  engine_priced_total: 0,
  lines,
  chain,
  warnings,
  context_used: contextUsed,
});

/**
 * Resolve the brick project sell price through the injected pricing engine.
 *
 * input.record          BrickStoneProject-like record
 * input.lines           optional explicit BrickWireLine[] override
 * input.baselineSell    the module's sell price today (record.total_cost /
 *                       sourceProjectEconomics customerPrice) — returned
 *                       verbatim on every passthrough path
 * input.internalCost    module internal cost (record.subtotal), echoed only
 * input.markupPercent   baseline sell factor; default record.markup_percent,
 *                       else markup_amount/subtotal
 * input.context         brickPricingContextOf-compatible registries (merged
 *                       over the record-embedded engine block)
 * input.engine          injected { pricePart, resolveTemplatePrice,
 *                       templatePartDescriptor }
 * input.now             effective-window override (tests)
 */
export function resolveBrickSellPricing(input: any = {}): BrickSellPricingResult {
  const warnings: string[] = [];
  const chain: BrickSellPricingResult['chain'] = [];
  const record = isRecord(input.record) ? input.record : null;
  const baselineSell = num(input.baselineSell ?? input.baseline_sell);
  const internalCost = num(input.internalCost ?? input.internal_cost);

  const rec = record ?? {};
  const subtotalBase = firstFinite(rec, ['subtotal']);
  const markupPct = firstFinite(input, ['markupPercent', 'markup_percent'])
    ?? firstFinite(rec, ['markup_percent'])
    ?? (subtotalBase && subtotalBase > 0 ? (num(rec.markup_amount) / subtotalBase) * 100 : 0);

  const context = brickPricingContextOf(rec, input.context);
  const contextUsed = {
    context_block: context.field || '',
    customer_tier: asString(
      isRecord(context.customerTier)
        ? (context.customerTier as any).tier_name ?? (context.customerTier as any).tier_number ?? (context.customerTier as any).id
        : context.customerTier,
    ),
    tier_rule_count: context.tierRules.length,
    template_count: context.templates.length,
    tier_count: context.tiers.length,
    default_markup_pct: num(context.defaultMarkupPct),
  };

  const engine: BrickWireEngine = isRecord(input.engine) ? input.engine : {};
  const pricePart = typeof engine.pricePart === 'function' ? engine.pricePart : null;

  // --- line normalization -----------------------------------------------------
  const wireLines: BrickWireLine[] = Array.isArray(input.lines) && input.lines.length
    ? input.lines.map((l: any, position: number) => ({
        key: asString(l?.key) || `line-${position}`,
        index: position,
        label: asString(l?.label) || componentOf(l?.key)?.label || `Component ${position + 1}`,
        qty: l?.qty !== undefined ? num(l.qty, 1) : (componentOf(l?.key) ? (firstFinite(rec, componentOf(l?.key)!.qtyFields) ?? 1) : 1),
        cost: l?.cost !== undefined ? toFiniteNumber(l.cost) : (componentOf(l?.key) ? firstFinite(rec, componentOf(l?.key)!.costFields) : toFiniteNumber(l?.item_total_cost ?? l?.line_total_cost ?? l?.total_cost ?? l?.cost)),
        category_key: asString(l?.category_key) || componentOf(l?.key)?.category_key || '',
        item: isRecord(l?.item) ? l.item : rec,
        descriptor: isRecord(l) ? l : null,
        origin: 'caller' as const,
      }))
    : brickCostLines(rec);

  const scan = brickConfigScan(rec, wireLines);
  const engaged = context.hasContextBlock || scan.configured;
  chain.push({
    layer: 'config_scan',
    hit: engaged,
    won: false,
    detail: context.hasContextBlock
      ? `context block via ${context.field}${scan.configured ? ` + ${scan.configuredCount} configured component(s)` : ''}`
      : scan.configured
        ? `${scan.configuredCount} of ${scan.lineCount} components carry pricing config`
        : `no pricing config on ${scan.lineCount} components`,
  });

  if (!record) return passthroughResult('no_record', baselineSell, internalCost, markupPct, false, [], chain, warnings, contextUsed);
  if (!wireLines.length) return passthroughResult('no_lines', baselineSell, internalCost, markupPct, context.hasContextBlock, [], chain, warnings, contextUsed);
  if (!engaged) return passthroughResult('no_config', baselineSell, internalCost, markupPct, false, [], chain, warnings, contextUsed);
  if (!pricePart) {
    warnings.push('pricing engine not injected — lines left at baseline sell');
    return passthroughResult('no_engine', baselineSell, internalCost, markupPct, context.hasContextBlock, [], chain, warnings, contextUsed);
  }

  // --- per-line engine resolution ----------------------------------------------
  const markupFactor = 1 + markupPct / 100;
  const results: BrickSellLineResult[] = [];
  let configuredCostSum = 0;
  let engineSubtotalSum = 0;
  let pricedCount = 0;
  let skippedCount = 0;

  wireLines.forEach((line, position) => {
    const descriptor = brickLineDescriptor(line, rec);
    const configured = descriptorHasPricingContent(descriptor);
    // Under context-block engagement the engine owns EVERY component line
    // (channel-wire parity); an unconfigured line then prices via the context
    // chart / default markup — landing back on its own baseline contribution.
    const enginePrices = configured || context.hasContextBlock;
    const cost = line.cost !== undefined ? line.cost : null;
    const qty = num(line.qty, 1);
    const base: BrickSellLineResult = {
      key: line.key || `line-${position}`,
      label: line.label || `Component ${position + 1}`,
      index: position,
      qty,
      cost: cost ?? 0,
      unit_cost: cost !== null ? (qty > 0 ? cost / qty : cost) : 0,
      baseline_sell: cost !== null ? cost * markupFactor : 0,
      configured,
      priced: false,
      priced_via: null,
      skipped: null,
      engine: null,
    };
    results.push(base);
    if (!enginePrices) return;

    if (cost === null || !Number.isFinite(cost)) {
      base.skipped = 'skipped_no_cost';
      skippedCount += 1;
      warnings.push(`component '${base.label}' carries pricing config but has no cost base — left at baseline sell`);
      return;
    }

    // Template layer first (pricingTemplateModel): the bound PricingTemplate /
    // tier-set chart resolves the unit price, then the descriptor adapter
    // encodes it for the engine's own part layer. res.applied === false
    // returns the descriptor VERBATIM so remaining part config still prices.
    let partDescriptor: any = { ...(descriptor ?? {}) };
    // Line-scoped formula modifiers ride input.modifiers (run after the winning
    // rule's own modifiers) — remove them from the descriptor so overrideRule
    // can't also fold them into the part rule (that would apply them twice).
    const lineModifiers = firstField(partDescriptor, FORMULA_FIELDS);
    for (const f of FORMULA_FIELDS) delete partDescriptor[f];
    const embeddedTemplates = EMBEDDED_TEMPLATE_FIELDS.reduce(
      (acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []),
      [] as unknown[],
    );
    let templateApplied = false;
    let templateReason: string | null = null;
    if (typeof engine.resolveTemplatePrice === 'function') {
      try {
        const resolution = engine.resolveTemplatePrice({
          part: partDescriptor,
          qty,
          base_price: base.unit_cost,
          templates: [...embeddedTemplates, ...context.templates],
          tiers: context.tiers,
          tier: firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier,
          default_markup_pct: contextUsed.default_markup_pct,
        });
        if (resolution && isRecord(resolution)) {
          templateApplied = resolution.applied === true;
          templateReason = asString(resolution.reason) || null;
          if (Array.isArray(resolution.warnings)) warnings.push(...resolution.warnings.map((w: unknown) => `component '${base.label}': ${asString(w)}`));
          if (typeof engine.templatePartDescriptor === 'function') {
            partDescriptor = engine.templatePartDescriptor(partDescriptor, resolution);
          }
        }
      } catch (e: any) {
        warnings.push(`component '${base.label}': template resolution failed (${asString(e?.message)}) — part fields priced directly`);
      }
    }

    const customerTier = firstField(partDescriptor, TIER_CONTEXT_FIELDS) ?? context.customerTier;
    const tierRules = [
      ...(nonEmptyArrayField(partDescriptor, EMBEDDED_RULE_FIELDS)
        ? EMBEDDED_RULE_FIELDS.reduce((acc: unknown[], f) => acc.concat(Array.isArray(partDescriptor[f]) ? partDescriptor[f] : []), [])
        : []),
      ...context.tierRules,
    ];
    const machine = firstField(partDescriptor, MACHINE_FIELDS) ?? context.machine;
    const setupFee = firstFinite(partDescriptor, SETUP_FIELDS) ?? (context.setupFee || undefined);
    const minimumCharge = firstFinite(partDescriptor, MIN_FIELDS) ?? (context.minimumCharge || undefined);
    const modifiers = Array.isArray(lineModifiers) ? lineModifiers : context.modifiers;
    const taxable = typeof partDescriptor.taxable === 'boolean' ? partDescriptor.taxable : context.taxable;
    const taxPercent = firstFinite(partDescriptor, TAX_PCT_FIELDS) ?? (context.taxPercent || undefined);

    let priced: any = null;
    try {
      priced = pricePart({
        label: base.label,
        category: line.category_key || asString(partDescriptor.category_key ?? partDescriptor.category),
        qty,
        unitCost: base.unit_cost,
        pricingUnit: asString(firstField(partDescriptor, UNIT_FIELDS)) || 'each',
        customerTier,
        tierRules,
        part: partDescriptor,
        machine,
        defaultMarkupPct: contextUsed.default_markup_pct,
        setupFee,
        minimumCharge,
        taxable,
        taxPercent,
        modifiers,
        now: input.now ?? context.now,
      });
    } catch (e: any) {
      base.skipped = 'engine_error';
      skippedCount += 1;
      warnings.push(`component '${base.label}': engine pricing failed (${asString(e?.message)}) — left at baseline sell`);
      return;
    }

    const pricedRecord = isRecord(priced) ? priced : {};
    const lineSubtotal = firstFinite(pricedRecord, ['subtotal']) ?? num(pricedRecord.extended);
    base.priced = true;
    base.priced_via = configured ? 'descriptor' : 'context';
    pricedCount += 1;
    configuredCostSum += cost;
    engineSubtotalSum += lineSubtotal;
    base.engine = {
      unit_price: num(pricedRecord.unitPrice),
      extended: num(pricedRecord.extended),
      setup_fee: num(pricedRecord.setupFee),
      subtotal: lineSubtotal,
      total: num(pricedRecord.total),
      price_source: asString(pricedRecord.priceSource),
      tier_source: asString(pricedRecord?.tier?.source),
      minimum_applied: pricedRecord.minimumApplied === true,
      dangling_tier_ref: asString(pricedRecord.danglingTierRef) || null,
      template_applied: templateApplied,
      template_reason: templateReason,
      trace: Array.isArray(pricedRecord?.tier?.trace) ? pricedRecord.tier.trace : [],
    };
    if (base.engine?.dangling_tier_ref) {
      warnings.push(`component '${base.label}': tier ref '${base.engine.dangling_tier_ref}' did not resolve — priced via remaining layers`);
    }
  });

  chain.push({
    layer: 'engine_pricing',
    hit: pricedCount > 0,
    won: false,
    detail: skippedCount
      ? `${pricedCount} engine-priced, ${skippedCount} skipped (kept at baseline)`
      : `${pricedCount} engine-priced`,
  });

  if (!pricedCount) {
    return passthroughResult('no_priced_lines', baselineSell, internalCost, markupPct, context.hasContextBlock, results, chain, warnings, contextUsed);
  }

  const configuredBaseline = configuredCostSum * markupFactor;
  const remainder = baselineSell - configuredBaseline;
  const engineTotal = engineSubtotalSum;
  const customerPrice = round2(remainder + engineTotal);
  if (remainder < 0) {
    warnings.push(`priced components' baseline (${round2(configuredBaseline)}) exceeds project sell — remainder ${round2(remainder)}`);
  }

  chain.push({
    layer: 'remainder',
    hit: true,
    won: false,
    detail: `baseline ${round2(baselineSell)} - priced baseline ${round2(configuredBaseline)} = remainder ${round2(remainder)}`,
  });
  chain.push({
    layer: 'customer_price',
    hit: true,
    won: true,
    detail: `remainder ${round2(remainder)} + engine ${round2(engineTotal)} = ${customerPrice}`,
  });

  return {
    applied: true,
    passthrough: false,
    reason: 'priced',
    customer_price: customerPrice,
    baseline_sell: baselineSell,
    internal_cost: internalCost,
    markup_pct: markupPct,
    context_engaged: context.hasContextBlock,
    configured_baseline: configuredBaseline,
    remainder_sell: remainder,
    engine_priced_total: engineTotal,
    lines: results,
    chain,
    warnings,
    context_used: contextUsed,
  };
}

// Shared pricing engine — pure, deterministic, zero entity/io access.
//
// Importable by Deno-style base44 functions AND the Vite frontend: no node:*,
// no npm:*, no imports at all. Callers hand the engine plain row objects
// (PricingTierMatrix-like chart rows, part/machine override descriptors) and
// get back fully-traced price breakdowns.
//
// Pipeline (pricePart): cost base -> tier lookup -> markup/fixed/market unit
// price -> formula modifiers -> qty extension -> minimum charge -> setup fee
// -> tax -> total.
//
// Tier precedence (resolveTier) follows the CoreBridge section-8 chain —
// "customer tier -> part-specific tier/fixed -> machine override" — read as a
// base-to-override ladder: the global default is the base, each configured
// layer overrides the previous one, so the MOST SPECIFIC layer wins:
//
//   machine_override  (strongest: the machine the part runs on)
//   part_fixed        (explicit sell price pinned on the part)
//   part_tier         (part-bound tier ref / part qty chart / part markup)
//   customer_tier     (chart row pinning the customer's assigned tier)
//   global_default    (weakest: category/blank chart row, else defaultMarkupPct)
//
// WITHIN the two chart-row layers the winning row follows legacy
// matchSpecificity (src/components/pricing/pricingEngine.js resolveMatrixRow):
// cat+tier (3) > cat-only (2) > tier-only (1) > blank (0) — so a
// category-pinned default row still outranks a bare customer_tier row even
// though it lives in the "weaker" ladder layer (F-27 parity). Part/machine
// descriptors keep the strict ladder ordering above the chart.
//
// Money semantics mirror src/components/pricing/pricingEngine.js:
//   markup_pct is a PERCENT over cost (50 = cost x 1.50); market mode stores a
//   retail price minus a discount percent; per_unit_breaks are qty thresholds
//   {qty, unit_price} where the highest qualifying bracket wins (in market
//   mode a break only wins when it undercuts the market unit price).
//   Money figures round to cents (round2); unit prices to 4 decimals (round4).

const num = (v: unknown, fallback = 0): number => {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
};

const normStr = (v: unknown): string => String(v ?? '').trim().toLowerCase();

export const round2 = (n: unknown): number => Math.round((num(n) + Number.EPSILON) * 100) / 100;
export const round4 = (n: unknown): number => Math.round((num(n) + Number.EPSILON) * 10000) / 10000;

// Weakest -> strongest. resolveTier walks this order for the OVERRIDE layers
// (part/machine); the two chart-row layers beneath them compete on legacy
// row specificity instead of raw layer order (see the header block above).
export const TIER_PRECEDENCE = Object.freeze([
  'global_default',
  'customer_tier',
  'part_tier',
  'part_fixed',
  'machine_override',
] as const);

export type TierSource = typeof TIER_PRECEDENCE[number];

export const PRICING_MODES = Object.freeze({
  MARKUP: 'markup',
  COST_PLUS: 'cost_plus',
  MARKET: 'market',
  // F-05 activation vocabulary: 'market_based' is the entity/admin spelling of
  // the same retail-minus-discount chart family the engine rows call 'market'
  // (PricingTemplate.market_based, GlobalPricingTier.rules[].market_based).
  // 'fixed' is a pinned unit sell price (part.fixed_price family).
  MARKET_BASED: 'market_based',
  FIXED: 'fixed',
} as const);

// --- Date windows (chart rows may carry effective_from / effective_to) --------

const DATE_ONLY = /^\d{4}-\d{2}-\d{2}$/;
const toTime = (v: unknown, { endOfDay = false } = {}): number | null => {
  if (v == null || v === '') return null;
  if (v instanceof Date) {
    const t = v.getTime();
    return Number.isFinite(t) ? t : null;
  }
  const s = String(v).trim();
  if (!s) return null;
  const t = Date.parse(s);
  if (!Number.isFinite(t)) return null;
  return endOfDay && DATE_ONLY.test(s) ? t + 86399999 : t;
};

const rowIsActive = (row: any): boolean => normStr(row?.status ?? 'active') !== 'inactive';

export function rowIsEffective(row: any, now: unknown = new Date()): boolean {
  const t = now instanceof Date ? now.getTime() : toTime(now);
  const at = Number.isFinite(t) ? (t as number) : Date.now();
  const from = toTime(row?.effective_from);
  const to = toTime(row?.effective_to, { endOfDay: true });
  if (from != null && at < from) return false;
  if (to != null && at > to) return false;
  return true;
}

// --- Tier key matching ---------------------------------------------------------

// A customerTier may arrive as a MarkupTier-like record ({id, tier_name,
// tier_number, name}) or a bare string/number. Rows match on whichever of
// tier_name / tier_number / id / name the admin typed into customer_tier.
const tierKeySet = (customerTier: unknown): Set<string> => {
  const keys = new Set<string>();
  const add = (v: unknown) => {
    const k = normStr(v);
    if (k) keys.add(k);
  };
  if (customerTier && typeof customerTier === 'object') {
    const t: any = customerTier;
    add(t.tier_name);
    add(t.tier_number);
    add(t.id);
    add(t.name);
  } else {
    add(customerTier);
  }
  return keys;
};

const rowPinsTier = (row: any, tierKeys: Set<string>): boolean =>
  !!normStr(row?.customer_tier) && tierKeys.has(normStr(row?.customer_tier));

const rowFitsCategory = (row: any, category: unknown): boolean =>
  !normStr(row?.category) || normStr(row?.category) === normStr(category);

// Deterministic tie-break inside a match bucket: most recent effective_from,
// then most recent updated_date, then lowest id.
const newerRow = (a: any, b: any): any => {
  if (!b) return a;
  const aFrom = toTime(a?.effective_from) ?? -Infinity;
  const bFrom = toTime(b?.effective_from) ?? -Infinity;
  if (aFrom !== bFrom) return aFrom > bFrom ? a : b;
  const aUp = toTime(a?.updated_date) ?? -Infinity;
  const bUp = toTime(b?.updated_date) ?? -Infinity;
  if (aUp !== bUp) return aUp > bUp ? a : b;
  return String(a?.id || '') <= String(b?.id || '') ? a : b;
};

// --- Qty-break charts -----------------------------------------------------------

// The bracket with the highest qualifying `qty` threshold wins.
// opts.interpolate === true switches to linear interpolation between bracket
// points (see interpolateUnitBreak). With opts absent/false the pick is
// byte-for-byte the legacy bracket pick — callers never interpolate unless a
// chart explicitly opts in (interpolate_breaks / break_interpolation:'linear').
export function pickUnitBreak(breaks: any, qty: unknown, opts: any = {}): any {
  const q = num(qty);
  if (!Array.isArray(breaks) || q <= 0) return null;
  if (opts && opts.interpolate === true) return interpolateUnitBreak(breaks, q);
  let pick: any = null;
  for (const b of breaks) {
    const bq = num(b?.qty, NaN);
    if (!Number.isFinite(bq) || bq <= 0 || bq > q) continue;
    if (!Number.isFinite(Number(b?.unit_price))) continue;
    if (!pick || bq > num(pick.qty)) pick = b;
  }
  return pick;
}

// Valid brackets ({qty>0, finite unit_price}) sorted ascending by qty with
// duplicate thresholds collapsed — the first-declared bracket wins its slot.
// This is the lattice interpolation walks.
const sortedUnitBreaks = (breaks: any): any[] => {
  const list: any[] = [];
  for (const b of Array.isArray(breaks) ? breaks : []) {
    const bq = num(b?.qty, NaN);
    if (!Number.isFinite(bq) || bq <= 0) continue;
    if (!Number.isFinite(Number(b?.unit_price))) continue;
    list.push(b);
  }
  list.sort((a: any, b: any) => num(a.qty) - num(b.qty));
  return list.filter((b: any, i: number) => i === 0 || num(b.qty) !== num(list[i - 1].qty));
};

// Linear interpolation between neighboring bracket points (F-04 — CoreBridge
// interpolated qty-break charts). Semantics:
//   qty in [lo.qty, hi.qty): unit_price = lo.p + (hi.p - lo.p) * t where
//     t = (qty - lo.qty) / (hi.qty - lo.qty); result rounds to 4 decimals
//     (round4 — same precision as every engine unit price).
//   qty below the FIRST bracket  -> null (never extrapolate below the chart;
//     the caller falls back to markup/market exactly like a missed break).
//   qty exactly ON a bracket qty -> that bracket object verbatim.
//   qty at/above the TOP bracket -> top bracket verbatim (clamp — the best
//     published volume price, never an extrapolation off the chart's end).
//   0 or 1 valid brackets        -> plain bracket-pick semantics.
// Mid-bracket hits return a synthetic bracket
//   {qty: lower.qty, unit_price, interpolated: true, at_qty: <requested>,
//    between: [lowerBracket, upperBracket]}
// so a downstream `breakApplied` audit can show the interpolation anchors.
export function interpolateUnitBreak(breaks: any, qty: unknown): any {
  const q = num(qty);
  const list = sortedUnitBreaks(breaks);
  if (!list.length || q <= 0 || q < num(list[0].qty)) return null;
  const last = list[list.length - 1];
  if (q >= num(last.qty)) return last;
  let lower = list[0];
  let upper = last;
  for (let i = 0; i < list.length - 1; i += 1) {
    if (q < num(list[i + 1].qty)) {
      lower = list[i];
      upper = list[i + 1];
      break;
    }
  }
  if (q === num(lower.qty)) return lower;
  const loQ = num(lower.qty);
  const hiQ = num(upper.qty);
  const loP = num(lower.unit_price);
  const hiP = num(upper.unit_price);
  const t = (q - loQ) / (hiQ - loQ);
  return {
    qty: loQ,
    unit_price: round4(loP + (hiP - loP) * t),
    interpolated: true,
    at_qty: q,
    between: [lower, upper],
  };
}

// --- Formula modifiers -----------------------------------------------------------

// Ordered unit-price adjustments, applied left-to-right ({type, value}):
//   add_pct  price = price x (1 + value/100)   (negative discounts)
//   mul      price = price x value
//   add_flat price = price + value
//   min      price = max(price, value)         (unit floor)
//   max      price = min(price, value)         (unit cap)
// Unknown types / non-finite values are skipped; price can never go below 0.
export function applyFormulaModifiers(unitPrice: unknown, modifiers: any): { unitPrice: number; applied: any[] } {
  let price = num(unitPrice);
  const applied: any[] = [];
  for (const m of Array.isArray(modifiers) ? modifiers : []) {
    const type = normStr(m?.type);
    const value = Number(m?.value);
    if (!Number.isFinite(value)) continue;
    const before = price;
    if (type === 'add_pct') price = price * (1 + value / 100);
    else if (type === 'mul') price = price * value;
    else if (type === 'add_flat') price = price + value;
    else if (type === 'min') price = Math.max(price, value);
    else if (type === 'max') price = Math.min(price, value);
    else continue;
    price = Math.max(0, price);
    applied.push({ type, value, before: round4(before), after: round4(price) });
  }
  return { unitPrice: round4(price), applied };
}

// --- Rule normalization ------------------------------------------------------------
//
// Every pricing layer resolves to one normalized rule:
//   kind: 'fixed' | 'markup' | 'market' | 'breaks'
//   fixedPrice?         unit sell price (fixed)
//   markupPct?          percent over unit cost (markup; also breaks fallback)
//   marketRetail?       market list price (market)
//   marketDiscountPct?  percent off retail (market)
//   unitBreaks?         [{qty, unit_price}] qty-break chart
//   minimumCharge?      extension floor
//   formulaModifiers?   ordered unit-price adjustments
//   ref?                originating record/descriptor (echoed for audit)

const marketKind = (row: any): boolean => {
  const pm = normStr(row?.pricing_mode);
  // 'market' is the engine token; 'market_based' is the entity/admin spelling
  // of the same chart family — both require a POSITIVE finite market_retail.
  // Legacy parity (F-27): retail <= 0 / non-finite is treated as absent — the
  // row falls back to its markup path exactly like resolveEffectivePrice's
  // `retail > 0` gate (pricingEngine.js).
  return (pm === PRICING_MODES.MARKET || pm === PRICING_MODES.MARKET_BASED)
    && Number.isFinite(Number(row?.market_retail)) && Number(row?.market_retail) > 0;
};

// A chart row / override descriptor opts its qty-break chart into interpolated
// pricing via interpolate_breaks (boolean | 'true' | 'linear'), the camelCase
// twins interpolateBreaks/interpolate, or break_interpolation:'linear'.
// Off by default — every unflagged chart keeps exact bracket-pick semantics.
const wantsInterpolatedBreaks = (src: any): boolean => {
  if (!src || typeof src !== 'object') return false;
  if (normStr(src.break_interpolation) === 'linear') return true;
  for (const f of ['interpolate_breaks', 'interpolateBreaks', 'interpolate']) {
    const v = (src as any)[f];
    if (v === true || normStr(v) === 'true' || normStr(v) === 'linear') return true;
  }
  return false;
};

function ruleFromChartRow(row: any): any {
  return {
    kind: marketKind(row) ? 'market' : 'markup',
    markupPct: num(row?.markup_pct),
    marketRetail: marketKind(row) ? num(row?.market_retail) : undefined,
    marketDiscountPct: marketKind(row) ? num(row?.market_discount_pct) : undefined,
    unitBreaks: Array.isArray(row?.per_unit_breaks) ? row.per_unit_breaks : undefined,
    interpolateBreaks: wantsInterpolatedBreaks(row) || undefined,
    minimumCharge: Number.isFinite(Number(row?.minimum_charge)) ? num(row.minimum_charge) : undefined,
    formulaModifiers: Array.isArray(row?.formula_modifiers) ? row.formula_modifiers : undefined,
    ref: row,
  };
}

const firstFinite = (...vals: unknown[]): number | null => {
  for (const v of vals) if (Number.isFinite(Number(v))) return Number(v);
  return null;
};

// Candidate rule from a part- or machine-shaped override descriptor.
// Markup field family — the spellings the wire detection layer counts as
// config (MARKUP_FIELDS in every *PricingWire.ts): markup_pct canonical,
// markup and markup_percent tolerated spellings. An explicit 0 means
// sell-at-cost, so absence (null) is the only "not configured" state.
const markupField = (src: any): number | null =>
  firstFinite(src?.markup_pct, src?.markup, src?.markup_percent);

// Within a layer: fixed_price > tier_ref > per_unit_breaks > pricing_mode
// 'market' > markup_pct. Returns null when the descriptor overrides nothing.
function overrideRule(source: any, tierRules: any[]): any {
  if (!source || typeof source !== 'object') return null;

  const fixed = firstFinite(source.fixed_price, source.price_override, source.override_price);
  if (fixed != null && fixed > 0) {
    return {
      kind: 'fixed',
      fixedPrice: fixed,
      minimumCharge: firstFinite(source.minimum_charge) ?? undefined,
      formulaModifiers: Array.isArray(source.formula_modifiers) ? source.formula_modifiers : undefined,
      ref: source,
    };
  }

  const tierRef = source.tier_ref ?? source.tier ?? source.tier_name;
  if (tierRef != null && normStr(tierRef)) {
    const wanted = normStr(typeof tierRef === 'object' ? (tierRef as any).name ?? (tierRef as any).id : tierRef);
    const row = (Array.isArray(tierRules) ? tierRules : []).find(
      (r: any) => r && rowIsActive(r) && (normStr(r.name) === wanted || normStr(r.id) === wanted),
    );
    if (row) return ruleFromChartRow(row);
    // A dangling tier ref must NOT silently fall through to weaker layers —
    // report it as an unpriced hit so the caller sees the misconfiguration.
    return { kind: 'markup', markupPct: 0, ref: source, danglingTierRef: String(wanted) };
  }

  const breaks = Array.isArray(source.per_unit_breaks) ? source.per_unit_breaks
    : Array.isArray(source.unit_breaks) ? source.unit_breaks
    : null;
  if (breaks && breaks.length) {
    return {
      kind: 'breaks',
      unitBreaks: breaks,
      interpolateBreaks: wantsInterpolatedBreaks(source) || undefined,
      markupPct: markupField(source) ?? undefined,
      minimumCharge: firstFinite(source.minimum_charge) ?? undefined,
      formulaModifiers: Array.isArray(source.formula_modifiers) ? source.formula_modifiers : undefined,
      ref: source,
    };
  }

  if (marketKind(source)) {
    return {
      kind: 'market',
      marketRetail: num(source.market_retail),
      marketDiscountPct: num(source.market_discount_pct),
      unitBreaks: Array.isArray(source.per_unit_breaks) ? source.per_unit_breaks : undefined,
      interpolateBreaks: wantsInterpolatedBreaks(source) || undefined,
      minimumCharge: firstFinite(source.minimum_charge) ?? undefined,
      formulaModifiers: Array.isArray(source.formula_modifiers) ? source.formula_modifiers : undefined,
      ref: source,
    };
  }

  // Any finite markup is an authored override — including 0, which pins
  // the part at cost (explicit sell-at-cost, F-23 markup-0 signal). All three
  // wire-detected spellings price identically (markup_pct/markup/markup_percent).
  // An ABSENT markup still returns null so weaker/default layers price the part.
  const markup = markupField(source);
  if (markup != null) {
    return {
      kind: 'markup',
      markupPct: markup,
      interpolateBreaks: wantsInterpolatedBreaks(source) || undefined,
      minimumCharge: firstFinite(source.minimum_charge) ?? undefined,
      formulaModifiers: Array.isArray(source.formula_modifiers) ? source.formula_modifiers : undefined,
      ref: source,
    };
  }

  return null;
}

// --- resolveTier -------------------------------------------------------------------
//
// context:
//   customerTier      assigned tier (string | number | MarkupTier-like record)
//   category          line category key (chart rows may pin a category)
//   tierRules         pricing chart rows (PricingTierMatrix-like)
//   part              part-level override descriptor
//   machine           machine-level override descriptor
//   defaultMarkupPct  shop fallback percent over cost
//   now               override for effective-window checks (tests)
//
// Returns { source, rule, layer, trace } where trace walks the ladder
// base -> override and marks which layers were hit and which one won.
export function resolveTier({
  customerTier = null,
  category = '',
  tierRules = [],
  part = null,
  machine = null,
  defaultMarkupPct = 0,
  now = undefined,
}: any = {}): any {
  const rules = Array.isArray(tierRules) ? tierRules : [];
  const tierKeys = tierKeySet(customerTier);
  const eligible = rules.filter((r: any) => r && rowIsActive(r) && rowIsEffective(r, now) && rowFitsCategory(r, category));

  // Customer-tier layer: rows that PIN this customer's tier.
  // category+tier beats tier-only inside the layer.
  let tierRow: any = null;
  let tierRowScoped = false;
  for (const row of eligible) {
    if (!rowPinsTier(row, tierKeys)) continue;
    const scoped = !!normStr(row.category);
    if (!tierRow || (scoped && !tierRowScoped) || scoped === tierRowScoped) {
      if (!tierRow || (scoped && !tierRowScoped)) { tierRow = row; tierRowScoped = scoped; }
      else tierRow = newerRow(row, tierRow);
    }
  }

  // Global-default layer: rows that pin NO tier — category rows beat blank
  // rows; failing both, the shop defaultMarkupPct is the implicit rule.
  let catRow: any = null;
  let blankRow: any = null;
  for (const row of eligible) {
    if (normStr(row.customer_tier)) continue;
    if (normStr(row.category)) catRow = newerRow(row, catRow);
    else blankRow = newerRow(row, blankRow);
  }

  // Part layer: fixed price outranks the part's own tier/chart/markup.
  const partRule = overrideRule(part, rules);
  const partSource = partRule?.kind === 'fixed' ? 'part_fixed' : 'part_tier';

  // Machine layer: anything the machine descriptor overrides wins outright.
  const machineRule = overrideRule(machine, rules);

  const defaultRule = catRow || blankRow
    ? ruleFromChartRow(catRow || blankRow)
    : { kind: 'markup', markupPct: num(defaultMarkupPct), ref: null, implicit: true };

  const ladder: any[] = [
    { layer: 'global_default', source: 'global_default', rule: defaultRule, hit: true,
      detail: catRow ? 'category_row' : blankRow ? 'blank_row' : 'default_markup_pct' },
    { layer: 'customer_tier', source: 'customer_tier', rule: tierRow ? ruleFromChartRow(tierRow) : null,
      hit: !!tierRow, detail: tierRow ? (tierRowScoped ? 'category+tier' : 'tier') : 'no tier row' },
    { layer: 'part', source: partSource, rule: partRule, hit: !!partRule,
      detail: partRule ? partRule.kind : 'no part override' },
    { layer: 'machine', source: 'machine_override', rule: machineRule, hit: !!machineRule,
      detail: machineRule ? machineRule.kind : 'no machine override' },
  ];

  // Chart-row layers compete on legacy matchSpecificity, NOT ladder order
  // (F-27 parity with resolveMatrixRow): cat+tier (3) > cat-only (2) >
  // tier-only (1) > blank (0). Scores never tie across layers (tier adds 1,
  // category adds 2), and each layer's row is already its best by the shared
  // tie-break (scoped > unscoped, then effective_from -> updated_date -> id).
  // The implicit defaultMarkupPct rule only wins when no chart row matched.
  const tierRowSpec = tierRow ? (tierRowScoped ? 3 : 1) : -1;
  const defaultRowSpec = catRow ? 2 : blankRow ? 0 : -1;
  let winner = tierRowSpec > defaultRowSpec ? ladder[1] : ladder[0];
  // Part/machine descriptors still override the winning chart layer in order.
  for (const step of ladder.slice(2)) if (step.hit && step.rule) winner = step;

  return {
    source: winner.source as TierSource,
    layer: winner.layer,
    rule: winner.rule,
    matchedRow: winner.rule?.ref ?? null,
    trace: ladder.map((step) => ({
      layer: step.layer,
      source: step.source,
      hit: step.hit,
      won: step === winner,
      detail: step.detail,
    })),
  };
}

// --- pricePart ---------------------------------------------------------------------
//
// input:
//   label, category, qty, unitCost (internal cost base per pricing unit),
//   pricingUnit (echo only — caller measures qty in pricing units),
//   customerTier, tierRules, part, machine, defaultMarkupPct  -> resolveTier
//   setupFee        flat dollars added after the minimum floor
//   minimumCharge   caller-side floor; combined with the winning rule's own
//                   minimum_charge (the higher floor wins)
//   taxable         false exempts the whole line (incl. setup fee) from tax
//   taxPercent      percent applied to (extension + setupFee) when taxable
//   modifiers       caller-level formula modifiers (run after rule modifiers)
//   now             effective-window override
//
// Returns a fully-traced breakdown. Never throws on bad numbers — non-finite
// inputs coerce to 0. Legacy parity (F-27): qty/unitCost pass through
// UNCLAMPED exactly like pricingEngine.js num() — a negative qty or cost
// yields a negative extension (minimums still never fire on extension <= 0).
export function pricePart(input: any = {}): any {
  const qty = num(input.qty ?? input.quantity, 0);
  const unitCost = num(input.unitCost ?? input.cost ?? input.costBase);
  const tier = resolveTier(input);
  const rule = tier.rule || { kind: 'markup', markupPct: 0 };

  let unitPrice = 0;
  let priceSource = 'cost_passthrough';
  let breakApplied: any = null;
  let market: any = null;

  const breaks = Array.isArray(rule.unitBreaks) ? rule.unitBreaks : null;
  // Interpolated break charts opt in via rule.interpolateBreaks (matrix row /
  // descriptor flag) — unflagged charts keep exact bracket-pick semantics.
  const brk = breaks ? pickUnitBreak(breaks, qty, { interpolate: rule.interpolateBreaks === true }) : null;

  if (rule.kind === 'fixed') {
    unitPrice = num(rule.fixedPrice);
    priceSource = 'fixed_price';
  } else if (rule.kind === 'market') {
    const retail = num(rule.marketRetail);
    const discountPct = num(rule.marketDiscountPct);
    const marketUnit = Math.max(0, retail * (1 - discountPct / 100));
    // A volume break must actually beat the market unit price to win.
    if (brk && num(brk.unit_price) < marketUnit) {
      unitPrice = num(brk.unit_price);
      priceSource = 'qty_break';
      breakApplied = brk;
    } else {
      unitPrice = marketUnit;
      priceSource = 'market';
    }
    market = { marketRetail: retail, marketDiscountPct: discountPct, marketUnit: round4(marketUnit) };
  } else if (rule.kind === 'breaks') {
    if (brk) {
      unitPrice = num(brk.unit_price);
      priceSource = 'qty_break';
      breakApplied = brk;
    } else {
      // No qualifying bracket — fall back to the descriptor's markup (or cost).
      unitPrice = unitCost * (1 + num(rule.markupPct) / 100);
      priceSource = Number.isFinite(Number(rule.markupPct)) ? 'markup' : 'cost_passthrough';
    }
  } else {
    // markup: a qualifying qty break beats the markup chart outright.
    if (brk) {
      unitPrice = num(brk.unit_price);
      priceSource = 'qty_break';
      breakApplied = brk;
    } else {
      unitPrice = unitCost * (1 + num(rule.markupPct) / 100);
      priceSource = 'markup';
    }
  }

  const baseUnitPrice = unitPrice;
  // Caller modifiers identical to rule-borne ones must not double-apply — a
  // caller that forwards a part's own formula_modifiers as input.modifiers
  // would otherwise run the same adjustment twice. Dedupe by (type, value);
  // distinct modifiers still stack in order.
  const ruleMods = Array.isArray(rule.formulaModifiers) ? rule.formulaModifiers : [];
  const ruleModKeys = new Set(ruleMods.map((m: any) => `${normStr(m?.type)}|${Number(m?.value)}`));
  const callerMods = (Array.isArray(input.modifiers) ? input.modifiers : [])
    .filter((m: any) => !ruleModKeys.has(`${normStr(m?.type)}|${Number(m?.value)}`));
  const modResult = applyFormulaModifiers(unitPrice, [...ruleMods, ...callerMods]);
  unitPrice = modResult.unitPrice;

  const extension = round2(unitPrice * qty);
  const ruleMin = num(rule.minimumCharge);
  const callerMin = num(input.minimumCharge);
  const minimumCharge = Math.max(ruleMin, callerMin);
  const minimumApplied = minimumCharge > 0 && extension > 0 && extension < minimumCharge;
  const extended = minimumApplied ? round2(minimumCharge) : extension;

  const setupFee = Math.max(0, num(input.setupFee ?? input.setup_fee));
  const subtotal = round2(extended + setupFee);

  const taxable = input.taxable !== false;
  const taxPercent = Math.max(0, num(input.taxPercent ?? input.tax_percent));
  const tax = taxable ? round2(subtotal * (taxPercent / 100)) : 0;
  const total = round2(subtotal + tax);

  return {
    label: String(input.label ?? ''),
    category: String(input.category ?? ''),
    pricingUnit: String(input.pricingUnit ?? input.pricing_unit ?? 'each'),
    qty,
    unitCost,
    tier,
    rule,
    baseUnitPrice: round4(baseUnitPrice),
    unitPrice: round4(unitPrice),
    priceSource,
    breakApplied,
    market,
    modifiersApplied: modResult.applied,
    extension,
    minimumCharge: minimumCharge > 0 ? minimumCharge : 0,
    minimumApplied,
    extended,
    setupFee,
    subtotal,
    taxable,
    taxPercent,
    tax,
    total,
    danglingTierRef: rule.danglingTierRef || null,
  };
}

// --- priceLines ----------------------------------------------------------------------
//
// Convenience roll-up: pricePart over an array of lines sharing the same
// context (customerTier, tierRules, taxPercent...). Per-line `part`, `machine`,
// `taxable`, `setupFee`, `minimumCharge`, `modifiers` stay on each line object.
export function priceLines({ lines = [], ...shared }: any = {}): any {
  const priced = (Array.isArray(lines) ? lines : []).map((line: any, index: number) =>
    pricePart({ label: line?.label ?? `Line ${index + 1}`, ...shared, ...line }));

  const extended = round2(priced.reduce((s: number, l: any) => s + l.extended, 0));
  const setupFees = round2(priced.reduce((s: number, l: any) => s + l.setupFee, 0));
  const subtotal = round2(priced.reduce((s: number, l: any) => s + l.subtotal, 0));
  const tax = round2(priced.reduce((s: number, l: any) => s + l.tax, 0));
  const total = round2(priced.reduce((s: number, l: any) => s + l.total, 0));

  return {
    lines: priced,
    extended,
    setupFees,
    subtotal,
    tax,
    total,
    minimumsApplied: priced
      .map((l: any, index: number) => (l.minimumApplied
        ? { index, label: l.label, extension: l.extension, minimumCharge: l.minimumCharge, source: l.tier.source }
        : null))
      .filter(Boolean),
  };
}

// --- Entity activation layer (F-04 / F-05) -------------------------------------
//
// The engine resolves plain chart-row objects; this section bridges persisted
// Base44 entity shapes to those rows. Still pure/deterministic — no io.
//
// PricingTierMatrix.jsonc field reality (verified against the schema):
//   name, status ('active'|'inactive'), customer_tier (MarkupTier.tier_name /
//   tier_number / record id; blank = every tier), category (MarkupCategory
//   .category_key; blank = every category), markup_pct, minimum_charge,
//   per_unit_breaks [{qty, unit_price}], effective_from / effective_to
//   (YYYY-MM-DD; `to` inclusive through end of day), updated_by, updated_note,
//   sort_order — plus tolerated extras the engine understands when present:
//   pricing_mode ('market'|'market_based'), market_retail,
//   market_discount_pct, formula_modifiers, interpolate_breaks.
//
// matrixRowToRule normalizes one row: tolerated aliases collapse onto the
// canonical engine fields (unit_breaks / qty_breaks -> per_unit_breaks; bracket
// {price|unit_price} and {qty|min_qty|quantity} -> {qty, unit_price};
// 'market-based' -> 'market_based'; retail / retail_price -> market_retail;
// discount_pct -> market_discount_pct; any interpolation spelling ->
// interpolate_breaks:true). Break charts are sanitized: non-positive qty and
// non-finite price brackets drop; a chart emptied that way is removed entirely
// so it can't mask the markup path. NOTE `breaks` is deliberately NOT aliased —
// PricingTemplate.breaks carries {qty, tier_markups} which is a different
// chart, not a {qty, unit_price} list.
//
// matrixRowsToRules applies the row gate the entity contract requires —
// status:'inactive' rows and rows outside their effective_from/effective_to
// window (checked at `now`) never reach the resolver — then maps each
// survivor through matrixRowToRule. Output rows are drop-in `tierRules` for
// resolveTier / pricePart (which re-check status + window themselves, so a
// stale adapted list still can't price an expired row).
export function matrixRowToRule(row: any, opts: any = {}): any {
  if (!row || typeof row !== 'object') return null;
  const out: any = { ...row };

  // Canonical status token: anything but 'inactive' is live (blank = active).
  out.status = normStr(row.status) === 'inactive' ? 'inactive' : 'active';

  const rawBreaks = Array.isArray(row.per_unit_breaks) ? row.per_unit_breaks
    : Array.isArray(row.unit_breaks) ? row.unit_breaks
    : Array.isArray(row.qty_breaks) ? row.qty_breaks
    : null;
  if (rawBreaks) {
    const clean = rawBreaks
      .map((b: any) => ({
        qty: num(b?.qty ?? b?.min_qty ?? b?.quantity, NaN),
        unit_price: num(b?.unit_price ?? b?.price, NaN),
      }))
      .filter((b: any) => Number.isFinite(b.qty) && b.qty > 0 && Number.isFinite(b.unit_price));
    if (clean.length) out.per_unit_breaks = clean;
    else delete out.per_unit_breaks;
  }

  if (normStr(out.pricing_mode) === 'market-based') out.pricing_mode = 'market_based';
  const retail = firstFinite(row.market_retail, row.retail_price, row.retail);
  if (retail != null) out.market_retail = retail;
  const discount = firstFinite(row.market_discount_pct, row.discount_pct);
  if (discount != null) out.market_discount_pct = discount;

  if (wantsInterpolatedBreaks(row) || opts.interpolateBreaks === true) {
    out.interpolate_breaks = true;
  }
  return out;
}

export function matrixRowsToRules(rows: any, opts: any = {}): any[] {
  const now = opts.now ?? new Date();
  const list = Array.isArray(rows) ? rows : Array.isArray(rows?.rows) ? rows.rows : [];
  const out: any[] = [];
  for (const row of list) {
    if (!row || typeof row !== 'object') continue;
    if (!rowIsActive(row)) continue;          // status:'inactive' never competes
    if (!rowIsEffective(row, now)) continue;  // effective_from/to window (entity field names)
    out.push(matrixRowToRule(row, opts));
  }
  return out;
}

// --- resolvePricingMode -----------------------------------------------------------
//
// Which pricing FAMILY a part prices under (F-05):
//   'cost_plus'    markup over unit cost — includes the %-tier matrix chart;
//                  PricingMode.active_mode 'tier' maps here.
//   'market_based' retail minus discount — PricingTemplate.market_based /
//                  GlobalPricingTier rule market_based / market_retail data.
//   'fixed'        pinned unit sell price (fixed_price / price_override family).
//
// Precedence: part > template > globalDefault > 'cost_plus' fallback.
// Within each layer: explicit mode token > fixed_price > bound tier_ref's
// chart row > market signals > markup_pct (any finite — an explicit 0
// resolves cost_plus, "sell at cost") — mirroring overrideRule's precedence.
//   { part, template, globalDefault, tierRules }
//   part          part-level descriptor. Field-name trap: inventory entities
//                 use `pricing_mode` for UNIT enums ('per_piece', 'per_roll'…)
//                 — unrecognized tokens are skipped, never guessed as a family.
//   template      PricingTemplate-like ({market_based, breaks, ...}) or any
//                 descriptor carrying the same signals.
//   globalDefault PricingMode entity ({active_mode:'tier'|'cost_plus'}),
//                 a settings-like object, or a bare mode string.
//   tierRules     optional chart rows so a bound tier_ref resolves to its row's
//                 family (a dangling ref resolves nothing — falls through).
// Returns {mode, source:'part'|'template'|'global'|'default', raw, via}.

const MODE_TOKENS: Record<string, string> = {
  fixed: PRICING_MODES.FIXED,
  fixed_price: PRICING_MODES.FIXED,
  flat: PRICING_MODES.FIXED,
  market: PRICING_MODES.MARKET_BASED,
  market_based: PRICING_MODES.MARKET_BASED,
  'market-based': PRICING_MODES.MARKET_BASED,
  retail: PRICING_MODES.MARKET_BASED,
  retail_minus_discount: PRICING_MODES.MARKET_BASED,
  cost_plus: PRICING_MODES.COST_PLUS,
  'cost-plus': PRICING_MODES.COST_PLUS,
  costplus: PRICING_MODES.COST_PLUS,
  markup: PRICING_MODES.COST_PLUS,
  tier: PRICING_MODES.COST_PLUS,
  tier_markup: PRICING_MODES.COST_PLUS,
  tiered: PRICING_MODES.COST_PLUS,
};

export const normalizePricingMode = (v: unknown): string | null =>
  MODE_TOKENS[normStr(v)] ?? null;

// Explicit token fields, checked in order. A bare string/number descriptor is
// itself the token (via:'value').
const explicitModeHit = (src: any): any => {
  if (src == null) return null;
  if (typeof src !== 'object') {
    const m = normalizePricingMode(src);
    return m ? { mode: m, raw: src, via: 'value' } : null;
  }
  for (const f of ['pricing_mode', 'price_mode', 'mode', 'active_mode']) {
    const m = normalizePricingMode(src[f]);
    if (m) return { mode: m, raw: src[f], via: f };
  }
  return null;
};

const fixedSignalHit = (src: any): any => {
  if (!src || typeof src !== 'object') return null;
  const fixed = firstFinite(src.fixed_price, src.price_override, src.override_price);
  return fixed != null && fixed > 0
    ? { mode: PRICING_MODES.FIXED, raw: fixed, via: 'fixed_price' }
    : null;
};

const marketSignalHit = (src: any): any => {
  if (!src || typeof src !== 'object') return null;
  if (src.market_based === true || normStr(src.market_based) === 'true') {
    return { mode: PRICING_MODES.MARKET_BASED, raw: src.market_based, via: 'market_based' };
  }
  const retail = firstFinite(src.market_retail, src.retail_price, src.retail);
  return retail != null && retail > 0
    ? { mode: PRICING_MODES.MARKET_BASED, raw: retail, via: 'market_retail' }
    : null;
};

// tier_ref / tier / tier_name binding -> the bound chart row's family. A market
// row (pricing_mode market + finite market_retail) resolves 'market_based';
// any other bound row is the cost-plus family. A DANGLING ref resolves
// nothing — falls through rather than guessing.
const tierRefModeHit = (src: any, rows: any): any => {
  if (!src || typeof src !== 'object') return null;
  const ref = src.tier_ref ?? src.tier ?? src.tier_name;
  if (ref == null || !normStr(ref)) return null;
  const wanted = normStr(typeof ref === 'object' ? (ref as any).name ?? (ref as any).id : ref);
  const row = (Array.isArray(rows) ? rows : []).find(
    (r: any) => r && rowIsActive(r) && (normStr(r.name) === wanted || normStr(r.id) === wanted),
  );
  if (!row) return null;
  return {
    mode: marketKind(row) ? PRICING_MODES.MARKET_BASED : PRICING_MODES.COST_PLUS,
    raw: row,
    via: 'tier_ref',
  };
};

// A finite markup_pct IS a pricing-family signal — including 0 (sell at
// cost). Same field family as overrideRule: markup_pct/markup/markup_percent
// — the spellings the wires detect are the spellings the engine prices.
// Weakest signal — ranks below explicit tokens, fixed, tier refs, and
// market data, mirroring overrideRule's own precedence.
const markupSignalHit = (src: any): any => {
  if (!src || typeof src !== 'object') return null;
  const markup = markupField(src);
  return markup != null
    ? { mode: PRICING_MODES.COST_PLUS, raw: markup, via: 'markup_pct' }
    : null;
};

const descriptorModeHit = (src: any, rows: any): any =>
  explicitModeHit(src) || fixedSignalHit(src) || tierRefModeHit(src, rows) || marketSignalHit(src) || markupSignalHit(src);

export function resolvePricingMode({ part = null, template = null, globalDefault = null, tierRules = null }: any = {}): any {
  const partHit = descriptorModeHit(part, tierRules);
  if (partHit) return { mode: partHit.mode, source: 'part', raw: partHit.raw, via: partHit.via };
  const tplHit = descriptorModeHit(template, tierRules);
  if (tplHit) return { mode: tplHit.mode, source: 'template', raw: tplHit.raw, via: tplHit.via };
  const gHit = descriptorModeHit(globalDefault, tierRules);
  if (gHit) return { mode: gHit.mode, source: 'global', raw: gHit.raw, via: gHit.via };
  return { mode: PRICING_MODES.COST_PLUS, source: 'default', raw: null, via: 'fallback' };
}

// PricingTemplate application — pure TS, ZERO imports, NO IO.
// (ESTIMATOR_MASTERPLAN F-06; entities base44/entities/PricingTemplate.jsonc
// (A-04), GlobalPricingTier.jsonc (A-07), BuilderPart.jsonc `pricing_template_id`
// (A-03 — DECLARED), PricingTierMatrix shape per pricingEngine.ts F-04 notes.)
//
// A catalog part picks a PricingTemplate on its Pricing Tiers tab; this module
// resolves the template's quantity-break x customer-tier margin chart against
// an order qty + tier context and produces the unit/extended price the caller
// folds into the shared pricing engine (base44/shared/pricingEngine.ts). It
// never imports: Deno functions and the Vite frontend can both bundle it.
//
// ---------------------------------------------------------------------------
// Entity contract — canonical stored spellings
// ---------------------------------------------------------------------------
//   PricingTemplate:  name, unit_category (SqFt|LinFt|Each|Hourly|Pixels|...),
//                     breaks[] = {qty:number, tier_markups:{<tierKey>: markup_pct}}
//                     in ASCENDING qty order — "when order qty >= bracket qty,
//                     that bracket's tier_markups chart applies". markup_pct is
//                     a PERCENT over cost (50 = cost x 1.50). market_based flag
//                     flips tier_markups values to market-based retail/discount
//                     chart entries. status 'active'|'inactive' (blank=active).
//   BuilderPart:      pricing_template_id — the link field (DECLARED A-03).
//                     unit — pricing-unit the template's unit_category gates on.
//                     fixed_price / per_unit_breaks / markup_pct / market_retail
//                     (tolerated part-descriptor extras per pricingEngine
//                     overrideRule). min_charge — part-level extension floor.
//   GlobalPricingTier rules[] = {tier, markup_pct, market_based} — a part may
//                     pin a named shared rule set as a fallback chart when the
//                     bound template cannot price a (qty, tier) point. Part
//                     link fields are TOLERATED EXTRAS today (no declared
//                     field — see "Schema gaps" below).
//   MarkupTier rows   ({tier_name, tier_number, id, name}) expand the customer
//                     tier's match keys — a '2' customer matches a chart entry
//                     keyed 'Wholesale' when the catalog row supplies it.
//
// ---------------------------------------------------------------------------
// Resolution precedence (resolveTemplatePrice) — engine-ladder parity
// ---------------------------------------------------------------------------
// The part layer of pricingEngine.overrideRule ranks: fixed_price > bound
// tier ref > per_unit_breaks > market > markup_pct. A bound PricingTemplate is
// that "bound chart ref" — so the chain walked here (strongest first, FIRST
// producing source wins, echoed in result.chain):
//
//   1. part_fixed      — part fixed_price/price_override/override_price > 0
//                        pins the unit price outright (source 'part_fixed').
//   2. template        — resolved template + qualifying bracket (see below).
//   3. tier_rule_set   — part-linked GlobalPricingTier rule hit (fallback when
//                        the template produced no price for this qty+tier).
//   4. part_chart      — part's own per_unit_breaks/unit_breaks bracket pick.
//   5. part_market     — part market_retail > 0 (+ market_discount_pct).
//   6. default_markup  — part.markup_pct (nonzero) else opts.default_markup_pct.
//   7. cost_passthrough— nothing finite anywhere; unit = base_price verbatim.
//
// Inside the template layer:
//   a. unit gate — a non-blank template.unit_category must ci-match the part's
//      pricing unit (unit|pricing_unit|pricingUnit|uom|unit_of_measure|
//      unit_category). Mismatch -> template cannot price
//      (reason 'unit_category_mismatch'). A BLANK part unit cannot disprove the
//      admin's pick — the template applies with `unit_unverified:true` flagged.
//   b. bracket pick — brackets qualify on (order qty >= bracket qty) AND the
//      bracket resolving a price for the customer tier (machineCosts
//      pickMarginBracket + F-27 shape-map parity: a bracket that cannot price
//      this tier simply doesn't qualify, so a LOWER bracket that covers the
//      tier wins over a higher bracket that doesn't). Highest qualifying
//      bracket qty wins; equal thresholds -> first declared. qty <= 0 prices
//      no bracket (engine pickUnitBreak parity) -> reason 'qty_not_positive'.
//   c. within a qualifying bracket (tier-scoped entry first — the map is the
//      chart's purpose; flat fields are the bracket's own fallback):
//      markup (cost-plus) template: tier_markups hit > unit_price >
//                                   markup_pct > discount_pct
//      market_based template:       tier_markups retail (>0) > market_retail >
//                                   template market_retail > unit_price >
//                                   markup_pct > discount_pct
//      DELIBERATE DEVIATION from machineCosts bracketPct (flat fields before
//      the map): there the tier map is a tolerated extra on margin charts;
//      here tier_markups is the DECLARED chart — "that bracket's
//      tier_markups chart applies" (PricingTemplate.jsonc).
//      Market values are retail UNIT prices; a row/template discount field
//      takes percent off (engine market parity: retail <= 0 counts as absent
//      and falls back to the markup path — F-27 i5).
//   d. tier_markups lookup (machineCosts tierMarkupsPct parity): normalized
//      customer-tier keys (tier_name/tier_number/id/name + 'tier'/'key' aliases,
//      catalog-expanded via `tiers`) > 'default' > '*' > lone numeric entry
//      (only when the map holds exactly one value AND it is finite).
//   e. template root flat fields (markup_pct|unit_price|market_retail|
//      discount_pct — tolerated extras) act as the chart-level default when no
//      bracket resolves (machineCosts 'chart_default' parity):
//      pct_source 'template_default', still source 'template' (applied:true).
//
// Malformed chart rows are REJECTED at normalization (warning recorded):
// non-record rows, a present-but-non-finite or negative qty, rows carrying no
// usable pricing content at all. A MISSING qty field means min 0 — a catch-all
// bracket covering every positive qty (machineCosts bracketMinQty parity).
//
// extended = round2(unit_price x qty); the highest finite minimum_charge found
// across bracket row -> template root -> part.min_charge -> opts floors the
// extension when 0 < extension < min (engine Math.max(ruleMin, callerMin)
// parity; minimums never fire on extension <= 0).
//
// ---------------------------------------------------------------------------
// Determinism / template swap
// ---------------------------------------------------------------------------
// Every function is pure — same rows in, same price out; swapping
// part.pricing_template_id re-prices deterministically. Registry match order:
// ref field precedence pricing_template_id > template_id > margin_template_id
// > pricing_template_name > template_name; within the registry, id match >
// name match; duplicate names -> active rows first, then lowest `sort`, then
// lowest id. An embedded part-carried template record
// (part.pricing_template|part.template with a chart array) is the fallback
// when the ref dangles; opts.template wins over everything (caller's
// pre-resolved pick).
//
// ---------------------------------------------------------------------------
// Schema gaps (orchestrator notes — nothing required for the core path)
// ---------------------------------------------------------------------------
//   - BuilderPart.pricing_template_id is DECLARED (A-03) — core link needs no
//     schema work. PartTemplate.jsonc declares it too.
//   - Part -> GlobalPricingTier link has NO declared field; tolerated extras
//     read here: global_pricing_tier_id|pricing_tier_id|tier_set_id|
//     pricing_tier_set_id|pricing_rule_set_id (+_name spellings). Declare one
//     canonical field when the tier-set fallback needs persistence.
//   - Template root flat fields + bracket flat fields (unit_price/markup_pct/
//     discount_pct/market_retail/minimum_charge) are tolerated extras beyond
//     the declared {qty, tier_markups} shape — supported, not required.
//
// ---------------------------------------------------------------------------
// Engine seam (wiring spec — see worker log / claims note)
// ---------------------------------------------------------------------------
// pricingEngine.ts exposes NO price-level template hook today: resolvePricingMode
// ({part, template,...}) resolves the pricing FAMILY only. Clean integration is
// a CALLER-SIDE adapter — no engine restructure needed:
//   const res = resolveTemplatePrice({part, qty: line.qty, templates, tiers,
//                                     customer_tier, base_price: line.unitCost});
//   pricePart({...line, part: templatePartDescriptor(part, res)});
// templatePartDescriptor strips the part's own chart fields the template
// supersedes (tier_ref / per_unit_breaks / market_* / markup_pct) and injects
// the resolved value in overrideRule's vocabulary (markup_pct | market_*
// pricing_mode:'market_based' | per_unit_breaks [{qty, unit_price}]), so the
// part_tier ladder layer emits the template-priced rule untouched. When
// res.applied is false the descriptor returns `part` verbatim — the engine's
// own default chain (customer_tier -> global_default -> markup) prices it.
// (A future engine-native seam would slot into pricingEngine.ts `resolveTier`
// where `const partRule = overrideRule(part, rules)` runs (~line 431): a
// template branch between the tier_ref and per_unit_breaks blocks inside
// `overrideRule` (~lines 326-351), fed by threading {qty, customerTier,
// templates} through as a third `ctx` arg.)

// ---------------------------------------------------------------------------
// shared coercion (same reject set as sizeDiscounts/modifierPricing)
// ---------------------------------------------------------------------------

const isRecord = (v: unknown): v is Record<string, unknown> =>
  v !== null && typeof v === 'object' && !Array.isArray(v);

const asString = (v: unknown): string =>
  v === null || v === undefined ? '' : String(v).trim();

const toFiniteNumber = (v: unknown): number | null => {
  if (
    v === null || v === undefined || v === '' ||
    typeof v === 'object' || typeof v === 'function' ||
    typeof v === 'symbol' || typeof v === 'bigint'
  ) {
    return null;
  }
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const num = (v: unknown, fallback = 0): number => toFiniteNumber(v) ?? fallback;

const lc = (v: unknown): string => asString(v).toLowerCase();

/** Shared pricing convention: half-up cents / 4-decimal units with EPSILON nudge. */
export const round2 = (n: unknown): number =>
  Math.round((num(n) + Number.EPSILON) * 100) / 100;
export const round4 = (n: unknown): number =>
  Math.round((num(n) + Number.EPSILON) * 10000) / 10000;

/** First field value that is present (not undefined/null/''). */
const firstField = (rec: Record<string, unknown> | null, fields: readonly string[]): unknown => {
  if (!rec) return undefined;
  for (const f of fields) {
    const v = rec[f];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
};

/** First finite number across a field-name scan; null when none resolve. */
const firstFinite = (rec: Record<string, unknown> | null, fields: readonly string[]): number | null => {
  if (!rec) return null;
  for (const f of fields) {
    const n = toFiniteNumber(rec[f]);
    if (n !== null) return n;
  }
  return null;
};

/** Same field scanned across nested scopes (root -> detail_overrides -> pricing_basis_snapshot). */
const scopedFinite = (part: Record<string, unknown> | null, fields: readonly string[]): number | null => {
  if (!part) return null;
  return firstFinite(part, fields)
    ?? firstFinite(isRecord(part.detail_overrides) ? part.detail_overrides : null, fields)
    ?? firstFinite(isRecord(part.pricing_basis_snapshot) ? part.pricing_basis_snapshot : null, fields);
};

// ---------------------------------------------------------------------------
// types + constants
// ---------------------------------------------------------------------------

export interface NormalizedTemplateBreak {
  /** Minimum order qty that unlocks this bracket (missing qty field -> 0). */
  qty: number;
  /** tier_markups map with ORIGINAL keys (finite values only). */
  tier_markups: Record<string, number>;
  /** Flat pinned unit price on the bracket row, else null. */
  unit_price: number | null;
  /** Flat markup percent on the bracket row, else null. */
  markup_pct: number | null;
  /** Flat discount percent on the bracket row, else null. */
  discount_pct: number | null;
  /** Market retail list price on the bracket row, else null. */
  market_retail: number | null;
  /** Discount percent off market retail on the bracket row, else null. */
  market_discount_pct: number | null;
  /** Extension floor on the bracket row, else null. */
  minimum_charge: number | null;
  /** Declaration index — deterministic tie-break for equal thresholds. */
  index: number;
  /** The raw row as supplied (audit echo). */
  raw: unknown;
}

export interface NormalizedPricingTemplate {
  id: string;
  name: string;
  unit_category: string;
  /** Chart rows sorted qty-ASC, declaration order preserved within ties. */
  breaks: NormalizedTemplateBreak[];
  market_based: boolean;
  status: string;
  active: boolean;
  sort: number;
  description: string;
  /** Chart-level flat fallbacks (tolerated extras — 'template_default'). */
  unit_price: number | null;
  markup_pct: number | null;
  discount_pct: number | null;
  market_retail: number | null;
  market_discount_pct: number | null;
  minimum_charge: number | null;
  /** Count of rows dropped during normalization (each warned). */
  rejected_breaks: number;
  warnings: string[];
  raw: unknown;
}

export type TemplatePctSource =
  | 'tier_markups'
  | 'tier_markups_default'
  | 'tier_markups_lone'
  | 'unit_price'
  | 'market_retail'
  | 'markup_pct'
  | 'discount_pct'
  | 'template_default'
  | 'tier_rule_set';

export type TemplatePriceSource =
  | 'part_fixed'
  | 'template'
  | 'tier_rule_set'
  | 'part_chart'
  | 'part_market'
  | 'default_markup'
  | 'cost_passthrough';

export interface TemplatePriceResult {
  /** True only when a PricingTemplate produced the unit price. */
  applied: boolean;
  template_id: string | null;
  template_name: string;
  template: NormalizedPricingTemplate | null;
  /** Winning precedence-layer token. */
  source: TemplatePriceSource;
  /** Which field inside the winning layer produced the value (null on fixed/cost passthrough). */
  pct_source: TemplatePctSource | 'fixed_price' | 'part_chart' | 'fallback' | null;
  /** The pricing FAMILY used — pricingEngine PRICING_MODES vocabulary. */
  pricing_mode: 'markup' | 'market_based' | 'fixed' | 'default_markup' | 'cost_passthrough';
  qty: number;
  base_price: number;
  unit_price: number;
  extended: number;
  /** Winning normalized bracket, else null. */
  tier_row: NormalizedTemplateBreak | null;
  /** Winning bracket's qty threshold, else null. */
  bracket_min_qty: number | null;
  /** tier_markups key that matched + its raw value, else null. */
  matched_tier: { key: string; value: number } | null;
  markup_pct: number | null;
  discount_pct: number | null;
  market_retail: number | null;
  market_discount_pct: number | null;
  minimum_charge: number;
  minimum_applied: boolean;
  /** Why the template did not price (null when it did / on part_fixed). */
  reason:
    | 'fixed_price'
    | 'no_template_ref'
    | 'template_not_found'
    | 'template_inactive'
    | 'unit_category_mismatch'
    | 'qty_not_positive'
    | 'no_qualifying_break'
    | null;
  /** Precedence walk, strongest first; exactly one entry has won:true. */
  chain: Array<{ layer: string; hit: boolean; won: boolean; detail: string }>;
  /** Non-blank template.unit_category could not be verified against a blank part unit. */
  unit_unverified: boolean;
  warnings: string[];
}

// ---------------------------------------------------------------------------
// field vocabularies
// ---------------------------------------------------------------------------

/** Bracket qty-threshold aliases (canonical `qty` first; machineCosts set). */
const BREAK_QTY_FIELDS = [
  'qty', 'min_qty', 'qty_from', 'from_qty', 'min_quantity', 'quantity',
  'break_qty', 'threshold',
] as const;

/** tier_markups map aliases (canonical first; machineCosts tolerated set). */
const TIER_MAP_FIELDS = [
  'tier_markups', 'tierMarkups', 'tier_margins', 'tierMargins', 'tiers',
] as const;

const UNIT_PRICE_FIELDS = ['unit_price', 'price', 'sell_price', 'rate'] as const;
const MARKUP_FIELDS = ['markup_pct', 'markup', 'markup_percent'] as const;
const DISCOUNT_FIELDS = ['discount_pct', 'discount', 'discount_percent', 'pct_off'] as const;
const RETAIL_FIELDS = ['market_retail', 'retail', 'retail_price', 'list_price'] as const;
const RETAIL_DISCOUNT_FIELDS = ['market_discount_pct', 'retail_discount_pct'] as const;
const MIN_CHARGE_FIELDS = ['minimum_charge', 'min_charge', 'minimum'] as const;

/** Chart-array fields on a template record (canonical `breaks` first). */
const CHART_FIELDS = ['breaks', 'rows', 'margin_rows', 'brackets', 'chart'] as const;

/** Part fields that reference a PricingTemplate (canonical declared first). */
const PART_TEMPLATE_ID_FIELDS = [
  'pricing_template_id', 'template_id', 'margin_template_id',
] as const;
const PART_TEMPLATE_NAME_FIELDS = [
  'pricing_template_name', 'template_name',
] as const;
/** Part fields that may embed a template record (or carry a ref scalar). */
const PART_TEMPLATE_EMBED_FIELDS = ['pricing_template', 'template'] as const;

/** Part link fields for a GlobalPricingTier rule set (tolerated extras). */
const PART_TIER_SET_FIELDS = [
  'global_pricing_tier_id', 'pricing_tier_id', 'tier_set_id',
  'pricing_tier_set_id', 'pricing_rule_set_id', 'global_tier_id',
] as const;
const PART_TIER_SET_NAME_FIELDS = [
  'global_pricing_tier_name', 'pricing_tier_name', 'tier_set_name',
] as const;

// Engine overrideRule vocabulary (+ machineCosts' flat_price): 'sell_price'
// deliberately NOT an alias — snapshots carry it for display and it must not
// silently pin the line.
const PART_FIXED_FIELDS = [
  'fixed_price', 'price_override', 'override_price', 'flat_price',
] as const;
const PART_BREAK_FIELDS = ['per_unit_breaks', 'unit_breaks', 'qty_breaks'] as const;
const PART_MARKET_RETAIL_FIELDS = RETAIL_FIELDS;
const PART_MARKET_DISCOUNT_FIELDS = ['market_discount_pct', 'retail_discount_pct', 'discount_pct'] as const;
const PART_MARKUP_FIELDS = ['markup_pct', 'markup', 'markup_percent'] as const;
const PART_MIN_CHARGE_FIELDS = ['min_charge', 'minimum_charge', 'minimum'] as const;
const PART_UNIT_FIELDS = [
  'unit', 'pricing_unit', 'pricingUnit', 'unit_category', 'uom', 'unit_of_measure',
] as const;

/** Template field that may carry a pricing-mode token (tolerated extra). */
const TEMPLATE_MODE_FIELDS = ['pricing_mode', 'price_mode', 'mode'] as const;
const MARKET_MODE_TOKENS = new Set(['market', 'market_based', 'market-based', 'retail', 'retail_minus_discount']);

// ---------------------------------------------------------------------------
// tier keys (customerTierModel/pricingEngine parity — normalized key space)
// ---------------------------------------------------------------------------

/** Normalize ONE tier value to its canonical key ('02'/'2.0' -> '2'). */
const normalizeTierKey = (v: unknown): string => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'object') return '';
  const s = lc(v);
  if (!s) return '';
  const n = Number(s);
  if (Number.isFinite(n) && /^[-+]?\d+(\.\d+)?$/.test(s)) return String(n);
  return s;
};

/** Every normalized key a tier value answers to (object contributes all fields). */
const tierKeysOf = (tier: unknown): Set<string> => {
  const keys = new Set<string>();
  const add = (v: unknown) => {
    const k = normalizeTierKey(v);
    if (k) keys.add(k);
  };
  if (isRecord(tier)) {
    for (const f of ['tier_number', 'tier_name', 'name', 'id', 'tier', 'key']) add(tier[f]);
  } else {
    add(tier);
  }
  return keys;
};

// ---------------------------------------------------------------------------
// template normalization — never throws
// ---------------------------------------------------------------------------

const chartRows = (raw: Record<string, unknown>): unknown[] => {
  for (const f of CHART_FIELDS) {
    if (Array.isArray(raw[f])) return raw[f] as unknown[];
  }
  return [];
};

const normalizeTierMarkups = (
  raw: Record<string, unknown>,
  warnings: string[],
  rowIdx: number,
): Record<string, number> => {
  const src = firstField(raw, TIER_MAP_FIELDS);
  const out: Record<string, number> = {};
  if (src === undefined) return out;
  if (!isRecord(src)) {
    warnings.push(`break ${rowIdx + 1}: tier_markups is not an object — ignored`);
    return out;
  }
  for (const [k, v] of Object.entries(src)) {
    const n = toFiniteNumber(v);
    if (n === null) {
      warnings.push(`break ${rowIdx + 1}: tier_markups["${k}"] is not a number — dropped`);
      continue;
    }
    out[k] = n;
  }
  return out;
};

const normalizeBreak = (
  raw: unknown,
  index: number,
  warnings: string[],
): NormalizedTemplateBreak | null => {
  if (!isRecord(raw)) {
    warnings.push(`break ${index + 1}: non-object row rejected`);
    return null;
  }
  const qtyField = BREAK_QTY_FIELDS.find((f) => raw[f] !== undefined && raw[f] !== null && raw[f] !== '');
  if (qtyField !== undefined) {
    const q = toFiniteNumber(raw[qtyField]);
    if (q === null || q < 0) {
      warnings.push(`break ${index + 1}: ${qtyField} '${asString(raw[qtyField])}' is not a non-negative number — row rejected`);
      return null;
    }
  }
  const qty = qtyField !== undefined ? num(raw[qtyField]) : 0;

  const tier_markups = normalizeTierMarkups(raw, warnings, index);
  const unit_price = firstFinite(raw, UNIT_PRICE_FIELDS);
  const markup_pct = firstFinite(raw, MARKUP_FIELDS);
  const discount_pct = firstFinite(raw, DISCOUNT_FIELDS);
  const market_retail = firstFinite(raw, RETAIL_FIELDS);
  const market_discount_pct = firstFinite(raw, RETAIL_DISCOUNT_FIELDS);
  const minimum_charge = firstFinite(raw, MIN_CHARGE_FIELDS);

  const hasContent =
    Object.keys(tier_markups).length > 0 ||
    unit_price !== null || markup_pct !== null || discount_pct !== null ||
    market_retail !== null;
  if (!hasContent) {
    warnings.push(`break ${index + 1}: no usable pricing content — row rejected`);
    return null;
  }

  return {
    qty,
    tier_markups,
    unit_price,
    markup_pct,
    discount_pct,
    market_retail,
    market_discount_pct,
    minimum_charge,
    index,
    raw,
  };
};

const templateIsMarketBased = (raw: Record<string, unknown>): boolean => {
  if (raw.market_based === true || lc(raw.market_based) === 'true') return true;
  for (const f of TEMPLATE_MODE_FIELDS) {
    if (MARKET_MODE_TOKENS.has(lc(raw[f]))) return true;
  }
  return false;
};

/**
 * Validate + normalize a PricingTemplate-like row. ALWAYS deterministic —
 * non-record input returns null (callers gate with template!=null), bad
 * breaks are dropped with warnings, surviving rows sort qty-ASC (stable).
 * Idempotent: re-normalizing a normalized row round-trips unchanged.
 */
export function normalizePricingTemplate(raw: unknown): NormalizedPricingTemplate | null {
  if (!isRecord(raw)) return null;
  const warnings: string[] = [];

  const rows = chartRows(raw);
  const breaks: NormalizedTemplateBreak[] = [];
  let rejected = 0;
  for (let i = 0; i < rows.length; i += 1) {
    const b = normalizeBreak(rows[i], i, warnings);
    if (b === null) rejected += 1;
    else breaks.push(b);
  }
  breaks.sort((a, b) => a.qty - b.qty || a.index - b.index);

  const status = asString(raw.status) || 'active';
  return {
    id: asString(raw.id ?? raw.template_id),
    name: asString(raw.name),
    unit_category: asString(raw.unit_category ?? raw.unitCategory),
    breaks,
    market_based: templateIsMarketBased(raw),
    status,
    active: lc(status) !== 'inactive',
    sort: num(raw.sort ?? raw.sort_order),
    description: asString(raw.description),
    unit_price: firstFinite(raw, UNIT_PRICE_FIELDS),
    markup_pct: firstFinite(raw, MARKUP_FIELDS),
    discount_pct: firstFinite(raw, DISCOUNT_FIELDS),
    market_retail: firstFinite(raw, RETAIL_FIELDS),
    market_discount_pct: firstFinite(raw, RETAIL_DISCOUNT_FIELDS),
    minimum_charge: firstFinite(raw, MIN_CHARGE_FIELDS),
    rejected_breaks: rejected,
    warnings,
    raw,
  };
}

// ---------------------------------------------------------------------------
// part -> template link resolution
// ---------------------------------------------------------------------------

export interface TemplateRef {
  /** Raw reference value (id or name) the part carries, '' when embedded-only. */
  ref: string;
  /** Which part field supplied it ('pricing_template_id', 'template', ...). */
  via: string;
  /** Embedded template record on the part, when present. */
  embedded: Record<string, unknown> | null;
}

const recordLooksLikeTemplate = (v: unknown): v is Record<string, unknown> =>
  isRecord(v) &&
  (Array.isArray(v.breaks) || Array.isArray(v.rows) ||
    Array.isArray(v.margin_rows) || Array.isArray(v.brackets) ||
    Array.isArray(v.chart));

/**
 * Extract the part's template reference + any embedded template record.
 * Ref-field precedence (canonical declared field first):
 *   pricing_template_id > template_id > margin_template_id >
 *   pricing_template_name > template_name > scalar pricing_template|template.
 * An embedded record under part.pricing_template|part.template rides along as
 * fallback (registry rows outrank snapshots).
 */
export function templateRefForPart(part: unknown): TemplateRef | null {
  const p = isRecord(part) ? part : null;
  if (!p) return null;

  let embedded: Record<string, unknown> | null = null;
  for (const f of PART_TEMPLATE_EMBED_FIELDS) {
    if (recordLooksLikeTemplate(p[f])) { embedded = p[f] as Record<string, unknown>; break; }
  }

  for (const f of PART_TEMPLATE_ID_FIELDS) {
    const v = asString(p[f]);
    if (v) return { ref: v, via: f, embedded };
  }
  for (const f of PART_TEMPLATE_NAME_FIELDS) {
    const v = asString(p[f]);
    if (v) return { ref: v, via: f, embedded };
  }
  for (const f of PART_TEMPLATE_EMBED_FIELDS) {
    const v = p[f];
    if (isRecord(v)) {
      const inner = asString(v.id ?? v.name ?? v.template_id);
      if (inner) return { ref: inner, via: `${f}.id`, embedded: embedded ?? v };
    } else {
      const s = asString(v);
      if (s) return { ref: s, via: f, embedded };
    }
  }
  if (embedded) return { ref: asString(embedded.id ?? embedded.name), via: 'embedded', embedded };
  return null;
}

/** Template record's identity keys for registry matching. */
const templateIds = (t: Record<string, unknown>): Set<string> => {
  const keys = new Set<string>();
  for (const k of [t.id, t.template_id]) {
    const s = lc(k);
    if (s) keys.add(s);
  }
  return keys;
};

/**
 * Resolve the part's bound PricingTemplate record from the registry.
 * `templates` accepts a row array, a {rows|templates:[...]} wrapper, or a bare
 * record. Match order: id > name; duplicate names -> active first, then
 * lowest sort, then lowest id (deterministic). A template record is returned
 * regardless of status — resolveTemplatePrice decides usability. Falls back
 * to the part-embedded record when the ref dangles. Returns null when the
 * part declares no resolvable template.
 */
export function templateForPart(
  part: unknown,
  templates: unknown = [],
): Record<string, unknown> | null {
  const ref = templateRefForPart(part);
  if (!ref) return null;

  const list: Record<string, unknown>[] = Array.isArray(templates)
    ? (templates as unknown[]).filter(isRecord)
    : isRecord(templates) && Array.isArray((templates as any).rows)
      ? ((templates as any).rows as unknown[]).filter(isRecord)
      : isRecord(templates) && Array.isArray((templates as any).templates)
        ? ((templates as any).templates as unknown[]).filter(isRecord)
        : isRecord(templates)
          ? [templates as Record<string, unknown>]
          : [];

  const wanted = lc(ref.ref);
  if (wanted) {
    const idHit = list.find((t) => templateIds(t).has(wanted));
    if (idHit) return idHit;
    const nameHits = list.filter((t) => lc(t.name) === wanted);
    if (nameHits.length) {
      nameHits.sort((a, b) => {
        const aAct = lc(a.status ?? 'active') !== 'inactive' ? 0 : 1;
        const bAct = lc(b.status ?? 'active') !== 'inactive' ? 0 : 1;
        return aAct - bAct || num(a.sort) - num(b.sort) ||
          String(a.id ?? '').localeCompare(String(b.id ?? ''));
      });
      return nameHits[0];
    }
  }
  return ref.embedded ?? null;
}

// ---------------------------------------------------------------------------
// bracket price resolution
// ---------------------------------------------------------------------------

interface TierMapHit {
  key: string;
  value: number;
  match: 'exact' | 'default' | 'lone';
}

/** machineCosts tierMarkupsPct parity: exact keys -> 'default' -> '*' -> lone. */
const tierMarkupsHit = (map: Record<string, number>, tierKeys: Set<string>): TierMapHit | null => {
  for (const [k, v] of Object.entries(map)) {
    if (tierKeys.has(lc(k)) && Number.isFinite(Number(v))) {
      return { key: k, value: Number(v), match: 'exact' };
    }
  }
  for (const fallback of ['default', '*']) {
    for (const [k, v] of Object.entries(map)) {
      if (lc(k) === fallback && Number.isFinite(Number(v))) {
        return { key: k, value: Number(v), match: 'default' };
      }
    }
  }
  const entries = Object.entries(map);
  if (entries.length === 1 && Number.isFinite(Number(entries[0][1]))) {
    return { key: entries[0][0], value: Number(entries[0][1]), match: 'lone' };
  }
  return null;
};

interface BracketPrice {
  unit: number;
  pct_source: TemplatePctSource;
  pricing_mode: 'markup' | 'market_based' | 'fixed';
  markup_pct: number | null;
  discount_pct: number | null;
  market_retail: number | null;
  market_discount_pct: number | null;
  matched_tier: { key: string; value: number } | null;
  detail: string;
}

const marketUnit = (retail: number, discountPct: number | null): number =>
  Math.max(0, retail * (1 - num(discountPct) / 100));

/**
 * Resolve ONE bracket's price contribution for the customer tier.
 * Markup charts: tier hit (markup%) > unit_price > markup_pct > discount_pct.
 * Market charts: tier hit (retail $) > row retail > template retail >
 * unit_price > markup_pct > discount_pct. Returns null when the bracket has
 * nothing for this tier/qty point.
 */
const bracketPrice = (
  b: NormalizedTemplateBreak,
  tmpl: NormalizedPricingTemplate,
  tierKeys: Set<string>,
  base: number,
): BracketPrice | null => {
  const tierHit = tierMarkupsHit(b.tier_markups, tierKeys);
  const pct_source: TemplatePctSource | null = tierHit
    ? tierHit.match === 'exact'
      ? 'tier_markups'
      : tierHit.match === 'default'
        ? 'tier_markups_default'
        : 'tier_markups_lone'
    : null;
  const matched_tier = tierHit ? { key: tierHit.key, value: tierHit.value } : null;

  if (tmpl.market_based) {
    // tier_markups value = retail unit price under market_based (engine-
    // defined interpretation; F-27: "no legacy analog"). Retail must be
    // POSITIVE — <=0 counts as absent exactly like marketKind parity.
    if (tierHit && tierHit.value > 0) {
      const disc = b.market_discount_pct ?? b.discount_pct ?? tmpl.market_discount_pct;
      return {
        unit: marketUnit(tierHit.value, disc),
        pct_source: pct_source as TemplatePctSource,
        pricing_mode: 'market_based',
        markup_pct: null,
        discount_pct: disc ?? 0,
        market_retail: tierHit.value,
        market_discount_pct: num(disc),
        matched_tier,
        detail: `tier retail ${tierHit.key}`,
      };
    }
    const rowRetail = b.market_retail !== null && b.market_retail > 0 ? b.market_retail : null;
    const tmplRetail = tmpl.market_retail !== null && tmpl.market_retail > 0 ? tmpl.market_retail : null;
    const retail = rowRetail ?? tmplRetail;
    if (retail !== null) {
      const disc = b.market_discount_pct ?? b.discount_pct ?? tmpl.market_discount_pct;
      return {
        unit: marketUnit(retail, disc),
        pct_source: 'market_retail',
        pricing_mode: 'market_based',
        markup_pct: null,
        discount_pct: disc ?? 0,
        market_retail: retail,
        market_discount_pct: num(disc),
        matched_tier,
        detail: rowRetail !== null ? 'row market_retail' : 'template market_retail',
      };
    }
    // Market chart falls back to the markup path (F-27 i5 parity): a flat
    // markup/price field on the bracket still prices this tier.
    if (b.markup_pct !== null) {
      return {
        unit: base * (1 + b.markup_pct / 100),
        pct_source: 'markup_pct',
        pricing_mode: 'markup',
        markup_pct: b.markup_pct,
        discount_pct: null,
        market_retail: null,
        market_discount_pct: null,
        matched_tier,
        detail: 'market chart markup fallback',
      };
    }
    if (b.unit_price !== null) {
      return {
        unit: b.unit_price,
        pct_source: 'unit_price',
        pricing_mode: 'fixed',
        markup_pct: null,
        discount_pct: null,
        market_retail: null,
        market_discount_pct: null,
        matched_tier,
        detail: 'bracket unit_price',
      };
    }
    if (b.discount_pct !== null) {
      return {
        unit: Math.max(0, base * (1 - b.discount_pct / 100)),
        pct_source: 'discount_pct',
        pricing_mode: 'market_based',
        markup_pct: null,
        discount_pct: b.discount_pct,
        market_retail: null,
        market_discount_pct: b.discount_pct,
        matched_tier,
        detail: 'market chart discount off base',
      };
    }
    return null;
  }

  // Cost-plus template: tier-scoped markup first, then flat bracket fields.
  if (tierHit) {
    return {
      unit: base * (1 + tierHit.value / 100),
      pct_source: pct_source as TemplatePctSource,
      pricing_mode: 'markup',
      markup_pct: tierHit.value,
      discount_pct: null,
      market_retail: null,
      market_discount_pct: null,
      matched_tier,
      detail: `tier markup ${tierHit.key}=${tierHit.value}`,
    };
  }
  if (b.unit_price !== null) {
    return {
      unit: b.unit_price,
      pct_source: 'unit_price',
      pricing_mode: 'fixed',
      markup_pct: null,
      discount_pct: null,
      market_retail: null,
      market_discount_pct: null,
      matched_tier,
      detail: 'bracket unit_price',
    };
  }
  if (b.markup_pct !== null) {
    return {
      unit: base * (1 + b.markup_pct / 100),
      pct_source: 'markup_pct',
      pricing_mode: 'markup',
      markup_pct: b.markup_pct,
      discount_pct: null,
      market_retail: null,
      market_discount_pct: null,
      matched_tier,
      detail: 'bracket markup_pct',
    };
  }
  if (b.discount_pct !== null) {
    return {
      unit: Math.max(0, base * (1 - b.discount_pct / 100)),
      pct_source: 'discount_pct',
      pricing_mode: 'markup',
      markup_pct: null,
      discount_pct: b.discount_pct,
      market_retail: null,
      market_discount_pct: b.discount_pct,
      matched_tier,
      detail: 'bracket discount off base',
    };
  }
  return null;
};

/** Highest qualifying bracket that resolves a price for this tier, or null. */
const pickTemplateBreak = (
  tmpl: NormalizedPricingTemplate,
  qty: number,
  tierKeys: Set<string>,
  base: number,
): { bracket: NormalizedTemplateBreak; price: BracketPrice } | null => {
  let pick: { bracket: NormalizedTemplateBreak; price: BracketPrice } | null = null;
  for (const b of tmpl.breaks) {
    if (b.qty > qty) continue;             // sorted ASC — keeps scanning safe
    const price = bracketPrice(b, tmpl, tierKeys, base);
    if (price === null) continue;          // can't price this tier -> not eligible
    // `>=` never fires (qty-ASC + first-declared tie order), `>` stands.
    if (!pick || b.qty > pick.bracket.qty) pick = { bracket: b, price };
  }
  return pick;
};

// ---------------------------------------------------------------------------
// GlobalPricingTier linked-set fallback (tolerated-extra link fields)
// ---------------------------------------------------------------------------

const isRuleSet = (v: unknown): v is Record<string, unknown> =>
  isRecord(v) && Array.isArray(v.rules);

const ruleSetIds = (set: Record<string, unknown>): Set<string> => {
  const keys = new Set<string>();
  for (const k of [set.id, set.name]) {
    const s = lc(k);
    if (s) keys.add(s);
  }
  return keys;
};

const partTierSetRefs = (part: Record<string, unknown>): string[] => {
  const refs: string[] = [];
  for (const f of [...PART_TIER_SET_FIELDS, ...PART_TIER_SET_NAME_FIELDS]) {
    const v = asString(part[f]);
    if (v) refs.push(v);
  }
  return refs;
};

/**
 * Part-linked GlobalPricingTier rule sets consulted when the template can't
 * price. Only sets the part explicitly links (id or name) are eligible —
 * scanning every supplied set would let unrelated registries reprice parts.
 * First rule (in part-link order, then set order) pinning a customer key with
 * a finite markup_pct wins; market_based rules with no markup contribute
 * nothing (F-27 i5 parity — the markup path takes over).
 */
const tierRuleSetHit = (
  part: Record<string, unknown>,
  ruleSets: Record<string, unknown>[],
  tierKeys: Set<string>,
  base: number,
): { unit: number; markup_pct: number; set: Record<string, unknown>; rule: Record<string, unknown> } | null => {
  const refs = partTierSetRefs(part).map(lc);
  if (!refs.length) return null;
  for (const wanted of refs) {
    for (const set of ruleSets) {
      if (lc(set.status ?? 'active') === 'inactive') continue;
      if (!ruleSetIds(set).has(wanted)) continue;
      for (const rule of Array.isArray(set.rules) ? set.rules : []) {
        if (!isRecord(rule)) continue;
        const pin = lc(rule.tier ?? rule.customer_tier);
        const pinned = pin && (tierKeys.has(pin) || pin === '*' || pin === 'default');
        if (!pinned) continue;
        const pct = toFiniteNumber(rule.markup_pct);
        if (pct === null) continue;      // market_based-only rule -> no markup
        return {
          unit: base * (1 + pct / 100),
          markup_pct: pct,
          set,
          rule,
        };
      }
    }
  }
  return null;
};

// ---------------------------------------------------------------------------
// part-carried fallback charts (engine overrideRule vocabulary)
// ---------------------------------------------------------------------------

const partChartBreaks = (part: Record<string, unknown>): unknown[] => {
  for (const f of PART_BREAK_FIELDS) {
    if (Array.isArray(part[f])) return part[f] as unknown[];
  }
  return [];
};

/** Engine pickUnitBreak parity: highest qualifying qty (>0) w/ finite unit_price. */
const pickPartUnitBreak = (breaks: unknown[], qty: number): Record<string, unknown> | null => {
  let pick: Record<string, unknown> | null = null;
  for (const b of breaks) {
    if (!isRecord(b)) continue;
    const bq = num(b.qty ?? b.min_qty ?? b.quantity, NaN);
    if (!Number.isFinite(bq) || bq <= 0 || bq > qty) continue;
    if (!Number.isFinite(Number(b.unit_price ?? b.price))) continue;
    if (!pick || bq > num(pick.qty ?? pick.min_qty ?? pick.quantity)) pick = b;
  }
  return pick;
};

// ---------------------------------------------------------------------------
// resolveTemplatePrice
// ---------------------------------------------------------------------------

/**
 * Resolve the price for one part line under its bound PricingTemplate.
 *
 * input:
 *   part                  part record (pricing_template_id link lives here)
 *   qty | quantity        order qty in pricing units
 *   base_price | unit_cost | cost | costBase   unit cost base the chart marks up
 *   templates             PricingTemplate registry rows (array | {rows} | record)
 *   tiers                 customer-tier context: a bare tier value, OR an array
 *                         mixing MarkupTier-like catalog rows (key expansion)
 *                         and GlobalPricingTier-like rule sets ({rules:[]})
 *   tier | customer_tier | customerTier   explicit customer tier value
 *   template              caller pre-resolved template record (wins over refs)
 *   default_markup_pct | defaultMarkupPct   shop fallback percent
 *   minimum_charge | minimumCharge          caller-side extension floor
 *
 * Never throws; non-finite input coerces to 0. Result carries the winning
 * `source`, the precedence `chain` walked, the winning `tier_row` bracket and
 * enough echo (template_id/matched_tier/markup_pct/...) for audit trails.
 */
export function resolveTemplatePrice(input: any = {}): TemplatePriceResult {
  const args = isRecord(input) ? input : {};
  const part = isRecord(args.part) ? args.part : {};
  const qty = num(args.qty ?? args.quantity);
  const base = num(firstField(args, ['base_price', 'basePrice', 'unit_cost', 'unitCost', 'cost', 'costBase', 'cost_base']) ?? 0);
  const warnings: string[] = [];

  // --- customer tier key set -------------------------------------------------
  const tierValue = firstField(args, ['tier', 'customer_tier', 'customerTier']);
  const tiersArg = args.tiers;
  const tierCatalog: unknown[] = Array.isArray(tiersArg) ? tiersArg : [];
  const bareTier = tierValue ?? (!Array.isArray(tiersArg) && !isRecord(tiersArg) ? tiersArg : null);
  const tierKeys = tierKeysOf(
    bareTier !== null && bareTier !== undefined ? bareTier : (isRecord(tiersArg) ? tiersArg : null),
  );
  // Expand keys through MarkupTier-like catalog rows (a '2' customer picks up
  // the catalog row's tier_name/id/... keys — tierKeysOf union, engine parity).
  for (const row of tierCatalog) {
    if (!isRecord(row) || isRuleSet(row)) continue;
    const rowKeys = tierKeysOf(row);
    let shared = false;
    for (const k of rowKeys) if (tierKeys.has(k)) { shared = true; break; }
    if (shared) for (const k of rowKeys) tierKeys.add(k);
  }
  const ruleSets = tierCatalog.filter(isRuleSet);

  // --- template resolution ---------------------------------------------------
  const ref = templateRefForPart(part);
  const templatePool: unknown[] = Array.isArray(args.templates)
    ? args.templates
    : isRecord(args.templates) && Array.isArray((args.templates as any).rows)
      ? (args.templates as any).rows
      : isRecord(args.templates) && Array.isArray((args.templates as any).templates)
        ? (args.templates as any).templates
        : isRecord(args.templates)
          ? [args.templates]
          : [];

  let rawTemplate: Record<string, unknown> | null = null;
  let templateVia = '';
  if (isRecord(args.template)) {
    rawTemplate = args.template;
    templateVia = 'opts.template';
  } else if (args.template !== undefined && args.template !== null && asString(args.template)) {
    // Caller's template ref resolved against the same pool.
    const wanted = lc(args.template);
    rawTemplate = templatePool.filter(isRecord).find(
      (t) => templateIds(t).has(wanted) || lc(t.name) === wanted,
    ) ?? null;
    templateVia = 'opts.template';
  } else if (ref) {
    rawTemplate = templateForPart(part, templatePool);
    templateVia = ref.via;
  }
  const tmpl = rawTemplate ? normalizePricingTemplate(rawTemplate) : null;
  if (tmpl) warnings.push(...tmpl.warnings);
  const templateId = tmpl ? (tmpl.id || asString((rawTemplate as any)?.name) || asString(ref?.ref)) : null;

  // --- part unit gate ----------------------------------------------------------
  const partUnit = lc(firstField(part, PART_UNIT_FIELDS));
  const unitCategory = tmpl ? lc(tmpl.unit_category) : '';
  const unitMismatch = !!tmpl && !!unitCategory && !!partUnit && partUnit !== unitCategory;
  const unitUnverified = !!tmpl && !!unitCategory && !partUnit;

  // --- precedence walk ---------------------------------------------------------
  // Engine resolveTier-trace parity: EVERY layer is evaluated and recorded —
  // `hit` marks what the layer could resolve, `won` marks the first hit (the
  // layer that actually priced the line). Exactly one won:true per result.
  const chain: TemplatePriceResult['chain'] = [];
  let won = false;
  const record = (layer: string, hit: boolean, detail: string) =>
    chain.push({ layer, hit, won: false, detail });
  const markWon = () => { chain[chain.length - 1].won = true; won = true; };
  /** Apply this layer's outputs only while nothing has won yet. */
  const take = (fn: () => void) => { if (!won) fn(); };

  let unit: number | null = null;
  let source: TemplatePriceSource = 'cost_passthrough';
  let pctSource: TemplatePriceResult['pct_source'] = null;
  let pricingMode: TemplatePriceResult['pricing_mode'] = 'cost_passthrough';
  let tierRow: NormalizedTemplateBreak | null = null;
  let matchedTier: { key: string; value: number } | null = null;
  let markupPct: number | null = null;
  let discountPct: number | null = null;
  let marketRetail: number | null = null;
  let marketDiscountPct: number | null = null;
  let reason: TemplatePriceResult['reason'] = null;
  let breakMinCharge: number | null = null;
  let applied = false;

  // 1. part_fixed — pinned sell price outranks every chart (engine ladder).
  const fixed = scopedFinite(part, PART_FIXED_FIELDS);
  if (fixed !== null && fixed > 0) {
    record('part_fixed', true, `fixed_price ${fixed}`);
    take(() => {
      markWon();
      unit = fixed;
      source = 'part_fixed';
      pctSource = 'fixed_price';
      pricingMode = 'fixed';
      reason = 'fixed_price';
    });
  } else {
    record('part_fixed', false, fixed !== null ? 'fixed_price not positive' : 'no fixed price');
  }

  // 2. template — bound chart resolution.
  {
    let layerReason: TemplatePriceResult['reason'] = null;
    if (!ref && !rawTemplate) layerReason = 'no_template_ref';
    else if (!tmpl) layerReason = 'template_not_found';
    else if (!tmpl.active) layerReason = 'template_inactive';
    else if (unitMismatch) layerReason = 'unit_category_mismatch';
    else if (qty <= 0) layerReason = 'qty_not_positive';

    if (layerReason) {
      record('template', false, layerReason);
      reason = reason ?? layerReason;
    } else {
      const pick = pickTemplateBreak(tmpl as NormalizedPricingTemplate, qty, tierKeys, base);
      if (pick) {
        record('template', true,
          `bracket qty>=${pick.bracket.qty} via ${pick.price.pct_source}${templateVia ? ` [${templateVia}]` : ''}`);
        take(() => {
          markWon();
          applied = true;
          source = 'template';
          pctSource = pick.price.pct_source;
          pricingMode = pick.price.pricing_mode === 'fixed' ? 'fixed'
            : pick.price.pricing_mode === 'market_based' ? 'market_based' : 'markup';
          unit = pick.price.unit;
          tierRow = pick.bracket;
          matchedTier = pick.price.matched_tier;
          markupPct = pick.price.markup_pct;
          discountPct = pick.price.discount_pct;
          marketRetail = pick.price.market_retail;
          marketDiscountPct = pick.price.market_discount_pct;
          breakMinCharge = pick.bracket.minimum_charge;
        });
      } else {
        // Chart-level flat default (machineCosts chart_default parity).
        const t = tmpl as NormalizedPricingTemplate;
        const flat = bracketPrice(
          {
            qty: 0, tier_markups: {}, unit_price: t.unit_price,
            markup_pct: t.markup_pct, discount_pct: t.discount_pct,
            market_retail: t.market_retail, market_discount_pct: t.market_discount_pct,
            minimum_charge: null, index: -1, raw: t.raw,
          },
          t, tierKeys, base,
        );
        if (flat) {
          record('template', true, `template_default ${flat.pct_source}${templateVia ? ` [${templateVia}]` : ''}`);
          take(() => {
            markWon();
            applied = true;
            source = 'template';
            pctSource = 'template_default';
            pricingMode = flat.pricing_mode === 'fixed' ? 'fixed'
              : flat.pricing_mode === 'market_based' ? 'market_based' : 'markup';
            unit = flat.unit;
            matchedTier = flat.matched_tier;
            markupPct = flat.markup_pct;
            discountPct = flat.discount_pct;
            marketRetail = flat.market_retail;
            marketDiscountPct = flat.market_discount_pct;
          });
        } else {
          record('template', false, 'no_qualifying_break');
          reason = reason ?? 'no_qualifying_break';
        }
      }
    }
  }

  // 3. tier_rule_set — part-linked GlobalPricingTier chart rescue.
  {
    const hit = tierRuleSetHit(part, ruleSets, tierKeys, base);
    if (hit) {
      record('tier_rule_set', true, `rule tier ${asString(hit.rule.tier ?? hit.rule.customer_tier)} -> ${hit.markup_pct}%`);
      take(() => {
        markWon();
        source = 'tier_rule_set';
        pctSource = 'tier_rule_set';
        pricingMode = 'markup';
        unit = hit.unit;
        markupPct = hit.markup_pct;
      });
    } else {
      record('tier_rule_set', false, partTierSetRefs(part).length ? 'no matching rule' : 'no linked rule set');
    }
  }

  // 4. part_chart — the part's own unit-price qty chart.
  {
    const brk = pickPartUnitBreak(partChartBreaks(part), qty);
    if (brk) {
      const price = num(brk.unit_price ?? brk.price);
      record('part_chart', true, `per_unit_breaks qty>=${num(brk.qty ?? brk.min_qty ?? brk.quantity)} -> ${price}`);
      take(() => {
        markWon();
        source = 'part_chart';
        pctSource = 'part_chart';
        pricingMode = 'fixed';
        unit = price;
      });
    } else {
      record('part_chart', false, 'no qualifying part break');
    }
  }

  // 5. part_market — part-level retail-minus-discount.
  {
    const retail = scopedFinite(part, PART_MARKET_RETAIL_FIELDS);
    if (retail !== null && retail > 0) {
      const disc = scopedFinite(part, PART_MARKET_DISCOUNT_FIELDS) ?? 0;
      record('part_market', true, `market_retail ${retail} - ${disc}%`);
      take(() => {
        markWon();
        source = 'part_market';
        pctSource = 'market_retail';
        pricingMode = 'market_based';
        unit = marketUnit(retail, disc);
        marketRetail = retail;
        marketDiscountPct = disc;
        discountPct = disc;
      });
    } else {
      record('part_market', false, 'no positive market_retail');
    }
  }

  // 6. default_markup — part markup, then the shop fallback percent.
  {
    const partMarkup = scopedFinite(part, PART_MARKUP_FIELDS);
    const shopDefault = toFiniteNumber(args.default_markup_pct ?? args.defaultMarkupPct);
    if (partMarkup !== null && partMarkup !== 0) {
      record('default_markup', true, `part.markup_pct ${partMarkup}`);
      take(() => {
        markWon();
        source = 'default_markup';
        pctSource = 'markup_pct';
        pricingMode = 'markup';
        unit = base * (1 + partMarkup / 100);
        markupPct = partMarkup;
      });
    } else if (shopDefault !== null) {
      record('default_markup', true, `default_markup_pct ${shopDefault}`);
      take(() => {
        markWon();
        source = 'default_markup';
        pctSource = 'fallback';
        pricingMode = 'default_markup';
        unit = base * (1 + shopDefault / 100);
        markupPct = shopDefault;
      });
    } else {
      record('default_markup', false, 'no finite fallback percent');
    }
  }

  // 7. cost_passthrough — always present as the floor; the caller's own
  // default chain still applies underneath (engine tierRules untouched).
  {
    record('cost_passthrough', true, 'unit = base_price');
    take(() => {
      markWon();
      source = 'cost_passthrough';
      pricingMode = 'cost_passthrough';
      unit = base;
    });
  }

  const unitPrice = num(unit);
  const extension = round2(unitPrice * qty);

  // Minimum-charge floor: highest finite candidate wins (engine parity).
  const minCandidates = [
    breakMinCharge,
    tmpl?.minimum_charge ?? null,
    scopedFinite(part, PART_MIN_CHARGE_FIELDS),
    toFiniteNumber(args.minimum_charge ?? args.minimumCharge),
  ];
  let minimumCharge = 0;
  for (const c of minCandidates) {
    if (c !== null && c > minimumCharge) minimumCharge = c;
  }
  const minimumApplied = minimumCharge > 0 && extension > 0 && extension < minimumCharge;
  const extended = minimumApplied ? round2(minimumCharge) : extension;

  return {
    applied,
    template_id: templateId,
    template_name: tmpl?.name ?? '',
    template: tmpl,
    source,
    pct_source: pctSource,
    pricing_mode: pricingMode,
    qty,
    base_price: base,
    unit_price: round4(unitPrice),
    extended,
    tier_row: tierRow,
    bracket_min_qty: tierRow ? tierRow.qty : null,
    matched_tier: matchedTier,
    markup_pct: markupPct,
    discount_pct: discountPct,
    market_retail: marketRetail,
    market_discount_pct: marketDiscountPct,
    minimum_charge: minimumCharge,
    minimum_applied: minimumApplied,
    reason,
    chain,
    unit_unverified: unitUnverified,
    warnings,
  };
}

// ---------------------------------------------------------------------------
// engine adapter (wiring spec — Option A, zero pricingEngine changes)
// ---------------------------------------------------------------------------

/** Part chart/reference fields a resolved template supersedes. */
const TEMPLATE_SUPERSEDED_FIELDS = [
  'tier_ref', 'tier', 'tier_name',
  'per_unit_breaks', 'unit_breaks', 'qty_breaks',
  'market_retail', 'retail', 'retail_price', 'list_price',
  'market_discount_pct', 'market_based', 'pricing_mode', 'price_mode',
  'markup_pct', 'markup', 'markup_percent', 'discount_pct',
] as const;

/**
 * Fold a resolveTemplatePrice result into a pricingEngine `part` descriptor.
 * When the template priced the line, the part's own chart fields are stripped
 * (the template supersedes them — CoreBridge part/template exclusivity) and
 * the resolved value is re-expressed in overrideRule's vocabulary:
 *   markup hit      -> {markup_pct: resolved pct}  (pct===0 still pins the
 *                      unit price via a qty-break — equivalent to a 0-markup
 *                      override now that overrideRule honors explicit 0s; the
 *                      break layer just outranks any stronger fields too)
 *   discount hit    -> {markup_pct: -discount_pct} (cost x (1 - d/100) parity)
 *   market hit      -> {pricing_mode:'market_based', market_retail,
 *                       market_discount_pct}
 *   fixed/break hit -> {per_unit_breaks:[{qty: order qty, unit_price}]}
 * The descriptor is SINGLE-SHOT — it encodes the resolution for the qty it was
 * built with; rebuild per line (a reused pin must not freeze another qty's
 * bracket pick). `minimumCharge`/`modifiers` still flow through pricePart
 * untouched; res.applied === false returns `part` VERBATIM (the engine's own
 * default chain prices it — template misses must not mask part config).
 */
export function templatePartDescriptor(part: unknown, resolution: TemplatePriceResult | null | undefined): any {
  const p = isRecord(part) ? { ...part } : {};
  if (!resolution || !resolution.applied) return part;
  for (const f of TEMPLATE_SUPERSEDED_FIELDS) delete (p as any)[f];
  const pinUnit = () => {
    (p as any).per_unit_breaks = [{ qty: resolution.qty || 1, unit_price: resolution.unit_price }];
  };
  switch (resolution.pricing_mode) {
    case 'market_based':
      if (resolution.pct_source === 'discount_pct' && resolution.market_retail === null) {
        // Discount was already folded into unit_price off base_price — re-
        // expressing it as market_retail+discount_pct would double-discount.
        if (resolution.discount_pct !== null && resolution.discount_pct !== 0) {
          (p as any).markup_pct = -resolution.discount_pct;
        } else {
          pinUnit();
        }
      } else {
        (p as any).pricing_mode = 'market_based';
        (p as any).market_retail = resolution.market_retail ?? resolution.unit_price;
        (p as any).market_discount_pct = resolution.market_discount_pct ?? resolution.discount_pct ?? 0;
      }
      break;
    case 'fixed':
      pinUnit();
      break;
    case 'markup':
    default:
      if (resolution.pct_source === 'discount_pct' && resolution.discount_pct !== null) {
        // cost x (1 - d/100) expressed as a negative markup; 0 falls to the pin.
        if (resolution.discount_pct !== 0) (p as any).markup_pct = -resolution.discount_pct;
        else pinUnit();
      } else if (resolution.markup_pct !== null && resolution.markup_pct !== 0) {
        (p as any).markup_pct = resolution.markup_pct;
      } else {
        pinUnit(); // markup_pct 0 = "sell at cost" — pin keeps it pinned even at the stronger break layer
      }
      break;
  }
  return p;
}
